 40	
 41	ALLOCATOR = r'''static int contest_i2s_tx_alloc_dma_slots(
 42	  FAR struct contest_i2s_tx_s *priv, unsigned int limit)
 43	{
 44	  static const unsigned int choices[] = {16, 8, 4};
 45	  unsigned int attempt;
 46	  unsigned int i;
 47	  unsigned int selected = 0;
 48	  struct mallinfo info;
 49	
 50	  if (limit != 0 && limit != 4 && limit != 8 && limit != 16)
 51	    {
 52	      return -EINVAL;
 53	    }
 54	  if (limit == 0) limit = CONTEST_I2S_TX_RING_SLOTS;
 55	
 56	  /* START is called only while stopped. Clear every possible old slot,
 57	   * including partial allocations left by an interrupted earlier START. */
 58	  for (i = 0; i < CONTEST_I2S_TX_RING_SLOTS; i++)
 59	    {
 60	      if (priv->xfer[i].dma_data) kmm_free(priv->xfer[i].dma_data);
 61	      priv->xfer[i].dma_data = NULL;
 62	      priv->xfer[i].dma_bound = false;
 63	    }
 64	  priv->dma_slot_count = 0;
 65	
 66	  for (attempt = 0; attempt < sizeof(choices) / sizeof(choices[0]); attempt++)
 67	    {
 68	      selected = choices[attempt];
 69	      if (selected > limit) continue;
 70	      for (i = 0; i < selected; i++)
 71	        {
 72	          priv->xfer[i].dma_data = kmm_memalign(CONTEST_I2S_TX_DMA_ALIGN,
 73	                                               CONTEST_I2S_TX_SLOT_BYTES);
 74	          if (!priv->xfer[i].dma_data) break;
 75	          memset(priv->xfer[i].dma_data, 0, CONTEST_I2S_TX_SLOT_BYTES);
 76	          up_clean_dcache((uintptr_t)priv->xfer[i].dma_data,
 77	                          (uintptr_t)priv->xfer[i].dma_data +
 78	                          CONTEST_I2S_TX_SLOT_BYTES);
 79	        }
 80	      if (i == selected)
 81	        {
 82	          priv->dma_slot_count = selected;
 83	          info = kmm_mallinfo();
