 87	          return OK;
 88	        }
 89	
 90	      info = kmm_mallinfo();
 91	      syslog(LOG_WARNING, "[RV-DMA] allocation failed slots=%u allocated=%u kmm_free=%zu largest=%zu\n",
 92	             selected, i, (size_t)info.fordblks, (size_t)info.mxordblk);
