   502	static void release(struct rv_connection *slot, bool keep)
   503	{
   504	  /* Two idle connections maximum leaves capacity for transient task groups.
   505	   * Never close another group's fd through the caller's descriptor table. */
   506	  pthread_mutex_lock(&pool_lock);
   507	  unsigned int idle = 0;
   508	  for (unsigned int i = 0; i < 4; i++)
   509	    if (&pool[i] != slot && !pool[i].busy && pool[i].tls) idle++;
   510	  if (idle >= 2) keep = false;
   511	  if (!keep) { tls_close(slot->tls); slot->tls = NULL; }
   512	  slot->last_used = now_ms();
   513	  slot->busy = false;
   514	  pthread_cond_broadcast(&pool_changed);
   515	  pthread_mutex_unlock(&pool_lock);
   516	}
