   518	void robot_voice_http_close_idle(void)
   519	{
   520	  pthread_mutex_lock(&pool_lock);
   521	  for (unsigned int i = 0; i < 4; i++) {
   522	    if (!pool[i].busy && pool[i].tls && pool[i].owner == getpid()) {
   523	      tls_close(pool[i].tls); pool[i].tls = NULL;
   524	    }
   525	  }
   526	  pthread_mutex_unlock(&pool_lock);
   527	}
