   529	bool robot_voice_http_network_recovery_begin(void)
   530	{
   531	  pthread_mutex_lock(&pool_lock);
   532	  bool idle = !network_recovering;
   533	  for (unsigned int i = 0; i < 4; i++)
   534	    if (pool[i].busy) idle = false;
   535	  if (idle) {
   536	    network_recovering = true;
   537	    network_generation++;
   538	  }
   539	  pthread_mutex_unlock(&pool_lock);
   540	  /* Other task groups retire their own stale descriptors on their next use. */
   541	  if (idle) robot_voice_http_close_idle();
   542	  return idle;
   543	}
