 24	static unsigned long long rv_wifi_now_ms(void)
 25	{
 26	  struct timespec ts;
 27	  if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) return 0;
 28	  return (unsigned long long)ts.tv_sec * 1000 +
 29	         (unsigned long long)ts.tv_nsec / 1000000;
 30	}
