 32	static void rv_wifi_link_ready(void)
 33	{
 34	  pthread_mutex_lock(&g_wifi_watch_lock);
 35	  g_wifi_link_misses = 0;
 36	  g_wifi_backoff_ms = ROBOT_VOICE_WIFI_RECOVER_MIN_MS;
 37	  g_wifi_next_recovery_ms = 0;
 38	  pthread_mutex_unlock(&g_wifi_watch_lock);
 39	}
 40	
 41	static void rv_wifi_schedule_failure(int rc)
 42	{
 43	  pthread_mutex_lock(&g_wifi_watch_lock);
 44	  unsigned int delay = rc == -ENOENT ? ROBOT_VOICE_WIFI_RECOVER_MAX_MS :
 45	                                       g_wifi_backoff_ms;
 46	  if (delay < ROBOT_VOICE_WIFI_RECOVER_MIN_MS)
 47	    delay = ROBOT_VOICE_WIFI_RECOVER_MIN_MS;
 48	  if (delay > ROBOT_VOICE_WIFI_RECOVER_MAX_MS)
 49	    delay = ROBOT_VOICE_WIFI_RECOVER_MAX_MS;
 50	  g_wifi_next_recovery_ms = rv_wifi_now_ms() + delay;
 51	  g_wifi_backoff_ms = g_wifi_backoff_ms >= ROBOT_VOICE_WIFI_RECOVER_MAX_MS / 2 ?
 52	                      ROBOT_VOICE_WIFI_RECOVER_MAX_MS : g_wifi_backoff_ms * 2;
 53	  g_wifi_recovery_active = false;
 54	  pthread_mutex_unlock(&g_wifi_watch_lock);
 55	
 56	  network_wifi_diag();
 57	  printf("[网络恢复] failed rc=%d retry_after=%ums%s\n", rc, delay,
 58	         rc == -ENOENT ? " missing-saved-credentials" : "");
 59	}
