 86	/* Called by the voice controller while it is listening, including acoustic
 87	 * wake standby. This never restarts wlan0 because a cloud request was slow;
 88	 * network_is_connected() checks both association and usable IPv4 first. */
 89	void robot_voice_wifi_poll(void)
 90	{
 91	  unsigned long long now = rv_wifi_now_ms();
 92	  pthread_mutex_lock(&g_wifi_watch_lock);
 93	  if (now < g_wifi_next_check_ms)
 94	    {
 95	      pthread_mutex_unlock(&g_wifi_watch_lock);
 96	      return;
 97	    }
 98	  g_wifi_next_check_ms = now + ROBOT_VOICE_WIFI_CHECK_MS;
 99	  pthread_mutex_unlock(&g_wifi_watch_lock);
100	
101	  if (network_is_connected())
102	    {
103	      rv_wifi_link_ready();
104	      return;
105	    }
106	
107	  pthread_mutex_lock(&g_wifi_watch_lock);
108	  if (g_wifi_link_misses < ROBOT_VOICE_WIFI_LINK_MISSES)
109	    g_wifi_link_misses++;
110	  bool confirmed_down = g_wifi_link_misses >= ROBOT_VOICE_WIFI_LINK_MISSES;
111	  bool due = confirmed_down && !g_wifi_recovery_active &&
112	             now >= g_wifi_next_recovery_ms;
113	  if (due)
114	    {
115	      /* If a request is active, retry the health check on the next tick. */
116	      g_wifi_next_recovery_ms = now + ROBOT_VOICE_WIFI_CHECK_MS;
117	      g_wifi_recovery_active = true;
118	    }
119	  pthread_mutex_unlock(&g_wifi_watch_lock);
120	  if (!due) return;
121	
122	  /* Do not tear down a socket that is still servicing ASR/LLM/TTS. The HTTP
123	   * gate also prevents a new request from starting in the recovery window. */
124	  if (!robot_voice_http_network_recovery_begin())
125	    {
126	      pthread_mutex_lock(&g_wifi_watch_lock);
127	      g_wifi_recovery_active = false;
128	      pthread_mutex_unlock(&g_wifi_watch_lock);
129	      return;
130	    }
131	
132	  /* Recheck after becoming the sole network owner. This avoids a stale
133	   * negative snapshot racing a successful set_wifi transaction. */
134	  if (network_is_connected())
135	    {
136	      robot_voice_http_network_recovery_end();
137	      rv_wifi_link_ready();
138	      pthread_mutex_lock(&g_wifi_watch_lock);
139	      g_wifi_recovery_active = false;
140	      pthread_mutex_unlock(&g_wifi_watch_lock);
141	      return;
142	    }
143	
144	  pthread_attr_t attr;
145	  pthread_t thread;
146	  int create_rc = pthread_attr_init(&attr);
147	  if (create_rc == 0)
148	    {
149	      create_rc = pthread_attr_setstacksize(&attr, 16 * 1024);
150	      if (create_rc == 0)
151	        create_rc = pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
152	      if (create_rc == 0)
153	        create_rc = pthread_create(&thread, &attr, rv_wifi_recovery_worker, NULL);
154	      pthread_attr_destroy(&attr);
155	    }
156	  if (create_rc != 0)
157	    {
158	      robot_voice_http_network_recovery_end();
159	      pthread_mutex_lock(&g_wifi_watch_lock);
160	      g_wifi_recovery_active = false;
161	      pthread_mutex_unlock(&g_wifi_watch_lock);
162	      rv_wifi_schedule_failure(-create_rc);
163	    }
