453	static struct rv_connection *acquire(const char *host, const char *port,
454	                                     bool allow_reuse, bool *reused, unsigned long long deadline)
455	{
456	  struct rv_connection *slot = NULL;
457	  pid_t owner = getpid();
458	  pthread_mutex_lock(&pool_lock);
459	retry_slot:
460	  if (!network_recovering) {
461	  for (unsigned int i = 0; i < 4; i++) {
462	    if (!pool[i].busy && pool[i].tls && pool[i].owner == owner && !strcmp(pool[i].host, host) && !strcmp(pool[i].port, port)) {
463	      slot = &pool[i]; break;
464	    }
465	  }
466	  if (!slot) for (unsigned int i = 0; i < 4; i++) if (!pool[i].busy && !pool[i].tls) {
467	    slot = &pool[i]; break;
468	  }
469	  if (!slot) for (unsigned int i = 0; i < 4; i++) if (!pool[i].busy && pool[i].owner == owner) {
470	    slot = &pool[i]; break;
471	  }
472	  }
473	  if (!slot && remaining_ms(deadline, 1)) {
474	    /* ASR/Flash may temporarily occupy all slots. Sleep without allocating
475	     * TLS/IOB resources; the request's original deadline still applies. */
476	    struct timespec until;
477	    unsigned int ms = remaining_ms(deadline, 50);
478	    clock_gettime(CLOCK_REALTIME, &until);
479	    until.tv_nsec += (long)ms * 1000000;
480	    if (until.tv_nsec >= 1000000000) { until.tv_sec++; until.tv_nsec -= 1000000000; }
481	    pthread_cond_timedwait(&pool_changed, &pool_lock, &until);
482	    goto retry_slot;
483	  }
484	  if (slot) {
485	    slot->busy = true;
486	    slot->owner = owner;
487	    slot->id = ++next_id;
488	    *reused = allow_reuse && slot->generation == network_generation &&
489	              slot->tls && !strcmp(slot->host, host) && !strcmp(slot->port, port) &&
490	              now_ms() - slot->last_used < 25000;
491	    slot->generation = network_generation;
492	  }
493	  pthread_mutex_unlock(&pool_lock);
494	  if (slot && !*reused) { tls_close(slot->tls); slot->tls = NULL; }
495	  if (slot) {
496	    snprintf(slot->host, sizeof(slot->host), "%s", host);
497	    snprintf(slot->port, sizeof(slot->port), "%s", port);
498	  }
499	  return slot;
500	}
