589	/* Log a short, printable server error body for LLM requests only. This is
590	 * response data, never the request (which may contain user text or secrets).
591	 * Control bytes are replaced so a provider message cannot forge log lines. */
592	static void rv_log_llm_error_body(int status, const char *response,
593	                                  size_t capacity)
594	{
595	  char preview[193];
596	  size_t len;
597	  size_t i;
598	  size_t used = 0;
599	
600	  if (response == NULL || capacity == 0)
601	    {
602	      printf("[RV-LLM-ERROR] http_status=%d body_bytes=0 body_preview=<empty>\n",
603	             status);
604	      return;
605	    }
606	
607	  len = strnlen(response, capacity);
608	  for (i = 0; i < len && used < sizeof(preview) - 1; i++)
609	    {
610	      unsigned char ch = (unsigned char)response[i];
611	      preview[used++] = (ch >= 0x20 && ch != 0x7f) ? (char)ch : ' ';
612	    }
613	  preview[used] = '\0';
614	
615	  printf("[RV-LLM-ERROR] http_status=%d body_bytes=%zu preview_bytes=%zu "
616	         "truncated=%u body_preview=\"%s\"\n",
617	         status, len, used, len > used, preview);
618	}
