620	static int entity(const char *data, size_t len, void *arg)
621	{
622	  struct rv_response *r = arg;
623	  if (!r->first) {
624	    r->first = now_ms();
625	    RV_VERBOSE("[RV-HTTP] id=%u first_body_ms=%llu status=%d framing=%s\n",
626	           r->id, r->first - r->start, r->parser->status, r->parser->framing);
627	  }
628	  if (r->callback) {
629	    /* Never feed an HTTP error document to a PCM/SSE consumer. */
630	    if (r->parser->status < 200 || r->parser->status >= 300) return 0;
631	    return r->callback(data, len, r->arg);
632	  }
633	  if (len > r->capacity - 1 - r->used) return -EOVERFLOW;
634	  memcpy(r->buffer + r->used, data, len);
635	  r->used += len;
636	  r->buffer[r->used] = 0;
637	  return 0;
638	}
