1884	
1885	      if (pb->i2s != NULL && pb->i2s_started)
1886	        {
1887	          pb->i2s_started = 0;
1888	          I2S_IOCTL(pb->i2s, AUDIOIOC_STOP, 0);
1889	          rv_signal_all(pb);
1890	        }
1891	
1892	      pthread_join(pb->worker, NULL);
1893	      pb->worker_started = 0;
1894	    }
