1896	  (void)rv_drain(pb);
1897	
1898	  if (pb->i2s != NULL && pb->i2s_started)
1899	    {
1900	      pb->i2s_started = 0;
1901	      I2S_IOCTL(pb->i2s, AUDIOIOC_STOP, 0);
1902	    }
