1904	  if (!pb->finished)
1905	    RV_VERBOSE("[RV-PB] cancelled id=%u cached=%zu consumed=%zu dma_start_ms=%llu result=%d\n",
1906	           pb->id, pb->total_written, pb->total_read, pb->dma_start_ms, rv_get_result(pb));
