/****************************************************************************
 * Name: wlan_transmit
 *
 * Description:
 *   Try to send all TX packets in TX ready queue to Wi-Fi driver. If this
 *    sending fails, then breaks loop and returns.
 *
 * Input Parameters:
 *   priv - Reference to the driver state structure
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

static void wlan_transmit(struct wlan_priv_s *priv)
{
  static uint32_t submit_ok;
  static uint32_t submit_enomem;
  static uint32_t credit_stalls;
  struct wlan_pktbuf *pktbuf;
  int ret;

  if (wlan_tx_retry_is_pending(priv))
    {
      return;
    }

  while ((pktbuf = wlan_txframe(priv)))
    {
      bool tls443;

      /*
       * Do not flood the Espressif dynamic TX pool.  Put the packet back at
       * the head and wait for a TX-done callback to return a credit.
       */
      if (!wlan_tx_credit_take(priv))
        {
          credit_stalls++;

          if (credit_stalls <= 8 || (credit_stalls & 0x3f) == 0)
            {
              syslog(LOG_INFO,
                     "[WLAN-TXFLOW] credit stall=%" PRIu32
                     " inflight=%u max=%u\n",
                     credit_stalls,
                     (unsigned int)wlan_tx_credit_count(priv),
                     (unsigned int)WLAN_WIFI_TX_INFLIGHT_MAX);
            }

          wlan_add_txpkt_head(priv, pktbuf);
          break;
        }

      tls443 = wlan_diag_is_tcp443(pktbuf->buffer, pktbuf->len);
      wlan_diag_tls_frame("TX", pktbuf->buffer, pktbuf->len);

      ret = priv->ops->send(pktbuf->buffer, pktbuf->len);

      if (ret < 0)
        {
          /* No TX-done is expected for a failed submission. */

          wlan_tx_credit_release(priv);
        }

      if (ret == -ENOMEM)
        {
          uint32_t attempts;

          submit_enomem++;
          attempts = wlan_tx_retry_count(priv);

          syslog(LOG_ERR,
                 "[WLAN-TXFLOW] vendor ENOMEM count=%" PRIu32
                 " len=%u inflight=%u free=%u attempt=%" PRIu32 "/%u\n",
                 submit_enomem,
                 (unsigned int)pktbuf->len,
                 (unsigned int)wlan_tx_credit_count(priv),
                 (unsigned int)priv->free_count,
                 attempts + 1,
                 (unsigned int)WLAN_TX_RETRY_MAX_ATTEMPTS);

          if (attempts >= WLAN_TX_RETRY_MAX_ATTEMPTS)
            {
              /*
               * This is only the driver's copied Ethernet frame.  Dropping it
               * is equivalent to ordinary link loss: TCP still owns the
               * unacknowledged stream data and will retransmit later.
               *
               * Do not pin the interface forever in a driver-level retry
               * loop when the vendor TX path is persistently out of memory.
               */

              syslog(LOG_ERR,
                     "[WLAN-TXFLOW] retry giveup len=%u after=%" PRIu32
                     " delayed attempts; let TCP retransmit\n",
                     (unsigned int)pktbuf->len, attempts);

              wlan_free_buffer(priv, pktbuf->buffer);
              wlan_tx_retry_reset(priv);
              break;
            }

          wlan_add_txpkt_head(priv, pktbuf);
          wlan_tx_retry_schedule(priv);
          break;
        }

      if (ret < 0)
        {
          nwarn("WARN: Failed to send pkt, ret: %d\n", ret);
          wlan_free_buffer(priv, pktbuf->buffer);
          continue;
        }

      submit_ok++;
      wlan_tx_retry_reset(priv);

      /*
       * Rate-limit success logging.  Serial output from the Wi-Fi worker can
       * itself make queue starvation worse during certificate bursts.
       */
      if (tls443 && (submit_ok <= 12 || (submit_ok & 0x3f) == 0))
        {
          syslog(LOG_INFO,
                 "[WLAN-TXSUBMIT] ok=%" PRIu32
                 " len=%u inflight=%u\n",
                 submit_ok,
                 (unsigned int)pktbuf->len,
                 (unsigned int)wlan_tx_credit_count(priv));
        }

      /*
       * esp_wifi_internal_tx() copies the Ethernet frame before returning,
       * so the NuttX packet buffer can be returned immediately.  The
       * tx_inflight credit is released later by wlan_sta_tx_done().
       */
      wlan_free_buffer(priv, pktbuf->buffer);
    }
}

/****************************************************************************
 * Name: wlan_tx_done
 *
 * Description:
 *   Wi-Fi TX done callback function. If this is called, it means sending
 *   next packet.
 *
 * Input Parameters:
 *   priv   - Reference to the driver state structure
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

static void wlan_tx_done(struct wlan_priv_s *priv)
{
  wd_cancel(&priv->txtimeout);

  wlan_txavail(&priv->dev);
}

/****************************************************************************
 * Function: wlan_rx_done
 *
 * Description:
 *   Wi-Fi RX done callback function. If this is called, it means receiving
 *   packet.
 *
 * Input Parameters:
 *   priv   - Reference to the driver state structure
 *   buffer - Wi-Fi received packet buffer
 *   len    - Length of received packet
 *   eb     - Wi-Fi receive callback input eb pointer
 *
 * Returned Value:
 *   0 on success or a negated errno on failure
 *
 ****************************************************************************/

static int wlan_rx_done(struct wlan_priv_s *priv, void *buffer,
                        uint16_t len, void *eb)
{
  struct wlan_pktbuf *pktbuf;
  irqstate_t flags;
  bool schedule = false;
  int workret;
  int ret = 0;

  wlan_diag_tls_frame("RX", buffer, len);

  if (!priv->ifup)
    {
      goto out;
    }

  if (len > WLAN_BUF_SIZE)
    {
      g_wlan_tls_rx_oversize++;
      syslog(LOG_ERR,
             "[WLAN-RX] OVERSIZE count=%" PRIu32
             " len=%u max=%u -- dropping frame\n",
             g_wlan_tls_rx_oversize,
             (unsigned int)len, (unsigned int)WLAN_BUF_SIZE);
      nwarn("ERROR: Wlan receive %d larger than %d\n",
             len, WLAN_BUF_SIZE);
      ret = -EINVAL;
      goto out;
    }

  pktbuf = wlan_alloc_buffer(priv);
  if (!pktbuf)
    {
      g_wlan_tls_rx_nobuf++;
      syslog(LOG_ERR,
             "[WLAN-RX] NOBUF count=%" PRIu32
             " len=%u free=%u reserve=%u -- dropping frame\n",
             g_wlan_tls_rx_nobuf, (unsigned int)len,
             (unsigned int)priv->free_count,
             (unsigned int)WLAN_RX_RESERVED_BUFS);
      ret = -ENOBUFS;
      goto out;
    }

  memcpy(pktbuf->buffer, buffer, len);
  pktbuf->len = len;

  if (eb)
    {
      esp_wifi_free_eb(eb);
    }

  flags = spin_lock_irqsave(&priv->lock);
  sq_addlast(&pktbuf->entry, &priv->rxb);
  if (!priv->rx_work_pending)
    {
      priv->rx_work_pending = true;
      schedule = true;
    }
  spin_unlock_irqrestore(&priv->lock, flags);

  if (schedule)
    {
      workret = work_queue(WLAN_WORK, &priv->rxwork, wlan_rxpoll, priv, 0);
      if (workret < 0)
        {
          flags = spin_lock_irqsave(&priv->lock);
          priv->rx_work_pending = false;
          spin_unlock_irqrestore(&priv->lock, flags);

          syslog(LOG_ERR,
                 "[WLAN-RX] work queue failed ret=%d\n", workret);
        }
    }

  return 0;

out:
  if (eb)
    {
      esp_wifi_free_eb(eb);
    }

  return ret;
}

/****************************************************************************
 * Function: wlan_rxpoll
 *
 * Description:
 *   Try to receive packets from RX done queue and pass packets into IP
 *   stack and send packets which is from IP stack if necessary.
 *
 * Input Parameters:
 * Input Parameters:
 *   priv - Reference to the driver state structure
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

static void wlan_rxpoll(void *arg)
{
  struct wlan_pktbuf *pktbuf;
  struct eth_hdr_s *eth_hdr;
  struct wlan_priv_s *priv = (struct wlan_priv_s *)arg;
  struct net_driver_s *dev = &priv->dev;
  irqstate_t flags;
  bool requeue;
#ifdef WLAN_RX_THRESHOLD
  uint32_t rbytes = 0;
#endif

  /* Try to send all cached TX packets for TX ack and so on */

  wlan_transmit(priv);

  /* Loop while while wlan_recvframe() successfully retrieves valid
   * Ethernet frames.
   */

  net_lock();

  while ((pktbuf = wlan_recvframe(priv)) != NULL)
    {
      dev->d_buf = pktbuf->buffer;
      dev->d_len = pktbuf->len;

#ifdef WLAN_RX_THRESHOLD
      rbytes += pktbuf->len;
#endif

#ifdef CONFIG_NET_PKT

      /* When packet sockets are enabled,
       * feed the frame into the packet tap.
       */

      pkt_input(&priv->dev);
#endif

      /* Check if the packet is a valid size for the network
       * buffer configuration (this should not happen)
       */

      if (dev->d_len > WLAN_BUF_SIZE)
        {
          nwarn("WARNING: DROPPED Too big: %d\n", dev->d_len);

          /* Free dropped packet buffer */

          if (dev->d_buf)
            {
              wlan_free_buffer(priv, dev->d_buf);
              dev->d_buf = NULL;
              dev->d_len = 0;
            }

          continue;
        }

      eth_hdr = (struct eth_hdr_s *)dev->d_buf;

      /* We only accept IP packets of the configured type and ARP packets */

#ifdef CONFIG_NET_IPv4
      if (eth_hdr->type == HTONS(ETHTYPE_IP))
        {
          ninfo("IPv4 frame\n");

          /* Receive an IPv4 packet from the network device */

          ipv4_input(&priv->dev);

          /* If the above function invocation resulted in data
           * that should be sent out on the network,
           * the field  d_len will set to a value > 0.
           */

          if (priv->dev.d_len > 0)
            {
              /* And send the packet */

              wlan_cache_txpkt_tail(priv);
            }
        }
      else
#endif
#ifdef CONFIG_NET_IPv6
      if (eth_hdr->type == HTONS(ETHTYPE_IP6))
        {
          ninfo("IPv6 frame\n");

          /* Give the IPv6 packet to the network layer */

          ipv6_input(&priv->dev);

          /* If the above function invocation resulted in data
           * that should be sent out on the network, the field
           * d_len will set to a value > 0.
           */

          if (priv->dev.d_len > 0)
            {
              /* And send the packet */

              wlan_cache_txpkt_tail(priv);
            }
        }
      else
#endif
#ifdef CONFIG_NET_ARP
      if (eth_hdr->type == HTONS(ETHTYPE_ARP))
        {
          ninfo("ARP frame\n");

          /* Handle ARP packet */

          arp_input(&priv->dev);

          /* If the above function invocation resulted in data
           * that should be sent out on the network, the field
           * d_len will set to a value > 0.
           */

          if (priv->dev.d_len > 0)
            {
              wlan_cache_txpkt_tail(priv);
            }
        }
      else
#endif
        {
          ninfo("INFO: Dropped, Unknown type: %04x\n", eth_hdr->type);
        }

      /* We are finished with the RX buffer.  NOTE:  If the buffer is
       * re-used for transmission, the dev->d_buf field will have been
       * nullified.
       */

      if (dev->d_buf)
        {
          /* Free the receive packet buffer */

          wlan_free_buffer(priv, dev->d_buf);
          dev->d_buf = NULL;
          dev->d_len = 0;
        }

#ifdef WLAN_RX_THRESHOLD
      /* If received total bytes is larger than receive threshold,
       * then do "unlock" to try to active applicantion to receive
       * data from low-level buffer of IP stack.
       */

      if (rbytes >= WLAN_RX_THRESHOLD)
        {
          net_unlock();
          rbytes = 0;
          net_lock();
        }
#endif
    }

