   892	  struct wlan_pktbuf *pktbuf;
   893	  uint8_t *txbuf;
   894	  int ret;
   895	
   896	  pktbuf = wlan_alloc_buffer(priv);
   897	  if (!pktbuf)
   898	    {
   899	      return;
   900	    }
   901	
   902	  dev->d_buf = pktbuf->buffer;
   903	  dev->d_len = WLAN_BUF_SIZE;
