   905	  /* Try to let TCP/IP to send all packets to netcard driver */
   906	
   907	  do
   908	    {
   909	      txbuf = dev->d_buf;
   910	      ret = devif_poll(dev, wlan_txpoll);
   911	    }
   912	  while ((ret == 0) &&
   913	         (dev->d_buf != txbuf));
   914	
   915	  if (dev->d_buf)
