   917	      wlan_free_buffer(priv, dev->d_buf);
   918	
   919	      dev->d_buf = NULL;
   920	      dev->d_len = 0;
   921	    }
   922	
   923	  /* Try to send all cached TX packets */
   924	
   925	  wlan_transmit(priv);
   926	}
