    48	static void work_queue_start(FAR struct kwork_wqueue_s *wqueue,
    49	                             FAR struct work_s *work, worker_t worker,
    50	                             FAR void *arg, clock_t expected)
    51	{
    52	  bool retimer;
    53	
    54	  /* Ensure the work has been removed. */
    55	
    56	  retimer = work_available(work) ? false : work_remove(wqueue, work);
    57	
    58	  /* Initialize the work structure. */
    59	
    60	  work->worker = worker;   /* Work callback. non-NULL means queued */
    61	  work->arg    = arg;      /* Callback argument */
    62	  work->qtime  = expected; /* Expected time */
    63	
    64	  /* Insert to the pending list of the wqueue. */
    65	
    66	  retimer |= work_insert_pending(wqueue, work);
    67	
    68	  if (retimer)
    69	    {
    70	      /* Start the timer if the work is the earliest expired work. */
    71	
    72	      wd_start_abstick(&wqueue->timer, expected,
    73	                       work_timer_expired, (wdparm_t)wqueue);
    74	    }
    75	}
