    86	 *   time. This function must be called in the workqueue callback.
    87	 *
    88	 * Input Parameters:
    89	 *   qid    - The work queue ID (must be HPWORK or LPWORK)
    90	 *   wqueue - The work queue handle
    91	 *   work   - The work structure to queue
    92	 *   worker - The worker callback to be invoked.  The callback will be
    93	 *            invoked on the worker thread of execution.
    94	 *   arg    - The argument that will be passed to the worker callback when
    95	 *            it is invoked.
    96	 *   delay  - Delay (in clock ticks) from the time queue until the worker
    97	 *            is invoked. Zero means to perform the work immediately.
    98	 *
    99	 * Returned Value:
   100	 *   Zero on success, a negated errno on failure
   101	 *
   102	 ****************************************************************************/
   103	
   104	int work_queue_next_wq(FAR struct kwork_wqueue_s *wqueue,
   105	                       FAR struct work_s *work, worker_t worker,
   106	                       FAR void *arg, clock_t delay)
   107	{
   108	  irqstate_t flags;
   109	  int ret = -EINVAL;
   110	
   111	  if (wqueue && work && worker && delay <= WDOG_MAX_DELAY)
   112	    {
   113	      ret   = OK;
   114	      flags = spin_lock_irqsave(&wqueue->lock);
   115	      work_queue_start(wqueue, work, worker, arg, work->qtime + delay);
   116	      spin_unlock_irqrestore(&wqueue->lock, flags);
   117	    }
   118	
   119	  return ret;
   120	}
