   128	/****************************************************************************
   129	 * Name: work_queue/work_queue_wq
   130	 *
   131	 * Description:
   132	 *   Queue work to be performed at a later time.  All queued work will be
   133	 *   performed on the worker thread of execution (not the caller's).
   134	 *
   135	 *   The work structure is allocated and must be initialized to all zero by
   136	 *   the caller.  Otherwise, the work structure is completely managed by the
   137	 *   work queue logic.  The caller should never modify the contents of the
   138	 *   work queue structure directly.  If work_queue() is called before the
   139	 *   previous work has been performed and removed from the queue, then any
   140	 *   pending work will be canceled and lost.
   141	 *
   142	 * Input Parameters:
   143	 *   qid    - The work queue ID (must be HPWORK or LPWORK)
   144	 *   wqueue - The work queue handle
   145	 *   work   - The work structure to queue
   146	 *   worker - The worker callback to be invoked.  The callback will be
   147	 *            invoked on the worker thread of execution.
   148	 *   arg    - The argument that will be passed to the worker callback when
   149	 *            it is invoked.
   150	 *   delay  - Delay (in clock ticks) from the time queue until the worker
   151	 *            is invoked. Zero means to perform the work immediately.
   152	 *
   153	 * Returned Value:
   154	 *   Zero on success, a negated errno on failure
   155	 *
   156	 ****************************************************************************/
   157	
   158	int work_queue_wq(FAR struct kwork_wqueue_s *wqueue,
   159	                  FAR struct work_s *work, worker_t worker,
   160	                  FAR void *arg, clock_t delay)
   161	{
   162	  irqstate_t flags;
   163	  clock_t expected;
   164	  int          ret = -EINVAL;
   165	
   166	  if (wqueue && work && worker && delay <= WDOG_MAX_DELAY)
   167	    {
   168	      ret      = OK;
   169	      expected = clock_delay2abstick(delay);
   170	      flags    = spin_lock_irqsave(&wqueue->lock);
   171	      work_queue_start(wqueue, work, worker, arg, expected);
   172	      spin_unlock_irqrestore(&wqueue->lock, flags);
   173	    }
   174	
   175	  return ret;
   176	}
   177	
   178	int work_queue(int qid, FAR struct work_s *work, worker_t worker,
   179	               FAR void *arg, clock_t delay)
   180	{
   181	  return work_queue_wq(work_qid2wq(qid), work, worker, arg, delay);
   182	}
