 ****************************************************************************/

/* TX timeout = 1 minute */

#define WLAN_TXTOUT               (60 * CLK_TCK)

/* Low-priority work queue processes RX/TX */

#define WLAN_WORK                 LPWORK

/* Ethernet frame:
 *     Resource address   :   6 bytes
 *     Destination address:   6 bytes
 *     Type               :   2 bytes
 *     Payload            :   MAX 1500
 *     Checksum           :   Ignore
 *
 *     Total size         :   1514
 */

#define WLAN_BUF_SIZE             (CONFIG_NET_ETH_PKTSIZE)

/* WLAN packet buffer number */

#define WLAN_PKTBUF_NUM           (CONFIG_ESP32S3_WLAN_PKTBUF_NUM)

/*
 * RX reserve for the shared WLAN packet-buffer pool.
 *
 * RX and TX currently share pktbuf[].  During a large TCP write, devif_poll()
 * may enqueue many TX frames before wlan_transmit() gets a chance to drain
 * txb.  With CONFIG_ESP32S3_WLAN_PKTBUF_NUM=16 this can consume the entire
 * pool and make wlan_rx_done() fail with -ENOBUFS, dropping TCP ACKs and
 * eventually resetting the TLS connection.
 *
 * Keep half of the pool unavailable to normal TX polling.  RX still uses the
 * full pool, so receive bursts can consume the reserve when needed.
 */
#define WLAN_RX_RESERVED_BUFS \
  ((WLAN_PKTBUF_NUM >= 8) ? (WLAN_PKTBUF_NUM / 2) : 2)

/*
 * Upper-layer Wi-Fi TX flow control.
 *
 * esp_wifi_internal_tx() uses the vendor driver's dynamic TX resources.
 * Submitting an entire NuttX txb burst in one wlan_transmit() call can
 * exhaust those resources and return -ENOMEM, even for small TCP ACKs.
 *
 * Keep only a small number of vendor TX submissions in flight.  TX-done
 * callbacks return credits and immediately schedule more work.
 */
#define WLAN_WIFI_TX_INFLIGHT_MAX 4

/* Vendor ESP_ERR_NO_MEM is temporary backpressure, not a reason to spin.
 * Retry the same queued packet with bounded exponential backoff.
 */

#define WLAN_TX_RETRY_MIN_MS       10
#define WLAN_TX_RETRY_MAX_MS       160
#define WLAN_TX_RETRY_MAX_ATTEMPTS 8



/*
 * HTTPS/TLS receive-path diagnostics.
 *
 * The contest configuration currently uses CONFIG_NET_ETH_PKTSIZE=590.
 * Log only TCP/443 traffic, with a strict rate limit, so we can determine:
 *   - the MSS advertised in SYN/SYN-ACK;
 *   - whether MiMo's first TLS response reaches the Wi-Fi callback;
 *   - whether an incoming Ethernet frame exceeds WLAN_BUF_SIZE;
 *   - whether the small wlan_pktbuf pool is exhausted.
 *
 * This code does not modify packets.
 */
#define WLAN_TLS_DIAG_PORT          443
#define WLAN_TLS_DIAG_PAYLOAD_LIMIT 32 /* retained for source compatibility */

static uint32_t g_wlan_tls_diag_frames;
static uint32_t g_wlan_tls_rx_oversize;
static uint32_t g_wlan_tls_rx_nobuf;
static uint32_t g_wlan_tls_rx_work_requeue;
static uint32_t g_wlan_tls_txdone_ok;
static uint32_t g_wlan_tls_txdone_fail;

static uint16_t wlan_diag_be16(const uint8_t *p)
}

/* Receive threshold which allows the receive function to trigger a scheduler
 * to activate the application if possible.
 */

#ifdef CONFIG_MM_IOB
#  define IOBBUF_SIZE             (CONFIG_IOB_NBUFFERS * CONFIG_IOB_BUFSIZE)
#  if (IOBBUF_SIZE) > (WLAN_BUF_SIZE + 1)
#    define WLAN_RX_THRESHOLD     (IOBBUF_SIZE - WLAN_BUF_SIZE + 1)
#  endif
#endif

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* WLAN packet buffer */

struct wlan_pktbuf
{
  sq_entry_t    entry;                  /* Queue entry */

  /* Packet data buffer */

  uint8_t       buffer[WLAN_BUF_SIZE];
  uint16_t      len;                    /* Packet data length */
};

/* WLAN operations */

struct wlan_ops
{
  int (*start)(void);
  int (*send)(void *pdata, size_t n);
  int (*essid)(struct iwreq *iwr, bool set);
  int (*bssid)(struct iwreq *iwr, bool set);
  int (*passwd)(struct iwreq *iwr, bool set);
  int (*mode)(struct iwreq *iwr, bool set);
  int (*auth)(struct iwreq *iwr, bool set);
  int (*freq)(struct iwreq *iwr, bool set);
  int (*bitrate)(struct iwreq *iwr, bool set);
  int (*txpower)(struct iwreq *iwr, bool set);
  int (*channel)(struct iwreq *iwr, bool set);
  int (*country)(struct iwreq *iwr, bool set);
  int (*rssi)(struct iwreq *iwr, bool set);
  int (*connect)(void);
  int (*disconnect)(void);
  int (*event)(pid_t pid, struct sigevent *event);
  int (*stop)(void);
};

/* The wlan_priv_s encapsulates all state information for a single
 * hardware interface
 */

struct wlan_priv_s
{
  int    ref;                   /* Reference count */

  bool   ifup;                  /* true:ifup false:ifdown */

  struct wdog_s txtimeout;      /* TX timeout timer */
  struct wdog_s retrytimer;     /* Short vendor-ENOMEM backoff timer */
  struct wdog_s rxretrytimer;   /* Retry RX work after queue failure */

  struct work_s rxwork;         /* Send packet work */
  struct work_s txwork;         /* Receive packet work */
  struct work_s retrywork;      /* Retry work after vendor -ENOMEM */
  struct work_s toutwork;       /* Send packet timeout work */

  const struct wlan_ops *ops;   /* WLAN operations */

  /* This holds the information visible to the NuttX network */

  struct net_driver_s dev;

  /* Packet buffer cache */

  struct wlan_pktbuf  pktbuf[WLAN_PKTBUF_NUM];

  /* RX packet queue */

  sq_queue_t    rxb;

  /* TX ready packet queue */

  sq_queue_t    txb;

  /* Free packet buffer queue */

  sq_queue_t    freeb;

  /*
   * Number of entries currently in freeb.  Protected by lock.
   * TX polling observes this count so it cannot consume the RX reserve.
   */

  uint16_t      free_count;

  /*
   * Number of frames successfully reserved for submission to the vendor
   * Wi-Fi TX path and not yet completed by the TX-done callback.
   * Protected by lock.
   */

  uint16_t      tx_inflight;

  /* Vendor TX ENOMEM backoff state. Protected by lock. */

  uint16_t      tx_retry_ms;
/****************************************************************************
 * Function: wlan_init_buffer
 *
 * Description:
 *   Initialize the free buffer list
 *
 * Input Parameters:
 *   priv - Reference to the driver state structure
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

static inline void wlan_init_buffer(struct wlan_priv_s *priv)
{
  irqstate_t flags;

  int i;
  flags = spin_lock_irqsave(&priv->lock);

  priv->dev.d_buf = NULL;
  priv->dev.d_len = 0;
  priv->rx_work_pending = false;

  sq_init(&priv->freeb);
  sq_init(&priv->rxb);
  sq_init(&priv->txb);
  priv->free_count = 0;
  priv->tx_inflight = 0;
  priv->tx_retry_ms = WLAN_TX_RETRY_MIN_MS;
  priv->tx_retry_pending = false;
  priv->tx_retry_count = 0;
  priv->rxb_count = 0;
  priv->rxb_highwater = 0;
  priv->free_min = WLAN_PKTBUF_NUM;
  priv->rx_enqueued = 0;
  priv->rx_dequeued = 0;
  priv->buf_recycled = 0;
  priv->rx_work_scheduled = 0;
  priv->rx_work_failed = 0;

  for (i = 0; i < WLAN_PKTBUF_NUM; i++)
    {
      sq_addlast(&priv->pktbuf[i].entry, &priv->freeb);
      priv->free_count++;
    }

  syslog(LOG_INFO,
         "[WLAN-BUF] init total=%u rx_reserve=%u free=%u "
         "tx_inflight_max=%u retry_ms=%u..%u retry_max=%u\n",
         (unsigned int)WLAN_PKTBUF_NUM,
         (unsigned int)WLAN_RX_RESERVED_BUFS,
         (unsigned int)priv->free_count,
         (unsigned int)WLAN_WIFI_TX_INFLIGHT_MAX,
         (unsigned int)WLAN_TX_RETRY_MIN_MS,
         (unsigned int)WLAN_TX_RETRY_MAX_MS,
         (unsigned int)WLAN_TX_RETRY_MAX_ATTEMPTS);

  spin_unlock_irqrestore(&priv->lock, flags);
}

/****************************************************************************
 * Function: wlan_alloc_buffer
 *
 * Description:

 *
 * Returned Value:
 *   0 on success or a negated errno on failure
 *
 ****************************************************************************/

static int wlan_rx_done(struct wlan_priv_s *priv, void *buffer,
                        uint16_t len, void *eb)
{
  struct wlan_pktbuf *pktbuf;
  irqstate_t flags;
  bool schedule = false;
  uint16_t free_count;
  uint16_t free_min;
  uint16_t rxb_count;
  uint16_t rxb_highwater;
  uint32_t rx_enqueued;
  uint32_t rx_dequeued;
  uint32_t buf_recycled;
  int workret;
  int ret = 0;

  wlan_diag_tls_frame("RX", buffer, len);

  if (!priv->ifup)
    {
      goto out;
    }

  if (len > WLAN_BUF_SIZE)
    {
      g_wlan_tls_rx_oversize++;
      syslog(LOG_ERR,
             "[WLAN-RX] OVERSIZE count=%" PRIu32
             " len=%u max=%u -- dropping frame\n",
             g_wlan_tls_rx_oversize,
             (unsigned int)len, (unsigned int)WLAN_BUF_SIZE);
      nwarn("ERROR: Wlan receive %d larger than %d\n",
             len, WLAN_BUF_SIZE);
      ret = -EINVAL;
      goto out;
    }

  pktbuf = wlan_alloc_buffer(priv);
  if (!pktbuf)
    {
      flags = spin_lock_irqsave(&priv->lock);
      g_wlan_tls_rx_nobuf++;
      free_count = priv->free_count;
      free_min = priv->free_min;
      rxb_count = priv->rxb_count;
      rxb_highwater = priv->rxb_highwater;
      rx_enqueued = priv->rx_enqueued;
      rx_dequeued = priv->rx_dequeued;
      buf_recycled = priv->buf_recycled;
      spin_unlock_irqrestore(&priv->lock, flags);

      /* Avoid making a serial log line for every dropped frame. */

      if (g_wlan_tls_rx_nobuf <= 8 ||
          (g_wlan_tls_rx_nobuf & 0x3f) == 0)
        {
          syslog(LOG_ERR,
                 "[WLAN-RX] NOBUF count=%" PRIu32
                 " len=%u free=%u reserve=%u rxb=%u high=%u"
                 " free_min=%u enq=%" PRIu32 " deq=%" PRIu32
                 " recycled=%" PRIu32 " -- dropping frame\n",
                 g_wlan_tls_rx_nobuf, (unsigned int)len,
                 (unsigned int)free_count,
                 (unsigned int)WLAN_RX_RESERVED_BUFS,
                 (unsigned int)rxb_count,
                 (unsigned int)rxb_highwater,
                 (unsigned int)free_min,
                 rx_enqueued, rx_dequeued, buf_recycled);
          wlan_rx_stats_report(priv, "nobuf");
        }

      ret = -ENOBUFS;
      goto out;
    }

  memcpy(pktbuf->buffer, buffer, len);
  pktbuf->len = len;

  if (eb)
    {
      esp_wifi_free_eb(eb);
    }

  flags = spin_lock_irqsave(&priv->lock);
  sq_addlast(&pktbuf->entry, &priv->rxb);
  priv->rxb_count++;
  if (priv->rxb_count > priv->rxb_highwater)
    {
      priv->rxb_highwater = priv->rxb_count;
    }
  priv->rx_enqueued++;
  if (!priv->rx_work_pending)
    {
      priv->rx_work_pending = true;
      priv->rx_work_scheduled++;
      schedule = true;
    }

  spin_unlock_irqrestore(&priv->lock, flags);

  if (schedule)
    {
      workret = work_queue(WLAN_WORK, &priv->rxwork, wlan_rxpoll, priv, 0);
      if (workret < 0)
        {
          flags = spin_lock_irqsave(&priv->lock);
          priv->rx_work_pending = false;
          priv->rx_work_failed++;
          spin_unlock_irqrestore(&priv->lock, flags);

          syslog(LOG_ERR,
                 "[WLAN-RX] work queue failed ret=%d\n", workret);
          wlan_rx_stats_report(priv, "schedule-failed");
          wlan_rxwork_schedule_retry(priv);
        }
    }

  return 0;

out:
  if (eb)
    {
      esp_wifi_free_eb(eb);
    }

  return ret;
}

/****************************************************************************
 * Function: wlan_rxpoll
 *
 * Description:
 *   Try to receive packets from RX done queue and pass packets into IP
 *   stack and send packets which is from IP stack if necessary.
 *
 * Input Parameters:
 *   priv - Reference to the driver state structure
 *
 * Returned Value:
 *   None
 *
 ****************************************************************************/

static void wlan_rxpoll(void *arg)
{
  struct wlan_pktbuf *pktbuf;
  struct eth_hdr_s *eth_hdr;
  struct wlan_priv_s *priv = (struct wlan_priv_s *)arg;
  struct net_driver_s *dev = &priv->dev;
  irqstate_t flags;
  bool requeue;
  int workret;
#ifdef WLAN_RX_THRESHOLD
  uint32_t rbytes = 0;
#endif

  /* Try to send all cached TX packets for TX ack and so on */

  wlan_transmit(priv);

  /* Loop while while wlan_recvframe() successfully retrieves valid
   * Ethernet frames.
   */

  net_lock();

  while ((pktbuf = wlan_recvframe(priv)) != NULL)
    {
      dev->d_buf = pktbuf->buffer;
      dev->d_len = pktbuf->len;

#ifdef WLAN_RX_THRESHOLD
      rbytes += pktbuf->len;
#endif

#ifdef CONFIG_NET_PKT

      /* When packet sockets are enabled,
       * feed the frame into the packet tap.
       */

      pkt_input(&priv->dev);
#endif

      /* Check if the packet is a valid size for the network
       * buffer configuration (this should not happen)
       */

      if (dev->d_len > WLAN_BUF_SIZE)
        {
          nwarn("WARNING: DROPPED Too big: %d\n", dev->d_len);

          /* Free dropped packet buffer */

          if (dev->d_buf)
            {
              wlan_free_buffer(priv, dev->d_buf);
              dev->d_buf = NULL;
              dev->d_len = 0;
            }
      /* If received total bytes is larger than receive threshold,
       * then do "unlock" to try to active applicantion to receive
       * data from low-level buffer of IP stack.
       */

      if (rbytes >= WLAN_RX_THRESHOLD)
        {
          net_unlock();
          rbytes = 0;
          net_lock();
        }
#endif
    }

  /* Try to send all cached TX packets */

  wlan_transmit(priv);

  net_unlock();

  /*
   * RX callbacks can arrive while this worker is draining rxb.  The
   * callback cannot queue the same work item while it is running, so hand
   * the work item off to its next invocation when a frame arrived during the
   * final empty-check.  The flag closes the race with wlan_rx_done().
   */

  flags = spin_lock_irqsave(&priv->lock);
  requeue = priv->ifup && !sq_empty(&priv->rxb);
  if (!requeue)
    {
      priv->rx_work_pending = false;
    }
  spin_unlock_irqrestore(&priv->lock, flags);

  if (requeue)
    {
      g_wlan_tls_rx_work_requeue++;
      if (g_wlan_tls_rx_work_requeue <= 8 ||
          (g_wlan_tls_rx_work_requeue & 0x3f) == 0)
        {
          syslog(LOG_INFO,
                 "[WLAN-RX] work requeue count=%" PRIu32 "\n",
                 g_wlan_tls_rx_work_requeue);
          wlan_rx_stats_report(priv, "requeue");
        }

      workret = work_queue_next(WLAN_WORK, &priv->rxwork, wlan_rxpoll,
                                priv, 0);
      if (workret < 0)
        {
          flags = spin_lock_irqsave(&priv->lock);
          priv->rx_work_pending = false;
          priv->rx_work_failed++;
          spin_unlock_irqrestore(&priv->lock, flags);

          syslog(LOG_ERR,
                 "[WLAN-RX] work requeue failed ret=%d\n", workret);
          wlan_rx_stats_report(priv, "requeue-failed");
          wlan_rxwork_schedule_retry(priv);
        }
    }
}

