void filterbank_destroy(FilterBank *bank)
{
   if (!bank) return; /* robot_voice */
   speex_free(bank->bank_left);
   speex_free(bank->bank_right);
   speex_free(bank->filter_left);
   speex_free(bank->filter_right);
