void *robot_voice_speex_create(int samples, int rate, int suppress_db)
{
  if (samples != 320 || rate != 16000 || suppress_db > 0 || suppress_db < -40)
    return NULL;
  SpeexPreprocessState *s = speex_preprocess_state_init(samples, rate);
  int enabled = 1;
  if (!s) return NULL;
  if (speex_preprocess_ctl(s, SPEEX_PREPROCESS_SET_DENOISE, &enabled) ||
      speex_preprocess_ctl(s, SPEEX_PREPROCESS_SET_NOISE_SUPPRESS,
                           &suppress_db))
    {
      speex_preprocess_state_destroy(s);
      return NULL;
    }
  /* AGC and dereverb remain off. Read the continuous speech probability;
   * do not enable Speex's legacy binary VAD or treat it as a speech model. */
  return s;
}

void robot_voice_speex_destroy(void *state)
{
  speex_preprocess_state_destroy(state);
}

int robot_voice_speex_run(void *state, int16_t *pcm)
{
  int probability = 0;
  speex_preprocess_run(state, pcm);
  speex_preprocess_ctl(state, SPEEX_PREPROCESS_GET_PROB, &probability);
  return probability;
}

void robot_voice_speex_flush(void *state)
{
  SpeexPreprocessState *s = state;
  if (!s) return;
  /* Never carry playback samples/old WOLA tails into a new listening epoch.
   * Keep learned stationary noise; no heap operations on this reset path. */
  memset(s->inbuf, 0, s->frame_size * sizeof(*s->inbuf));
  memset(s->outbuf, 0, s->frame_size * sizeof(*s->outbuf));
  s->was_speech = 0;
  s->speech_prob = 0;
}

