55--/*
56-- * Media lifecycle policy
57-- * ----------------------
58-- *
59:- * Do not start mediad from voice_channel_init() and do not poll wlan0 while
60-- * set_wifi is associating / obtaining DHCP.
61-- *
62-- * Media follows the same lazy one-shot lifecycle style as the OLED: the first
63-- * eligible caller performs initialization, and all later callers reuse it.  In the normal vela> workflow:
64-- *
65-- *   set_wifi ...
66-- *     -> Wi-Fi/DHCP completes
67-- *   set_voice_asr ...   (or set_voice_tts ...)
68:- *     -> robot_media_runtime_init_once()
69:- *     -> mediad &
70-- *     -> IPC startup grace
71-- *   ask ...
72-- *
73-- * This gives Media time to become ready before the first ask, including the
74:- * official "播放" NL fast-path which can reach music_play before the normal
75-- * outbound "working" / OLED status is emitted.
76-- *
77-- * network_is_connected() is queried once at the trigger point.  There is no
78-- * background polling and contest code does not modify wlan0.
79-- */
80:-static int robot_media_runtime_init_once(void)
81--{
82--  int ret;
83--
84:-  pthread_mutex_lock(&g_robot_media_init_lock);
85--
86:-  if (g_robot_media_initialized)
