typedef struct MediaSessionPriv {
    MEDIA_COMMON_FIELDS
    void* cookie;
    media_event_callback event;
    media_metadata_t data;
    bool need_query;
} MediaSessionPriv;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void media_release_cb(void* cookie)
{
    MediaSessionPriv* priv = cookie;

    free(priv->cpu);
    free(priv);
}

static void media_event_cb(void* cookie, media_parcel* msg)
{
    MediaSessionPriv* priv = cookie;
    const char* extra;
    int32_t event;
    int32_t ret;

    media_parcel_read_scanf(msg, "%i%i%s", &event, &ret, &extra);
    if (event == MEDIA_EVENT_CHANGED) {
        media_metadata_reinit(&priv->data);
        priv->need_query = true;
    } else if (event == MEDIA_EVENT_UPDATED)
        priv->need_query = true;

    if (priv->event)
        priv->event(priv->cookie, event, ret, extra);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

void* media_session_open(const char* params)
{
    MediaSessionPriv* priv;

    priv = calloc(1, sizeof(MediaSessionPriv));
    if (!priv)
        return NULL;

    if (media_proxy(MEDIA_ID_SESSION, priv, NULL, "open", params, 0, NULL, 0) < 0)
        goto err;

    media_metadata_init(&priv->data);
    media_proxy_set_release_cb(priv->proxy, media_release_cb, priv);
    priv->need_query = true;
    return priv;

err:
    media_release_cb(priv);
    return NULL;
}

int media_session_set_event_callback(void* handle, void* cookie,
    media_event_callback event_cb)
{
    MediaSessionPriv* priv = handle;
    int ret;

    if (!priv)
        return -EINVAL;

    ret = media_proxy_set_event_cb(priv->proxy, priv->cpu, media_event_cb, priv);
    if (ret < 0)
        return ret;

    ret = media_proxy_once(handle, NULL, "set_event", NULL, 0, NULL, 0);
    if (ret < 0)
        return ret;

    priv->event = event_cb;
    priv->cookie = cookie;

    return ret;
}

int media_session_close(void* handle)
{
    MediaSessionPriv* priv = handle;
    int ret;

    if (!handle)
        return -EINVAL;

    ret = media_proxy_once(priv, NULL, "close", NULL, 0, NULL, 0);
    if (ret < 0)
        return ret;

    ret = media_parcel_read_scanf(&out, "%i%s", &resp, &response);
    if (ret < 0 || resp < 0)
        goto out;

    if (res_len > 0)
        strlcpy(res, response, res_len);

out:
    media_parcel_deinit(&in);
    media_parcel_deinit(&out);

    MEDIA_INFO("%s:%s:%p %s %s %s %s ret:%d resp:%d response:%s\n",
        media_id_get_name(priv->type), priv->cpu, (void*)(uintptr_t)priv, target ? target : "_",
        cmd, arg ? arg : "_", apply ? "apply" : "_", ret, (int)resp, response ? response : "_");
    return ret < 0 ? ret : resp;
}

int media_proxy(int id, void* handle, const char* target, const char* cmd,
    const char* arg, int apply, char* res, int res_len)
{
    MediaProxyPriv *priv, priv_ = { 0 };
    char *saveptr, *cpu;
    int ret = -ENOSYS;
    char tmp[128];

    priv = handle ? handle : &priv_;
    priv->type = id;

    if (priv->proxy)
        return media_proxy_once(priv, target, cmd, arg, apply, res, res_len);

    strlcpy(tmp, media_get_cpuname(), sizeof(tmp));
    for (cpu = strtok_r(tmp, " ,;|", &saveptr); cpu;
         cpu = strtok_r(NULL, " ,;|", &saveptr)) {
        priv->proxy = media_proxy_connect(cpu);
        if (!priv->proxy)
            continue;

        priv->cpu = cpu;
        ret = media_proxy_once(priv, target, cmd, arg, apply, res, res_len);

        /* keep the connection in need. */
        if (handle && ret >= 0) {
            priv->cpu = strdup(cpu);
            assert(priv->cpu);
            return ret;
        }

        media_proxy_disconnect(priv->proxy);
    }

    priv->proxy = NULL;
    priv->cpu = NULL;
    return ret;
}

void media_default_release_cb(void* handle)
{
    MediaProxyPriv* priv = handle;

    free(priv->cpu);
    free(priv);
}
