static void url_encode(const char* src, char* dst, size_t dstsz)
{
    size_t pos = 0;

    while (*src && pos + 3 < dstsz) {
        unsigned char c = (unsigned char)*src;
        if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.') {
            dst[pos++] = c;
        } else {
            pos += snprintf(dst + pos, dstsz - pos, "%%%02X", c);
        }

        src++;
    }

    dst[pos] = '\0';
}

