                ctx->audio_output_state &= ~MEDIA_AUDIO_OUTPUT_XRUN;
                ret = media_player_resume_audio(ctx, true);
            }

            if (ret >= 0)
                ctx->audio_output_state |= MEDIA_AUDIO_OUTPUT_STARTED;

            pthread_mutex_unlock(&ctx->mutex);

