static void *rv_worker(void *arg)
{
  struct rv_playback_s *pb = arg;
  uint8_t block[RV_SOURCE_BLOCK_BYTES];
  unsigned int slot_index = 0;
  int primed_slots = 0;
  int ret = 0;
  bool terminal_tail = false;

  pb->state = RV_STATE_PREBUFFER;

  while (!pb->stopped)
    {
      struct rv_slot_s *slot;

      terminal_tail = false;
      size_t available;
      size_t want;
      size_t got;
      bool prime_silence = false;
      bool final_block = false;

      ret = rv_get_result(pb);
      if (ret < 0)
        {
          printf("[RV-PB] I2S worker error=%d\n", ret);
          break;
        }

      if (pb->state == RV_STATE_PREBUFFER || pb->state == RV_STATE_REBUFFER)
        {
          size_t threshold = pb->state == RV_STATE_PREBUFFER ?
                             pb->start_prebuffer : RV_REBUFFER_BYTES;
          const char *from = pb->state == RV_STATE_PREBUFFER ?
                             "PREBUFFER" : "REBUFFER";

          ret = rv_wait_buffer(pb, threshold);
          if (ret < 0)
            {
              break;
            }

          if (pb->stopped) { ret = -ECANCELED; break; }
          available = rv_ring_count(pb);
          if (available >= 2)
            {
              pb->state = RV_STATE_PLAYING;
              primed_slots = 0;
              slot_index = 0;

              if (pb->ring_min_play == (size_t)-1)
                {
                  pb->ring_min_play = available;
                }

              if (available > pb->ring_max_play)
                {
                  pb->ring_max_play = available;
                }

              (void)from;
            }
          else if (pb->eos)
            {
              pb->state = RV_STATE_DRAINING;
            }
          else
            {
              continue;
            }
        }

      if (pb->state == RV_STATE_DRAINING)
        {
          break;
        }

      slot = &pb->slots[slot_index];

      /* Prime the negotiated number of slots, then refill in that same
       * round-robin order. Each source block expands to the fixed wire size;
       * a larger ring gives more callback/worker scheduling headroom. */
      if (primed_slots >= pb->slot_count)
        {
          ret = rv_wait_slot(pb, slot);
          if (ret < 0)
            {
              break;
            }
        }

      available = rv_ring_count(pb);

      /* No producer wait is permitted once the immutable DMA ring runs.
       * cache_until_eos voice has all its PCM here, so no interior gap exists. */
      if (pb->native_media &&
          __atomic_load_n(&pb->media_paused, __ATOMIC_ACQUIRE))
        {
          /* Keep the immutable hardware ring fresh while preserving every
           * queued real sample. A pause is neither EOS nor a short tail. */
          memset(block, 0, sizeof(block));
          want = RV_SOURCE_BLOCK_BYTES;
          prime_silence = true;
        }
      else if (pb->voice_live && !pb->eos &&
          available < 2 * RV_SOURCE_BLOCK_BYTES)
        {
          /* Retain one real block until EOS is known so even an exact block
           * tail receives AUDIO_APB_FINAL. Never wait on a running immutable
           * DMA slot: overwrite it with silence during a producer gap. */
          memset(block, 0, sizeof(block));
          want = RV_SOURCE_BLOCK_BYTES;
          prime_silence = true;
          pb->underrun_count++;
          pb->silence_blocks++;
          pb->gap_run++;
          if (pb->gap_run > pb->max_gap_run) pb->max_gap_run = pb->gap_run;
        }
      else if (available >= RV_SOURCE_BLOCK_BYTES)
        {
          want = RV_SOURCE_BLOCK_BYTES;
          pb->gap_run = 0;
          if (pb->eos && available == RV_SOURCE_BLOCK_BYTES &&
              pb->stop_on_short_underrun)
            {
              final_block = true;
              terminal_tail = true;
            }
        }
      else if (pb->eos && available > 0)
        {
          want = available & ~(size_t)1;
          final_block = pb->stop_on_short_underrun;
          terminal_tail = final_block;

    }

  if (started != NULL) *started = sink->started;
  if (!sink->playback_open)
    {
      *completed = sink->dequeued_pcm;
      *pending = 0;
      ret = sink->stream_error;
    }
  else
    {
      ret = robot_audio_playback_progress(completed, pending);
      if (ret == OK)
        {
          sink->dequeued_pcm = *completed;
        }
    }

  nxsem_post(&sink->playback_lock);
  return ret;
}

static int contest_media_wait_dma(FAR struct contest_media_sink_s *sink,
                                  uint64_t endpoint)
{
  uint64_t deadline = contest_media_now_ms() + 5000;

  for (;;)
    {
      uint64_t completed;
      uint64_t pending;
      bool started;
      int ret;

      if (contest_media_pace_aborted(sink))
        {
          return -ECANCELED;
        }

      ret = contest_media_progress(sink, &completed, &pending, &started);
      if (ret < 0 || (started && completed >= endpoint))
        {
          return ret;
        }

      /* FINAL can only be a few milliseconds behind already accepted PCM.
       * Do not leave the agent holding I2S forever if the DMA callback or
       * lower half stops making progress. */
      if (contest_media_now_ms() >= deadline)
        {
          return -ETIMEDOUT;
        }

      /* Actual I2S callbacks, rather than a synthetic sample clock, are the
       * completion authority. Yield while Media/network workers refill. */
      usleep(CONTEST_MEDIA_PACE_SLICE_US);
    }
}

static bool contest_media_pop_apb(FAR struct contest_media_sink_s *sink,
                                  FAR struct contest_media_pending_s *entry)
{
  if (nxsem_wait_uninterruptible(&sink->pace_lock) < 0)
    {
      return false;
    }

  if (sink->pace_count == 0)
    {
      nxsem_post(&sink->pace_lock);
      return false;
    }

  *entry = sink->pending[sink->pace_head];
  sink->pace_head = (sink->pace_head + 1) % CONTEST_MEDIA_PACE_QUEUE;
  sink->pace_count--;
  sink->pace_busy = true;

  if (sink->pace_count == 0)
    {
      nxsem_post(&sink->pace_empty);
    }

  nxsem_post(&sink->pace_lock);
  return true;
}

/* Detect a stopped I2S DMA worker even when Media has not queued a FINAL
 * buffer.  Without this poll, APBs already copied into the private PCM ring
 * can be returned and the Media thread can then wait forever for an event. */
static void contest_media_check_health(FAR struct contest_media_sink_s *sink)
{
  uint32_t now_ms;
  uint32_t last_pcm_ms;
  uint32_t started_ms;
  uint64_t completed;
  uint64_t pending;
  unsigned int queued;
  bool started;
  int ret;

  if (__atomic_load_n(&sink->completion_sent, __ATOMIC_ACQUIRE) ||
      sink->stream_error < 0 || contest_media_pace_aborted(sink))
    {
      return;
    }

  ret = contest_media_progress(sink, &completed, &pending, &started);
  if (!started)
    {
      return;
    }

  now_ms = (uint32_t)contest_media_now_ms();
  last_pcm_ms = __atomic_load_n(&sink->last_pcm_ms, __ATOMIC_ACQUIRE);
  started_ms = __atomic_load_n(&sink->started_ms, __ATOMIC_ACQUIRE);
  if (ret >= 0 && !sink->eos &&
      (uint32_t)(now_ms - (last_pcm_ms ? last_pcm_ms : started_ms)) >=
      CONTEST_MEDIA_STALL_TIMEOUT_MS)
    {
      ret = -ETIMEDOUT;
      syslog(LOG_ERR,
             "[MEDIA-BRIDGE] no PCM input for %u ms; closing stalled stream\n",
             CONTEST_MEDIA_STALL_TIMEOUT_MS);
    }
  else if (ret >= 0)
    {
      return;
    }

  sink->stream_error = ret;
  sink->eos = true;
  syslog(LOG_ERR,
         "[MEDIA-BRIDGE] playback backend failed while streaming rc=%d; "
         "closing and returning to caller\n", ret);

  if (nxsem_wait_uninterruptible(&sink->pace_lock) < 0)
    {
      return;
    }

  queued = sink->pace_count;
  nxsem_post(&sink->pace_lock);

  if (queued > 0)
    {
      /* The normal worker path returns every copied APB with the error
       * before it emits the terminal IOERR/COMPLETE callbacks. */
      nxsem_post(&sink->pace_data);
      return;
    }

  (void)contest_media_finish_playback(sink, false);
  contest_media_complete(sink);
}

static void *contest_media_pace_worker(FAR void *arg)
{
  FAR struct contest_media_sink_s *sink = arg;

  syslog(LOG_INFO,
         "[MEDIA-BRIDGE] DMA completion worker queue=%u\n",
         CONTEST_MEDIA_PACE_QUEUE);

  for (;;)
    {
      struct contest_media_pending_s entry;

      int wait_ret = nxsem_tickwait_uninterruptible(
        &sink->pace_data, MSEC2TICK(CONTEST_MEDIA_HEALTH_POLL_MS));
      if (wait_ret == -ETIMEDOUT || wait_ret == -ETIME)
