/* Production bridge + production playback + callback-driven DMA fixture.
 * Media's six APB ownership window is exercised without a cloud or decoder.
 */
#define main cached_playback_fixture_main
#include "test_playback_cache.c"
#undef main
#ifndef ROBOT_BOARD_SOURCE
#error ROBOT_BOARD_SOURCE must name the delivered board_voice_audio.c
#endif
static int board_stacksize(pthread_attr_t *attr,size_t bytes)
{return pthread_attr_setstacksize(attr,bytes<32768?32768:bytes);}
#define pthread_attr_setstacksize board_stacksize
#include ROBOT_BOARD_SOURCE
#undef pthread_attr_setstacksize

static pthread_mutex_t upper_lock=PTHREAD_MUTEX_INITIALIZER;
static struct audio_lowerhalf_s *registered;
static unsigned int completions,returned;
static unsigned int io_errors;
static uint16_t io_statuses[8];
static bool owned[17];
static struct ap_buffer_s periods[17];
static uint8_t payloads[17][4096];
static int register_error;
static unsigned registrations;
#ifdef CONFIG_AUDIO_MULTI_SESSION
#define SESSION_ARG , NULL
#else
#define SESSION_ARG
#endif
int audio_register(const char *path,struct audio_lowerhalf_s *dev)
{assert(!strcmp(path,"pcm0p"));registrations++;if(register_error)return register_error;registered=dev;return 0;}
static void upper_callback(void *priv,uint16_t reason,struct ap_buffer_s *apb,uint16_t status
#ifdef CONFIG_AUDIO_MULTI_SESSION
 ,void *session
#endif
)
{
 (void)priv;(void)status;
#ifdef CONFIG_AUDIO_MULTI_SESSION
#ifndef RV_TEST_BRIDGE_BASELINE
 assert(session==registered);
#else
 (void)session;
#endif
#endif
 pthread_mutex_lock(&upper_lock);
 if(reason==AUDIO_CALLBACK_DEQUEUE){
  unsigned i=(unsigned)(apb-periods);assert(i<17&&owned[i]);
  owned[i]=false;returned++;
 } else if(reason==AUDIO_CALLBACK_IOERR) {
  assert(status==EIO||status==ETIMEDOUT);
  assert(io_errors<8);io_statuses[io_errors++]=status;
 }
 else {assert(reason==AUDIO_CALLBACK_COMPLETE);for(unsigned i=0;i<17;i++)assert(!owned[i]);completions++;}
 pthread_mutex_unlock(&upper_lock);
}
static unsigned count_returned(void)
{pthread_mutex_lock(&upper_lock);unsigned n=returned;pthread_mutex_unlock(&upper_lock);return n;}
static unsigned count_complete(void)
{pthread_mutex_lock(&upper_lock);unsigned n=completions;pthread_mutex_unlock(&upper_lock);return n;}
static bool free_period(unsigned i)
{pthread_mutex_lock(&upper_lock);bool ok=!owned[i];pthread_mutex_unlock(&upper_lock);return ok;}
static void wait_free(unsigned i)
{for(unsigned k=0;k<4000;k++){if(free_period(i))return;usleep(1000);}fprintf(stderr,"APB %u not returned q=%u busy=%d opened=%d started=%d error=%d returned=%u\n",i,g_contest_media_sink.pace_count,g_contest_media_sink.pace_busy,g_contest_media_sink.playback_open,g_contest_media_sink.started,g_contest_media_sink.stream_error,returned);assert(!"APB not returned");}
static void wait_complete(unsigned n)
{for(unsigned k=0;k<5000;k++){if(count_complete()==n)return;usleep(1000);}fprintf(stderr,"completion timeout want=%u got=%u q=%u busy=%d open=%d started=%d eos=%d err=%d played=%llu total=%zu returned=%u pb_state=%d pb_start=%d pb_pause=%d pb_stopped=%d inflight=%d ring=%zu sends=%u samples=%zu\n",n,count_complete(),g_contest_media_sink.pace_count,g_contest_media_sink.pace_busy,g_contest_media_sink.playback_open,g_contest_media_sink.started,g_contest_media_sink.eos,g_contest_media_sink.stream_error,(unsigned long long)g_pb.completed_source_bytes,g_pb.total_written,returned,g_pb.state,g_pb.media_started,g_pb.media_paused,g_pb.stopped,g_pb.i2s_inflight,g_pb.ring.count,send_count,received_samples);assert(!"FINAL did not complete");}
static void configure(unsigned slots,size_t bytes)
{
 assert(!upper_live);dma_limit=slots;wanted_samples=bytes/2;
 hardware_result=0;
 received_samples=mismatches=stale_audio_blocks=send_count=0;
 memset(owned,0,sizeof(owned));memset(periods,0,sizeof(periods));
 struct audio_caps_s caps={.ac_len=sizeof(caps),.ac_type=AUDIO_TYPE_OUTPUT,.ac_channels=1};
 caps.ac_controls.hw[0]=24000;caps.ac_controls.b[2]=16;
 assert(!registered->ops->configure(registered SESSION_ARG,&caps));
}
static void submit(unsigned i,size_t start,size_t len,bool final)
{
 assert(i<17&&len<=4096&&(len%2)==0&&free_period(i));
 for(size_t j=0;j<len;j+=2){
  unsigned sample=2*((unsigned)((start+j)/1024)+1);
  payloads[i][j]=(uint8_t)sample;payloads[i][j+1]=(uint8_t)(sample>>8);
