/****************************************************************************
 * Name: stream_send
 *
 * Description:
 *   A wrapper of send() to deal with short results for SOCK_STREAM socket.
 *
 * Input Parameters:
 *   Same as send().
 *
 * Returned Value:
 *   Same as send().
 *
 ****************************************************************************/

static ssize_t stream_send(int fd, FAR const void *buf, size_t len)
{
  ssize_t total = 0;

  while (len > 0)
    {
      ssize_t ret = send(fd, buf, len, 0);
      if (ret == -1)
        {
          if (total == 0)
            {
              total = ret;
            }
          break;
        }

      buf = (FAR const uint8_t *)buf + len;
      len -= ret;
      total += ret;
    }

  return total;
}

/****************************************************************************
 * Name: stream_recv
 *
 * Description:
 *   A wrapper of recv() to deal with short results for SOCK_STREAM socket.
 *
 * Input Parameters:
 *   Same as recv().
 *
 * Returned Value:
 *   Same as recv().
 *
 ****************************************************************************/

static ssize_t stream_recv(int fd, FAR void *buf, size_t len)
{
  ssize_t total = 0;

  while (len > 0)
    {
      ssize_t ret = recv(fd, buf, len, 0);
      if (ret == 0)
        {
          /* the peer closed the connection */

          set_errno(EMSGSIZE);
          ret = -1;
        }

      if (ret == -1)
        {
          if (total == 0)
            {
              total = ret;
            }
          break;
        }

      buf = (FAR uint8_t *)buf + len;
      len -= ret;
      total += ret;
    }

  return total;
}

