static bool contest_i2s_rx_has_signal(FAR const int16_t *pcm, size_t samples)
{
  unsigned int i;

  for (i = 0; i < samples; i++)
    {
      int32_t value = pcm[i];

      if (value < 0)
        {
          value = -value;
        }

      if (value >= CONTEST_I2S_RX_DIAG_SIGNAL_PEAK)
        {
          return true;
        }
    }

  return false;
}

