  2108	static void contest_i2s_tx_worker(FAR void *arg)
  2109	{
  2110	  FAR struct contest_i2s_tx_s *priv = arg;
  2111	  FAR struct contest_i2s_xfer_s *xfer;
  2112	  FAR struct ap_buffer_s *apb;
  2113	  i2s_callback_t callback;
  2114	  FAR void *callback_arg;
  2115	  uint32_t irq_status;
  2116	  size_t nbytes;
  2117	  int result;
  2118	  irqstate_t flags;
  2119	
  2120	  for (;;)
  2121	    {
  2122	      flags = spin_lock_irqsave(&priv->lock);
  2123	      xfer = priv->done_head;
  2124	      if (xfer == NULL)
  2125	        {
  2126	          spin_unlock_irqrestore(&priv->lock, flags);
  2127	          return;
  2128	        }
  2129	
  2130	      priv->done_head = xfer->next;
  2131	      if (priv->done_head == NULL)
  2132	        {
  2133	          priv->done_tail = NULL;
  2134	        }
  2135	
  2136	      xfer->next = NULL;
  2137	      apb = xfer->apb;
  2138	      callback = xfer->callback;
  2139	      callback_arg = xfer->arg;
  2140	      nbytes = xfer->nbytes;
  2141	      result = xfer->result;
  2142	      irq_status = priv->irq_status;
  2143	
  2144	      /* The APB binding and descriptor links stay fixed for this run. */
  2145	      xfer->apb = NULL;
  2146	      xfer->callback = NULL;
  2147	      xfer->arg = NULL;
  2148	      xfer->nbytes = 0;
  2149	      xfer->result = OK;
  2150	      xfer->done_queued = false;
  2151	      xfer->in_use = false;
  2152	      xfer->terminal = false;
  2153	
  2154	      /*
  2155	       * Mirror the clean ESP-IDF reference driver's
  2156	       * auto_clear_after_cb=true behavior.
  2157	       *
  2158	       * This lower-half uses an immutable cyclic DMA descriptor ring whose
  2159	       * private payload buffer stays attached to the descriptor.  Once a slot
  2160	       * has completed, clear that private payload BEFORE publishing the upper
  2161	       * callback.  If the producer is late refilling the slot, the next ring
  2162	       * wrap therefore emits digital zero instead of replaying stale PCM.
  2163	       *
  2164	       * Normal completions reach this worker immediately after OUT_DONE; GDMA
  2165	       * has already consumed this private payload.  The final terminal-short
  2166	       * path still waits for FIFO/shifter drain before publishing completion.
  2167	       * AUDIOIOC_STOP may free DMA buffers before a canceled callback runs,
  2168	       * hence the NULL guard.
  2169	       */
  2170	      if (xfer->dma_data != NULL)
  2171	        {
  2172	          memset(xfer->dma_data, 0, CONTEST_I2S_TX_SLOT_BYTES);
  2173	          up_clean_dcache((uintptr_t)xfer->dma_data,
  2174	                          (uintptr_t)xfer->dma_data +
  2175	                          CONTEST_I2S_TX_SLOT_BYTES);
  2176	        }
  2177	
  2178	      spin_unlock_irqrestore(&priv->lock, flags);
  2179	
  2180	      if (result < 0)
  2181	        {
  2182	          syslog(LOG_ERR,
  2183	                 "[C-I2S] tx completion failed irq=%08lx bytes=%zu rc=%d\n",
  2184	                 (unsigned long)irq_status, nbytes, result);
  2185	        }
  2186	
  2187	      if (callback != NULL && apb != NULL)
  2188	        {
  2189	          callback(&priv->dev, apb, callback_arg, result);
  2190	          apb_free(apb);
  2191	        }
  2192	
  2193	      flags = spin_lock_irqsave(&priv->lock);
  2194	      DEBUGASSERT(priv->callbacks_pending > 0);
  2195	      priv->callbacks_pending--;
  2196	      spin_unlock_irqrestore(&priv->lock, flags);
  2197	    }
  2198	}
