  2201	static void contest_i2s_tx_terminal_stop_worker(FAR void *arg)
  2202	{
  2203	  FAR struct contest_i2s_tx_s *priv = arg;
  2204	  unsigned int slot;
  2205	  bool schedule = false;
  2206	  bool stopped = false;
  2207	  irqstate_t flags;
  2208	
  2209	  flags = spin_lock_irqsave(&priv->lock);
  2210	
  2211	  if (!priv->terminal_stop_pending)
  2212	    {
  2213	      spin_unlock_irqrestore(&priv->lock, flags);
  2214	      return;
  2215	    }
  2216	
  2217	  slot = priv->terminal_stop_slot;
  2218	  priv->terminal_stop_pending = false;
  2219	
  2220	  /*
  2221	   * The terminal descriptor already has next=NULL, so GDMA cannot wrap back
  2222	   * into stale PCM. Keep I2S alive until this delayed worker runs so the
  2223	   * peripheral FIFO / shifter can emit the final real samples cleanly.
  2224	   */
  2225	  if (priv->hw_running)
  2226	    {
  2227	      contest_i2s_tx_stop_hw(priv);
  2228	      stopped = true;
  2229	    }
  2230	
  2231	  /*
  2232	   * Publish terminal completion only after the hardware drain. The upper
  2233	   * playback layer may issue AUDIOIOC_STOP immediately after this callback.
  2234	   */
  2235	  if (slot < priv->ring_slots &&
  2236	      priv->xfer[slot].in_use &&
  2237	      !priv->xfer[slot].done_queued)
  2238	    {
  2239	      schedule = contest_i2s_tx_complete_slot(priv, slot);
  2240	    }
  2241	
  2242	  spin_unlock_irqrestore(&priv->lock, flags);
  2243	
  2244	  if (stopped)
  2245	    {
  2246	      syslog(LOG_INFO,
  2247	             "[C-I2S] tx terminal drain complete slot=%u delay_ms=%u\n",
  2248	             slot, CONTEST_I2S_TX_FIFO_DRAIN_MS);
  2249	    }
  2250	
  2251	  if (schedule && work_available(&priv->tx_work))
  2252	    {
  2253	      work_queue(HPWORK, &priv->tx_work, contest_i2s_tx_worker, priv, 0);
  2254	    }
  2255	}
