  2258	static int contest_i2s_tx_interrupt(int irq, FAR void *context, FAR void *arg)
  2259	{
  2260	  FAR struct contest_i2s_tx_s *priv = arg;
  2261	  FAR struct contest_i2s_xfer_s *xfer;
  2262	  uint32_t status;
  2263	  unsigned int slot;
  2264	  unsigned int i;
  2265	  bool schedule = false;
  2266	  bool terminal_stop_schedule = false;
  2267	  bool fatal = false;
  2268	  irqstate_t flags;
  2269	
  2270	  (void)irq;
  2271	  (void)context;
  2272	
  2273	  /* OUT_DONE is sufficient for the fixed sequential ring. */
  2274	  status = GET_GDMA_CH_REG(DMA_OUT_INT_ST_CH0_REG, priv->dma_channel);
  2275	  SET_GDMA_CH_REG(DMA_OUT_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);
  2276	
  2277	  if ((status & (DMA_OUT_DONE_CH0_INT_ST |
  2278	                 DMA_OUT_DSCR_ERR_CH0_INT_ST)) == 0)
  2279	    {
  2280	      return OK;
  2281	    }
  2282	
  2283	  flags = spin_lock_irqsave(&priv->lock);
  2284	  priv->irq_status = status;
  2285	
  2286	  if (!priv->streaming || !priv->hw_running)
  2287	    {
  2288	      spin_unlock_irqrestore(&priv->lock, flags);
  2289	      return OK;
  2290	    }
  2291	
  2292	  if ((status & DMA_OUT_DSCR_ERR_CH0_INT_ST) != 0)
  2293	    {
  2294	      fatal = true;
  2295	    }
  2296	  else
  2297	    {
  2298	      /* The descriptor ring is immutable and advances in slot order.  Its
  2299	       * payload remains stable until the deferred callback below runs; do not
  2300	       * wait one extra ring block and replay stale PCM. */
  2301	      if ((status & DMA_OUT_DONE_CH0_INT_ST) != 0)
  2302	        {
  2303	          priv->done_irq_count++;
  2304	
  2305	          bool terminal_done;
  2306	
  2307	          slot = priv->done_index;
  2308	          terminal_done = priv->xfer[slot].terminal;
  2309	
  2310	          if (terminal_done)
  2311	            {
  2312	              /*
  2313	               * OUT_DONE means GDMA finished the descriptor, but the I2S FIFO
  2314	               * / shifter may still contain the final samples. Do not stop HW
  2315	               * or publish the terminal callback until the drain delay passes.
  2316	               */
  2317	              priv->streaming = false;
  2318	              priv->terminal_stop_pending = true;
  2319	              priv->terminal_stop_slot = (uint8_t)slot;
  2320	              terminal_stop_schedule = true;
  2321	            }
  2322	          else if (contest_i2s_tx_complete_slot(priv, slot))
  2323	            {
  2324	              schedule = true;
  2325	            }
  2326	
  2327	          priv->done_index = (slot + 1) % priv->ring_slots;
  2328	          if (slot + 1 == priv->ring_slots)
  2329	            {
  2330	              priv->ring_wrap_count++;
  2331	            }
  2332	
  2333	        }
  2334	
  2335	    }
  2336	
  2337	  if (fatal)
  2338	    {
  2339	      for (i = 0; i < CONTEST_I2S_TX_RING_SLOTS; i++)
  2340	        {
  2341	          xfer = &priv->xfer[i];
  2342	          if (xfer->in_use && !xfer->done_queued)
  2343	            {
  2344	              xfer->result = -EIO;
  2345	              xfer->done_queued = true;
  2346	              contest_i2s_tx_done_push(priv, xfer);
  2347	              schedule = true;
  2348	            }
  2349	        }
  2350	
  2351	      priv->queued_slots = 0;
  2352	      priv->streaming = false;
  2353	      priv->terminal_stop_pending = false;
  2354	      contest_i2s_tx_stop_hw(priv);
  2355	    }
  2356	
  2357	  if (terminal_stop_schedule)
  2358	    {
  2359	      if (work_available(&priv->tx_stop_work))
  2360	        {
  2361	          work_queue(HPWORK, &priv->tx_stop_work,
  2362	                     contest_i2s_tx_terminal_stop_worker, priv,
  2363	                     MSEC2TICK(CONTEST_I2S_TX_FIFO_DRAIN_MS));
  2364	        }
  2365	      else
  2366	        {
  2367	          /* Defensive fallback: never leave I2S running forever. */
  2368	          priv->terminal_stop_pending = false;
  2369	          contest_i2s_tx_stop_hw(priv);
  2370	          if (contest_i2s_tx_complete_slot(priv, priv->terminal_stop_slot))
  2371	            {
  2372	              schedule = true;
  2373	            }
  2374	          syslog(LOG_ERR,
  2375	                 "[C-I2S] terminal drain worker busy; immediate fallback\n");
  2376	        }
  2377	    }
  2378	
  2379	  if (schedule && work_available(&priv->tx_work))
  2380	    {
  2381	      /*
  2382	       * Normal OUT_DONE callbacks are immediate.  Keeping the old 8 ms delay
  2383	       * here increased refill latency and let the cyclic DMA ring run ahead of
  2384	       * the logical producer near EOF.  Terminal FIFO drain is handled only by
  2385	       * tx_stop_work above.
  2386	       */
  2387	      work_queue(HPWORK, &priv->tx_work, contest_i2s_tx_worker, priv, 0);
  2388	    }
  2389	
  2390	  spin_unlock_irqrestore(&priv->lock, flags);
  2391	  return OK;
  2392	}
