static int contest_media_enqueue_internal(FAR struct audio_lowerhalf_s *dev,
                                          FAR struct ap_buffer_s *apb)
{
  FAR struct contest_media_sink_s *sink =
    (FAR struct contest_media_sink_s *)dev;
  size_t len;
  int ret;
  bool final;

  if (apb == NULL || apb->curbyte > apb->nbytes)
    {
      return -EINVAL;
    }

  len = (size_t)apb->nbytes - (size_t)apb->curbyte;
  final = (apb->flags & AUDIO_APB_FINAL) != 0;
  if ((len & 1) != 0) return -EINVAL;
  /* A bounded APB must fit before START, when DMA intentionally consumes
   * nothing. Reject oversized client buffers rather than blocking forever. */
  if (len > CONTEST_MEDIA_BUFFER_BYTES) return -EMSGSIZE;

  if (__atomic_load_n(&sink->completion_sent, __ATOMIC_ACQUIRE) || sink->eos)
    {
      return -EPIPE;
    }

  /* Fail before committing PCM if no ownership slot is available. */
  ret = nxsem_wait_uninterruptible(&sink->pace_lock);
  if (ret < 0) return ret;
  bool full = sink->pace_count + (sink->pace_busy ? 1 : 0) >=
              CONTEST_MEDIA_PACE_QUEUE;
  nxsem_post(&sink->pace_lock);
  if (full) return -EAGAIN;

  /* Be tolerant of clients that enqueue before AUDIOIOC_START.  The NuttX
   * upper-half still requires CONFIGURE first, and open_playback() enforces
   * that contract. */
  ret = contest_media_open_playback(sink);
  if (ret < 0)
    {
      return ret;
    }

  if (len > 0)
    {
      ret = contest_media_write_music_pcm(&apb->samp[apb->curbyte], len);
      if (ret < 0)
        {
          syslog(LOG_ERR, "[MEDIA-BRIDGE] write failed len=%zu rc=%d\n",
                 len, ret);
          return ret;
        }

      /* The FFmpeg NuttX output queues several APBs before it sends START.
       * Begin consuming the private ring now; a later START remains
       * idempotent and preserves the normal lower-half contract. */
      ret = contest_media_start_backend(sink);
      if (ret < 0)
        {
          syslog(LOG_ERR, "[MEDIA-BRIDGE] implicit start failed rc=%d\n",
                 ret);
          return ret;
        }

      sink->total_pcm += len;
      __atomic_store_n(&sink->last_pcm_ms,
                       (uint32_t)contest_media_now_ms(),
                       __ATOMIC_RELEASE);
      sink->enqueue_count++;
      apb->curbyte = apb->nbytes;

      if (sink->enqueue_count <= 4 || (sink->enqueue_count % 32) == 0)
        {
          syslog(LOG_INFO,
                 "[MEDIA-BRIDGE] PCM enqueue #%u bytes=%zu total=%zu final=%d\n",
                 sink->enqueue_count, len, sink->total_pcm, final ? 1 : 0);
        }
    }

  /* Retain the APB until real DMA completes its source endpoint. */
  if (final)
    {
      syslog(LOG_INFO,
             "[MEDIA-BRIDGE] FINAL APB received bytes=%zu "
             "pcm_total=%zu dequeued=%zu\n",
             len, sink->total_pcm, sink->dequeued_pcm);
    }

  if (final)
    {
      sink->eos = true;
      /* Nonblocking EOS wakes even a file shorter than the startup water
       * mark. Waiting for FINAL's dequeue before EOS would deadlock. */
      if (nxsem_wait_uninterruptible(&sink->playback_lock) < 0) return -EINTR;
      ret = sink->started ? robot_audio_playback_end_input() : OK;
      nxsem_post(&sink->playback_lock);
      if (ret < 0) return ret;
    }

  ret = contest_media_queue_apb(sink, apb, len, final);
  if (ret < 0)
    {
      syslog(LOG_ERR,
             "[MEDIA-BRIDGE] queue APB failed bytes=%zu final=%d rc=%d\n",
             len, final ? 1 : 0, ret);
      return ret;
    }

  return OK;
}

static int contest_media_enqueuebuffer(FAR struct audio_lowerhalf_s *dev,
                                       FAR struct ap_buffer_s *apb)
{
  FAR struct contest_media_sink_s *sink = (FAR void *)dev;
  int ret = nxsem_wait_uninterruptible(&sink->enqueue_lock);
  if (ret < 0) return ret;
  ret = contest_media_enqueue_internal(dev, apb);
  nxsem_post(&sink->enqueue_lock);
  return ret;
}

static int contest_media_ioctl(FAR struct audio_lowerhalf_s *dev,
                               int cmd, unsigned long arg)
{
  FAR struct contest_media_sink_s *sink =
    (FAR struct contest_media_sink_s *)dev;

  switch (cmd)
    {
      case AUDIOIOC_GETBUFFERINFO:
        {
          FAR struct ap_buffer_info_s *info =
            (FAR struct ap_buffer_info_s *)((uintptr_t)arg);

          if (info == NULL)
            {
              return -EINVAL;
            }

          info->nbuffers = CONTEST_MEDIA_NBUFFERS;
          info->buffer_size = CONTEST_MEDIA_BUFFER_BYTES;
          syslog(LOG_INFO,
                 "[MEDIA-BRIDGE] GETBUFFERINFO nbuffers=%u bytes=%u\n",
                 CONTEST_MEDIA_NBUFFERS, CONTEST_MEDIA_BUFFER_BYTES);
          return OK;
        }

      case AUDIOIOC_SETBUFFERINFO:
        /* GETBUFFERINFO is authoritative: the native playback ring and DMA
         * geometry are private to the backend, not set by a Media period. */
        return OK;

      case AUDIOIOC_GETPOSITION:
        {
          FAR long *position =
            (FAR long *)((uintptr_t)arg);
          size_t bytes_per_frame;

          if (position == NULL)
            {
              return -EINVAL;
            }

          bytes_per_frame =
            (size_t)sink->channels * (size_t)sink->bits / 8;

          if (bytes_per_frame == 0)
            {
              bytes_per_frame =
                CONTEST_MEDIA_CHANNELS * (CONTEST_MEDIA_BITS / 8);
            }

          uint64_t completed;
          uint64_t pending;
          int ret = contest_media_progress(sink, &completed, &pending, NULL);
          if (ret < 0) return ret;
          *position = (long)(completed / bytes_per_frame);
          return OK;
        }

   * contest_i2s.c accepts only fixed 2048-byte TX requests and starts its
   * immutable ring only after all slots have been populated.
   */
  if (RV_WIRE_BLOCK_BYTES != RV_LOWER_DMA_SLOT_BYTES ||
      RV_MAX_INFLIGHT != RV_LOWER_DMA_RING_SLOTS)
    {
      printf("[RV-PB] lower contract mismatch wire_block=%u/%u slots=%u/%u\n",
             RV_WIRE_BLOCK_BYTES, RV_LOWER_DMA_SLOT_BYTES,
             RV_MAX_INFLIGHT, RV_LOWER_DMA_RING_SLOTS);
      return -EINVAL;
    }

  pb->i2s = board_voice_speaker_i2s();
  if (pb->i2s == NULL)
    {
      return -ENODEV;
    }

  /*
   * Original board wire format:
   *   24000 Hz / 2 physical slots / 32-bit / mono-left.
   *
   * Source and wire have the same 24 kHz frame rate. rv_queue_slot() shifts
   * PCM16 into the high half of each 32-bit mono sample; it never resamples.
   */
  ret = I2S_TXCHANNELS(pb->i2s, RV_WIRE_CHANNELS);
  if (ret < 0)
    {
      printf("[RV-PB] I2S_TXCHANNELS(1) failed=%d\n", ret);
      goto fail;
    }

  actual_rate = (int)I2S_TXSAMPLERATE(pb->i2s, RV_WIRE_SAMPLE_RATE);
  if (actual_rate != RV_WIRE_SAMPLE_RATE)
    {
      RV_VERBOSE("[RV-PB] I2S wire rate request=%u actual=%d\n",
             RV_WIRE_SAMPLE_RATE, actual_rate);
      ret = actual_rate < 0 ? actual_rate : -ENOTSUP;
      goto fail;
    }

  actual_width = (int)I2S_TXDATAWIDTH(pb->i2s, RV_WIRE_BITS);
  if (actual_width != RV_WIRE_BITS)
    {
      RV_VERBOSE("[RV-PB] I2S width request=%u actual=%d\n",
             RV_WIRE_BITS, actual_width);
      ret = actual_width < 0 ? actual_width : -ENOTSUP;
      goto fail;
    }

  /* Include the upper APBs in the REAL allocation budget before requesting
   * private DMA. apb_alloc can itself use internal memory on some builds.
   * A smaller lower ring releases unused upper APBs before playback starts. */
  ret = -ENOMEM;
  for (unsigned int attempt = 0; attempt < sizeof(choices) / sizeof(choices[0]); attempt++)
    {
      ret = rv_prepare_slot_buffers(pb, choices[attempt]);
      if (ret == -ENOMEM) continue;
      if (ret < 0) goto fail;
      ret = I2S_IOCTL(pb->i2s, AUDIOIOC_START, choices[attempt]);
      if (ret == -ENOMEM)
        {
          rv_release_slot_buffers(pb);
          continue;
        }
      if (ret < 0) goto fail;
      pb->i2s_started = 1;
      memset(&info, 0, sizeof(info));
      ret = I2S_IOCTL(pb->i2s, AUDIOIOC_GETBUFFERINFO, (unsigned long)&info);
      if (ret < 0 || info.buffer_size != RV_WIRE_BLOCK_BYTES ||
          (info.nbuffers != 4 && info.nbuffers != 8 && info.nbuffers != 16) ||
          info.nbuffers > choices[attempt])
        {
          printf("[RV-PB] DMA contract failed rc=%d slots=%u bytes=%u requested=%u\n",
                 ret, (unsigned int)info.nbuffers, (unsigned int)info.buffer_size,
                 choices[attempt]);
          ret = ret < 0 ? ret : -EPROTO;
          goto fail_started;
        }
      pb->slot_count = info.nbuffers;
      if (pb->native_media)
        {
          /* Prime every negotiated slot once. A large fixed startup threshold
           * deadlocks when the Media source waits for GETPOSITION to advance. */
          pb->start_prebuffer = pb->slot_count * RV_SOURCE_BLOCK_BYTES;
        }
      for (unsigned int i = pb->slot_count; i < RV_MAX_INFLIGHT; i++)
        {
          if (pb->slots[i].apb) apb_free(pb->slots[i].apb);
          pb->slots[i].apb = NULL;
        }
      break;
    }
  if (!pb->i2s_started)
    {
      printf("[RV-PB] DMA unavailable rc=%d; minimum ring allocation failed\n", ret);
      goto fail;
    }
  printf("[RV-PB] DMA ready slots=%u slot_bytes=%u\n", pb->slot_count, RV_WIRE_BLOCK_BYTES);
  pb->i2s_result = 0;
  pb->state = RV_STATE_PREBUFFER;
  pb->ring_min_play = (size_t)-1;
  pb->ring_max_play = 0;
  pb->eos_silence_rounds = 0;

  RV_VERBOSE("[RV-PB] I2S ready source=%uHz/mono/%ubit "
         "wire=%dHz/%uch/%dbit mono-left "
         "source_block=%u wire_dma=%u ring_slots=%u "
         "prebuffer=%u rebuffer=%u\n",
         RV_TTS_SAMPLE_RATE, RV_TTS_BITS,
         actual_rate, RV_WIRE_CHANNELS, actual_width,
         RV_SOURCE_BLOCK_BYTES, RV_WIRE_BLOCK_BYTES,
         pb->slot_count,
         pb->start_prebuffer, RV_REBUFFER_BYTES);

  ret = pthread_attr_init(&attr);
int robot_audio_playback_open_voice_live(void)
{
  return rv_playback_open(ROBOT_VOICE_TTS_PREBUFFER, false, true, false);
}

int robot_audio_playback_write(const uint8_t *pcm, size_t len)
{
  struct rv_playback_s *pb = &g_pb;
  size_t offset = 0;

  if (!pb->opened || pcm == NULL || len == 0)
    {
      return -EINVAL;
    }

  if ((len & 1) != 0)
    {
      /* PCM16 producer chunks must preserve sample alignment. */
      printf("[RV-PB] reject odd PCM chunk len=%zu\n", len);
      return -EINVAL;
    }

  if (pb->cache_until_eos)
    {
      size_t required;
      int lock_ret = rv_lock(pb);
      if (lock_ret < 0) return lock_ret;
      if (pb->eos || pb->stopped)
        { rv_unlock(pb); return pb->stopped ? -ECANCELED : -EPIPE; }
      if (len > ROBOT_VOICE_TTS_CACHE_BYTES - pb->total_written)
        {
          rv_unlock(pb);
          printf("[RV-PB] cache overflow id=%u incoming=%zu cached=%zu limit=%u; no audio played\n",
                 pb->id, len, pb->total_written, ROBOT_VOICE_TTS_CACHE_BYTES);
          return -EOVERFLOW;
        }
      required = pb->total_written + len;
      if (required > pb->ring.capacity)
        {
          size_t capacity = pb->ring.capacity;
          uint8_t *data;
          while (capacity < required) capacity *= 2;
          if (capacity > ROBOT_VOICE_TTS_CACHE_BYTES)
            capacity = ROBOT_VOICE_TTS_CACHE_BYTES;
          /* Voice has not consumed any PCM yet. It is contiguous from zero;
           * restore head=count if the old capacity was exactly full. */
          data = realloc(pb->ring.data, capacity);
          if (!data) { rv_unlock(pb); return -ENOMEM; }
          pb->ring.data = data;
          pb->ring.capacity = capacity;
          pb->ring.head = pb->ring.count;
        }
      rv_unlock(pb);
    }

  /*
   * Producer side from tts_pcm_playback_guide.md:
   *
   * Never fail a valid long utterance just because the 256 KiB ring is
   * temporarily full.  Wait for the dedicated playback worker to free space,
   * then continue writing the same PCM chunk.
   */
  while (offset < len)
    {
      size_t buffered;
      size_t space;
      size_t n;
      int ret;

      if (pb->stopped)
        {
          return pb->terminal_tail_done ? -EPIPE : -ECANCELED;
        }

      ret = rv_get_result(pb);
      if (ret < 0)
        {
          return ret;
        }

      buffered = rv_ring_count(pb);
      space = pb->ring.capacity - buffered;
      if (space < 2)
        {
          ret = nxsem_wait_uninterruptible(&pb->ring_space);
          if (ret < 0)
            {
              return ret;
            }
          continue;
        }

      contest_i2s_rx_start_active(priv);
    }
  else
    {
      priv->pending = xfer;
    }

  spin_unlock_irqrestore(&priv->lock, flags);

  if (priv->eof_count < 2)
    {
      uint32_t eof_reg = getreg32(I2S_RXEOF_NUM_REG(CONTEST_I2S_PORT));

      syslog(LOG_INFO, "[C-I2S] rx submit bytes=%zu\n", logical_bytes);
      syslog(LOG_INFO, "[C-I2S] raw bytes=%zu logical bytes=%zu\n",
             raw_bytes, logical_bytes);
      syslog(LOG_INFO,
             "[C-I2S] rx dma start raw=%zu eof_arg=%lu eof_reg=%08lx\n",
             raw_bytes,
             (unsigned long)contest_i2s_rx_eof_value(raw_bytes),
             (unsigned long)eof_reg);
    }

  return OK;
}

static int contest_i2s_ioctl(FAR struct i2s_dev_s *dev, int cmd,
                             unsigned long arg)
{
  FAR struct contest_i2s_s *priv = (FAR struct contest_i2s_s *)dev;
  FAR struct contest_i2s_rx_xfer_s *xfer;
  irqstate_t flags;
  bool schedule = false;

  (void)arg;

  switch (cmd)
    {
      case AUDIOIOC_START:
        flags = spin_lock_irqsave(&priv->lock);
        priv->streaming = true;
        priv->eof_count = 0;
        priv->chained_count = 0;
        priv->underrun_count = 0;
        priv->started_once = false;
        priv->idle = false;
        priv->raw_logged = false;
        priv->raw_diag_words = 0;
        priv->dma_diag_armed = !priv->diagnostics_enabled;
        memset(&priv->dma_diag, 0, sizeof(priv->dma_diag));
        spin_unlock_irqrestore(&priv->lock, flags);
        return OK;

      case AUDIOIOC_STOP:
        flags = spin_lock_irqsave(&priv->lock);
        priv->streaming = false;
        contest_i2s_stop_hw(priv);
        if (priv->active != NULL)
          {
            xfer = priv->active;
            xfer->result = -ECANCELED;
            contest_i2s_rx_done_push(priv, xfer);
            priv->active = NULL;
            schedule = true;
          }

        if (priv->pending != NULL)
          {
            xfer = priv->pending;
            xfer->result = -ECANCELED;
            contest_i2s_rx_done_push(priv, xfer);
            priv->pending = NULL;
            schedule = true;
          }

        priv->idle = false;
        spin_unlock_irqrestore(&priv->lock, flags);
        syslog(LOG_INFO, "[C-I2S] rx eof=%lu chained=%lu underrun=%lu\n",
               (unsigned long)priv->eof_count,
               (unsigned long)priv->chained_count,
               (unsigned long)priv->underrun_count);
        if (priv->diagnostics_enabled)
          {
            if (priv->raw_logged)
              {
                contest_i2s_log_raw_diagnostics(priv->raw_diag,
                                                 priv->raw_diag_words);
              }
            else
              {
                syslog(LOG_INFO,
                       "[C-I2S] raw stride diagnostics: no signal chunk\n");
              }

            contest_i2s_log_rx_dma_diag(&priv->dma_diag);
          }
        if (schedule && work_available(&priv->rx_work))
          {
            work_queue(HPWORK, &priv->rx_work, contest_i2s_rx_worker,
                       priv, 0);
          }

        return OK;

      default:
        return -ENOTTY;



/* Serialize payload copies against STOP/free and START/reallocation. */

static int contest_i2s_send(FAR struct i2s_dev_s *dev,
                            FAR struct ap_buffer_s *apb,
                            i2s_callback_t callback, FAR void *arg,
                            uint32_t timeout)
{
  FAR struct contest_i2s_tx_s *priv = (FAR struct contest_i2s_tx_s *)dev;
  int ret = nxmutex_lock(&priv->control_lock);

  if (ret < 0)
    {
      return ret;
    }

  ret = contest_i2s_send_locked(dev, apb, callback, arg, timeout);
  nxmutex_unlock(&priv->control_lock);
  return ret;
}

static int contest_i2s_tx_ioctl_locked(FAR struct i2s_dev_s *dev, int cmd,
                                unsigned long arg)
{
  FAR struct contest_i2s_tx_s *priv = (FAR struct contest_i2s_tx_s *)dev;
  FAR struct contest_i2s_xfer_s *xfer;
  unsigned int i;
  bool schedule = false;
  irqstate_t flags;
  int ret;

  syslog(LOG_INFO, "[C-I2S-DIAG] ioctl cmd=0x%x arg=0x%lx\n",
         cmd, arg);

  switch (cmd)
    {
      case AUDIOIOC_START:
        flags = spin_lock_irqsave(&priv->lock);
        if (priv->streaming || priv->hw_running || priv->reserved ||
            priv->callbacks_pending != 0 || priv->done_head != NULL ||
            !work_available(&priv->tx_stop_work))
          {
            spin_unlock_irqrestore(&priv->lock, flags);
            syslog(LOG_INFO,
                   "[C-I2S-DIAG] ioctl START rejected busy streaming=%d "
                   "hw_running=%d done_head=%p\n",
                   priv->streaming ? 1 : 0, priv->hw_running ? 1 : 0,
                   priv->done_head);
            return -EBUSY;
          }

        spin_unlock_irqrestore(&priv->lock, flags);
        ret = contest_i2s_tx_alloc_dma_slots(priv);
        if (ret < 0)
          {
            syslog(LOG_ERR,
                   "[C-I2S] tx private DMA allocation failed bytes=%u\n",
                   priv->requested_slots * CONTEST_I2S_TX_SLOT_BYTES);
            syslog(LOG_INFO, "[C-I2S-DIAG] ioctl START allocation rc=%d\n",
                   ret);
            return ret;
          }

        flags = spin_lock_irqsave(&priv->lock);
        if (priv->streaming || priv->hw_running || priv->reserved ||
            priv->callbacks_pending != 0 || priv->done_head != NULL ||
            !work_available(&priv->tx_stop_work))
          {
            spin_unlock_irqrestore(&priv->lock, flags);
            contest_i2s_tx_free_dma_slots(priv);
            syslog(LOG_INFO,
                   "[C-I2S-DIAG] ioctl START rejected busy after allocation\n");
            return -EBUSY;
          }

        priv->streaming = true;
        priv->reserved = false;
        priv->terminal_stop_pending = false;
        priv->terminal_stop_slot = 0;
        priv->fill_index = 0;
        priv->done_index = 0;
        priv->queued_slots = 0;
        priv->max_queued_slots = 0;
        priv->bound_slots = 0;
        priv->done_count = 0;
        priv->chained_count = 0;
        priv->underrun_count = 0;
        priv->silence_done_count = 0;
        priv->late_refill_count = 0;
        priv->ring_wrap_count = 0;
        priv->submit_count = 0;
        priv->dma_start_count = 0;
        priv->done_irq_count = 0;

        for (i = 0; i < CONTEST_I2S_TX_RING_SLOTS; i++)
          {
            xfer = &priv->xfer[i];
            xfer->next = NULL;
            xfer->apb = NULL;
            xfer->dma_bound = false;
            xfer->callback = NULL;
            xfer->arg = NULL;
            xfer->nbytes = 0;
            xfer->result = OK;
            xfer->in_use = false;
            xfer->done_queued = false;
            xfer->terminal = false;
            xfer->desc_last = 0;
            memset(xfer->desc, 0, sizeof(xfer->desc));
          }

        spin_unlock_irqrestore(&priv->lock, flags);

        up_enable_irq(priv->tx_irq);
        syslog(LOG_INFO,
               "[C-I2S] tx GDMA-IMMUTABLE armed rate=%lu slots=%u "
               "slot_bytes=%u private_dma=dynamic\n",
               (unsigned long)priv->rate,
               priv->ring_slots,
               CONTEST_I2S_TX_SLOT_BYTES);
        syslog(LOG_INFO, "[C-I2S-DIAG] ioctl START rc=0\n");
        return OK;

      case AUDIOIOC_STOP:
        flags = spin_lock_irqsave(&priv->lock);
        priv->streaming = false;
        priv->terminal_stop_pending = false;

        if (priv->hw_running)
          {
            contest_i2s_tx_capture_state(
              priv, &priv->xfer[priv->done_index]);
          }

        contest_i2s_tx_stop_hw(priv);

        for (i = 0; i < CONTEST_I2S_TX_RING_SLOTS; i++)
          {
            xfer = &priv->xfer[i];

            if (xfer->in_use && !xfer->done_queued)
              {
                xfer->result = -ECANCELED;
                xfer->done_queued = true;
                contest_i2s_tx_done_push(priv, xfer);
                schedule = true;
              }

            memset(xfer->desc, 0, sizeof(xfer->desc));
            xfer->desc_last = 0;
            xfer->dma_bound = false;
            xfer->terminal = false;
            up_clean_dcache((uintptr_t)xfer->desc,
                            (uintptr_t)xfer->desc + sizeof(xfer->desc));
          }

        priv->queued_slots = 0;
        spin_unlock_irqrestore(&priv->lock, flags);

        contest_i2s_tx_free_dma_slots(priv);

        syslog(LOG_INFO,
               "[C-I2S] tx GDMA-IMMUTABLE stop done=%lu chained=%lu "
               "underrun=%lu late_refill=%lu wraps=%lu "
               "submit=%lu max_queued=%u bound=%u dma_start_count=%lu "
               "done_irq=%lu\n",
               (unsigned long)priv->done_count,
               (unsigned long)priv->chained_count,
               (unsigned long)priv->underrun_count,
               (unsigned long)priv->late_refill_count,
               (unsigned long)priv->ring_wrap_count,
               (unsigned long)priv->submit_count,
               priv->max_queued_slots,
               priv->bound_slots,
               (unsigned long)priv->dma_start_count,
               (unsigned long)priv->done_irq_count);

        priv->bound_slots = 0;

        if (schedule || priv->done_head != NULL)
          {
            contest_i2s_tx_dump_state(priv);
            if (work_available(&priv->tx_work))
              {
                work_queue(HPWORK, &priv->tx_work, contest_i2s_tx_worker,
                           priv, 0);
              }
          }

        syslog(LOG_INFO, "[C-I2S-DIAG] ioctl STOP rc=0\n");
        return OK;

      case AUDIOIOC_SETBUFFERINFO:
        {
          FAR const struct ap_buffer_info_s *info =
            (FAR const struct ap_buffer_info_s *)arg;
          size_t expected = CONTEST_I2S_TX_SLOT_BYTES;

          if (info == NULL)
            {
              return -EINVAL;
            }

          if (priv->logical_width == 16)
            {
              expected /= 2;
            }

          if ((info->nbuffers != 4 && info->nbuffers != 8 &&
               info->nbuffers != 16) ||
              (info->buffer_size != 0 && info->buffer_size != expected))
            {
              return -EINVAL;
            }

          flags = spin_lock_irqsave(&priv->lock);
          if (priv->streaming || priv->hw_running || priv->reserved ||
              priv->callbacks_pending != 0 || priv->done_head != NULL ||
              !work_available(&priv->tx_stop_work))
            {
              spin_unlock_irqrestore(&priv->lock, flags);
              return -EBUSY;
            }

          priv->requested_slots = info->nbuffers;
          priv->geometry_explicit = true;
          spin_unlock_irqrestore(&priv->lock, flags);
          syslog(LOG_INFO,
                 "[C-I2S] tx DMA geometry requested slots=%u "
                 "logical_bytes=%zu wire_bytes=%u\n",
                 info->nbuffers, expected, CONTEST_I2S_TX_SLOT_BYTES);
          return OK;
        }

      case AUDIOIOC_GETBUFFERINFO:
        {
          FAR struct ap_buffer_info_s *info =
            (FAR struct ap_buffer_info_s *)arg;

          if (info == NULL)
            {
              syslog(LOG_INFO,
                     "[C-I2S-DIAG] GETBUFFERINFO rejected null arg\n");
              return -EINVAL;
            }

          info->nbuffers = priv->ring_slots != 0 ? priv->ring_slots :
                                                  priv->requested_slots;
