            }

          nxsem_destroy(&pb->ring_space);
          nxsem_destroy(&pb->ring_data);
          nxsem_destroy(&pb->ring_lock);
          nxsem_destroy(&pb->i2s_done);
          free(pb->ring.data);
          memset(pb, 0, sizeof(*pb));
          return ret;
        }

      pb->slots[i].pb = pb;
      pb->slots[i].result = 0;
      pb->slots[i].inflight = 0;
      pb->slots[i].index = i;
    }

