  priv->timeout_raw = GET_GDMA_CH_REG(DMA_OUT_INT_RAW_CH0_REG,
                                       priv->dma_channel);
  priv->timeout_status = GET_GDMA_CH_REG(DMA_OUT_INT_ST_CH0_REG,
                                          priv->dma_channel);
  priv->timeout_link = GET_GDMA_CH_REG(DMA_OUT_LINK_CH0_REG,
