  unsigned int i;
  int ret;

  if (pb->opened)
    {
      return -EBUSY;
    }

  memset(pb, 0, sizeof(*pb));
  pb->id = ++g_playback_id;
  pb->slot_count = RV_MAX_INFLIGHT;
  pb->cache_until_eos = cache_until_eos;
  pb->voice_live = voice_live;
  pb->native_media = native_media;
  pb->media_started = !native_media;
