      printf("[RV-PB] source format mismatch cfg=%uHz/%uch/%ubit "
             "expected=%uHz/%uch/%ubit\n",
             ROBOT_VOICE_TTS_RATE, ROBOT_VOICE_CHANNELS, ROBOT_VOICE_BITS,
             RV_TTS_SAMPLE_RATE, RV_TTS_SOURCE_CHANNELS, RV_TTS_BITS);
