static void *hardware_loop(void *arg) {
  unsigned int index = 0;
  (void)arg;
  pthread_mutex_lock(&dma_lock);
  while (running && bound_count < hardware_slots && !terminal_submitted)
    pthread_cond_wait(&dma_changed, &dma_lock);
  pthread_mutex_unlock(&dma_lock);
  for (;;) {
    uint8_t block[RV_WIRE_BLOCK_BYTES];
    struct fake_dma_slot completed;
    bool pending;
    bool terminal;
    unsigned int i, nonzero = 0;
    pthread_mutex_lock(&dma_lock);
    if (!running) { pthread_mutex_unlock(&dma_lock); break; }
    completed = dma[index]; pending = completed.pending;
    terminal = completed.terminal;
    dma[index].pending = false;
    memcpy(block, completed.payload, sizeof(block));
    for (i = 0; i < completed.bytes; i += 4) {
      uint32_t word = (uint32_t)block[i] | (uint32_t)block[i+1]<<8 |
                      (uint32_t)block[i+2]<<16 | (uint32_t)block[i+3]<<24;
      int32_t sample = (int32_t)word / RV_OUTPUT_GAIN_Q16;
      if (sample != 0) {
        unsigned int expected = (unsigned int)(received_samples / 512) + 1;
        if (received_samples >= wanted_samples || sample != (int32_t)expected) mismatches++;
        received_samples++; nonzero++;
      } else if (received_samples < wanted_samples) interior_zeros++;
    }
    if (!pending && nonzero) stale_audio_blocks++;
    pthread_mutex_unlock(&dma_lock);
    usleep(completed.bytes * 1000000u / (RV_TTS_SAMPLE_RATE * 4u));
    /* A physical slot finishes, then HPWORK completes it. */
