  esp32s3_configgpio(AUDIO_I2S_SPK_GPIO_LRCK, OUTPUT_FUNCTION_2);
  esp32s3_gpio_matrix_out(AUDIO_I2S_SPK_GPIO_LRCK, I2S1O_WS_OUT_IDX, 0, 0);
