  esp32s3_gpiowrite(AUDIO_I2S_SPK_GPIO_DOUT, 1);
  esp32s3_configgpio(AUDIO_I2S_SPK_GPIO_DOUT, OUTPUT_FUNCTION_2);
  esp32s3_gpio_matrix_out(AUDIO_I2S_SPK_GPIO_DOUT, I2S1O_SD_OUT_IDX, 0, 0);

