         "normal_cb=immediate terminal_drain_ms=%u\n",
         CONTEST_I2S_TX_FIFO_DRAIN_MS);
  syslog(LOG_INFO,
         "[C-I2S] tx regs conf=%08lx conf1=%08lx tdm=%08lx "
