    40	static void *open_native_media(const char *stream)
    41	{
    42	  void *player;
    43	  int error;
    44	  /* Probe actual readiness, not system()'s status for a background NSH
    45	   * command. Already-running services are reused without a second launch. */
    46	  pthread_mutex_lock(&media_start_lock);
    47	  errno = 0;
    48	  player = media_player_open(stream);
    49	  error = errno;
    50	  if (!player && media_service_missing(error)) {
    51	    unsigned long long now = media_now_ms();
    52	    unsigned long long deadline = now + ROBOT_VOICE_MEDIA_STARTUP_MS;
    53	    if (!media_launched || now - media_last_launch >= 10000) {
    54	      media_launched = true;
    55	      media_last_launch = now;
    56	      int rc = system("mediad &");
    57	      printf("[RV-MEDIA-RUNTIME] lazy mediad launch rc=%d; waiting for native open\n", rc);
    58	    }
    59	    while (!player && media_service_missing(error) && media_now_ms() < deadline) {
    60	      struct timespec delay = {.tv_sec=0, .tv_nsec=50000000L};
    61	      while (nanosleep(&delay, &delay) < 0 && errno == EINTR) {}
    62	      errno = 0;
    63	      player = media_player_open(stream);
    64	      error = errno;
    65	    }
    66	  }
    67	  pthread_mutex_unlock(&media_start_lock);
    68	  if (!player) {
    69	    if (!error) error = EIO;
    70	    printf("[RV-MEDIA-RUNTIME] native open failed stream=%s errno=%d; "
    71	           "check mediad, IPC and Music graph\n", stream ? stream : "(null)", error);
    72	  }
    73	  errno = error;
    74	  return player;
    75	}
