   258	static int contest_media_write_music_pcm(FAR const uint8_t *pcm, size_t len)
   259	{
   260	  uint8_t scaled[CONTEST_MEDIA_GAIN_CHUNK];
   261	  size_t offset = 0;
   262	
   263	  if (pcm == NULL || len == 0 || (len & 1) != 0)
   264	    {
   265	      return -EINVAL;
   266	    }
   267	
   268	  while (offset < len)
   269	    {
   270	      size_t chunk = len - offset;
   271	      size_t i;
   272	      int ret;
   273	
   274	      if (chunk > sizeof(scaled))
   275	        {
   276	          chunk = sizeof(scaled);
   277	        }
   278	
   279	      chunk &= ~(size_t)1u;
   280	      if (chunk == 0)
   281	        {
   282	          return -EINVAL;
   283	        }
   284	
   285	      for (i = 0; i < chunk; i += sizeof(int16_t))
   286	        {
   287	          uint16_t raw = (uint16_t)pcm[offset + i] |
   288	                         ((uint16_t)pcm[offset + i + 1] << 8);
   289	          int16_t sample = (int16_t)raw;
   290	          int16_t quieter =
   291	            (int16_t)(((int32_t)sample * CONTEST_MEDIA_MUSIC_GAIN_NUM) /
   292	                      CONTEST_MEDIA_MUSIC_GAIN_DEN);
   293	
   294	          scaled[i] = (uint8_t)((uint16_t)quieter & 0xff);
   295	          scaled[i + 1] =
   296	            (uint8_t)(((uint16_t)quieter >> 8) & 0xff);
   297	        }
   298	
   299	      ret = robot_audio_playback_write(scaled, chunk);
   300	      if (ret < 0)
   301	        {
   302	          return ret;
   303	        }
   304	
   305	      offset += chunk;
   306	    }
   307	
   308	  return OK;
   309	}
