  5196	static int robot_voice_pcm_sink(const uint8_t *pcm, size_t len, void *arg)
  5197	{
  5198	  uint8_t scaled[ROBOT_VOICE_TTS_SCALE_CHUNK];
  5199	  size_t offset = 0;
  5200	
  5201	  (void)arg;
  5202	
  5203	  if (pcm == NULL || len == 0)
  5204	    {
  5205	      return -EINVAL;
  5206	    }
  5207	
  5208	  /*
  5209	   * TTS PCM is signed 16-bit little-endian.  Scale sample amplitude to 1/2
  5210	   * before handing it to the existing audio playback path.
  5211	   */
  5212	  while (offset < len)
  5213	    {
  5214	      size_t chunk = len - offset;
  5215	      size_t even;
  5216	      size_t i;
  5217	      int ret;
  5218	
  5219	      if (chunk > sizeof(scaled))
  5220	        {
  5221	          chunk = sizeof(scaled);
  5222	        }
  5223	
  5224	      /* Keep PCM16 sample pairs intact. */
  5225	      if ((chunk & 1u) != 0 && chunk > 1)
  5226	        {
  5227	          chunk--;
  5228	        }
  5229	
  5230	      even = chunk & ~(size_t)1u;
  5231	      for (i = 0; i < even; i += 2)
  5232	        {
  5233	          uint16_t raw = (uint16_t)pcm[offset + i] |
  5234	                         ((uint16_t)pcm[offset + i + 1] << 8);
  5235	          int16_t sample = (int16_t)raw;
  5236	          int16_t quieter =
  5237	            (int16_t)((sample * ROBOT_VOICE_TTS_GAIN_NUM) /
  5238	                      ROBOT_VOICE_TTS_GAIN_DEN);
  5239	
  5240	          scaled[i] = (uint8_t)((uint16_t)quieter & 0xff);
  5241	          scaled[i + 1] = (uint8_t)(((uint16_t)quieter >> 8) & 0xff);
  5242	        }
