  5244	      /* PCM16 should always arrive aligned. Preserve a final odd byte rather
  5245	       * than dropping it if an upstream callback ever violates that contract. */
  5246	      if (chunk > even)
  5247	        {
  5248	          scaled[even] = pcm[offset + even];
  5249	        }
