   560	static int contest_media_wait_dma(FAR struct contest_media_sink_s *sink,
   561	                                  uint64_t endpoint)
   562	{
   563	  uint64_t deadline = contest_media_now_ms() + 5000;
   564	
   565	  for (;;)
   566	    {
   567	      uint64_t completed;
   568	      uint64_t pending;
   569	      bool started;
   570	      int ret;
   571	
   572	      if (contest_media_pace_aborted(sink))
   573	        {
   574	          return -ECANCELED;
   575	        }
   576	
   577	      ret = contest_media_progress(sink, &completed, &pending, &started);
   578	      if (ret < 0 || (started && completed >= endpoint))
   579	        {
   580	          return ret;
   581	        }
   582	
   583	      /* FINAL can only be a few milliseconds behind already accepted PCM.
   584	       * Do not leave the agent holding I2S forever if the DMA callback or
   585	       * lower half stops making progress. */
   586	      if (contest_media_now_ms() >= deadline)
   587	        {
   588	          return -ETIMEDOUT;
   589	        }
   590	
   591	      /* Actual I2S callbacks, rather than a synthetic sample clock, are the
   592	       * completion authority. Yield while Media/network workers refill. */
   593	      usleep(CONTEST_MEDIA_PACE_SLICE_US);
   594	    }
   595	}
