   597	static bool contest_media_pop_apb(FAR struct contest_media_sink_s *sink,
   598	                                  FAR struct contest_media_pending_s *entry)
   599	{
   600	  if (nxsem_wait_uninterruptible(&sink->pace_lock) < 0)
   601	    {
   602	      return false;
   603	    }
   604	
   605	  if (sink->pace_count == 0)
   606	    {
   607	      nxsem_post(&sink->pace_lock);
   608	      return false;
   609	    }
   610	
   611	  *entry = sink->pending[sink->pace_head];
   612	  sink->pace_head = (sink->pace_head + 1) % CONTEST_MEDIA_PACE_QUEUE;
   613	  sink->pace_count--;
   614	  sink->pace_busy = true;
   615	
   616	  if (sink->pace_count == 0)
   617	    {
   618	      nxsem_post(&sink->pace_empty);
   619	    }
   620	
   621	  nxsem_post(&sink->pace_lock);
   622	  return true;
   623	}
