1478	  /* 1024 bytes fits in one ESP32-S3 GDMA descriptor.  Keep exactly one
1479	   * descriptor per audio slot so OUT_EOF maps 1:1 to one 21.33 ms slot.
1480	   */
1481	  if (i != 0 || (xfer->desc[i].ctrl & ESP32S3_DMA_CTRL_EOF) == 0)
1482	    {
