1697	{
1698	  FAR struct contest_i2s_xfer_s *xfer = &priv->xfer[slot];
1699	  bool schedule = false;
1700	
1701	  /*
1702	   * The descriptor owns xfer->dma_data, never the upper APB.
1703	   *
1704	   * For a normal block, OUT_EOF means GDMA has already handed the payload to
1705	   * the I2S peripheral, so publish its completion immediately.  Delaying every
1706	   * normal callback makes refill lag behind the immutable cyclic ring and can
1707	   * let hardware lap the producer at EOF.
1708	   *
1709	   * Only a terminal-short descriptor gets the separate 8 ms FIFO/shifter
1710	   * drain in contest_i2s_tx_terminal_stop_worker().
1711	   */
1712	
1713	  if (xfer->in_use && !xfer->done_queued)
1714	    {
1715	      xfer->result = OK;
1716	      xfer->done_queued = true;
1717	      contest_i2s_tx_done_push(priv, xfer);
1718	      schedule = true;
1719	
1720	      if (priv->queued_slots > 0)
1721	        {
1722	          priv->queued_slots--;
1723	        }
1724	    }
1725	  else
1726	    {
1727	      priv->silence_done_count++;
1728	      priv->late_refill_count++;
1729	      priv->underrun_count++;
1730	    }
1731	
1732	  priv->done_count++;
1733	  priv->chained_count++;
1734	  return schedule;
1735	}
