 62	static void robot_music_scale_pcm16_half(uint8_t *buf, size_t len)
 63	{
 64	  size_t i;
 65	
 66	  for (i = 0; i + 1 < len; i += 2)
 67	    {
 68	      uint16_t raw = (uint16_t)buf[i] | ((uint16_t)buf[i + 1] << 8);
 69	      int16_t sample = (int16_t)raw;
 70	      int16_t scaled =
 71	        (int16_t)((sample * ROBOT_MUSIC_GAIN_NUM) / ROBOT_MUSIC_GAIN_DEN);
 72	
 73	      buf[i] = (uint8_t)((uint16_t)scaled & 0xff);
 74	      buf[i + 1] = (uint8_t)(((uint16_t)scaled >> 8) & 0xff);
 75	    }
 76	}
 77	
 78	static uint16_t robot_music_u16le(const uint8_t *p)
 79	{
 80	  return (uint16_t)p[0] | ((uint16_t)p[1] << 8);
 81	}
 82	
 83	static uint32_t robot_music_u32le(const uint8_t *p)
 84	{
 85	  return (uint32_t)p[0] |
 86	         ((uint32_t)p[1] << 8) |
 87	         ((uint32_t)p[2] << 16) |
 88	         ((uint32_t)p[3] << 24);
 89	}
