 91	static int robot_music_read_exact(int fd, uint8_t *buf, size_t len)
 92	{
 93	  size_t done = 0;
 94	
 95	  while (done < len)
 96	    {
 97	      ssize_t nread = read(fd, buf + done, len - done);
 98	
 99	      if (nread < 0)
100	        {
101	          if (errno == EINTR)
102	            {
103	              continue;
104	            }
105	
106	          return -errno;
107	        }
108	
109	      if (nread == 0)
110	        {
111	          return -EIO;
112	        }
113	
114	      done += (size_t)nread;
115	    }
116	
117	  return 0;
118	}
