135	int robot_music_play_file(const char *path)
136	{
137	  uint8_t riff[12];
138	  uint8_t chunk[8];
139	  uint8_t fmt[16];
140	  uint8_t pcm[ROBOT_MUSIC_READ_BYTES];
141	  uint16_t audio_format = 0;
142	  uint16_t channels = 0;
143	  uint16_t bits_per_sample = 0;
144	  uint32_t sample_rate = 0;
145	  uint32_t data_bytes = 0;
146	  off_t data_offset = (off_t)-1;
147	  bool fmt_found = false;
148	  bool playback_opened = false;
149	  bool music_expression_set = false;
150	  int fd = -1;
151	  int ret = 0;
152	
153	  if (path == NULL || path[0] == '\0')
154	    {
155	      return -EINVAL;
156	    }
157	
158	  RV_VERBOSE("[ROBOT-MUSIC] source=%s\n", path);
159	
160	  fd = open(path, O_RDONLY);
161	  if (fd < 0)
162	    {
163	      ret = -errno;
164	      printf("[ROBOT-MUSIC] open failed rc=%d\n", ret);
165	      return ret;
166	    }
167	
168	  ret = robot_music_read_exact(fd, riff, sizeof(riff));
169	  if (ret < 0)
170	    {
171	      printf("[ROBOT-MUSIC] failed to read RIFF header rc=%d\n", ret);
172	      goto out;
173	    }
174	
175	  if (memcmp(riff, "RIFF", 4) != 0 || memcmp(riff + 8, "WAVE", 4) != 0)
176	    {
177	      printf("[ROBOT-MUSIC] unsupported container: expected RIFF/WAVE\n");
178	      ret = -EINVAL;
179	      goto out;
180	    }
181	
182	  for (;;)
183	    {
184	      uint32_t chunk_size;
185	      off_t chunk_data_offset;
186	      ssize_t nread;
187	
188	      nread = read(fd, chunk, sizeof(chunk));
189	      if (nread == 0)
190	        {
191	          break;
192	        }
193	
194	      if (nread < 0)
195	        {
196	          if (errno == EINTR)
197	            {
198	              continue;
199	            }
200	
201	          ret = -errno;
202	          goto out;
203	        }
204	
205	      if (nread != (ssize_t)sizeof(chunk))
206	        {
207	          ret = -EIO;
208	          goto out;
209	        }
210	
211	      chunk_size = robot_music_u32le(chunk + 4);
212	      chunk_data_offset = lseek(fd, 0, SEEK_CUR);
213	      if (chunk_data_offset < 0)
214	        {
215	          ret = -errno;
216	          goto out;
217	        }
218	
219	      if (memcmp(chunk, "fmt ", 4) == 0)
220	        {
221	          uint32_t remaining;
222	
223	          if (chunk_size < sizeof(fmt))
224	            {
225	              RV_VERBOSE("[ROBOT-MUSIC] invalid fmt chunk size=%lu\n",
226	                     (unsigned long)chunk_size);
227	              ret = -EINVAL;
228	              goto out;
229	            }
230	
231	          ret = robot_music_read_exact(fd, fmt, sizeof(fmt));
232	          if (ret < 0)
233	            {
234	              goto out;
235	            }
236	
237	          audio_format = robot_music_u16le(fmt);
238	          channels = robot_music_u16le(fmt + 2);
239	          sample_rate = robot_music_u32le(fmt + 4);
240	          bits_per_sample = robot_music_u16le(fmt + 14);
241	          fmt_found = true;
242	
243	          remaining = chunk_size - sizeof(fmt);
244	          ret = robot_music_skip(fd, remaining);
245	          if (ret < 0)
246	            {
247	              goto out;
248	            }
249	        }
250	      else
251	        {
252	          if (memcmp(chunk, "data", 4) == 0 && data_offset < 0)
253	            {
254	              data_offset = chunk_data_offset;
255	              data_bytes = chunk_size;
256	            }
257	
258	          ret = robot_music_skip(fd, chunk_size);
259	          if (ret < 0)
260	            {
261	              goto out;
262	            }
263	        }
264	
265	      if ((chunk_size & 1u) != 0)
266	        {
267	          ret = robot_music_skip(fd, 1);
268	          if (ret < 0)
269	            {
270	              goto out;
271	            }
272	        }
273	    }
274	
275	  if (!fmt_found || data_offset < 0 || data_bytes == 0)
276	    {
277	      printf("[ROBOT-MUSIC] missing fmt/data chunk fmt=%d data_bytes=%lu\n",
