279	      ret = -EINVAL;
280	      goto out;
281	    }
282	
283	  RV_VERBOSE("[ROBOT-MUSIC] PCM format=%u channels=%u rate=%lu bits=%u "
284	         "data_bytes=%lu\n",
285	         audio_format, channels, (unsigned long)sample_rate,
286	         bits_per_sample, (unsigned long)data_bytes);
287	
288	  if (audio_format != 1 ||
