295	      goto out;
296	    }
297	
298	  if ((data_bytes & 1u) != 0)
299	    {
300	      RV_VERBOSE("[ROBOT-MUSIC] invalid odd PCM data size=%lu\n",
301	             (unsigned long)data_bytes);
302	      ret = -EINVAL;
303	      goto out;
304	    }
305	
306	  if (lseek(fd, data_offset, SEEK_SET) < 0)
