326	    {
327	      music_expression_set = true;
328	    }
329	
330	  RV_VERBOSE("[ROBOT-MUSIC] playback start via robot_audio_playback\n");
331	
332	  {
333	    uint32_t remaining = data_bytes;
334	
335	    while (remaining > 0)
336	      {
337	        size_t want;
338	        ssize_t nread;
339	
340	        if (robot_music_stop_requested())
341	          {
342	            RV_VERBOSE("[ROBOT-MUSIC] stop observed before next PCM chunk\n");
343	            break;
344	          }
345	
346	        want = remaining < sizeof(pcm) ? (size_t)remaining : sizeof(pcm);
347	        nread = read(fd, pcm, want);
348	
349	        if (nread < 0)
350	          {
351	            if (errno == EINTR)
352	              {
353	                continue;
354	              }
355	
356	            ret = -errno;
357	            printf("[ROBOT-MUSIC] PCM read failed rc=%d\n", ret);
358	            break;
359	          }
360	
361	        if (nread == 0)
362	          {
363	            ret = -EIO;
364	            printf("[ROBOT-MUSIC] unexpected EOF remaining=%lu\n",
365	                   (unsigned long)remaining);
366	            break;
367	          }
368	
369	        if (((size_t)nread & 1u) != 0)
370	          {
371	            ret = -EIO;
372	            RV_VERBOSE("[ROBOT-MUSIC] odd PCM read bytes=%ld\n", (long)nread);
373	            break;
374	          }
375	
376	        robot_music_scale_pcm16_half(pcm, (size_t)nread);
377	        ret = robot_audio_playback_write(pcm, (size_t)nread);
378	        if (ret < 0)
379	          {
380	            printf("[ROBOT-MUSIC] playback write failed rc=%d\n", ret);
381	            break;
382	          }
383	
384	        remaining -= (uint32_t)nread;
385	      }
386	  }
387	
388	  if (ret == 0 && !robot_music_stop_requested())
389	    {
390	      ret = robot_audio_playback_finish();
391	      if (ret < 0)
392	        {
393	          printf("[ROBOT-MUSIC] playback finish failed rc=%d\n", ret);
394	        }
395	    }
396	  else if (robot_music_stop_requested())
397	    {
398	      /* Immediate user stop: close playback without draining queued music. */
399	      RV_VERBOSE("[ROBOT-MUSIC] playback stopped by request\n");
400	      ret = 0;
401	    }
402	
403	  RV_VERBOSE("[ROBOT-MUSIC] playback done rc=%d\n", ret);
404	
405	out:
406	  if (music_expression_set)
407	    {
408	      (void)robot_expression_clear(ROBOT_EXPRESSION_SOURCE_MUSIC);
409	    }
410	
411	  if (playback_opened)
412	    {
413	      robot_audio_playback_close();
