449	  g_robot_music_active = false;
450	  g_robot_music_stop_requested = false;
451	  g_robot_music_path[0] = '\0';
452	  pthread_cond_broadcast(&g_robot_music_cond);
453	  pthread_mutex_unlock(&g_robot_music_lock);
