460	int robot_music_stop(void)
461	{
462	  bool local_active;
463	  int media_ret = 0;
464	  int wait_loops = 0;
465	
466	  pthread_mutex_lock(&g_robot_music_lock);
467	  local_active = g_robot_music_active;
468	  if (local_active)
469	    {
470	      g_robot_music_stop_requested = true;
471	      RV_VERBOSE("[ROBOT-MUSIC] stop requested path=%s\n", g_robot_music_path);
472	    }
473	  pthread_mutex_unlock(&g_robot_music_lock);
474	
475	  /* Stop official/online Media playback too, when that compatibility layer
476	   * is linked. This makes one voice command stop either music backend. */
477	  if (robot_media_stop_active != NULL)
478	    {
479	      media_ret = robot_media_stop_active();
480	    }
481	
482	  /* Wait briefly until local worker closes robot_audio_playback, otherwise
483	   * immediate confirmation TTS can race the still-owned speaker device. */
484	  while (local_active)
485	    {
486	      pthread_mutex_lock(&g_robot_music_lock);
487	      local_active = g_robot_music_active;
488	      pthread_mutex_unlock(&g_robot_music_lock);
489	
490	      if (!local_active)
491	        {
492	          break;
493	        }
494	
495	      if (++wait_loops >= 100) /* 100 * 20 ms = 2 s */
496	        {
497	          printf("[ROBOT-MUSIC] stop wait timeout; worker still active\n");
498	          return -ETIMEDOUT;
499	        }
500	
501	      usleep(20 * 1000);
502	    }
503	
504	  RV_VERBOSE("[ROBOT-MUSIC] stop complete media_rc=%d\n", media_ret);
505	  return media_ret < 0 ? media_ret : 0;
506	}
