 531	static bool contest_media_pop_apb(FAR struct contest_media_sink_s *sink,
 532	                                  FAR struct contest_media_pending_s *entry)
 533	{
 534	  if (nxsem_wait_uninterruptible(&sink->pace_lock) < 0)
 535	    {
 536	      return false;
 537	    }
 538	
 539	  if (sink->pace_count == 0)
 540	    {
 541	      nxsem_post(&sink->pace_lock);
 542	      return false;
 543	    }
 544	
 545	  *entry = sink->pending[sink->pace_head];
 546	  sink->pace_head = (sink->pace_head + 1) % CONTEST_MEDIA_PACE_QUEUE;
 547	  sink->pace_count--;
 548	  sink->pace_busy = true;
 549	
 550	  if (sink->pace_count == 0)
 551	    {
 552	      nxsem_post(&sink->pace_empty);
 553	    }
 554	
 555	  nxsem_post(&sink->pace_lock);
 556	  return true;
