1823	static void contest_i2s_tx_free_dma_slots(FAR struct contest_i2s_tx_s *priv)
1824	{
1825	  FAR uint8_t *data;
1826	  unsigned int i;
1827	  irqstate_t flags;
1828	
1829	  for (i = 0; i < CONTEST_I2S_TX_RING_SLOTS; i++)
1830	    {
1831	      /* The completion worker clears payloads under the same spinlock.
1832	       * Detach before freeing so a canceled callback cannot touch freed RAM.
1833	       * START/STOP/SEND are serialized by control_lock.
1834	       */
1835	
1836	      flags = spin_lock_irqsave(&priv->lock);
1837	      data = priv->xfer[i].dma_data;
1838	      priv->xfer[i].dma_data = NULL;
1839	      priv->xfer[i].dma_bound = false;
1840	      spin_unlock_irqrestore(&priv->lock, flags);
1841	      kmm_free(data);
1842	    }
1843	
1844	  priv->ring_slots = 0;
