 694	static void *contest_media_pace_worker(FAR void *arg)
 695	{
 696	  FAR struct contest_media_sink_s *sink = arg;
 697	
 698	  syslog(LOG_INFO,
 699	         "[MEDIA-BRIDGE] DMA completion worker queue=%u\n",
 700	         CONTEST_MEDIA_PACE_QUEUE);
 701	
 702	  for (;;)
 703	    {
 704	      struct contest_media_pending_s entry;
 705	
 706	      int wait_ret = nxsem_tickwait_uninterruptible(
 707	        &sink->pace_data, MSEC2TICK(CONTEST_MEDIA_HEALTH_POLL_MS));
 708	      if (wait_ret == -ETIMEDOUT || wait_ret == -ETIME)
 709	        {
 710	          contest_media_check_health(sink);
 711	          continue;
 712	        }
 713	      if (wait_ret < 0)
 714	        {
 715	          continue;
 716	        }
 717	
 718	      while (contest_media_pop_apb(sink, &entry))
 719	        {
 720	          bool aborted = contest_media_pace_aborted(sink);
 721	          bool dma_done = false;
 722	          uint64_t played = 0;
 723	          uint64_t pending = 0;
 724	
 725	          int ret = aborted ? -ECANCELED : sink->stream_error;
 726	
 727	          /* robot_audio_playback_write() copies every source byte into the
 728	           * private PCM ring.  Once copied, Media no longer owns or needs
 729	           * this APB; holding it until the samples reach the speaker pins
 730	           * starves abufsrc's six-buffer pool and causes xrun on network
 731	           * streams.  Only FINAL has to wait for acoustic DMA completion. */
 732	          if (ret == OK && entry.final)
 733	            {
 734	              ret = contest_media_wait_dma(sink, entry.endpoint);
 735	            }
 736	
 737	          /* Report actual backend progress. Ordinary APBs are deliberately
 738	           * returned after copying into the private ring, so ret==OK alone
 739	           * does not mean that their samples have reached DMA. */
 740	          if (contest_media_progress(sink, &played, &pending, NULL) == OK)
 741	            {
 742	              dma_done = played >= entry.endpoint;
 743	            }
 744	
 745	          /* STOP can arrive while waiting. Do not turn that cancellation
 746	           * into natural EOS or finish()/drain the queued music. */
 747	          aborted = contest_media_pace_aborted(sink);
 748	          if (ret < 0 && !aborted)
 749	            {
 750	              sink->stream_error = ret;
 751	            }
 752	
 753	          contest_media_dequeue(sink, entry.apb,
 754	                                ret < 0 ? (uint16_t)-ret : OK);
 755	          sink->dequeue_count++;
 756	
 757	          if (sink->dequeue_count <= 4 ||
 758	              (sink->dequeue_count % 32) == 0 ||
 759	              entry.final)
 760	            {
 761	              syslog(LOG_INFO,
 762	                     "[MEDIA-BRIDGE] PCM dequeue #%u bytes=%zu "
 763	                     "dma_done=%d final=%d played=%zu copied=%zu\n",
 764	                     sink->dequeue_count, entry.bytes,
 765	                     dma_done ? 1 : 0, entry.final ? 1 : 0,
 766	                     (size_t)played, sink->total_pcm);
 767	            }
 768	
 769	          if (entry.final && !aborted && ret == OK)
 770	            {
 771	              int ret;
 772	
 773	              /* FINAL's actual samples have completed DMA. Finish joins
 774	               * the backend worker and closes before announcing COMPLETE. */
 775	              ret = contest_media_finish_playback(sink, true);
 776	              if (ret < 0) sink->stream_error = ret;
 777	              contest_media_complete(sink);
 778	
 779	              if (ret < 0)
 780	                {
 781	                  syslog(LOG_ERR,
 782	                         "[MEDIA-BRIDGE] final drain failed=%d\n", ret);
 783	                }
 784	            }
 785	
 786	          /* Mark the APB idle only after its callback and any FINAL handling
 787	           * have finished.  STOP waits for this flag as well as an empty
 788	           * queue, otherwise it can race the current DMA wait operation. */
 789	          if (nxsem_wait_uninterruptible(&sink->pace_lock) == OK)
 790	            {
 791	              bool failed = sink->stream_error < 0 && !sink->pace_abort &&
 792	                            sink->pace_count == 0;
 793	              sink->pace_busy = false;
 794	              nxsem_post(&sink->pace_empty);
 795	              nxsem_post(&sink->pace_lock);
