static int stop_borrowed(unsigned long run)
{
  int ret=0;
  pthread_mutex_lock(&music_lock);struct rv_music_handle *h=active_music;
  if(!h||!h->started){
    pthread_mutex_unlock(&music_lock);return 0;
  }
  if(run&&h->run>run){pthread_mutex_unlock(&music_lock);return -ECANCELED;}
  h->users++;pthread_mutex_unlock(&music_lock);
#ifdef CONFIG_MEDIA
  ret=media_player_stop(h->player);
#else
  ret=-ENOSYS;
#endif
  pthread_mutex_lock(&music_lock);
  if(!ret)h->started=false;
  h->users--;pthread_cond_broadcast(&music_changed);pthread_mutex_unlock(&music_lock);
  return ret;
}
