  (void)dev;

  if (slot == NULL || slot->pb == NULL)
    {
      return;
    }

  pb = slot->pb;

  if (rv_lock(pb) == 0)
    {
      if (!slot->inflight || (apb && apb != slot->apb))
        {
          pb->callback_errors++;
          if (pb->i2s_result >= 0) pb->i2s_result = -EPROTO;
          rv_unlock(pb);
          nxsem_post(&slot->done);
          nxsem_post(&pb->i2s_done);
