static void *rv_worker(void *arg)
{
  struct rv_playback_s *pb = arg;
  uint8_t block[RV_SOURCE_BLOCK_BYTES];
  unsigned int slot_index = 0;
  int primed_slots = 0;
  int ret = 0;
  bool terminal_tail = false;

  pb->state = RV_STATE_PREBUFFER;

  if (pb->native_media)
    {
      printf("[RV-PB] native worker ready slots=%u prebuffer=%u\n",
             pb->slot_count, pb->start_prebuffer);
    }

  while (!pb->stopped)
    {
      struct rv_slot_s *slot;

      terminal_tail = false;
      size_t available;
      size_t want;
      size_t got;
      bool prime_silence = false;
      bool final_block = false;

      ret = rv_get_result(pb);
      if (ret < 0)
        {
          printf("[RV-PB] I2S worker error=%d\n", ret);
          break;
        }

      if (pb->state == RV_STATE_PREBUFFER || pb->state == RV_STATE_REBUFFER)
        {
          size_t threshold = pb->state == RV_STATE_PREBUFFER ?
                             pb->start_prebuffer : RV_REBUFFER_BYTES;
          const char *from = pb->state == RV_STATE_PREBUFFER ?
                             "PREBUFFER" : "REBUFFER";

          ret = rv_wait_buffer(pb, threshold);
          if (ret < 0)
            {
              break;
            }

          if (pb->stopped) { ret = -ECANCELED; break; }
          available = rv_ring_count(pb);
          if (available >= 2)
            {
              pb->state = RV_STATE_PLAYING;
              primed_slots = 0;
              slot_index = 0;

              if (pb->ring_min_play == (size_t)-1)
                {
                  pb->ring_min_play = available;
                }

              if (available > pb->ring_max_play)
                {
                  pb->ring_max_play = available;
                }

              (void)from;
            }
          else if (pb->eos)
            {
              pb->state = RV_STATE_DRAINING;
            }
          else
            {
              continue;
            }
        }

      if (pb->state == RV_STATE_DRAINING)
        {
          break;
        }

      slot = &pb->slots[slot_index];

      /* Prime the negotiated number of slots, then refill in that same
       * round-robin order. Each source block expands to the fixed wire size;
       * a larger ring gives more callback/worker scheduling headroom. */
      if (primed_slots >= pb->slot_count)
        {
          ret = rv_wait_slot(pb, slot);
          if (ret < 0)
            {
              break;
            }
        }

      available = rv_ring_count(pb);

      /* No producer wait is permitted once the immutable DMA ring runs.
       * cache_until_eos voice has all its PCM here, so no interior gap exists. */
      if (pb->native_media &&
          __atomic_load_n(&pb->media_paused, __ATOMIC_ACQUIRE))
        {
          /* Keep the immutable hardware ring fresh while preserving every
           * queued real sample. A pause is neither EOS nor a short tail. */
          memset(block, 0, sizeof(block));
          want = RV_SOURCE_BLOCK_BYTES;
          prime_silence = true;
        }
      else if (pb->voice_live && !pb->eos &&
          available < 2 * RV_SOURCE_BLOCK_BYTES)
        {
          /* Retain one real block until EOS is known so even an exact block
           * tail receives AUDIO_APB_FINAL. Never wait on a running immutable
           * DMA slot: overwrite it with silence during a producer gap. */
          memset(block, 0, sizeof(block));
          want = RV_SOURCE_BLOCK_BYTES;
          prime_silence = true;
          pb->underrun_count++;
          pb->silence_blocks++;
          pb->gap_run++;
          if (pb->gap_run > pb->max_gap_run) pb->max_gap_run = pb->gap_run;
        }
      else if (available >= RV_SOURCE_BLOCK_BYTES)
        {
          want = RV_SOURCE_BLOCK_BYTES;
          pb->gap_run = 0;
          if (pb->eos && available == RV_SOURCE_BLOCK_BYTES &&
              pb->stop_on_short_underrun)
            {
              final_block = true;
              terminal_tail = true;
            }
        }
      else if (pb->eos && available > 0)
        {
          want = available & ~(size_t)1;
          final_block = pb->stop_on_short_underrun;
          terminal_tail = final_block;
          if (want == 0)
            {
              (void)rv_ring_read(pb, block, available);
              continue;
            }
        }
      else if (pb->eos && available == 0)
        {
          if (pb->stop_on_short_underrun)
            {
              /*
               * Exact finite-file EOF: there is no real PCM left.  Do not
               * manufacture ten extra silent submissions just to walk the
               * cyclic ring.  Drain the already-submitted real blocks and
               * stop.
               */

              pb->eos_silence_rounds = 0;
              pb->state = RV_STATE_DRAINING;
              break;
            }

          if (pb->eos_silence_rounds < pb->slot_count)
            {
              memset(block, 0, sizeof(block));
              want = RV_SOURCE_BLOCK_BYTES;
              prime_silence = true;
              pb->eos_silence_rounds++;
              pb->silence_blocks++;
            }
          else
            {

              pb->eos_silence_rounds = 0;
              pb->state = RV_STATE_DRAINING;
              break;
            }
        }

      else
        {
          /*
           * Legacy streaming-music path only: NEVER stop feeding the immutable cyclic DMA ring after
           * PLAYING has started.
           *
           * The lower half keeps its 16 frozen descriptors circulating even
           * when the upper layer has no logical requests in flight.  The old
           * REBUFFER path stopped submitting new payloads while waiting for
           * 48 KiB of producer data; hardware then replayed the stale tail
           * still stored in those DMA slots ("...变化量量量量...").
           *
           * Keep cadence tied to rv_wait_slot()/DMA completion instead:
           *   - if a short aligned tail exists, play it and let
           *     rv_queue_slot() zero-pad the rest of the 2048-byte wire slot;
           *   - if no complete PCM16 sample exists, submit one full silent
           *     source block.
           *
           * A producer stall can therefore create silence, never stale-audio
           * repetition. Complete-cache voice must never enter this path.
           */
          if (pb->cache_until_eos)
            {
              /* Complete-cache voice can never starve. Stop on invariant
               * failure instead of adding any silence in the utterance. */
              ret = -EPROTO;
              break;
            }
          pb->underrun_count++;
          pb->gap_run++;
          if (pb->gap_run > pb->max_gap_run) pb->max_gap_run = pb->gap_run;

          if (pb->native_media &&
              (pb->underrun_count == 1 ||
               (pb->underrun_count % 512) == 0))
            {
              printf("[RV-PB] native Media PCM underflow=%lu buffered=%zu/%zu "
                     "silence=%lu\n",
                     (unsigned long)pb->underrun_count, available,
                     pb->ring.capacity,
                     (unsigned long)pb->silence_blocks);
            }

          if (available >= sizeof(int16_t))
            {
              want = available;
              if (want > RV_SOURCE_BLOCK_BYTES)
                {
                  want = RV_SOURCE_BLOCK_BYTES;
                }

              want &= ~(size_t)1;

              if (pb->stop_on_short_underrun && !pb->native_media)
                {
                  terminal_tail = true;
                  final_block = true;
                  pb->eos = 1;
                  (void)0;
                }
              else if (pb->underrun_count <= 4 ||
                       (pb->underrun_count % 32) == 0)
                {
                  (void)0;
                }
            }
          else
            {
              memset(block, 0, sizeof(block));
              want = RV_SOURCE_BLOCK_BYTES;
              prime_silence = true;

              if (available > 0)
                {
                  /* Preserve PCM16 alignment: discard a lone impossible
                   * byte rather than carrying it into the next sample. */
                  (void)rv_ring_read(pb, block, available);
                }

              if (pb->stop_on_short_underrun && !pb->native_media)
                {
                  (void)0;
                  pb->eos = 1;
                  pb->stopped = 1;
                  pb->terminal_tail_done = 1;

                  if (pb->i2s != NULL && pb->i2s_started)
                    {
                      pb->i2s_started = 0;
                      I2S_IOCTL(pb->i2s, AUDIOIOC_STOP, 0);
                    }

                  rv_signal_all(pb);
                  break;

  if (nxsem_wait_uninterruptible(&sink->pace_lock) < 0)
    {
      return false;
    }

  if (sink->pace_count == 0)
    {
      nxsem_post(&sink->pace_lock);
      return false;
    }

  *entry = sink->pending[sink->pace_head];
  sink->pace_head = (sink->pace_head + 1) % CONTEST_MEDIA_PACE_QUEUE;
  sink->pace_count--;
  sink->pace_busy = true;

  if (sink->pace_count == 0)
    {
      nxsem_post(&sink->pace_empty);
    }

  nxsem_post(&sink->pace_lock);
  return true;
}

/* Detect a stopped I2S DMA worker even when Media has not queued a FINAL
 * buffer.  Without this poll, APBs already copied into the private PCM ring
 * can be returned and the Media thread can then wait forever for an event. */
static void contest_media_check_health(FAR struct contest_media_sink_s *sink)
{
  uint32_t now_ms;
  uint32_t last_pcm_ms;
  uint32_t started_ms;
  uint64_t completed;
  uint64_t pending;
  unsigned int queued;
  bool started;
  int ret;

  if (__atomic_load_n(&sink->completion_sent, __ATOMIC_ACQUIRE) ||
      sink->stream_error < 0 || contest_media_pace_aborted(sink))
    {
      return;
    }

  ret = contest_media_progress(sink, &completed, &pending, &started);
  if (!started)
    {
      return;
    }

  now_ms = (uint32_t)contest_media_now_ms();
  last_pcm_ms = __atomic_load_n(&sink->last_pcm_ms, __ATOMIC_ACQUIRE);
  started_ms = __atomic_load_n(&sink->started_ms, __ATOMIC_ACQUIRE);
  if (ret >= 0 && !sink->eos &&
      (uint32_t)(now_ms - (last_pcm_ms ? last_pcm_ms : started_ms)) >=
      CONTEST_MEDIA_STALL_TIMEOUT_MS)
    {
      ret = -ETIMEDOUT;
      syslog(LOG_ERR,
             "[MEDIA-BRIDGE] no PCM input for %u ms; closing stalled stream\n",
             CONTEST_MEDIA_STALL_TIMEOUT_MS);
    }
  else if (ret >= 0)
    {
      return;
    }

  sink->stream_error = ret;
  sink->eos = true;
  syslog(LOG_ERR,
         "[MEDIA-BRIDGE] playback backend failed while streaming rc=%d; "
         "closing and returning to caller\n", ret);

  if (nxsem_wait_uninterruptible(&sink->pace_lock) < 0)
    {
      return;
    }

  queued = sink->pace_count;
  nxsem_post(&sink->pace_lock);

static int contest_media_enqueue_internal(FAR struct audio_lowerhalf_s *dev,
                                          FAR struct ap_buffer_s *apb)
{
  FAR struct contest_media_sink_s *sink =
    (FAR struct contest_media_sink_s *)dev;
  size_t len;
  int ret;
  bool final;

  if (apb == NULL || apb->curbyte > apb->nbytes)
    {
      return -EINVAL;
    }

  len = (size_t)apb->nbytes - (size_t)apb->curbyte;
  final = (apb->flags & AUDIO_APB_FINAL) != 0;
  if ((len & 1) != 0) return -EINVAL;
  /* A bounded APB must fit before START, when DMA intentionally consumes
   * nothing. Reject oversized client buffers rather than blocking forever. */
  if (len > CONTEST_MEDIA_BUFFER_BYTES) return -EMSGSIZE;

  if (__atomic_load_n(&sink->completion_sent, __ATOMIC_ACQUIRE) || sink->eos)
    {
      return -EPIPE;
    }

  /* Fail before committing PCM if no ownership slot is available. */
  ret = nxsem_wait_uninterruptible(&sink->pace_lock);
  if (ret < 0) return ret;
  bool full = sink->pace_count + (sink->pace_busy ? 1 : 0) >=
              CONTEST_MEDIA_PACE_QUEUE;
  nxsem_post(&sink->pace_lock);
  if (full) return -EAGAIN;

  /* Be tolerant of clients that enqueue before AUDIOIOC_START.  The NuttX
   * upper-half still requires CONFIGURE first, and open_playback() enforces
   * that contract. */
  ret = contest_media_open_playback(sink);
  if (ret < 0)
    {
      return ret;
    }

  if (len > 0)
    {
      ret = contest_media_write_music_pcm(&apb->samp[apb->curbyte], len);
      if (ret < 0)
        {
          syslog(LOG_ERR, "[MEDIA-BRIDGE] write failed len=%zu rc=%d\n",
                 len, ret);
          return ret;
        }

      /* The FFmpeg NuttX output queues several APBs before it sends START.
       * Begin consuming the private ring now; a later START remains
       * idempotent and preserves the normal lower-half contract. */
      ret = contest_media_start_backend(sink);
      if (ret < 0)
        {
          syslog(LOG_ERR, "[MEDIA-BRIDGE] implicit start failed rc=%d\n",
                 ret);
          return ret;
        }

      sink->total_pcm += len;
      __atomic_store_n(&sink->last_pcm_ms,
                       (uint32_t)contest_media_now_ms(),
                       __ATOMIC_RELEASE);
      sink->enqueue_count++;
      apb->curbyte = apb->nbytes;

      if (sink->enqueue_count <= 4 || (sink->enqueue_count % 32) == 0)
        {
          syslog(LOG_INFO,
                 "[MEDIA-BRIDGE] PCM enqueue #%u bytes=%zu total=%zu final=%d\n",
                 sink->enqueue_count, len, sink->total_pcm, final ? 1 : 0);
        }
    }

  /* Retain the APB until real DMA completes its source endpoint. */
  if (final)
    {
      syslog(LOG_INFO,
             "[MEDIA-BRIDGE] FINAL APB received bytes=%zu "
             "pcm_total=%zu dequeued=%zu\n",
             len, sink->total_pcm, sink->dequeued_pcm);
    }

  if (final)
    {
      sink->eos = true;
      /* Nonblocking EOS wakes even a file shorter than the startup water
       * mark. Waiting for FINAL's dequeue before EOS would deadlock. */
      if (nxsem_wait_uninterruptible(&sink->playback_lock) < 0) return -EINTR;
      ret = sink->started ? robot_audio_playback_end_input() : OK;
      nxsem_post(&sink->playback_lock);
      if (ret < 0) return ret;
    }

  ret = contest_media_queue_apb(sink, apb, len, final);
  if (ret < 0)
    {
      syslog(LOG_ERR,
             "[MEDIA-BRIDGE] queue APB failed bytes=%zu final=%d rc=%d\n",
             len, final ? 1 : 0, ret);
      return ret;
    }

  return OK;
}

static int contest_media_enqueuebuffer(FAR struct audio_lowerhalf_s *dev,
                                       FAR struct ap_buffer_s *apb)
{
  FAR struct contest_media_sink_s *sink = (FAR void *)dev;
  int ret = nxsem_wait_uninterruptible(&sink->enqueue_lock);
  if (ret < 0) return ret;
  ret = contest_media_enqueue_internal(dev, apb);
  nxsem_post(&sink->enqueue_lock);
  return ret;
}

static int contest_media_ioctl(FAR struct audio_lowerhalf_s *dev,
                               int cmd, unsigned long arg)
{
  FAR struct contest_media_sink_s *sink =
    (FAR struct contest_media_sink_s *)dev;

  switch (cmd)
    {
      case AUDIOIOC_GETBUFFERINFO:
        {
          FAR struct ap_buffer_info_s *info =
            (FAR struct ap_buffer_info_s *)((uintptr_t)arg);

          if (info == NULL)
            {
              return -EINVAL;
            }

          info->nbuffers = CONTEST_MEDIA_NBUFFERS;
          info->buffer_size = CONTEST_MEDIA_BUFFER_BYTES;
          syslog(LOG_INFO,
                 "[MEDIA-BRIDGE] GETBUFFERINFO nbuffers=%u bytes=%u\n",
                 CONTEST_MEDIA_NBUFFERS, CONTEST_MEDIA_BUFFER_BYTES);
          return OK;
        }

      case AUDIOIOC_SETBUFFERINFO:
        /* GETBUFFERINFO is authoritative: the native playback ring and DMA
         * geometry are private to the backend, not set by a Media period. */
        return OK;

      case AUDIOIOC_GETPOSITION:
        {
          FAR long *position =
            (FAR long *)((uintptr_t)arg);
          size_t bytes_per_frame;

          if (position == NULL)
            {
              return -EINVAL;
            }

          bytes_per_frame =
            (size_t)sink->channels * (size_t)sink->bits / 8;

          if (bytes_per_frame == 0)
            {
              bytes_per_frame =
                CONTEST_MEDIA_CHANNELS * (CONTEST_MEDIA_BITS / 8);
            }

          uint64_t completed;
          uint64_t pending;
          int ret = contest_media_progress(sink, &completed, &pending, NULL);
          if (ret < 0) return ret;
          *position = (long)(completed / bytes_per_frame);
          return OK;
        }

      case AUDIOIOC_GETLATENCY:
        {
          FAR long *latency =
            (FAR long *)((uintptr_t)arg);

          if (latency == NULL)
            {
              return -EINVAL;
            }

          uint64_t completed;
          uint64_t pending;
          int ret = contest_media_progress(sink, &completed, &pending, NULL);
          if (ret < 0) return ret;
          *latency = (long)(pending / (CONTEST_MEDIA_CHANNELS *
                                      (CONTEST_MEDIA_BITS / 8)));
          return OK;
        }

      case AUDIOIOC_FLUSH:
        {
          bool restart = sink->started;
#ifndef CONFIG_AUDIO_EXCLUDE_PAUSE_RESUME
          bool paused = sink->paused;
#endif
          syslog(LOG_INFO, "[MEDIA-BRIDGE] FLUSH\n");
          (void)contest_media_abort_pending(sink);
          int ret = contest_media_finish_playback(sink, false);
          sink->eos = false;
          __atomic_store_n(&sink->completion_sent, false, __ATOMIC_RELEASE);
          sink->stream_error = OK;
          /* ff_nuttx_flush() keeps its running flag. Re-arm the lower half
           * here; the client will not send a new START after a seek/flush. */
          if (ret == OK && restart)
            {
#ifdef CONFIG_AUDIO_MULTI_SESSION
              ret = contest_media_start(dev, sink);
#else
              ret = contest_media_start(dev);
#endif
#ifndef CONFIG_AUDIO_EXCLUDE_PAUSE_RESUME
              if (ret == OK && paused)
                {
#ifdef CONFIG_AUDIO_MULTI_SESSION
                  ret = contest_media_pause(dev, sink);
#else
                  ret = contest_media_pause(dev);
#endif
                }

