static void contest_i2s_tx_free_dma_slots(FAR struct contest_i2s_tx_s *priv)
{
  unsigned int i;

  for (i = 0; i < CONTEST_I2S_TX_RING_SLOTS; i++)
    {
      if (priv->xfer[i].dma_data != NULL)
        {
          kmm_free(priv->xfer[i].dma_data);
