          sink->paused = false;
          uint32_t now_ms = (uint32_t)contest_media_now_ms();
          __atomic_store_n(&sink->started_ms, now_ms, __ATOMIC_RELEASE);
          __atomic_store_n(&sink->last_pcm_ms, now_ms, __ATOMIC_RELEASE);
        }
