  syslog(LOG_INFO,
         "[MEDIA-BRIDGE] playback close drain=%d pcm=%zu "
         "dequeued_pcm=%zu enqueues=%u dequeues=%u rc=%d\n",
         drain ? 1 : 0, sink->total_pcm, sink->dequeued_pcm,
         sink->enqueue_count, sink->dequeue_count, ret);
