+static void media_server_try_accept(struct media_server_priv* priv, int fd)
+{
+    struct pollfd pollfd;
+    int ret;
+
+    if (fd <= 0)
+        return;
+
+    pollfd.fd = fd;
+    pollfd.events = POLLIN;
+    pollfd.revents = POLLIN;
+
+    do {
+        ret = media_server_accept(priv, &pollfd);
+        if (ret == 0)
