+static int media_server_run_once(MediadPlugin* ctx)
+{
+    struct media_server_priv* priv = ctx->priv;
+    struct pollfd pollfd;
+    int ret;
+    int i;
+
+    if (priv == NULL)
+        return -EINVAL;
+
+    /* Accept probing is handled solely by the pump thread; this loop is the
+     * sole reader of conn sockets. Keeping accept out of here avoids two
+     * threads accept()ing the same listen fd / grabbing conn slots at once.
+     */
+    pollfd.events = POLLIN;
+    pollfd.revents = POLLIN;
