static int media_close(void* handle, int pending_stop)
{
    MediaIOPriv* priv = handle;
    char tmp[32];
    int ret;

    snprintf(tmp, sizeof(tmp), "%d", pending_stop);
    ret = media_proxy_once(priv, NULL, "close", tmp, 0, NULL, 0);
    if (ret < 0)
        return ret;

    media_close_socket(priv);
    media_proxy_disconnect(priv->proxy);
    return ret;
}

static int media_get_sockaddr(void* handle, struct sockaddr_storage* addr_)
{
    MediaIOPriv* priv = handle;

    if (!handle || !addr_)
        return -EINVAL;

    if (!strcmp(priv->cpu, CONFIG_RPMSG_LOCAL_CPUNAME)) {
        struct sockaddr_un* addr = (struct sockaddr_un*)addr_;

        addr->sun_family = AF_UNIX;
        snprintf(addr->sun_path, UNIX_PATH_MAX, MEDIA_GRAPH_SOCKADDR_NAME, priv);
    } else {
        struct sockaddr_rpmsg* addr = (struct sockaddr_rpmsg*)addr_;

        addr->rp_family = AF_RPMSG;
        snprintf(addr->rp_name, RPMSG_SOCKET_NAME_SIZE, MEDIA_GRAPH_SOCKADDR_NAME, priv);
        snprintf(addr->rp_cpu, RPMSG_SOCKET_CPU_SIZE, "%s", priv->cpu);
    }

    return 0;
}

static int media_bind_socket(void* handle)
{
    struct sockaddr_storage addr;
    int fd, ret;

    ret = media_get_sockaddr(handle, &addr);
    if (ret < 0)
        return ret;

    fd = socket(addr.ss_family, SOCK_STREAM | SOCK_CLOEXEC, 0);
    if (fd < 0)
        return -errno;

    ret = bind(fd, (const struct sockaddr*)&addr, sizeof(addr));
    if (ret < 0)
        goto out;

    ret = listen(fd, 1);
    if (ret < 0)
        goto out;

    return fd;

out:
    close(fd);
    return -errno;
}

static int media_prepare(void* handle, const char* url, const char* options)
{
    MediaIOPriv* priv = handle;
    const char* cpu = NULL;
    int ret = -EINVAL;
    char addr[32];
    int fd = 0;

    if (!priv || priv->socket > 0)
        return ret;

    if (!url || !url[0]) {
        /* Buffer mode, create listener and send cpuname and sockname. */
        fd = media_bind_socket(handle);
        if (fd < 0)
            return fd;

        cpu = CONFIG_RPMSG_LOCAL_CPUNAME;
        snprintf(addr, sizeof(addr), MEDIA_GRAPH_SOCKADDR_NAME, priv);
        url = addr;
    }

    if (options && options[0] != '\0') {
        ret = media_proxy_once(priv, NULL, "set_options", options, 0, NULL, 0);
        if (ret < 0)
            goto out;
    }
    ret = media_proxy_once(priv, cpu, "prepare", url, 0, NULL, 0);
    if (ret < 0)
        goto out;

    if (fd > 0) {
        priv->socket_fd = fd;
        priv->socket = accept4(fd, NULL, NULL, SOCK_CLOEXEC);
        if (priv->socket < 0) {
            priv->socket = 0;
            ret = -errno;
        }
    }

    pthread_detach(thread);

    return 0;

out:
    audio_graph_close(&ctx->audio_output);
    ctx->state = MEDIA_PLAYER_STATE_IDLE;
    return ret;
}

static int media_player_handler(MediadPlugin* handle, struct media_server_conn* conn, const char* target, const char* cmd, const char* arg, int flags, char* res, int res_len)
{
    MediaPlayerPriv* priv = handle->priv;
    char option_name[64] = { 0 };
    char options[256] = { 0 };
    int ret = 0;

    MEDIA_INFO("cmd: %s, arg %s, target %s.\n",
        cmd, arg ? arg : "NULL", target ? target : "NULL");

    if (!strcmp(cmd, "open")) {
        MediaPlayerContext* ctx = media_player_get_available_session(priv);
        if (!ctx) {
            MEDIA_ERR("player open failed...\n");
            return -ENOMEM;
        }

        ctx->tran_fd = media_server_get_tran_fd(conn);
        if (ctx->tran_fd < 0) {
            MEDIA_ERR("player get tran fd failed...\n");
            return -EINVAL;
        }

        media_server_clean_conn(conn);

        // get global options in criteria.txt
        snprintf(option_name, sizeof(option_name), "%sParams", arg);
        ret = media_stub_get_stream_name(option_name, options, sizeof(options));
        if (ret == 0 && strlen(options) != 0) {
            ret = av_dict_parse_string(&ctx->global_opts, options, "=", ":", 0);
            if (ret < 0) {
                MEDIA_ERR("parse global options failed %d\n", ret);
                return ret;
            }
        }

        ret = media_player_open(ctx, arg);
        if (ret < 0)
            return ret;

        MEDIA_INFO("ctx %p open %s success...\n", ctx, ctx->name);
    } else if (!strcmp(cmd, "dump")) {
        media_player_dump(priv);
    }

    return 0;
}

