static void link_uninit_dump_pcm(AVFilterLink *link, bool stop)
{
    if (link->dump_pcm_fds) {
        int i;
        for (i = 0; i < link->nb_dump_pcm_fds; i++) {
            if (link->dump_pcm_fds[i])
                close(link->dump_pcm_fds[i]);
        }
        av_free(link->dump_pcm_fds);
        link->dump_pcm_fds    = NULL;
        link->nb_dump_pcm_fds = 0;
    }

    if (stop)
        link->dump_pcm = false;
}

static int link_init_dump_pcm(AVFilterLink *link)
{
    char path[PATH_MAX];
    int fd, i;

    link->nb_dump_pcm_fds = av_sample_fmt_is_planar(link->format)? link->ch_layout.nb_channels : 1;
    link->dump_pcm_fds = av_malloc_array(link->nb_dump_pcm_fds, sizeof(int));
    if (!link->dump_pcm_fds)
        return AVERROR(ENOMEM);

    for (i = 0; i < link->nb_dump_pcm_fds; i++) {
        snprintf(path, sizeof(path), FFMPEG_TMPDIR"/%.16s-%.8s-%d.pcm", link->src->name, link->dst->name, i);
        fd = open(path, O_WRONLY | O_CREAT);
        if (fd < 0) {
            link_uninit_dump_pcm(link, true);
            return AVERROR(errno);
        }
        link->dump_pcm_fds[i] = fd;
    }

    return 0;
}

static int filter_set_dump_pcm(AVFilterContext *filter, const char *target, bool set)
{
    int i;

    for (i = 0; i < filter->nb_outputs; i++) {
        AVFilterLink *link = filter->outputs[i];
        if (!target || !strcmp(link->dst->name, target)) {
            if (set)
                link->dump_pcm = true;
            else
                link_uninit_dump_pcm(link, true);

            if (target)
                return 0;
        }
    }

    return target ? AVERROR(EINVAL) : 0;
}

static void link_free(AVFilterLink **link)
{
    FilterLinkInternal *li;

    if (!*link)
        return;
    li = ff_link_internal(*link);

    ff_framequeue_free(&li->fifo);
    ff_frame_pool_uninit(&li->frame_pool);
    av_channel_layout_uninit(&(*link)->ch_layout);

    link_uninit_dump_pcm(*link, true);

    av_buffer_unref(&li->l.hw_frames_ctx);

    av_freep(link);
}

#if FF_API_LINK_PUBLIC
void avfilter_link_free(AVFilterLink **link)
{
    link_free(link);
}
int avfilter_config_links(AVFilterContext *filter)
{
    return ff_filter_config_links(filter);
}
#endif

static void update_link_current_pts(FilterLinkInternal *li, int64_t pts)
{
    AVFilterLink *const link = &li->l.pub;

    if (pts == AV_NOPTS_VALUE)
        return;
    li->l.current_pts = pts;
    li->l.current_pts_us = av_rescale_q(pts, link->time_base, AV_TIME_BASE_Q);
    /* TODO use duration */
    if (li->l.graph && li->age_index >= 0)
        ff_avfilter_graph_update_heap(li->l.graph, li);
}

void ff_filter_set_ready(AVFilterContext *filter, unsigned priority)
{
    FFFilterContext *ctxi = fffilterctx(filter);
    ctxi->ready = FFMAX(ctxi->ready, priority);
}

/**
 * Clear frame_blocked_in on all outputs.
 * This is necessary whenever something changes on input.
 */
static void filter_unblock(AVFilterContext *filter)
{
    unsigned i;

    for (i = 0; i < filter->nb_outputs; i++) {
        FilterLinkInternal * const li = ff_link_internal(filter->outputs[i]);
        li->frame_blocked_in = 0;
    }
}


void ff_avfilter_link_set_in_status(AVFilterLink *link, int status, int64_t pts)
{
    FilterLinkInternal * const li = ff_link_internal(link);

    if (li->status_in == status)
        return;
    av_assert0(!li->status_in);
    li->status_in = status;
    li->status_in_pts = pts;
    li->frame_wanted_out = 0;
    li->frame_blocked_in = 0;
    filter_unblock(link->dst);
    ff_filter_set_ready(link->dst, 200);
}

/**
 * Set the status field of a link from the destination filter.
 * The pts should probably be left unset (AV_NOPTS_VALUE).
 */
static void link_set_out_status(AVFilterLink *link, int status, int64_t pts)
{
    FilterLinkInternal * const li = ff_link_internal(link);

    av_assert0(!li->frame_wanted_out);
    av_assert0(!li->status_out);
    li->status_out = status;
    if (pts != AV_NOPTS_VALUE)
        update_link_current_pts(li, pts);
    filter_unblock(link->dst);
    ff_filter_set_ready(link->src, 200);
}

