 */

static void log_url(const char* url, char* buf, size_t bufsz)
{
    const char* q = strchr(url, '?');
    if (q) {
        size_t len = (size_t)(q - url);
        if (len >= bufsz) {
            len = bufsz - 1;
        }

        memcpy(buf, url, len);
        buf[len] = '\0';
    } else {
        snprintf(buf, bufsz, "%s", url);
    }
}

