#  include <media_player.h>
#endif
struct rv_music_handle {
  void *player;
  bool started, closing;
  unsigned int users;
  unsigned long run;
};
static pthread_mutex_t music_lock = PTHREAD_MUTEX_INITIALIZER;
static struct rv_music_handle *active_music;
static pthread_cond_t music_changed=PTHREAD_COND_INITIALIZER;
extern unsigned long robot_voice_music_run_id(void) __attribute__((weak));
void robot_music_media_link_anchor(void) {}
#ifdef CONFIG_MEDIA
static pthread_mutex_t media_start_lock = PTHREAD_MUTEX_INITIALIZER;
static unsigned long long media_last_launch;
static bool media_launched;
static unsigned long long media_now_ms(void)
{
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (unsigned long long)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}
static bool media_service_missing(int error)
{
  return error == ENOENT || error == ENOTCONN || error == ECONNREFUSED;
}
static void *open_native_media(const char *stream)
{
  void *player;
  int error;
  /* Probe actual readiness, not system()'s status for a background NSH
   * command. Already-running services are reused without a second launch. */
  pthread_mutex_lock(&media_start_lock);
  errno = 0;
  player = media_player_open(stream);
  error = errno;
  if (!player && media_service_missing(error)) {
    unsigned long long now = media_now_ms();
    unsigned long long deadline = now + ROBOT_VOICE_MEDIA_STARTUP_MS;
    if (!media_launched || now - media_last_launch >= 10000) {
      media_launched = true;
      media_last_launch = now;
      int rc = system("mediad &");
      printf("[RV-MEDIA-RUNTIME] lazy mediad launch rc=%d; waiting for native open\n", rc);
    }
    while (!player && media_service_missing(error) && media_now_ms() < deadline) {
      struct timespec delay = {.tv_sec=0, .tv_nsec=50000000L};
      while (nanosleep(&delay, &delay) < 0 && errno == EINTR) {}
      errno = 0;
      player = media_player_open(stream);
      error = errno;
    }
  }
  pthread_mutex_unlock(&media_start_lock);
  if (!player) {
    if (!error) error = EIO;
    printf("[RV-MEDIA-RUNTIME] native open failed stream=%s errno=%d; "
           "check mediad, IPC and Music graph\n", stream ? stream : "(null)", error);
  }
  errno = error;
  return player;
}
#endif
void *robot_music_media_open(const char *stream)
{
#ifdef CONFIG_MEDIA
  struct rv_music_handle *h = calloc(1, sizeof(*h));
  int error;

  if (h == NULL)
    {
      errno = ENOMEM;
      return NULL;
    }

  /* The Agent follows the same OpenVela Media API sequence as mediatool:
   * open stream, prepare the supplied URL, then start.  A failed native open
   * remains a native Media error; there is deliberately no HTTP/MP3 fallback.
   */
  h->player = open_native_media(stream);
  if (h->player == NULL)
    {
      error = errno ? errno : EIO;
      free(h);
      errno = error;
      return NULL;
    }

  printf("[RV-MUSIC] backend=native-media api=open/prepare/start\n");
  return h;
#else
  (void)stream;
  errno = ENOSYS;
  printf("[RV-MUSIC] native OpenVela Media is disabled; refusing alternate decoder\n");
  return NULL;
#endif
}
int robot_music_media_close(void *handle,int pending)
{
  struct rv_music_handle *h=handle;if(!h)return -EINVAL;
  pthread_mutex_lock(&music_lock);
  h->closing=true;
  if(active_music==h)active_music=NULL;
  while(h->users)pthread_cond_wait(&music_changed,&music_lock);
  pthread_mutex_unlock(&music_lock);
#ifdef CONFIG_MEDIA
  int r = media_player_close(h->player,pending);
#endif
#ifndef CONFIG_MEDIA
  int r = -ENOSYS;
  (void)pending;
#endif
  free(h);return r;
}
int robot_music_media_prepare(void *handle,const char *url,const char *options)
{
  struct rv_music_handle *h=handle;if(!h)return -EINVAL;
#ifdef CONFIG_MEDIA
  return media_player_prepare(h->player,url,options);
#else
  (void)url;(void)options;return -ENOSYS;
#endif
}
int robot_music_media_set_event_callback(void *handle,void *cookie,robot_music_event_cb cb)
{
  struct rv_music_handle *h=handle;if(!h)return -EINVAL;
#ifdef CONFIG_MEDIA
  return media_player_set_event_callback(h->player,cookie,cb);
#else
  (void)cookie;(void)cb;return -ENOSYS;
#endif
}
int robot_music_media_start(void *handle)
{
  struct rv_music_handle *h=handle;if(!h)return -EINVAL;
#ifndef CONFIG_MEDIA
  return -ENOSYS;
#else
  pthread_mutex_lock(&music_lock);h->users++;pthread_mutex_unlock(&music_lock);
  unsigned long run=robot_voice_music_run_id?robot_voice_music_run_id():0;
  int ret=media_player_start(h->player);
  pthread_mutex_lock(&music_lock);
  if(!ret&&!h->closing){h->started=true;h->run=run;active_music=h;}
  h->users--;pthread_cond_broadcast(&music_changed);pthread_mutex_unlock(&music_lock);
  return ret;
#endif
}
int robot_music_media_stop(void *handle)
{
  struct rv_music_handle *h=handle;if(!h)return -EINVAL;
#ifndef CONFIG_MEDIA
  return -ENOSYS;
#else
  pthread_mutex_lock(&music_lock);h->users++;pthread_mutex_unlock(&music_lock);
  int ret=media_player_stop(h->player);
  pthread_mutex_lock(&music_lock);
  if(!ret)h->started=false;
  h->users--;pthread_cond_broadcast(&music_changed);pthread_mutex_unlock(&music_lock);
  return ret;
#endif
}
int robot_music_media_pause(void *handle)
{
  struct rv_music_handle *h=handle;if(!h)return -EINVAL;
