  if (status < 200 || status >= 300) s->cancel = true;
  if (!s->cancel && s->used && !s->first_logged)
    RV_EVENT("[耗时][Flash分句] 流结束后提交尾句=%lldms\n",
      rv_elapsed_ms(s->started_ms, robot_voice_now_ms()));
