    int idx = MEDIA_VOL_MIN_IDX + (int)round((double)vol * (MEDIA_VOL_MAX_IDX - MEDIA_VOL_MIN_IDX) / 100.0);

    if (idx < MEDIA_VOL_MIN_IDX) {
        idx = MEDIA_VOL_MIN_IDX;
    }

    if (idx > MEDIA_VOL_MAX_IDX) {
        idx = MEDIA_VOL_MAX_IDX;
    }

    return idx;
