      dst[i * 4]     = (uint8_t)(sample & 0xff);
      dst[i * 4 + 1] = (uint8_t)((uint32_t)sample >> 8);
      dst[i * 4 + 2] = (uint8_t)((uint32_t)sample >> 16);
      dst[i * 4 + 3] = (uint8_t)((uint32_t)sample >> 24);
