static int rv_drain(struct rv_playback_s *pb)
{
  int result = 0;
  int ret;

  for (;;)
    {
      ret = rv_get_result(pb);
      if (ret < 0 && result >= 0)
        {
          result = ret;
        }

      if (rv_get_inflight(pb) == 0)
        {
          return result;
        }

      ret = nxsem_wait_uninterruptible(&pb->i2s_done);
      if (ret < 0)
        {
          return ret;
        }
    }
}

