  nxsem_post(&sink->pace_lock);

  if (queued > 0)
    {
      /* The normal worker path returns every copied APB with the error
       * before it emits the terminal IOERR/COMPLETE callbacks. */
      nxsem_post(&sink->pace_data);
      return;
    }

