  ret = pthread_attr_init(&attr);
  if (ret != 0)
    {
      ret = -ret;
      goto fail_started;
    }

  ret = rv_thread_attributes(&attr, RV_WORKER_STACK, RV_WORKER_PRIORITY);
  if (ret != 0)
