static int abufsrc_proccess_command(AVFilterContext *ctx, const char *cmd, const char *args,
    char *res, int res_len, int flags)
{
    BuffSrcPriv *priv = ctx->priv;
    int ret = 0;
    int i;

    if (!cmd)
        return AVERROR(EINVAL);

    av_log(ctx, AV_LOG_INFO, "cmd:%s args:%s\n", cmd, args);
    if (!av_strcasecmp(cmd, "link")) {
        int (*on_event_cb)(void *udata, int evt, int64_t args);
        int format, sample_rate, channels;
        void *udata;

        if (!args)
            return AVERROR(EINVAL);

        if (sscanf(args, "%p %p fmt=%d:rate=%d:ch=%d", &on_event_cb, &udata, &format, &sample_rate, &channels) != 5)
            return AVERROR(EINVAL);

        priv->next_pts = 0;
        priv->paused = false;

        priv->sample_fmt = format;
        priv->sample_rate = sample_rate;
        av_channel_layout_default(&priv->ch_layout, channels);

        abufsrc_set_event_cb(ctx, on_event_cb, udata);

        for (i = 0; i < ctx->nb_outputs; i++) {
            if (priv->map[i] == ROUTE_ON) {
                avfilter_forward_command(ctx, i, NULL, "play", NULL, NULL, 0, 0);
            }

            ret = volume_init(&priv->vol_ctx[i], format, priv->precision);
            volume_set(&priv->vol_ctx[i], priv->player_volume * priv->volume[i]);
        }

        return ret;
    } else if (!av_strcasecmp(cmd, "unlink")) {
        if (priv->frame)
            ret = abufsrc_fadeout_last_frame(ctx);

        if (priv->on_event_cb)
            priv->on_event_cb(priv->on_event_cb_udata, -1, 0);

        for (i= 0; i < priv->nb_outputs; i++) {
            if (priv->map && priv->map[i] == ROUTE_ON) {
                ff_outlink_set_status(ctx->outputs[i], AVERROR_EOF, AV_NOPTS_VALUE);
                avfilter_forward_command(ctx, i, NULL, "pause", NULL, NULL, 0, 0);
            }

            volume_uninit(&priv->vol_ctx[i]);
        }

        priv->sample_fmt = AV_SAMPLE_FMT_NONE;
        priv->sample_rate = 0;
        av_channel_layout_uninit(&priv->ch_layout);

        abufsrc_set_event_cb(ctx, NULL, NULL);


        return ret;
    } else if (!av_strcasecmp(cmd, "map")) {
        int *old_map = NULL;

        if (!priv->map)
            return AVERROR(EINVAL);

        old_map = av_calloc(priv->nb_outputs, sizeof(*old_map));
        if (!old_map)
            return AVERROR(ENOMEM);

        memcpy(old_map, priv->map, priv->nb_outputs * sizeof(*old_map));

        ret = avfilter_parse_mapping(args, &priv->map, priv->nb_outputs);
        if (ret < 0) {
            av_freep(&old_map);
            return ret;
        }

        for (i = 0; i < priv->nb_outputs && old_map; i++) {
            if (old_map[i] != priv->map[i]) {
                if (old_map[i] == ROUTE_ON && priv->map[i] == ROUTE_OFF) {
                    ff_outlink_set_status(ctx->outputs[i], AVERROR_EOF, AV_NOPTS_VALUE);
                    avfilter_forward_command(ctx, i, NULL, "pause", NULL, NULL, 0, 0);
                } else if (old_map[i] == ROUTE_OFF && priv->map[i] == ROUTE_ON) {
                    FilterLinkInternal *li = ff_link_internal(ctx->outputs[i]);
                    li->frame_wanted_out = 1;
                    if (!ff_outlink_get_status(ctx->outputs[i]))
                        avfilter_forward_command(ctx, i, NULL, "play", NULL, NULL, 0, 0);
                }
            }
        }

        av_freep(&old_map);
        ff_filter_set_ready(ctx, 100);
        return ret;
    } else if (!av_strcasecmp(cmd, "get_parameter")) {
        if (!args || res_len <= 0)
            return AVERROR(EINVAL);

        return abufsrc_get_parameter(ctx, args, res, res_len);
    } else if (!av_strcasecmp(cmd, "set_parameter")) {
        if (!args)
            return AVERROR(EINVAL);

        return abufsrc_set_parameter(ctx, args);
    } else if (!av_strcasecmp(cmd, "pause")) {
        priv->paused = true;
        if (priv->frame)
            ret = abufsrc_fadeout_last_frame(ctx);

        for (i = 0; i < ctx->nb_outputs; i++) {
            if (priv->map && priv->map[i] == ROUTE_ON)
                avfilter_forward_command(ctx, i, NULL, "pause", NULL, NULL, 0, 0);
        }

        return 0;
    } else if (!av_strcasecmp(cmd, "resume")) {
        priv->paused = false;
        for (i = 0; i < ctx->nb_outputs; i++) {
            if (priv->map && priv->map[i] == ROUTE_ON)
                avfilter_forward_command(ctx, i, NULL, "play", NULL, NULL, 0, 0);
        }

        ff_filter_set_ready(ctx, 100);
        return 0;
    } else if (!av_strcasecmp(cmd, "dump")) {
        return abufsrc_dump_info(ctx, res, res_len);
    } else {
        return ff_filter_process_command(ctx, cmd, args, res, res_len, flags);
    }
}

  syslog(LOG_INFO,
         "[MEDIA-BRIDGE] configure fmt=%u rate=%lu ch=%u bits=%u\n",
         caps->ac_subtype, (unsigned long)sample_rate, channels, bits);

  if (sample_rate != CONTEST_MEDIA_RATE ||
      channels != CONTEST_MEDIA_CHANNELS ||
      bits != CONTEST_MEDIA_BITS)
    {
      syslog(LOG_ERR,
             "[MEDIA-BRIDGE] format rejected expected=%uHz/%uch/%ubit\n",
             CONTEST_MEDIA_RATE, CONTEST_MEDIA_CHANNELS, CONTEST_MEDIA_BITS);
      return -EINVAL;
    }

  sink->sample_rate = sample_rate;
  sink->channels = channels;
  sink->bits = bits;
  sink->configured = true;
  /* New configuration is a new stream, even after the preceding FINAL. */
  if (!sink->playback_open)
    {
      __atomic_store_n(&sink->completion_sent, false, __ATOMIC_RELEASE);
      sink->eos = false;
      sink->stream_error = OK;
    }
  return OK;
}

static int contest_media_shutdown(FAR struct audio_lowerhalf_s *dev)
{
  FAR struct contest_media_sink_s *sink =
    (FAR struct contest_media_sink_s *)dev;
  int ret;

  (void)contest_media_abort_pending(sink);
  ret = contest_media_finish_playback(sink, false);

  sink->configured = false;
  return ret;
}

#ifdef CONFIG_AUDIO_MULTI_SESSION
static int contest_media_start(FAR struct audio_lowerhalf_s *dev,
                               FAR void *session)
#else
static int contest_media_start(FAR struct audio_lowerhalf_s *dev)
#endif
{
  FAR struct contest_media_sink_s *sink =
    (FAR struct contest_media_sink_s *)dev;

#ifdef CONFIG_AUDIO_MULTI_SESSION
  (void)session;
#endif

  int ret = contest_media_open_playback(sink);
  if (ret < 0) return ret;
  ret = contest_media_start_backend(sink);
  if (ret == OK && sink->eos)
    {
      ret = robot_audio_playback_end_input();
    }
  syslog(LOG_INFO, "[MEDIA-BRIDGE] START DMA-backed rc=%d\n", ret);
  return ret;
}

#ifndef CONFIG_AUDIO_EXCLUDE_STOP
#ifdef CONFIG_AUDIO_MULTI_SESSION
static int contest_media_stop(FAR struct audio_lowerhalf_s *dev,
                              FAR void *session)
#else
static int contest_media_stop(FAR struct audio_lowerhalf_s *dev)
#endif
{
  FAR struct contest_media_sink_s *sink =
    (FAR struct contest_media_sink_s *)dev;
  int ret;

#ifdef CONFIG_AUDIO_MULTI_SESSION
  (void)session;
#endif

  syslog(LOG_INFO, "[MEDIA-BRIDGE] STOP -> immediate abort/close\n");

  /*
   * An explicit AUDIOIOC_STOP is a user/tool stop, not natural end-of-file.
   * Do not call robot_audio_playback_finish() here: finish() drains the
   * playback ring by design, which makes a "stop" command continue playing
