static int rv_wait_slot(struct rv_playback_s *pb,
                        struct rv_slot_s *slot)
{
  int ret;

  if (pb == NULL || slot == NULL)
    {
      return -EINVAL;
    }

  for (;;)
    {
      int inflight;
      int result;

      ret = rv_lock(pb);
      if (ret < 0)
        {
          return ret;
        }

      inflight = slot->inflight;
      result = slot->result;
      rv_unlock(pb);

      if (!inflight)
        {
          if (result < 0 && result != -ECANCELED)
            {
              return result;
            }
          return 0;
        }

      if (pb->stopped)
        {
          return -ECANCELED;
        }

      ret = nxsem_wait_uninterruptible(&slot->done);
      if (ret < 0)
        {
          return ret;
        }
    }
}

