        .settings_commit = settings_core_commit,
#if CONFIG_BLE_MESH_DEINIT
        .settings_deinit = settings_core_deinit,
        .settings_erase = settings_core_erase,
#endif /* CONFIG_BLE_MESH_DEINIT */
