    printf("[RV-PB] native Media buffer=%zuB (~%ums) prebuffer=%uB (~%ums) "
           "mode=OpenVela-Media\n",
           g_pb.ring.capacity,
           (unsigned int)(g_pb.ring.capacity * 1000ULL /
