static void *rv_worker(void *arg)
{
  struct rv_playback_s *pb = arg;
  uint8_t block[RV_SOURCE_BLOCK_BYTES];
  unsigned int slot_index = 0;
  int primed_slots = 0;
  int ret = 0;
  bool terminal_tail = false;

  pb->state = RV_STATE_PREBUFFER;

  if (pb->native_media)
    {
      printf("[RV-PB] native worker ready slots=%u prebuffer=%u\n",
             pb->slot_count, pb->start_prebuffer);
    }

  while (!pb->stopped)
    {
      struct rv_slot_s *slot;

      terminal_tail = false;
      size_t available;
      size_t want;
      size_t got;
      bool prime_silence = false;
      bool final_block = false;

      ret = rv_get_result(pb);
      if (ret < 0)
        {
          printf("[RV-PB] I2S worker error=%d\n", ret);
          break;
        }

      if (pb->state == RV_STATE_PREBUFFER || pb->state == RV_STATE_REBUFFER)
        {
          size_t threshold = pb->state == RV_STATE_PREBUFFER ?
                             pb->start_prebuffer : RV_REBUFFER_BYTES;
          const char *from = pb->state == RV_STATE_PREBUFFER ?
                             "PREBUFFER" : "REBUFFER";

          ret = rv_wait_buffer(pb, threshold);
          if (ret < 0)
            {
              break;
            }

          if (pb->stopped) { ret = -ECANCELED; break; }
          available = rv_ring_count(pb);
          if (available >= 2)
            {
              pb->state = RV_STATE_PLAYING;
              primed_slots = 0;
              slot_index = 0;

              if (pb->ring_min_play == (size_t)-1)
                {
                  pb->ring_min_play = available;
                }

              if (available > pb->ring_max_play)
                {
                  pb->ring_max_play = available;
                }

              (void)from;
            }
          else if (pb->eos)
            {
              pb->state = RV_STATE_DRAINING;
            }
          else
            {
              continue;
            }
        }

      if (pb->state == RV_STATE_DRAINING)
        {
          break;
        }

      slot = &pb->slots[slot_index];

      /* Prime the negotiated number of slots, then refill in that same
       * round-robin order. Each source block expands to the fixed wire size;
       * a larger ring gives more callback/worker scheduling headroom. */
      if (primed_slots >= pb->slot_count)
        {
          ret = rv_wait_slot(pb, slot);
          if (ret < 0)
            {
              break;
            }
        }

      available = rv_ring_count(pb);

      /* No producer wait is permitted once the immutable DMA ring runs.
       * cache_until_eos voice has all its PCM here, so no interior gap exists. */
      if (pb->native_media &&
          __atomic_load_n(&pb->media_paused, __ATOMIC_ACQUIRE))
        {
          /* Keep the immutable hardware ring fresh while preserving every
           * queued real sample. A pause is neither EOS nor a short tail. */
          memset(block, 0, sizeof(block));
          want = RV_SOURCE_BLOCK_BYTES;
          prime_silence = true;
        }
      else if (pb->voice_live && !pb->eos &&
          available < 2 * RV_SOURCE_BLOCK_BYTES)
        {
          /* Retain one real block until EOS is known so even an exact block
           * tail receives AUDIO_APB_FINAL. Never wait on a running immutable
           * DMA slot: overwrite it with silence during a producer gap. */
          memset(block, 0, sizeof(block));
          want = RV_SOURCE_BLOCK_BYTES;
          prime_silence = true;
          pb->underrun_count++;
          pb->silence_blocks++;
          pb->gap_run++;
          if (pb->gap_run > pb->max_gap_run) pb->max_gap_run = pb->gap_run;
        }
      else if (available >= RV_SOURCE_BLOCK_BYTES)
        {
          want = RV_SOURCE_BLOCK_BYTES;
          pb->gap_run = 0;
          if (pb->eos && available == RV_SOURCE_BLOCK_BYTES &&
              pb->stop_on_short_underrun)
            {
              final_block = true;
              terminal_tail = true;
            }
        }
      else if (pb->eos && available > 0)
        {
          want = available & ~(size_t)1;
          final_block = pb->stop_on_short_underrun;
          terminal_tail = final_block;
          if (want == 0)
            {
              (void)rv_ring_read(pb, block, available);
              continue;
            }
        }
      else if (pb->eos && available == 0)
        {
          if (pb->stop_on_short_underrun)
            {
              /*
               * Exact finite-file EOF: there is no real PCM left.  Do not
               * manufacture ten extra silent submissions just to walk the
               * cyclic ring.  Drain the already-submitted real blocks and
               * stop.
               */

              pb->eos_silence_rounds = 0;
              pb->state = RV_STATE_DRAINING;
              break;
            }

          if (pb->eos_silence_rounds < pb->slot_count)
            {
              memset(block, 0, sizeof(block));
              want = RV_SOURCE_BLOCK_BYTES;
              prime_silence = true;
              pb->eos_silence_rounds++;
              pb->silence_blocks++;
            }
          else
            {

              pb->eos_silence_rounds = 0;
              pb->state = RV_STATE_DRAINING;
              break;
            }
        }

      else
        {
          /*
           * Legacy streaming-music path only: NEVER stop feeding the immutable cyclic DMA ring after
           * PLAYING has started.
           *
           * The lower half keeps its 16 frozen descriptors circulating even
           * when the upper layer has no logical requests in flight.  The old
           * REBUFFER path stopped submitting new payloads while waiting for
           * 48 KiB of producer data; hardware then replayed the stale tail
           * still stored in those DMA slots ("...变化量量量量...").
           *
           * Keep cadence tied to rv_wait_slot()/DMA completion instead:
           *   - if a short aligned tail exists, play it and let
           *     rv_queue_slot() zero-pad the rest of the 2048-byte wire slot;
           *   - if no complete PCM16 sample exists, submit one full silent
           *     source block.
           *
           * A producer stall can therefore create silence, never stale-audio
           * repetition. Complete-cache voice must never enter this path.
           */
          if (pb->cache_until_eos)
            {
              /* Complete-cache voice can never starve. Stop on invariant
               * failure instead of adding any silence in the utterance. */
              ret = -EPROTO;
              break;
            }
          pb->underrun_count++;
          pb->gap_run++;
          if (pb->gap_run > pb->max_gap_run) pb->max_gap_run = pb->gap_run;

          if (pb->native_media &&
              (pb->underrun_count == 1 ||
               (pb->underrun_count % 512) == 0))
            {
              printf("[RV-PB] native Media PCM underflow=%lu buffered=%zu/%zu "
                     "silence=%lu\n",
                     (unsigned long)pb->underrun_count, available,
                     pb->ring.capacity,
                     (unsigned long)pb->silence_blocks);
            }

          if (available >= sizeof(int16_t))
            {
              want = available;
              if (want > RV_SOURCE_BLOCK_BYTES)
                {
                  want = RV_SOURCE_BLOCK_BYTES;
                }

              want &= ~(size_t)1;

              if (pb->stop_on_short_underrun && !pb->native_media)
                {
                  terminal_tail = true;
                  final_block = true;
                  pb->eos = 1;
                  (void)0;
                }
              else if (pb->underrun_count <= 4 ||
                       (pb->underrun_count % 32) == 0)
                {
                  (void)0;
                }
            }
          else
            {
              memset(block, 0, sizeof(block));
              want = RV_SOURCE_BLOCK_BYTES;
              prime_silence = true;

              if (available > 0)
                {
                  /* Preserve PCM16 alignment: discard a lone impossible
                   * byte rather than carrying it into the next sample. */
                  (void)rv_ring_read(pb, block, available);
                }

              if (pb->stop_on_short_underrun && !pb->native_media)
                {
                  (void)0;
                  pb->eos = 1;
                  pb->stopped = 1;
                  pb->terminal_tail_done = 1;

                  if (pb->i2s != NULL && pb->i2s_started)
                    {
                      pb->i2s_started = 0;
                      I2S_IOCTL(pb->i2s, AUDIOIOC_STOP, 0);
                    }

                  rv_signal_all(pb);
                  break;
                }

              if (pb->underrun_count <= 4 ||
                  (pb->underrun_count % 32) == 0)
                {
                  (void)0;
                }
            }
        }

      if (prime_silence)
        {
          got = want;
        }
      else
        {
          got = rv_ring_read(pb, block, want);
          if (got == 0)
            {
              continue;
            }
        }

      ret = rv_queue_slot(pb, slot, block, got, final_block,
                          prime_silence ? 0 : got);
      if (ret < 0)
        {
          if (ret != -ECANCELED)
            {
              printf("[RV-PB] queue slot=%u failed=%d\n",

              printf("[RV-PB] queue slot=%u failed=%d\n",
                     slot_index, ret);
            }
          break;
        }

      if (!pb->dma_start_ms &&
          (primed_slots + 1 >= pb->slot_count || final_block)) {
        /* A short finite chain starts on its FINAL send too. This software
         * submission timestamp is not an acoustic measurement. */
        pb->dma_start_ms = rv_audio_now_ms();
        if (pb->voice_live && pb->sentence)
          RV_EVENT("[耗时][TTS播放] run=%lu seq=%u 请求到播放提交=%lldms 音频交付到播放提交=%lldms\n",
            pb->run_id, pb->sentence, rv_elapsed_ms(pb->tts_start_ms, pb->dma_start_ms),
            rv_elapsed_ms(pb->tts_ready_ms, pb->dma_start_ms));
      }

      if (terminal_tail)
        {
          int tail_ret = rv_wait_slot(pb, slot);

          if (tail_ret < 0 && tail_ret != -ECANCELED && ret >= 0)
            {
              ret = tail_ret;
            }



          pb->terminal_tail_done = 1;
          pb->stopped = 1;
          pb->state = RV_STATE_STOPPED;

          if (pb->i2s != NULL && pb->i2s_started)
            {
              pb->i2s_started = 0;
              I2S_IOCTL(pb->i2s, AUDIOIOC_STOP, 0);
            }

          rv_signal_all(pb);
          break;
        }

      if (primed_slots < pb->slot_count)
        {
          primed_slots++;
        }

      slot_index = (slot_index + 1) % pb->slot_count;
    }

  /* Do not stop I2S before the logical slots have completed. */
  {
    unsigned int i;

    for (i = 0; i < pb->slot_count; i++)
      {
        int slot_ret = rv_wait_slot(pb, &pb->slots[i]);
        if (slot_ret < 0 && slot_ret != -ECANCELED && ret >= 0)
          {
            ret = slot_ret;
          }
      }
  }

  if (!pb->stopped)
    {
      int drain_ret = rv_drain(pb);
      if (drain_ret < 0 && ret >= 0)
        {
          ret = drain_ret;
        }
    }

  if (rv_lock(pb) == 0)
    {
      if (ret < 0 && ret != -ECANCELED && pb->i2s_result >= 0)
        {
          pb->i2s_result = ret;
        }
      pb->worker_exited = 1;
      pb->state = RV_STATE_STOPPED;
      rv_unlock(pb);
    }
  else
    {
      pb->worker_exited = 1;
      pb->state = RV_STATE_STOPPED;
    }

  pb->dma_done_ms = rv_audio_now_ms();
  rv_signal_all(pb); /* Wake a bounded producer if the DMA worker failed. */
  nxsem_post(&pb->i2s_done);
  return NULL;
}

static void rv_signal_all(struct rv_playback_s *pb)
{
  unsigned int i;

  nxsem_post(&pb->ring_data);
  nxsem_post(&pb->ring_space);
  nxsem_post(&pb->i2s_done);

  for (i = 0; i < RV_MAX_INFLIGHT; i++)
    {
      nxsem_post(&pb->slots[i].done);
    }
}

static void rv_release_slot_buffers(struct rv_playback_s *pb)
{
  unsigned int i;
  for (i = 0; i < RV_MAX_INFLIGHT; i++)
    {
      if (pb->slots[i].apb != NULL)
        {
          apb_free(pb->slots[i].apb);
          pb->slots[i].apb = NULL;
        }

    }
}

static int rv_prepare_slot_buffers(struct rv_playback_s *pb, unsigned int count)
{
  unsigned int i;
  rv_release_slot_buffers(pb);
  for (i = 0; i < count; i++)
    {
      struct audio_buf_desc_s desc;
      memset(&desc, 0, sizeof(desc));

static void contest_i2s_tx_worker(FAR void *arg)
{
  FAR struct contest_i2s_tx_s *priv = arg;
  FAR struct contest_i2s_xfer_s *xfer;
  FAR struct ap_buffer_s *apb;
  i2s_callback_t callback;
  FAR void *callback_arg;
  uint32_t irq_status;
  size_t nbytes;
  int result;
  irqstate_t flags;

  for (;;)
    {
      flags = spin_lock_irqsave(&priv->lock);
      xfer = priv->done_head;
      if (xfer == NULL)
        {
          spin_unlock_irqrestore(&priv->lock, flags);
          return;
        }

      priv->done_head = xfer->next;
      if (priv->done_head == NULL)
        {
          priv->done_tail = NULL;
        }

      xfer->next = NULL;
      apb = xfer->apb;
      callback = xfer->callback;
      callback_arg = xfer->arg;
      nbytes = xfer->nbytes;
      result = xfer->result;
      irq_status = priv->irq_status;

      /* The APB binding and descriptor links stay fixed for this run. */
      xfer->apb = NULL;
      xfer->callback = NULL;
      xfer->arg = NULL;
      xfer->nbytes = 0;
      xfer->result = OK;
      xfer->done_queued = false;
      xfer->in_use = false;
      xfer->terminal = false;

      /*
       * Mirror the clean ESP-IDF reference driver's
       * auto_clear_after_cb=true behavior.
       *
       * This lower-half uses an immutable cyclic DMA descriptor ring whose
       * private payload buffer stays attached to the descriptor.  Once a slot
       * has completed, clear that private payload BEFORE publishing the upper
       * callback.  If the producer is late refilling the slot, the next ring
       * wrap therefore emits digital zero instead of replaying stale PCM.
       *
       * Normal completions reach this worker immediately after OUT_DONE; GDMA
       * has already consumed this private payload.  The final terminal-short
       * path still waits for FIFO/shifter drain before publishing completion.
       * AUDIOIOC_STOP may free DMA buffers before a canceled callback runs,
       * hence the NULL guard.
       */
      if (xfer->dma_data != NULL)
        {
          memset(xfer->dma_data, 0, CONTEST_I2S_TX_SLOT_BYTES);
          up_clean_dcache((uintptr_t)xfer->dma_data,
                          (uintptr_t)xfer->dma_data +
                          CONTEST_I2S_TX_SLOT_BYTES);
        }

      spin_unlock_irqrestore(&priv->lock, flags);

      if (result < 0)
        {
          syslog(LOG_ERR,
                 "[C-I2S] tx completion failed irq=%08lx bytes=%zu rc=%d\n",
                 (unsigned long)irq_status, nbytes, result);
        }

      if (callback != NULL && apb != NULL)
        {
          callback(&priv->dev, apb, callback_arg, result);
          apb_free(apb);
        }

      flags = spin_lock_irqsave(&priv->lock);
      DEBUGASSERT(priv->callbacks_pending > 0);
      priv->callbacks_pending--;
      spin_unlock_irqrestore(&priv->lock, flags);
    }
}


static void contest_i2s_tx_terminal_stop_worker(FAR void *arg)
{
  FAR struct contest_i2s_tx_s *priv = arg;
  unsigned int slot;
  bool schedule = false;
  bool stopped = false;
  irqstate_t flags;

  flags = spin_lock_irqsave(&priv->lock);

  if (!priv->terminal_stop_pending)
    {
      spin_unlock_irqrestore(&priv->lock, flags);
      return;
    }

  slot = priv->terminal_stop_slot;
  priv->terminal_stop_pending = false;

  /*
   * The terminal descriptor already has next=NULL, so GDMA cannot wrap back
   * into stale PCM. Keep I2S alive until this delayed worker runs so the
   * peripheral FIFO / shifter can emit the final real samples cleanly.
   */
  if (priv->hw_running)
    {
      contest_i2s_tx_stop_hw(priv);
      stopped = true;
    }

  /*
   * Publish terminal completion only after the hardware drain. The upper
   * playback layer may issue AUDIOIOC_STOP immediately after this callback.
   */
  if (slot < priv->ring_slots &&
      priv->xfer[slot].in_use &&
      !priv->xfer[slot].done_queued)
    {
      schedule = contest_i2s_tx_complete_slot(priv, slot);
    }

  spin_unlock_irqrestore(&priv->lock, flags);

  if (stopped)
    {
      syslog(LOG_INFO,
             "[C-I2S] tx terminal drain complete slot=%u delay_ms=%u\n",
             slot, CONTEST_I2S_TX_FIFO_DRAIN_MS);
    }

  if (schedule && work_available(&priv->tx_work))
    {
      work_queue(HPWORK, &priv->tx_work, contest_i2s_tx_worker, priv, 0);
    }
}


static int contest_i2s_tx_interrupt(int irq, FAR void *context, FAR void *arg)
{
  FAR struct contest_i2s_tx_s *priv = arg;
  FAR struct contest_i2s_xfer_s *xfer;
  uint32_t status;
  unsigned int slot;
  unsigned int i;
  bool schedule = false;
  bool terminal_stop_schedule = false;
  bool fatal = false;
  irqstate_t flags;

  (void)irq;
  (void)context;

  /* OUT_DONE is the per-descriptor completion event for the sequential ring. */
  status = GET_GDMA_CH_REG(DMA_OUT_INT_ST_CH0_REG, priv->dma_channel);
  SET_GDMA_CH_REG(DMA_OUT_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);

  if ((status & (DMA_OUT_DONE_CH0_INT_ST |
                 DMA_OUT_DSCR_ERR_CH0_INT_ST)) == 0)
    {
      return OK;
    }

  flags = spin_lock_irqsave(&priv->lock);
  priv->irq_status = status;

  if (!priv->streaming || !priv->hw_running)
    {
      spin_unlock_irqrestore(&priv->lock, flags);
      return OK;
    }

  if ((status & DMA_OUT_DSCR_ERR_CH0_INT_ST) != 0)
    {
      fatal = true;
    }
  else
    {
      /* The descriptor ring is immutable and advances in slot order.  Its
       * payload remains stable until the deferred callback below runs; do not
       * wait one extra ring block and replay stale PCM. */
      if ((status & DMA_OUT_DONE_CH0_INT_ST) != 0)
        {
          priv->done_irq_count++;

          bool terminal_done;

          slot = priv->done_index;
          terminal_done = priv->xfer[slot].terminal;

          if (terminal_done)
            {
              /*
               * OUT_DONE means GDMA finished the descriptor, but the I2S FIFO
               * / shifter may still contain the final samples. Do not stop HW
               * or publish the terminal callback until the drain delay passes.
               */
              priv->streaming = false;
              priv->terminal_stop_pending = true;
              priv->terminal_stop_slot = (uint8_t)slot;
              terminal_stop_schedule = true;
            }
          else if (contest_i2s_tx_complete_slot(priv, slot))
            {
              schedule = true;
            }

          priv->done_index = (slot + 1) % priv->ring_slots;
          if (slot + 1 == priv->ring_slots)
            {
              priv->ring_wrap_count++;
            }

        }

    }

  if (fatal)
    {
      for (i = 0; i < CONTEST_I2S_TX_RING_SLOTS; i++)
        {
          xfer = &priv->xfer[i];
          if (xfer->in_use && !xfer->done_queued)
            {
              xfer->result = -EIO;
              xfer->done_queued = true;
              contest_i2s_tx_done_push(priv, xfer);
              schedule = true;
            }
        }

      priv->queued_slots = 0;
      priv->streaming = false;
      priv->terminal_stop_pending = false;
      contest_i2s_tx_stop_hw(priv);
    }

  if (terminal_stop_schedule)
    {
      if (work_available(&priv->tx_stop_work))
        {
          work_queue(HPWORK, &priv->tx_stop_work,
                     contest_i2s_tx_terminal_stop_worker, priv,
                     MSEC2TICK(CONTEST_I2S_TX_FIFO_DRAIN_MS));
        }
      else
        {
          /* Defensive fallback: never leave I2S running forever. */
          priv->terminal_stop_pending = false;
          contest_i2s_tx_stop_hw(priv);
          if (contest_i2s_tx_complete_slot(priv, priv->terminal_stop_slot))
            {
              schedule = true;
            }
          syslog(LOG_ERR,
                 "[C-I2S] terminal drain worker busy; immediate fallback\n");
        }
    }

  if (schedule && work_available(&priv->tx_work))
    {
      /*
       * Normal OUT_DONE callbacks are immediate.  Keeping the old 8 ms delay
       * here increased refill latency and let the cyclic DMA ring run ahead of
       * the logical producer near EOF.  Terminal FIFO drain is handled only by
       * tx_stop_work above.
       */
      work_queue(HPWORK, &priv->tx_work, contest_i2s_tx_worker, priv, 0);
    }

  spin_unlock_irqrestore(&priv->lock, flags);
  return OK;
}


static int contest_i2s_txchannels(FAR struct i2s_dev_s *dev,
                                  uint8_t channels)
{
  FAR struct contest_i2s_tx_s *priv = (FAR struct contest_i2s_tx_s *)dev;

  syslog(LOG_INFO, "[C-I2S-DIAG] txchannels requested=%u\n", channels);

  /* One logical PCM channel is emitted in the physical left 32-bit slot. */
  if (channels != 1)
    {
      syslog(LOG_INFO, "[C-I2S-DIAG] txchannels rejected=%u expected=1\n",
             channels);
      return -ENOTSUP;
      return -ENOTSUP;
    }

  priv->channels = channels;
  contest_i2s_tx_set_channels(priv);
  syslog(LOG_INFO,
         "[C-I2S] tx format channels=1 width=32 dma_bytes=%u "
         "mode=mono-left frame=4B\n",
         CONTEST_I2S_TX_SLOT_BYTES);
  return OK;
}

static uint32_t contest_i2s_txsamplerate(FAR struct i2s_dev_s *dev,
                                         uint32_t rate)
{
  FAR struct contest_i2s_tx_s *priv = (FAR struct contest_i2s_tx_s *)dev;

  syslog(LOG_INFO, "[C-I2S-DIAG] txsamplerate requested=%lu expected=%u\n",
         (unsigned long)rate, CONTEST_I2S_TX_RATE);

  if (rate != CONTEST_I2S_TX_RATE)
    {
      syslog(LOG_ERR,
             "[C-I2S] reject tx rate=%lu expected=%u\n",
             (unsigned long)rate, CONTEST_I2S_TX_RATE);
      syslog(LOG_INFO, "[C-I2S-DIAG] txsamplerate rejected=%lu\n",
             (unsigned long)rate);
      return 0;
    }

  priv->rate = rate;
  contest_i2s_tx_set_rate(priv);

  syslog(LOG_INFO,
         "[C-I2S] tx rate applied GUIDE24=%lu bclk=%lu mclk=%lu "
         "conf1=%08lx clkm=%08lx div=%08lx\n",
         (unsigned long)priv->rate,
         (unsigned long)(priv->rate * CONTEST_I2S_TX_SLOTS * priv->data_width),
         (unsigned long)(priv->rate * CONTEST_I2S_MCLK_MULTIPLE),
         (unsigned long)getreg32(I2S_TX_CONF1_REG(CONTEST_I2S_TX_PORT)),
         (unsigned long)getreg32(I2S_TX_CLKM_CONF_REG(CONTEST_I2S_TX_PORT)),
         (unsigned long)getreg32(I2S_TX_CLKM_DIV_CONF_REG(CONTEST_I2S_TX_PORT)));

  syslog(LOG_INFO, "[C-I2S-DIAG] txsamplerate applied=%lu\n",
         (unsigned long)rate);

  return rate;
}

static uint32_t contest_i2s_txdatawidth(FAR struct i2s_dev_s *dev, int bits)
{
  FAR struct contest_i2s_tx_s *priv = (FAR struct contest_i2s_tx_s *)dev;

  syslog(LOG_INFO, "[C-I2S-DIAG] txdatawidth requested=%d wire_width=%u\n",
         bits, CONTEST_I2S_TX_WIDTH);

  if (bits != 16 && bits != CONTEST_I2S_TX_WIDTH)
    {
      syslog(LOG_INFO, "[C-I2S-DIAG] txdatawidth rejected=%d\n", bits);
      return 0;
    }

  priv->logical_width = bits;
  priv->data_width = CONTEST_I2S_TX_WIDTH;
  contest_i2s_tx_set_format(priv);
  contest_i2s_tx_set_rate(priv);
  syslog(LOG_INFO,
         "[C-I2S-DIAG] txdatawidth applied logical=%d wire_width=%u\n",
         bits, CONTEST_I2S_TX_WIDTH);
  return bits;
}



