  syslog(LOG_INFO,
         "[MEDIA-BRIDGE] RESUME playback_open=%d complete=%d -> no-op\n",
         sink->playback_open ? 1 : 0,
         sink->completion_sent ? 1 : 0);
  return OK;
}
