 380	/* Start the contest-local backend only from AUDIOIOC_START.  Media fills
 381	 * several APBs before that command; starting on the first enqueue gives the
 382	 * decoder an 85 ms ring and immediately triggers source-side xrun. */
 383	static int contest_media_start_backend(FAR struct contest_media_sink_s *sink)
 384	{
 385	  int ret;
 386	
 387	  ret = nxsem_wait_uninterruptible(&sink->playback_lock);
 388	  if (ret < 0)
 389	    {
 390	      return ret;
 391	    }
 392	
 393	  if (!sink->playback_open)
 394	    {
 395	      ret = -EINVAL;
 396	    }
 397	  else if (sink->started)
 398	    {
 399	      ret = OK;
 400	    }
 401	  else
 402	    {
 403	      ret = robot_audio_playback_start_native_media();
 404	      if (ret == OK)
 405	        {
 406	          sink->started = true;
 407	          sink->paused = false;
 408	          uint32_t now_ms = (uint32_t)contest_media_now_ms();
 409	          __atomic_store_n(&sink->started_ms, now_ms, __ATOMIC_RELEASE);
 410	          __atomic_store_n(&sink->last_pcm_ms, now_ms, __ATOMIC_RELEASE);
 411	        }
 412	    }
 413	
 414	  nxsem_post(&sink->playback_lock);
 415	  return ret;
 416	}
