 579	/* Return Media APBs at the PCM consumption rate.  The native playback ring
 580	 * and I2S DMA continue independently; waiting for each DMA callback here
 581	 * starves adevsink of APBs and makes it report a false xrun after four
 582	 * buffers.  Use one absolute timeline so scheduler delay does not accumulate
 583	 * into audible gaps. */
 584	static void contest_media_pace_delay(FAR struct contest_media_sink_s *sink,
 585	                                     size_t bytes)
 586	{
 587	  uint64_t duration;
 588	
 589	  if (bytes == 0)
 590	    {
 591	      return;
 592	    }
 593	
 594	  duration = ((uint64_t)bytes * 1000000ULL +
 595	              CONTEST_MEDIA_BYTES_PER_SEC - 1) /
 596	             CONTEST_MEDIA_BYTES_PER_SEC;
 597	
 598	  uint64_t now = contest_media_now_us();
 599	  if (!sink->pace_clock_valid || now == 0)
 600	    {
 601	      sink->pace_deadline_us = now + duration;
 602	      sink->pace_clock_valid = true;
 603	    }
 604	  else
 605	    {
 606	      sink->pace_deadline_us += duration;
 607	    }
 608	
 609	  for (;;)
 610	    {
 611	      if (contest_media_pace_aborted(sink))
 612	        {
 613	          return;
 614	        }
 615	
 616	      now = contest_media_now_us();
 617	      if (now == 0 || now >= sink->pace_deadline_us)
 618	        {
 619	          return;
 620	        }
 621	
 622	      uint64_t remain = sink->pace_deadline_us - now;
 623	      unsigned int slice = remain > CONTEST_MEDIA_PACE_SLICE_US ?
 624	                           CONTEST_MEDIA_PACE_SLICE_US :
 625	                           (unsigned int)remain;
 626	      usleep(slice);
 627	    }
 628	}
