 630	static bool contest_media_pop_apb(FAR struct contest_media_sink_s *sink,
 631	                                  FAR struct contest_media_pending_s *entry)
 632	{
 633	  if (nxsem_wait_uninterruptible(&sink->pace_lock) < 0)
 634	    {
 635	      return false;
 636	    }
 637	
 638	  if (sink->pace_count == 0)
 639	    {
 640	      nxsem_post(&sink->pace_lock);
 641	      return false;
 642	    }
 643	
 644	  *entry = sink->pending[sink->pace_head];
 645	  sink->pace_head = (sink->pace_head + 1) % CONTEST_MEDIA_PACE_QUEUE;
 646	  sink->pace_count--;
 647	  sink->pace_busy = true;
 648	
 649	  if (sink->pace_count == 0)
 650	    {
 651	      nxsem_post(&sink->pace_empty);
 652	    }
 653	
 654	  nxsem_post(&sink->pace_lock);
 655	  return true;
 656	}
