 658	/* Detect a stopped I2S DMA worker even when Media has not queued a FINAL
 659	 * buffer.  Without this poll, APBs already copied into the private PCM ring
 660	 * can be returned and the Media thread can then wait forever for an event. */
 661	static void contest_media_check_health(FAR struct contest_media_sink_s *sink)
 662	{
 663	  uint32_t now_ms;
 664	  uint32_t last_pcm_ms;
 665	  uint32_t started_ms;
 666	  uint64_t completed;
 667	  uint64_t pending;
 668	  unsigned int queued;
 669	  bool started;
 670	  int ret;
 671	
 672	  if (__atomic_load_n(&sink->completion_sent, __ATOMIC_ACQUIRE) ||
 673	      sink->stream_error < 0 || contest_media_pace_aborted(sink))
 674	    {
 675	      return;
 676	    }
 677	
 678	  ret = contest_media_progress(sink, &completed, &pending, &started);
 679	  if (!started)
 680	    {
 681	      return;
 682	    }
 683	
 684	  now_ms = (uint32_t)contest_media_now_ms();
 685	  last_pcm_ms = __atomic_load_n(&sink->last_pcm_ms, __ATOMIC_ACQUIRE);
 686	  started_ms = __atomic_load_n(&sink->started_ms, __ATOMIC_ACQUIRE);
 687	  if (ret >= 0 && !sink->eos &&
 688	      (uint32_t)(now_ms - (last_pcm_ms ? last_pcm_ms : started_ms)) >=
 689	      CONTEST_MEDIA_STALL_TIMEOUT_MS)
 690	    {
 691	      ret = -ETIMEDOUT;
 692	      syslog(LOG_ERR,
 693	             "[MEDIA-BRIDGE] no PCM input for %u ms; closing stalled stream\n",
 694	             CONTEST_MEDIA_STALL_TIMEOUT_MS);
 695	    }
 696	  else if (ret >= 0)
 697	    {
 698	      return;
 699	    }
 700	
 701	  sink->stream_error = ret;
 702	  sink->eos = true;
 703	  syslog(LOG_ERR,
 704	         "[MEDIA-BRIDGE] playback backend failed while streaming rc=%d; "
 705	         "closing and returning to caller\n", ret);
 706	
 707	  if (nxsem_wait_uninterruptible(&sink->pace_lock) < 0)
 708	    {
 709	      return;
 710	    }
 711	
 712	  queued = sink->pace_count;
 713	  nxsem_post(&sink->pace_lock);
 714	
 715	  if (queued > 0)
 716	    {
 717	      /* The normal worker path returns every copied APB with the error
 718	       * before it emits the terminal IOERR/COMPLETE callbacks. */
 719	      nxsem_post(&sink->pace_data);
 720	      return;
 721	    }
 722	
 723	  (void)contest_media_finish_playback(sink, false);
 724	  contest_media_complete(sink);
 725	}
