 727	static void *contest_media_pace_worker(FAR void *arg)
 728	{
 729	  FAR struct contest_media_sink_s *sink = arg;
 730	
 731	  syslog(LOG_INFO,
 732	         "[MEDIA-BRIDGE] DMA completion worker queue=%u\n",
 733	         CONTEST_MEDIA_PACE_QUEUE);
 734	
 735	  for (;;)
 736	    {
 737	      struct contest_media_pending_s entry;
 738	
 739	      int wait_ret = nxsem_tickwait_uninterruptible(
 740	        &sink->pace_data, MSEC2TICK(CONTEST_MEDIA_HEALTH_POLL_MS));
 741	      if (wait_ret == -ETIMEDOUT || wait_ret == -ETIME)
 742	        {
 743	          contest_media_check_health(sink);
 744	          continue;
 745	        }
 746	      if (wait_ret < 0)
 747	        {
 748	          continue;
 749	        }
 750	
 751	      while (contest_media_pop_apb(sink, &entry))
 752	        {
 753	          bool aborted = contest_media_pace_aborted(sink);
 754	          bool dma_done = false;
 755	          uint64_t played = 0;
 756	          uint64_t pending = 0;
 757	
 758	          int ret = aborted ? -ECANCELED : sink->stream_error;
 759	
 760	          /* Return APBs on the PCM timeline so adevsink can continuously
 761	           * refill its queue.  PCM was already copied into the native ring;
 762	           * the I2S/DMA backend owns actual speaker delivery. */
 763	          if (ret == OK)
 764	            {
 765	              contest_media_pace_delay(sink, entry.bytes);
 766	              if (contest_media_pace_aborted(sink))
 767	                {
 768	                  ret = -ECANCELED;
 769	                }
 770	            }
 771	
 772	          /* Keep diagnostics tied to the real backend, while APB ownership
 773	           * follows the Media pacing timeline above. */
 774	          if (contest_media_progress(sink, &played, &pending, NULL) == OK)
 775	            {
 776	              dma_done = played >= entry.endpoint;
 777	            }
 778	
 779	          /* STOP can arrive while waiting. Do not turn that cancellation
 780	           * into natural EOS or finish()/drain the queued music. */
 781	          aborted = contest_media_pace_aborted(sink);
 782	          if (ret < 0 && !aborted)
 783	            {
 784	              sink->stream_error = ret;
 785	            }
 786	
 787	          contest_media_dequeue(sink, entry.apb,
 788	                                ret < 0 ? (uint16_t)-ret : OK);
 789	          sink->dequeue_count++;
 790	
 791	          if (sink->dequeue_count <= 4 ||
 792	              (sink->dequeue_count % 32) == 0 ||
 793	              entry.final)
 794	            {
 795	              syslog(LOG_INFO,
 796	                     "[MEDIA-BRIDGE] PCM dequeue #%u bytes=%zu "
 797	                     "dma_done=%d final=%d played=%zu copied=%zu\n",
 798	                     sink->dequeue_count, entry.bytes,
 799	                     dma_done ? 1 : 0, entry.final ? 1 : 0,
 800	                     (size_t)played, sink->total_pcm);
 801	            }
 802	
 803	          if (entry.final && !aborted && ret == OK)
 804	            {
 805	              int finish_ret;
 806	
 807	              /* FINAL's actual samples have completed DMA. Finish joins
 808	               * the backend worker and closes before announcing COMPLETE. */
 809	              finish_ret = contest_media_finish_playback(sink, true);
 810	              if (finish_ret < 0) sink->stream_error = finish_ret;
 811	              contest_media_complete(sink);
 812	
 813	              if (finish_ret < 0)
 814	                {
 815	                  syslog(LOG_ERR,
 816	                         "[MEDIA-BRIDGE] final drain failed=%d\n", finish_ret);
 817	                }
 818	            }
 819	
 820	          /* Mark the APB idle only after its callback and any FINAL handling
 821	           * have finished.  STOP waits for this flag as well as an empty
 822	           * queue, otherwise it can race the current DMA wait operation. */
 823	          if (nxsem_wait_uninterruptible(&sink->pace_lock) == OK)
 824	            {
 825	              bool failed = sink->stream_error < 0 && !sink->pace_abort &&
 826	                            sink->pace_count == 0;
 827	              sink->pace_busy = false;
 828	              nxsem_post(&sink->pace_empty);
 829	              nxsem_post(&sink->pace_lock);
 830	              if (failed)
 831	                {
 832	                  syslog(LOG_ERR, "[MEDIA-BRIDGE] DMA failed rc=%d\n",
 833	                         sink->stream_error);
 834	                  (void)contest_media_finish_playback(sink, false);
 835	                  contest_media_complete(sink);
 836	                }
 837	            }
 838	        }
 839	    }
