1202	   * Do not call robot_audio_playback_finish() here: finish() drains the
1203	   * playback ring by design, which makes a "stop" command continue playing
1204	   * any already-buffered PCM before the device is closed.
1205	   *
1206	   * First return APBs still waiting in the ownership queue, then close the
1207	   * hardware path without draining the private PCM ring.  COMPLETE tells the
1208	   * Media upper-half that this playback instance is terminal and permits the
1209	   * caller to return to the normal vela> state.
1210	   *
1211	   * Natural EOF remains handled by the FINAL APB / worker path below, where
1212	   * robot_audio_playback_finish() is intentionally used to drain the real
1213	   * tail before COMPLETE.
1214	   */
1215	  (void)contest_media_abort_pending(sink);
1216	  ret = contest_media_finish_playback(sink, false);
1217	  contest_media_complete(sink);
1218	  return ret;
1219	}
