 101	struct contest_media_sink_s
 102	{
 103	  struct audio_lowerhalf_s dev;
 104	  bool configured;
 105	  bool playback_open;
 106	  bool completion_sent;
 107	  uint32_t sample_rate;
 108	  uint8_t channels;
 109	  uint8_t bits;
 110	  size_t total_pcm;
 111	  size_t dequeued_pcm;
 112	  unsigned int enqueue_count;
 113	  unsigned int dequeue_count;
 114	  unsigned int position_query_count;
 115	
 116	  /* Media/APB pacing is deliberately separate from robot_audio_playback's
 117	   * own PCM ring.  The APB remains owned by this lower-half until the pacing
 118	   * worker returns AUDIO_CALLBACK_DEQUEUE. */
 119	  sem_t pace_lock;
 120	  sem_t pace_data;
 121	  sem_t pace_empty;
 122	  sem_t playback_lock;
 123	  pthread_t pace_worker;
 124	  bool pace_worker_started;
 125	  bool pace_abort;
 126	  unsigned int pace_head;
 127	  unsigned int pace_tail;
 128	  unsigned int pace_count;
 129	  bool pace_busy;
 130	  bool pace_clock_valid;
 300	  if (sink->playback_open)
 301	    {
 302	      nxsem_post(&sink->playback_lock);
 303	      return OK;
 304	    }
 305	
 306	  if (!sink->configured)
 307	    {
 308	      nxsem_post(&sink->playback_lock);
 309	      syslog(LOG_ERR, "[MEDIA-BRIDGE] start rejected: not configured\n");
 310	      return -EINVAL;
 311	    }
 312	
 313	  if (!contest_media_backend_available())
 314	    {
 315	      nxsem_post(&sink->playback_lock);
 316	      syslog(LOG_ERR,
 317	             "[MEDIA-BRIDGE] robot_audio_playback backend unavailable\n");
 318	      return -ENOSYS;
 319	    }
 320	
 321	  if (robot_audio_playback_set_stop_on_short_underrun != NULL)
 322	    {
 323	      robot_audio_playback_set_stop_on_short_underrun(true);
 324	    }
 325	
 326	  ret = robot_audio_playback_open();
 327	  if (ret < 0)
 328	    {
 329	      if (robot_audio_playback_set_stop_on_short_underrun != NULL)
 330	        {
 331	          robot_audio_playback_set_stop_on_short_underrun(false);
 332	        }
 333	
 334	      nxsem_post(&sink->playback_lock);
 335	      syslog(LOG_ERR, "[MEDIA-BRIDGE] playback open failed=%d\n", ret);
 336	      return ret;
 337	    }
 338	
 339	  sink->playback_open = true;
 340	  sink->completion_sent = false;
 341	  sink->total_pcm = 0;
 342	  sink->dequeued_pcm = 0;
 343	  sink->enqueue_count = 0;
 344	  sink->dequeue_count = 0;
 345	  sink->position_query_count = 0;
 346	  sink->pace_busy = false;
 347	  sink->pace_clock_valid = false;
 348	  sink->pace_deadline_us = 0;
 349	
 350	  nxsem_post(&sink->playback_lock);
 351	
 352	  syslog(LOG_INFO,
 353	         "[MEDIA-BRIDGE] playback open source=%luHz/%uch/%ubit\n",
 354	         (unsigned long)sink->sample_rate,
 355	         sink->channels, sink->bits);
 356	  return OK;
 357	}
