 359	static int contest_media_finish_playback(FAR struct contest_media_sink_s *sink,
 360	                                         bool drain)
 361	{
 362	  int lock_ret;
 363	  int ret = OK;
 364	
 365	  lock_ret = nxsem_wait_uninterruptible(&sink->playback_lock);
 366	  if (lock_ret < 0)
 367	    {
 368	      return lock_ret;
 369	    }
 370	
 371	  if (!sink->playback_open)
 372	    {
 373	      nxsem_post(&sink->playback_lock);
 374	      return OK;
 375	    }
 376	
 377	  if (drain && robot_audio_playback_finish != NULL)
 378	    {
 379	      syslog(LOG_INFO,
 380	             "[MEDIA-BRIDGE] producer EOS -> robot_audio_playback_finish\n");
 381	      ret = robot_audio_playback_finish();
 382	    }
 383	
 384	  if (robot_audio_playback_close != NULL)
 385	    {
 386	      robot_audio_playback_close();
 387	    }
 388	
 389	  if (robot_audio_playback_set_stop_on_short_underrun != NULL)
 390	    {
 391	      robot_audio_playback_set_stop_on_short_underrun(false);
 392	    }
 393	
 394	  sink->playback_open = false;
 395	  nxsem_post(&sink->playback_lock);
 396	
 397	  syslog(LOG_INFO,
 398	         "[MEDIA-BRIDGE] playback close drain=%d pcm=%zu "
 399	         "dequeued_pcm=%zu enqueues=%u dequeues=%u rc=%d\n",
 400	         drain ? 1 : 0, sink->total_pcm, sink->dequeued_pcm,
 401	         sink->enqueue_count, sink->dequeue_count, ret);
 402	  return ret;
 403	}
