 405	static void contest_media_dequeue(FAR struct contest_media_sink_s *sink,
 406	                                  FAR struct ap_buffer_s *apb)
 407	{
 408	  if (sink->dev.upper == NULL)
 409	    {
 410	      return;
 450	    }
 451	
 452	  aborted = sink->pace_abort;
 453	  nxsem_post(&sink->pace_lock);
 454	  return aborted;
 455	}
