 457	static uint64_t contest_media_now_us(void)
 458	{
 459	  struct timespec ts;
 460	
 461	  if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0)
 462	    {
 463	      return 0;
 464	    }
 465	
 466	  return (uint64_t)ts.tv_sec * 1000000ULL +
 467	         (uint64_t)ts.tv_nsec / 1000ULL;
 468	}
