 470	static void contest_media_pace_delay(FAR struct contest_media_sink_s *sink,
 471	                                     size_t bytes)
 472	{
 473	  uint64_t duration;
 474	  uint64_t now;
 475	
 476	  if (bytes == 0)
 477	    {
 478	      return;
 479	    }
 480	
 481	  duration = ((uint64_t)bytes * 1000000ULL +
 482	              CONTEST_MEDIA_BYTES_PER_SEC - 1) /
 483	             CONTEST_MEDIA_BYTES_PER_SEC;
 484	
 485	  now = contest_media_now_us();
 486	
 487	  /* F7J:
 488	   * Do NOT implement a period as a chain of relative usleep() calls.
 489	   * Each sleep can overshoot slightly; adding those overshoots to the next
 490	   * APB makes the producer permanently slower than the 48 kB/s consumer.
 491	   * That was the source of the audible "word-(gap)-word-(gap)" behavior.
 492	   *
 493	   * Maintain one absolute PCM timeline instead.  Scheduler oversleep on one
 494	   * APB is automatically recovered by a shorter/no sleep on the next APB.
 495	   */
 496	  if (!sink->pace_clock_valid || now == 0)
 497	    {
 498	      sink->pace_deadline_us = now + duration;
 499	      sink->pace_clock_valid = true;
 500	    }
 501	  else
 502	    {
 503	      sink->pace_deadline_us += duration;
 504	    }
 505	
 506	  for (;;)
 507	    {
 508	      uint64_t remain;
 509	      unsigned int slice;
 510	
 511	      if (contest_media_pace_aborted(sink))
 512	        {
 513	          return;
 514	        }
 515	
 516	      now = contest_media_now_us();
 517	      if (now == 0 || now >= sink->pace_deadline_us)
 518	        {
 519	          return;
 520	        }
 521	
 522	      remain = sink->pace_deadline_us - now;
 523	      slice = remain > CONTEST_MEDIA_PACE_SLICE_US ?
 524	              CONTEST_MEDIA_PACE_SLICE_US :
 525	              (unsigned int)remain;
 526	
 527	      usleep(slice);
 528	    }
 529	}
