 531	static bool contest_media_pop_apb(FAR struct contest_media_sink_s *sink,
 532	                                  FAR struct contest_media_pending_s *entry)
 533	{
 534	  if (nxsem_wait_uninterruptible(&sink->pace_lock) < 0)
 535	    {
 536	      return false;
 537	    }
 538	
 539	  if (sink->pace_count == 0)
 540	    {
 541	      nxsem_post(&sink->pace_lock);
 542	      return false;
 543	    }
 544	
 545	  *entry = sink->pending[sink->pace_head];
 546	  sink->pace_head = (sink->pace_head + 1) % CONTEST_MEDIA_PACE_QUEUE;
 547	  sink->pace_count--;
 548	  sink->pace_busy = true;
 549	
 550	  if (sink->pace_count == 0)
 551	    {
 552	      nxsem_post(&sink->pace_empty);
 553	    }
 554	
 555	  nxsem_post(&sink->pace_lock);
 556	  return true;
 557	}
 558	
 559	static void *contest_media_pace_worker(FAR void *arg)
 560	{
 561	  FAR struct contest_media_sink_s *sink = arg;
 562	
 563	  syslog(LOG_INFO,
 564	         "[MEDIA-BRIDGE] pacer worker start rate=%uB/s queue=%u\n",
 565	         CONTEST_MEDIA_BYTES_PER_SEC, CONTEST_MEDIA_PACE_QUEUE);
 566	
 567	  for (;;)
 568	    {
 569	      struct contest_media_pending_s entry;
 570	
 571	      if (nxsem_wait_uninterruptible(&sink->pace_data) < 0)
 572	        {
 573	          continue;
 574	        }
 575	
 576	      while (contest_media_pop_apb(sink, &entry))
 577	        {
 578	          bool aborted = contest_media_pace_aborted(sink);
 579	
 580	          if (!aborted)
 581	            {
 582	              contest_media_pace_delay(sink, entry.bytes);
 583	            }
 584	
 585	          contest_media_dequeue(sink, entry.apb);
 586	          sink->dequeue_count++;
 587	          sink->dequeued_pcm += entry.bytes;
 588	
 589	          if (sink->dequeue_count <= 4 ||
 590	              (sink->dequeue_count % 32) == 0 ||
 591	              entry.final)
 592	            {
 593	              syslog(LOG_INFO,
 594	                     "[MEDIA-BRIDGE] PCM dequeue #%u bytes=%zu "
 595	                     "paced=%d final=%d\n",
 596	                     sink->dequeue_count, entry.bytes,
 597	                     aborted ? 0 : 1, entry.final ? 1 : 0);
 598	            }
 599	
 600	          if (entry.final && !aborted)
 601	            {
 602	              int ret;
 603	
 604	              /* The final APB has now lived for its PCM duration.  EOS then
 605	               * drains the proven robot_audio_playback ring all the way to
 606	               * the I2S hardware before Media receives COMPLETE. */
 607	              ret = contest_media_finish_playback(sink, true);
 608	              contest_media_complete(sink);
 609	
 610	              if (ret < 0)
 611	                {
 612	                  syslog(LOG_ERR,
 613	                         "[MEDIA-BRIDGE] final drain failed=%d\n", ret);
 614	                }
 615	            }
 616	
 617	          /* Mark the APB idle only after its callback and any FINAL handling
 618	           * have finished.  STOP waits for this flag as well as an empty
 619	           * queue, otherwise it can race the current pacing operation. */
 620	          if (nxsem_wait_uninterruptible(&sink->pace_lock) == OK)
 621	            {
 622	              sink->pace_busy = false;
 623	              nxsem_post(&sink->pace_empty);
 624	              nxsem_post(&sink->pace_lock);
 625	            }
 626	        }
 627	    }
 628	
 629	  return NULL;
 630	}
1125	                     ret);
1126	              contest_media_dequeue(sink, apb);
1127	              (void)contest_media_finish_playback(sink, false);
1128	              contest_media_complete(sink);
1129	              return OK;
1130	            }
1131	
1132	          syslog(LOG_ERR, "[MEDIA-BRIDGE] write failed len=%zu rc=%d\n",
1133	                 len, ret);
1134	          return ret;
1135	        }
1136	
1137	      sink->total_pcm += len;
1138	      sink->enqueue_count++;
1139	      apb->curbyte = apb->nbytes;
1140	
1141	      if (sink->enqueue_count <= 4 || (sink->enqueue_count % 32) == 0)
1142	        {
1143	          syslog(LOG_INFO,
1144	                 "[MEDIA-BRIDGE] PCM enqueue #%u bytes=%zu total=%zu final=%d\n",
1145	                 sink->enqueue_count, len, sink->total_pcm, final ? 1 : 0);
1146	        }
1147	    }
1148	
1149	  /* robot_audio_playback_write() has copied the PCM, but that does NOT mean
1150	   * the hardware has consumed this period.  Keep ownership of the Media APB
1151	   * and return it later at the real 48 kB/s PCM cadence. */
1152	  if (final)
1153	    {
1154	      syslog(LOG_INFO,
1155	             "[MEDIA-BRIDGE] FINAL APB received bytes=%zu "
1156	             "pcm_total=%zu dequeued=%zu\n",
1157	             len, sink->total_pcm, sink->dequeued_pcm);
1158	    }
1159	
1160	  ret = contest_media_queue_apb(sink, apb, len, final);
1161	  if (ret < 0)
1162	    {
1163	      syslog(LOG_ERR,
1164	             "[MEDIA-BRIDGE] queue APB failed bytes=%zu final=%d rc=%d\n",
1165	             len, final ? 1 : 0, ret);
1166	      return ret;
1167	    }
1168	
1169	  return OK;
1170	}
