1899	{
1900	  struct rv_playback_s *pb = &g_pb;
1901	  int ret = 0;
1902	
1903	  if (!pb->opened)
1904	    {
1905	      return -EINVAL;
1906	    }
1907	
1908	  if (pb->finished)
1909	    {
1910	      return rv_get_result(pb);
1911	    }
1912	
1913	  if (pb->cache_until_eos && ROBOT_VOICE_TTS_CONTINUITY &&
1914	      !pb->worker_started && !pb->stopped && pb->total_written != 0)
1915	    {
1916	      ret = rv_start_i2s_playback(pb);
1917	      if (ret < 0)
1918	        {
1919	          if (rv_lock(pb) == 0)
1920	            {
