2785	      pthread_join(asr[--started], NULL);
2786	    }
2787	  pthread_mutex_lock(&g_monitor.lock);
2788	  g_monitor.enabled = false;
2789	  g_monitor.reply_locked = false;
2790	  g_monitor.muted = false;
