2809	static void *voice_record_worker(void *arg)
2810	{
2811	  size_t pcm_cap = (size_t)ROBOT_VOICE_CAPTURE_RATE * 2 *
2812	                   CONTEST_VOICE_CAPTURE_SECONDS;
2813	  uint8_t *pcm = malloc(pcm_cap);
2814	  char text[ROBOT_VOICE_TEXT_CAP];
2815	  (void)arg;
2816	
2817	  if (pcm == NULL)
2818	    {
2819	      printf("[contest_voice] worker cleanup: pcm allocation failed\n");
2820	      goto cleanup;
2821	    }
2822	
2823	  while (!g_voice_stop_requested)
2824	    {
2825	      size_t pcm_len = 0;
2826	      int ret;
2827	
2828	      contest_voice_set_state(CONTEST_VOICE_RECORDING);
2829	      (void)robot_expression_set(ROBOT_EXPRESSION_SOURCE_VOICE,
2830	                                  ROBOT_EXPRESSION_LISTENING, 0);
2831	      ret = robot_voice_capture_record_interruptible(
2832	          pcm, pcm_cap, &pcm_len, CONTEST_VOICE_CAPTURE_SECONDS * 1000,
2833	          &g_voice_stop_requested);
2834	      RV_VERBOSE("[RV-VOICE] capture returned rc=%d bytes=%zu\n", ret, pcm_len);
2835	      if (ret < 0 || g_voice_stop_requested)
2836	        {
2837	          break;
2838	        }
2839	      if (g_voice_speaking)
2840	        {
2841	          continue;
2842	        }
2843	      ret = robot_voice_afe_recording(pcm, pcm_len, g_monitor.afe_mode);
2844	      if (ret < 0) { printf("[RV-AFE] finite preprocessing failed rc=%d\n", ret); break; }
2845	      contest_voice_set_state(CONTEST_VOICE_ASR);
2846	      RV_VERBOSE("[RV-VOICE] invoking ASR bytes=%zu on dedicated worker\n", pcm_len);
2847	      ret = contest_voice_run_asr(pcm, pcm_len, text, sizeof(text));
2848	      if (g_voice_stop_requested)
2849	        {
2850	          break;
2851	        }
2852	      if (ret < 0 || text[0] == '\0')
2853	        {
2854	          (void)robot_expression_clear(ROBOT_EXPRESSION_SOURCE_VOICE);
2855	          (void)robot_expression_set(ROBOT_EXPRESSION_SOURCE_SYSTEM,
2856	                                      ROBOT_EXPRESSION_ERROR, 1500);
2857	          printf("[contest_voice] ASR failed: %d\n", ret);
2858	          if (g_voice_oneshot)
2859	            {
2860	              break;
2861	            }
2862	          continue;
2863	        }
2864	
2865	      ret = contest_voice_route_text(text);
2866	      if (ret < 0)
2867	        {
2868	          if (g_voice_oneshot)
2869	            {
2870	              break;
2960	    }
2961	  if (!g_voice_tap_registered)
2962	    {
2963	      if (mbus_tap_register(AGENT_CHAN_VOICE,
2964	                            robot_voice_outbound_tap, NULL) == OK)
2965	        {
2966	          g_voice_tap_registered = true;
2967	        }
2968	      else
2969	        {
2970	          printf("[RV-WAKE] voice outbound tap unavailable\n");
2971	        }
2972	    }
2973	  /* No Media daemon or wlan0 operation is started by voice initialization.
2974	   * TTS uses the contest-local sentence-buffer path. */
2975	  RV_VERBOSE("[contest_voice] no Media/Wi-Fi bootstrap in voice init\n");
2976	  g_voice_initialized = g_voice_tap_registered;
2977	  pthread_mutex_unlock(&g_voice_init_lock);
2978	  printf("[RV-VOICE-PROVIDER] contest TFLite voice ready; ASR=%s TTS=%s tap=%u\n",
2979	         g_voice_asr_backend, g_voice_tts_backend, g_voice_tap_registered);
2980	  return g_voice_tap_registered ? 0 : -EIO;
2981	}
