3061	int voice_channel_stop(void)
3062	{
3063	  enum contest_voice_state_e state;
3064	  bool join_needed = false;
3065	  pthread_t tid = 0;
3066	
3067	  pthread_mutex_lock(&g_voice_lock);
3068	  if (!g_voice_thread_valid)
3069	    {
3070	      pthread_mutex_unlock(&g_voice_lock);
3071	      return 0;
3072	    }
3073	  g_voice_stop_requested = true;
3074	  g_voice_reply_pending = false;
3075	  (void)robot_expression_clear(ROBOT_EXPRESSION_SOURCE_VOICE);
3076	  state = g_voice_state;
3077	  contest_voice_set_state(CONTEST_VOICE_STOPPING);
3078	  tid = g_voice_thread;
3079	  join_needed = !pthread_equal(pthread_self(), tid);
3080	  pthread_mutex_unlock(&g_voice_lock);
3081	
3082	  pthread_mutex_lock(&g_monitor.lock);
3083	  if (g_monitor.enabled)
3084	    {
3085	      g_monitor.stop = true;
3086	      g_monitor.epoch++;
3087	      rv_clear_locked();
3088	      pthread_cond_broadcast(&g_monitor.changed);
3089	    }
3090	  pthread_mutex_unlock(&g_monitor.lock);
3091	
3092	  RV_VERBOSE("[contest_voice] stop requested state=%s\n",
3093	         contest_voice_state_name(state));
3094	  if (join_needed)
3095	    {
3096	      RV_VERBOSE("[contest_voice] waiting capture callbacks and worker cleanup\n");
3097	      pthread_join(tid, NULL);
3098	      /* Finish already-started speech before a new voice_start is allowed. */
3099	      pthread_mutex_lock(&g_voice_speak_lock);
3100	      pthread_mutex_unlock(&g_voice_speak_lock);
3101	    }
3102	
3103	  pthread_mutex_lock(&g_voice_lock);
3104	  while (g_tts_jobs != 0)
3105	    {
3106	      pthread_cond_wait(&g_tts_jobs_changed, &g_voice_lock);
3107	    }
3108	  if (g_voice_worker_exited)
3109	    {
3110	      g_voice_thread_valid = 0;
3111	      g_voice_oneshot = 0;
3112	    }
3113	  pthread_mutex_unlock(&g_voice_lock);
3114	  RV_VERBOSE("[contest_voice] voice_channel_stop state=%s\n",
3115	         contest_voice_state_name(g_voice_state));
3116	  return 0;
3117	}
