  2221	static const char *rv_wake_command_tail(const char *text)
  2222	{
  2223	  const char *start = rv_skip_separators(text), *tail;
  2224	  /* Only the full configured wake phrase may be found inside cached context.
  2225	   * A bare product name is removed only at the beginning, never mid-command. */
  2226	  for (const char *p = start; *p; p++)
  2227	    {
  2228	      if (((unsigned char)*p & 0xc0) == 0x80) continue;
  2229	      const char *previous = p;
  2230	      if (p != start)
  2231	        {
  2232	          previous--;
  2233	          while (previous > start && ((unsigned char)*previous & 0xc0) == 0x80)
  2234	            previous--;
  2235	        }
  2236	      if ((p == start || rv_skip_separators(previous) == p) &&
  2237	          (tail = rv_phrase_tail(p, "你好openvela")) != NULL) return tail;
  2238	    }
  2239	  tail = rv_phrase_tail(start, "openvela");
  2240	  if (tail) return tail;
  2241	  tail = rv_phrase_tail(start, "你好");
  2242	  if (tail && !*tail) return tail;
  2243	  return start;
  2244	}
