  2250	    "退出语音模式", "结束语音模式", "退出语音聊天", "结束语音聊天",
  2251	    "退出聊天", "结束聊天", "退出对话", "结束对话", "停止聊天", "停止对话"
  2252	  };
  2253	  static const char *const prefixes[] = {"可以帮我", "可以", "请帮我", "请你", "帮我", "请", ""};
  2254	  for (size_t p = 0; p < sizeof(prefixes) / sizeof(*prefixes); p++) {
  2255	    const char *body = rv_phrase_tail(text, prefixes[p]);
