  2459	           (error ? ROBOT_PROMPT_NETWORK_ERROR : ROBOT_PROMPT_NOT_HEARD) :
  2460	           g_monitor.pending_text);
  2461	  g_monitor.pending_text[0] = '\0';
  2462	  g_monitor.pending_failed = false;
  2463	  g_monitor.pending_error = 0;
