  2570	/* Controller waits for a real RX frame, rather than assuming pthread_create
  2571	 * means the microphone is ready. No Flash request is needed for this greeting. */
  2572	static int rv_startup_announce(void)
  2573	{
  2574	  unsigned long run_id;
  2575	  unsigned long long start = robot_voice_now_ms();
  2576	  int ret = 0;
  2577	  pthread_mutex_lock(&g_monitor.lock);
  2578	  while (!g_monitor.capture_ready && !g_monitor.capture_exited &&
  2579	         !g_monitor.stop && !g_voice_stop_requested &&
  2580	         robot_voice_now_ms() - start < ROBOT_VOICE_READY_TIMEOUT_MS)
  2581	    rv_wait_locked(50);
  2582	  if (g_voice_stop_requested || g_monitor.stop) ret = -ECANCELED;
  2583	  else if (g_monitor.capture_exited)
  2584	    ret = g_monitor.capture_result < 0 ? g_monitor.capture_result : -EIO;
  2585	  else if (!g_monitor.capture_ready) ret = -ETIMEDOUT;
  2586	  run_id = g_monitor.run_id;
  2587	  g_monitor.reply_start_ms = robot_voice_now_ms();
  2588	  pthread_mutex_unlock(&g_monitor.lock);
  2589	  if (ret < 0) return ret;
  2590	  RV_EVENT("[语音] 系统准备就绪，开始问好\n");
  2591	  ret = robot_voice_tts_submit(ROBOT_PROMPT_STARTUP, true, run_id);
  2592	  if (ret < 0) {
  2593	    printf("[语音错误] 启动问好提交失败 rc=%d\n", ret);
  2594	    rv_reply_done(true); /* keep wake listening available after TTS failure */
  2595	  }
  2596	  return 0;
  2597	}
