static void test_native_media_sequence(void)
{
  const char *url = "https://music.163.com/song/media/outer/url?id=26217338.mp3";
  unsigned int position = 0;
  unsigned int duration = 0;
  int cookie = 7;
  int16_t pcm[2] = {0, 1};
  void *handle;

  native_available = true;
  handle = tool_open_fixture();
  assert(handle != NULL);
  assert(robot_music_media_prepare(handle, url, NULL) == 0);
  assert(robot_music_media_set_event_callback(handle, &cookie,
                                               test_event_callback) == 0);
  assert(robot_music_media_start(handle) == 0);
  assert(robot_music_media_owns_reply(42));
  assert(robot_music_media_get_position(handle, &position) == 0 && position == 12);
  assert(robot_music_media_get_duration(handle, &duration) == 0 && duration == 34);
  assert(robot_music_media_write_data(handle, pcm, sizeof(pcm)) == sizeof(pcm));
  assert(robot_music_media_pause(handle) == 0);
  assert(robot_music_media_seek(handle, 0) == 0);
  assert(robot_music_media_stop(handle) == 0);
  assert(!robot_music_media_owns_reply(42));
  assert(robot_music_media_close(handle, 0) == 0);
  assert(native_opens == 1 && native_prepares == 1 && native_starts == 1 &&
         native_stops == 1 && native_closes == 1);
}

static void test_native_open_failure_is_terminal(void)
{
  native_available = false;
  errno = 0;
  assert(tool_open_fixture() == NULL);
  assert(errno == ENOSYS);
  assert(native_opens == 2);
}

static void test_repeated_native_lifecycles(void)
{
  const char *url = "https://music.163.com/song/media/outer/url?id=26217338.mp3";
  unsigned int i;

  native_available = true;
  for (i = 0; i < 30; i++)
    {
      void *handle = tool_open_fixture();
      assert(handle != NULL);
      assert(robot_music_media_prepare(handle, url, NULL) == 0);
      assert(robot_music_media_start(handle) == 0);
      assert(robot_music_media_owns_reply(42));
      assert(robot_music_media_stop(handle) == 0);
      assert(robot_music_media_close(handle, 0) == 0);
      assert(!robot_music_media_owns_reply(42));
    }

  assert(native_opens == 32 && native_prepares == 31 && native_starts == 31 &&
         native_stops == 31 && native_closes == 31);
}

int main(void)
{
  test_native_media_sequence();
  test_native_open_failure_is_terminal();
  test_repeated_native_lifecycles();
  puts("PASS: Agent music uses OpenVela Media open/prepare/start only; native-open failure never selects a local decoder");
  return 0;
