  1386	/* A Flash reply locks recognition before TTS synthesis. Unscoped CLI
  1387	 * playback still waits for an active user utterance before muting capture. */
  1388	static bool rv_playback_begin_checked(bool (*cancelled)(void *), void *arg)
  1389	{
  1390	  bool allowed;
  1391	  pthread_mutex_lock(&g_monitor.lock);
  1392	  while (g_monitor.enabled && !g_monitor.stop &&
  1393	         !g_voice_stop_requested && !(cancelled && cancelled(arg)) &&
  1394	         !g_monitor.reply_locked &&
  1395	         (g_monitor.capture_active || g_monitor.wake_handoff_pending ||
  1396	          (robot_voice_now_ms() >= g_monitor.last_voice_ms &&
  1397	           robot_voice_now_ms() - g_monitor.last_voice_ms <
  1398	             ROBOT_VOICE_TURN_END_MS)))
  1399	    {
  1400	      rv_wait_locked(50);
  1401	    }
  1402	  allowed = (!g_monitor.enabled ||
  1403	            (!g_monitor.stop && !g_voice_stop_requested)) &&
  1404	            !(cancelled && cancelled(arg));
  1405	  if (allowed && g_monitor.enabled)
  1406	    {
  1407	      g_monitor.muted = true;
  1408	      g_monitor.playback_token = rv_run_token_load();
  1409	      (void)robot_wakeword_feed(NULL, 0, g_monitor.epoch, false);
  1410	      g_monitor.listening_announced = false;
  1411	    }
  1412	  pthread_mutex_unlock(&g_monitor.lock);
  1413	  return allowed;
  1414	}
