  1443	static void rv_reply_done_for_run(bool agent_reply, unsigned long run_id)
  1444	{
  1445	  pthread_mutex_lock(&g_monitor.lock);
  1446	  if (run_id && run_id != g_monitor.run_id)
  1447	    { pthread_mutex_unlock(&g_monitor.lock); return; }
  1448	  if (g_monitor.reply_locked && !agent_reply)
  1449	    { pthread_mutex_unlock(&g_monitor.lock); return; }
  1450	  if (agent_reply) {
  1451	    g_voice_reply_pending = false;
  1452	    g_monitor.reply_locked = false;
  1453	  }
  1454	  if (g_monitor.enabled && !g_voice_stop_requested)
  1455	    {
  1456	      /* No speaker mute means capture may already contain a new onset.
  1457	       * A download/empty reply finishing must not invent an echo interval. */
  1458	      if (g_monitor.muted)
  1459	        g_monitor.echo_until_ms = ROBOT_VOICE_ECHO_GUARD_MS ?
  1460	      robot_voice_now_ms() + ROBOT_VOICE_ECHO_GUARD_MS : 0;
  1461	      g_monitor.muted = false;
  1462	      g_monitor.chat_activity_ms = robot_voice_now_ms();
  1463	      if (agent_reply && g_monitor.phase == RV_MON_GREETING)
  1464	        {
  1465	          g_monitor.phase = RV_MON_WAKE;
  1466	          RV_VERBOSE("[RV-WAKE] ready: say 你好，OpenVela\n");
  1467	        }
