  1469	        {
  1470	          g_monitor.phase = RV_MON_LISTEN;
  1471	        }
  1472	      rv_listening_expression_locked();
  1473	      pthread_cond_broadcast(&g_monitor.changed);
  1474	    }
  1475	  pthread_mutex_unlock(&g_monitor.lock);
  1476	}
