   382	/* Start the contest-local backend only from AUDIOIOC_START.  Media fills
   383	 * several APBs before that command; starting on the first enqueue gives the
   384	 * decoder an 85 ms ring and immediately triggers source-side xrun. */
   385	static int contest_media_start_backend(FAR struct contest_media_sink_s *sink)
   386	{
   387	  int ret;
   388	
   389	  ret = nxsem_wait_uninterruptible(&sink->playback_lock);
   390	  if (ret < 0)
   391	    {
   392	      return ret;
   393	    }
   394	
   395	  if (!sink->playback_open)
   396	    {
   397	      ret = -EINVAL;
   398	    }
   399	  else if (sink->started)
   400	    {
   401	      ret = OK;
   402	    }
   403	  else
   404	    {
   405	      ret = robot_audio_playback_start_native_media();
   406	      if (ret == OK)
   407	        {
   408	          sink->started = true;
   409	          sink->paused = false;
   410	          uint32_t now_ms = (uint32_t)contest_media_now_ms();
   411	          __atomic_store_n(&sink->started_ms, now_ms, __ATOMIC_RELEASE);
   412	          __atomic_store_n(&sink->last_pcm_ms, now_ms, __ATOMIC_RELEASE);
   413	        }
   414	    }
   415	
   416	  nxsem_post(&sink->playback_lock);
   417	  return ret;
   418	}
   419	
   420	static int contest_media_finish_playback(FAR struct contest_media_sink_s *sink,
   421	                                         bool drain)
   422	{
   423	  int lock_ret;
   424	  int ret = OK;
   425	
   426	  lock_ret = nxsem_wait_uninterruptible(&sink->playback_lock);
   427	  if (lock_ret < 0)
   428	    {
   429	      return lock_ret;
   430	    }
   431	
   432	  if (!sink->playback_open)
   433	    {
   434	      nxsem_post(&sink->playback_lock);
   435	      return OK;
   436	    }
   437	
   438	  if (drain && robot_audio_playback_finish != NULL)
   439	    {
   440	      syslog(LOG_INFO,
   441	             "[MEDIA-BRIDGE] producer EOS -> robot_audio_playback_finish\n");
   442	      ret = robot_audio_playback_finish();
   443	    }
   444	
   445	  if (robot_audio_playback_progress != NULL)
   446	    {
   447	      uint64_t completed;
   448	      uint64_t pending;
   449	
   450	      if (robot_audio_playback_progress(&completed, &pending) == OK)
   451	        {
   452	          sink->dequeued_pcm = completed;
   453	        }
   454	    }
   455	
   456	  if (robot_audio_playback_close != NULL)
   457	    {
   458	      robot_audio_playback_close();
   459	    }
   460	
   461	  sink->playback_open = false;
   462	  sink->started = false;
   463	  nxsem_post(&sink->playback_lock);
   464	
   465	  syslog(LOG_INFO,
   466	         "[MEDIA-BRIDGE] playback close drain=%d pcm=%zu "
   467	         "dequeued_pcm=%zu enqueues=%u dequeues=%u rc=%d\n",
   468	         drain ? 1 : 0, sink->total_pcm, sink->dequeued_pcm,
   469	         sink->enqueue_count, sink->dequeue_count, ret);
   470	  return ret;
   471	}
