   490	static void contest_media_complete(FAR struct contest_media_sink_s *sink)
   491	{
   492	  if (__atomic_exchange_n(&sink->completion_sent, true, __ATOMIC_ACQ_REL))
   493	    {
   494	      return;
   495	    }
   496	
   497	  if (sink->dev.upper == NULL)
   498	    {
   499	      return;
   500	    }
   501	
   502	  syslog(LOG_INFO, "[MEDIA-BRIDGE] COMPLETE\n");
