   504	  if (sink->stream_error < 0)
   505	    {
   506	#ifdef CONFIG_AUDIO_MULTI_SESSION
   507	      sink->dev.upper(sink->dev.priv, AUDIO_CALLBACK_IOERR, NULL,
   508	                       (uint16_t)-sink->stream_error, sink);
