   510	      sink->dev.upper(sink->dev.priv, AUDIO_CALLBACK_IOERR, NULL,
   511	                       (uint16_t)-sink->stream_error);
   512	#endif
   513	    }
   514	
   515	#ifdef CONFIG_AUDIO_MULTI_SESSION
   516	  sink->dev.upper(sink->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK, sink);
   517	#else
   518	  sink->dev.upper(sink->dev.priv, AUDIO_CALLBACK_COMPLETE, NULL, OK);
   519	#endif
   520	}
