   522	static bool contest_media_pace_aborted(FAR struct contest_media_sink_s *sink)
   523	{
   524	  bool aborted;
   525	
   526	  if (nxsem_wait_uninterruptible(&sink->pace_lock) < 0)
   527	    {
   528	      return true;
   529	    }
   530	
   531	  aborted = sink->pace_abort;
   532	  nxsem_post(&sink->pace_lock);
   533	  return aborted;
   534	}
   535	
   536	/* Snapshot under the lifetime lock; STOP first aborts the queue and waits
   537	 * for this worker, then closes the backend. No polling of a freed ring. */
   538	static int contest_media_progress(FAR struct contest_media_sink_s *sink,
   539	                                  uint64_t *completed, uint64_t *pending,
   540	                                  bool *started)
   541	{
   542	  int ret = nxsem_wait_uninterruptible(&sink->playback_lock);
   543	  if (ret < 0)
   544	    {
   545	      return ret;
   546	    }
   547	
   548	  if (started != NULL) *started = sink->started;
   549	  if (!sink->playback_open)
   550	    {
   551	      *completed = sink->dequeued_pcm;
   552	      *pending = 0;
   553	      ret = sink->stream_error;
   554	    }
   555	  else
   556	    {
   557	      ret = robot_audio_playback_progress(completed, pending);
   558	      if (ret == OK)
   559	        {
   560	          sink->dequeued_pcm = *completed;
   561	        }
   562	    }
   563	
   564	  nxsem_post(&sink->playback_lock);
   565	  return ret;
   566	}
   567	
   568	static uint64_t contest_media_now_us(void)
   569	{
   570	  struct timespec ts;
   571	
   572	  if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0)
   573	    {
   574	      return 0;
   575	    }
   576	
   577	  return (uint64_t)ts.tv_sec * 1000000ULL +
   578	         (uint64_t)ts.tv_nsec / 1000ULL;
   579	}
   580	
   581	/* Return Media APBs at the PCM consumption rate.  The native playback ring
   582	 * and I2S DMA continue independently; waiting for each DMA callback here
   583	 * starves adevsink of APBs and makes it report a false xrun after four
   584	 * buffers.  Use one absolute timeline so scheduler delay does not accumulate
   585	 * into audible gaps. */
   586	static void contest_media_pace_delay(FAR struct contest_media_sink_s *sink,
   587	                                     size_t bytes)
   588	{
   589	  uint64_t duration;
   590	
   591	  if (bytes == 0)
   592	    {
   593	      return;
   594	    }
   595	
   596	  duration = ((uint64_t)bytes * 1000000ULL +
   597	              CONTEST_MEDIA_BYTES_PER_SEC - 1) /
   598	             CONTEST_MEDIA_BYTES_PER_SEC;
   599	
   600	  uint64_t now = contest_media_now_us();
   601	  if (!sink->pace_clock_valid || now == 0)
   602	    {
   603	      sink->pace_deadline_us = now + duration;
   604	      sink->pace_clock_valid = true;
   605	    }
   606	  else
   607	    {
   608	      sink->pace_deadline_us += duration;
   609	    }
   610	
   611	  for (;;)
   612	    {
   613	      if (contest_media_pace_aborted(sink))
   614	        {
   615	          return;
   616	        }
   617	
   618	      now = contest_media_now_us();
   619	      if (now == 0 || now >= sink->pace_deadline_us)
   620	        {
   621	          return;
   622	        }
   623	
   624	      uint64_t remain = sink->pace_deadline_us - now;
   625	      unsigned int slice = remain > CONTEST_MEDIA_PACE_SLICE_US ?
   626	                           CONTEST_MEDIA_PACE_SLICE_US :
   627	                           (unsigned int)remain;
   628	      usleep(slice);
   629	    }
   630	}
   631	
   632	static bool contest_media_pop_apb(FAR struct contest_media_sink_s *sink,
   633	                                  FAR struct contest_media_pending_s *entry)
   634	{
   635	  if (nxsem_wait_uninterruptible(&sink->pace_lock) < 0)
   636	    {
   637	      return false;
   638	    }
   639	
   640	  if (sink->pace_count == 0)
   641	    {
   642	      nxsem_post(&sink->pace_lock);
   643	      return false;
   644	    }
   645	
   646	  *entry = sink->pending[sink->pace_head];
   647	  sink->pace_head = (sink->pace_head + 1) % CONTEST_MEDIA_PACE_QUEUE;
   648	  sink->pace_count--;
   649	  sink->pace_busy = true;
   650	
   651	  if (sink->pace_count == 0)
   652	    {
   653	      nxsem_post(&sink->pace_empty);
   654	    }
   655	
   656	  nxsem_post(&sink->pace_lock);
   657	  return true;
   658	}
   659	
   660	/* Detect a stopped I2S DMA worker even when Media has not queued a FINAL
   661	 * buffer.  Without this poll, APBs already copied into the private PCM ring
   662	 * can be returned and the Media thread can then wait forever for an event. */
   663	static void contest_media_check_health(FAR struct contest_media_sink_s *sink)
   664	{
   665	  uint32_t now_ms;
   666	  uint32_t last_pcm_ms;
   667	  uint32_t started_ms;
   668	  uint64_t completed;
   669	  uint64_t pending;
   670	  unsigned int queued;
   671	  bool started;
   672	  int ret;
   673	
   674	  if (__atomic_load_n(&sink->completion_sent, __ATOMIC_ACQUIRE) ||
   675	      sink->stream_error < 0 || contest_media_pace_aborted(sink))
   676	    {
   677	      return;
   678	    }
   679	
   680	  ret = contest_media_progress(sink, &completed, &pending, &started);
   681	  if (!started)
   682	    {
   683	      return;
   684	    }
   685	
   686	  now_ms = (uint32_t)contest_media_now_ms();
   687	  last_pcm_ms = __atomic_load_n(&sink->last_pcm_ms, __ATOMIC_ACQUIRE);
   688	  started_ms = __atomic_load_n(&sink->started_ms, __ATOMIC_ACQUIRE);
   689	  if (ret >= 0 && !sink->eos &&
   690	      (uint32_t)(now_ms - (last_pcm_ms ? last_pcm_ms : started_ms)) >=
   691	      CONTEST_MEDIA_STALL_TIMEOUT_MS)
   692	    {
   693	      ret = -ETIMEDOUT;
   694	      syslog(LOG_ERR,
   695	             "[MEDIA-BRIDGE] no PCM input for %u ms; closing stalled stream\n",
   696	             CONTEST_MEDIA_STALL_TIMEOUT_MS);
   697	    }
   698	  else if (ret >= 0)
   699	    {
   700	      return;
   701	    }
   702	
   703	  sink->stream_error = ret;
   704	  sink->eos = true;
   705	  syslog(LOG_ERR,
   706	         "[MEDIA-BRIDGE] playback backend failed while streaming rc=%d; "
   707	         "closing and returning to caller\n", ret);
   708	
   709	  if (nxsem_wait_uninterruptible(&sink->pace_lock) < 0)
   710	    {
   711	      return;
   712	    }
   713	
   714	  queued = sink->pace_count;
   715	  nxsem_post(&sink->pace_lock);
   716	
   717	  if (queued > 0)
   718	    {
   719	      /* The normal worker path returns every copied APB with the error
   720	       * before it emits the terminal IOERR/COMPLETE callbacks. */
   721	      nxsem_post(&sink->pace_data);
   722	      return;
   723	    }
   724	
   725	  (void)contest_media_finish_playback(sink, false);
   726	  contest_media_complete(sink);
   727	}
   728	
   729	static void *contest_media_pace_worker(FAR void *arg)
   730	{
   731	  FAR struct contest_media_sink_s *sink = arg;
   732	
   733	  syslog(LOG_INFO,
   734	         "[MEDIA-BRIDGE] DMA completion worker queue=%u\n",
   735	         CONTEST_MEDIA_PACE_QUEUE);
   736	
   737	  for (;;)
   738	    {
   739	      struct contest_media_pending_s entry;
   740	
   741	      int wait_ret = nxsem_tickwait_uninterruptible(
   742	        &sink->pace_data, MSEC2TICK(CONTEST_MEDIA_HEALTH_POLL_MS));
   743	      if (wait_ret == -ETIMEDOUT || wait_ret == -ETIME)
   744	        {
   745	          contest_media_check_health(sink);
   746	          continue;
   747	        }
   748	      if (wait_ret < 0)
   749	        {
   750	          continue;
   751	        }
   752	
   753	      while (contest_media_pop_apb(sink, &entry))
   754	        {
   755	          bool aborted = contest_media_pace_aborted(sink);
   756	          bool dma_done = false;
   757	          uint64_t played = 0;
   758	          uint64_t pending = 0;
   759	
   760	          int ret = aborted ? -ECANCELED : sink->stream_error;
   761	
   762	          /* Return APBs on the PCM timeline so adevsink can continuously
   763	           * refill its queue.  PCM was already copied into the native ring;
   764	           * the I2S/DMA backend owns actual speaker delivery. */
   765	          if (ret == OK)
   766	            {
   767	              contest_media_pace_delay(sink, entry.bytes);
   768	              if (contest_media_pace_aborted(sink))
   769	                {
   770	                  ret = -ECANCELED;
   771	                }
   772	            }
   773	
   774	          /* Keep diagnostics tied to the real backend, while APB ownership
   775	           * follows the Media pacing timeline above. */
   776	          if (contest_media_progress(sink, &played, &pending, NULL) == OK)
   777	            {
   778	              dma_done = played >= entry.endpoint;
   779	            }
   780	
   781	          /* STOP can arrive while waiting. Do not turn that cancellation
   782	           * into natural EOS or finish()/drain the queued music. */
   783	          aborted = contest_media_pace_aborted(sink);
   784	          if (ret < 0 && !aborted)
   785	            {
   786	              sink->stream_error = ret;
   787	            }
   788	
   789	          contest_media_dequeue(sink, entry.apb,
   790	                                ret < 0 ? (uint16_t)-ret : OK);
   791	          sink->dequeue_count++;
   792	
   793	          if (sink->dequeue_count <= 4 ||
   794	              (sink->dequeue_count % 32) == 0 ||
   795	              entry.final)
   796	            {
   797	              syslog(LOG_INFO,
   798	                     "[MEDIA-BRIDGE] PCM dequeue #%u bytes=%zu "
   799	                     "dma_done=%d final=%d played=%zu copied=%zu\n",
   800	                     sink->dequeue_count, entry.bytes,
   801	                     dma_done ? 1 : 0, entry.final ? 1 : 0,
   802	                     (size_t)played, sink->total_pcm);
   803	            }
   804	
   805	          if (entry.final && !aborted && ret == OK)
   806	            {
   807	              int finish_ret;
   808	
   809	              /* FINAL's actual samples have completed DMA. Finish joins
   810	               * the backend worker and closes before announcing COMPLETE. */
   811	              finish_ret = contest_media_finish_playback(sink, true);
   812	              if (finish_ret < 0) sink->stream_error = finish_ret;
   813	              contest_media_complete(sink);
   814	
   815	              if (finish_ret < 0)
   816	                {
   817	                  syslog(LOG_ERR,
   818	                         "[MEDIA-BRIDGE] final drain failed=%d\n", finish_ret);
   819	                }
   820	            }
   821	
   822	          /* Mark the APB idle only after its callback and any FINAL handling
   823	           * have finished.  STOP waits for this flag as well as an empty
   824	           * queue, otherwise it can race the current DMA wait operation. */
   825	          if (nxsem_wait_uninterruptible(&sink->pace_lock) == OK)
   826	            {
   827	              bool failed = sink->stream_error < 0 && !sink->pace_abort &&
   828	                            sink->pace_count == 0;
   829	              sink->pace_busy = false;
   830	              nxsem_post(&sink->pace_empty);
   831	              nxsem_post(&sink->pace_lock);
   832	              if (failed)
   833	                {
   834	                  syslog(LOG_ERR, "[MEDIA-BRIDGE] DMA failed rc=%d\n",
   835	                         sink->stream_error);
   836	                  (void)contest_media_finish_playback(sink, false);
   837	                  contest_media_complete(sink);
   838	                }
   839	            }
   840	        }
   841	    }
   842	
   843	  return NULL;
   844	}
   845	
   846	static int contest_media_queue_apb(FAR struct contest_media_sink_s *sink,
   847	                                   FAR struct ap_buffer_s *apb,
   848	                                   size_t bytes, bool final)
   849	{
   850	  int ret;
   851	
   852	  ret = nxsem_wait_uninterruptible(&sink->pace_lock);
   853	  if (ret < 0)
   854	    {
   855	      return ret;
   856	    }
   857	
   858	  if (sink->pace_count >= CONTEST_MEDIA_PACE_QUEUE)
   859	    {
   860	      nxsem_post(&sink->pace_lock);
   861	      syslog(LOG_ERR,
   862	             "[MEDIA-BRIDGE] pacer queue full count=%u\n",
   863	             sink->pace_count);
   864	      return -ENOMEM;
   865	    }
   866	
   867	  sink->pending[sink->pace_tail].apb = apb;
   868	  sink->pending[sink->pace_tail].bytes = bytes;
   869	  sink->pending[sink->pace_tail].endpoint = sink->total_pcm;
   870	  sink->pending[sink->pace_tail].final = final;
  1120	         caps->ac_subtype, (unsigned long)sample_rate, channels, bits);
  1121	
  1122	  if (sample_rate != CONTEST_MEDIA_RATE ||
  1123	      channels != CONTEST_MEDIA_CHANNELS ||
  1124	      bits != CONTEST_MEDIA_BITS)
  1125	    {
  1126	      syslog(LOG_ERR,
  1127	             "[MEDIA-BRIDGE] format rejected expected=%uHz/%uch/%ubit\n",
  1128	             CONTEST_MEDIA_RATE, CONTEST_MEDIA_CHANNELS, CONTEST_MEDIA_BITS);
  1129	      return -EINVAL;
  1130	    }
  1131	
  1132	  sink->sample_rate = sample_rate;
  1133	  sink->channels = channels;
  1134	  sink->bits = bits;
  1135	  sink->configured = true;
  1136	  /* New configuration is a new stream, even after the preceding FINAL. */
  1137	  if (!sink->playback_open)
  1138	    {
  1139	      __atomic_store_n(&sink->completion_sent, false, __ATOMIC_RELEASE);
  1140	      sink->eos = false;
  1141	      sink->stream_error = OK;
  1142	    }
  1143	  return OK;
  1144	}
