  1183	
  1184	#ifndef CONFIG_AUDIO_EXCLUDE_STOP
  1185	#ifdef CONFIG_AUDIO_MULTI_SESSION
  1186	static int contest_media_stop(FAR struct audio_lowerhalf_s *dev,
  1187	                              FAR void *session)
  1188	#else
  1189	static int contest_media_stop(FAR struct audio_lowerhalf_s *dev)
  1190	#endif
  1191	{
  1192	  FAR struct contest_media_sink_s *sink =
  1193	    (FAR struct contest_media_sink_s *)dev;
  1194	  int ret;
  1195	
  1196	#ifdef CONFIG_AUDIO_MULTI_SESSION
  1197	  (void)session;
  1198	#endif
  1199	
  1200	  syslog(LOG_INFO, "[MEDIA-BRIDGE] STOP -> immediate abort/close\n");
  1201	
  1202	  /*
  1203	   * An explicit AUDIOIOC_STOP is a user/tool stop, not natural end-of-file.
  1204	   * Do not call robot_audio_playback_finish() here: finish() drains the
  1205	   * playback ring by design, which makes a "stop" command continue playing
  1206	   * any already-buffered PCM before the device is closed.
  1207	   *
  1208	   * First return APBs still waiting in the ownership queue, then close the
  1209	   * hardware path without draining the private PCM ring.  COMPLETE tells the
  1210	   * Media upper-half that this playback instance is terminal and permits the
  1211	   * caller to return to the normal vela> state.
  1212	   *
  1213	   * Natural EOF remains handled by the FINAL APB / worker path below, where
