}

static int robot_music_read_exact(int fd, uint8_t *buf, size_t len)
{
  size_t done = 0;

  while (done < len)
    {
      ssize_t nread = read(fd, buf + done, len - done);

      if (nread < 0)
        {
          if (errno == EINTR)
            {
              continue;
            }

          return -errno;
        }

      if (nread == 0)
        {
          return -EIO;
        }

      done += (size_t)nread;
    }

  return 0;
}

