#ifndef ROBOT_MEDIA_STARTUP_GRACE_US
#  define ROBOT_MEDIA_STARTUP_GRACE_US (1500 * 1000)
#endif

static bool g_robot_media_initialized;
static pthread_mutex_t g_robot_media_init_lock = PTHREAD_MUTEX_INITIALIZER;

#ifdef CONFIG_MEDIA
static bool robot_media_service_ready(void)
{
  void *player;

  errno = 0;
  player = media_player_open("Music");
  if (player != NULL)
    {
      (void)media_player_close(player, 0);
      return true;
    }

  return false;
}
#endif

/*
 * Media is deliberately started lazily.  Starting it during board bring-up
 * races Wi-Fi/DHCP and consumes resources before voice is ready.  The first
 * voice backend selection happens after set_wifi in the normal flow, so it is
 * a stable point to launch mediad once and give its IPC endpoint time to
 * appear.  A failed background shell status is not treated as a failure:
 * NSH may return before the detached task reports its status.
 */
static int robot_media_runtime_init_once(void)
{
  int ret;

  pthread_mutex_lock(&g_robot_media_init_lock);

  if (g_robot_media_initialized)
    {
      pthread_mutex_unlock(&g_robot_media_init_lock);
      return 0;
    }

  if (!network_is_connected())
    {
      printf("[RV-MEDIA] init deferred: WiFi is not connected yet\n");
      pthread_mutex_unlock(&g_robot_media_init_lock);
      return -ENETDOWN;
    }

  /* NSH users may start mediad explicitly.  Probe the actual IPC service
   * before launching another daemon; a second daemon cannot bind the same
   * local/RPMSG sockets and leaves the media stack in a broken state. */
#ifdef CONFIG_MEDIA
  if (robot_media_service_ready())
    {
      g_robot_media_initialized = true;
      printf("[RV-MEDIA] existing mediad service reused\n");
      pthread_mutex_unlock(&g_robot_media_init_lock);
      return 0;
    }
#endif

  printf("[RV-MEDIA] init begin -> launching: mediad &\n");
  ret = system("mediad &");
  if (ret != 0)
    {
      printf("[RV-MEDIA] background shell returned rc=%d; "
             "waiting for the Media IPC service\n", ret);
    }

  usleep(ROBOT_MEDIA_STARTUP_GRACE_US);
#ifdef CONFIG_MEDIA
  if (!robot_media_service_ready())
    {
      printf("[RV-MEDIA] mediad did not become ready\n");
      pthread_mutex_unlock(&g_robot_media_init_lock);
      return -EIO;
    }
#endif

  g_robot_media_initialized = true;
  printf("[RV-MEDIA] init complete; subsequent calls are no-op\n");
  pthread_mutex_unlock(&g_robot_media_init_lock);
  return 0;
}

