static int rv_write_pcm(struct rv_mp3_decoder *decoder, const int16_t *samples,
                        int sample_count, int channels, int sample_rate)
{
  int mono_count = 0;
  int output_count = 0;
  int i;

  if (channels < 1 || channels > 2 || sample_rate <= 0 ||
      sample_count <= 0)
    {
      return -EINVAL;
