                  return ret;
                }
              output_count = 0;
            }
        }
    }

  if (output_count > 0)
    {
      int ret = robot_audio_playback_write((const uint8_t *)decoder->pcm,
                                           (size_t)output_count * sizeof(int16_t));
      if (ret < 0)
        {
          return ret;
        }
    }

  return 0;
}

