    39	 *
    40	 * Description:
    41	 *   Parse an URL, not only HTTP ones. The parsing is according to this rule:
    42	 *   SCHEME :// HOST [: PORT] / PATH
    43	 *   - scheme is everything before the first colon
    44	 *   - scheme must be followed by ://
    45	 *   - host is everything until colon or slash
    46	 *   - port is optional, parsed only if host ends with colon
    47	 *   - path is everything after the host.
    48	 *   This is noticeably simpler that the official URL parsing method, since
    49	 *   - it does not take into account the user:pass@ part that can be present
    50	 *     before the host. Support of these fields is planned in the url_s
    51	 *     structure, but it is not parsed yet/
    52	 *   - it does not separate the URL parameters nor the bookmark
    53	 *   Note: see here for the documentation of a complete URL parsing routine:
    54	 *   https://www.php.net/manual/fr/function.parse-url.php
    55	 *
    56	 ****************************************************************************/
    57	
    58	int netlib_parseurl(FAR const char *str, FAR struct url_s *url)
    59	{
    60	  FAR const char *src = str;
    61	  FAR char *dest;
    62	  size_t bytesleft;
    63	  int ret = OK;
    64	  size_t pathlen;
    65	
    66	  /* Each fields should have at least 1 byte to store
    67	   * the terminating NUL.
    68	   */
    69	
    70	  if (url->schemelen == 0 || url->hostlen == 0 || url->pathlen == 0)
    71	    {
    72	      return -EINVAL;
    73	    }
    74	
    75	  /* extract the protocol field, a set of a-z letters */
    76	
    77	  dest      = url->scheme;
    78	  bytesleft = url->schemelen;
    79	
    80	  while (*src != '\0' && *src != ':')
    81	    {
    82	      /* Make sure that there is space for another character in the
    83	       * scheme (reserving space for the null terminator).
    84	       */
    85	
    86	      if (bytesleft > 1)
    87	        {
    88	          /* Copy the byte */
    89	
    90	          *dest++ = *src++;
    91	          bytesleft--;
    92	        }
    93	      else
    94	        {
    95	          /* Note the error, but continue parsing until the end of the
    96	           * hostname
    97	           */
    98	
    99	          src++;
   100	          ret = -E2BIG;
   101	        }
   102	    }
   103	
   104	  *dest = '\0';
   105	
   106	  /* Parse and skip the scheme separator */
   107	
   108	  if (*src != ':')
   109	    {
   110	      return -EINVAL;
   111	    }
   112	
   113	  src++;
   114	
   115	  if (*src != '/')
   116	    {
   117	      return -EINVAL;
   118	    }
   119	
   120	  src++;
   121	
   122	  if (*src != '/')
   123	    {
   124	      return -EINVAL;
   125	    }
   126	
   127	  src++;
   128	
   129	  /* Concatenate the hostname following http:// and up to the termnator */
   130	
   131	  dest      = url->host;
   132	  bytesleft = url->hostlen;
   133	
   134	  while (*src != '\0' && *src != '/' && *src != ' ' && *src != ':')
   135	    {
   136	      /* Make sure that there is space for another character in the
   137	       * hostname (reserving space for the null terminator).
   138	       */
   139	
   140	      if (bytesleft > 1)
   141	        {
   142	          /* Copy the byte */
   143	
   144	          *dest++ = *src++;
   145	          bytesleft--;
   146	        }
   147	      else
   148	        {
   149	          /* Note the error, but continue parsing until the end of the
   150	           * hostname
   151	           */
   152	
   153	          src++;
   154	          ret = -E2BIG;
   155	        }
   156	    }
   157	
   158	  *dest = '\0';
   159	
   160	  /* Check if the hostname is following by a port number */
   161	
   162	  if (*src == ':')
   163	    {
   164	      uint16_t accum = 0;
   165	      src++; /* Skip over the colon */
   166	
   167	      while (*src >= '0' && *src <= '9')
   168	        {
   169	          accum = 10*accum + *src - '0';
   170	          src++;
   171	        }
   172	
   173	      url->port = accum;
   174	    }
   175	
   176	  /* Make sure the file name starts with exactly one '/' */
   177	
   178	  dest      = url->path;
   179	  bytesleft = url->pathlen;
   180	
   181	  while (*src == '/')
   182	    {
   183	      src++;
   184	    }
   185	
   186	  /* Note: the current implementation does not distinguish
   187	   * an empty path and "/". While it's fine for HTTP, maybe it's
   188	   * cleaner to move the HTTP-specific normalization to the caller.
   189	   */
   190	
   191	  *dest++ = '/';
   192	  bytesleft--;
   193	
   194	  /* The copy the rest of the file name to the user buffer */
   195	
   196	  pathlen = strlen(src);
   197	  if (bytesleft >= pathlen + 1)
   198	    {
   199	      memcpy(dest, src, pathlen);
   200	      dest[pathlen] = '\0';
   201	    }
   202	  else
   203	    {
   204	      dest[0] = '\0';
   205	      ret = -E2BIG;
   206	    }
   207	
   208	  return ret;
   209	}

