   431	                        struct ap_buffer_s *apb,
   432	                        void *arg, int result)
   433	{
   434	  struct rv_slot_s *slot = arg;
   435	  struct rv_playback_s *pb;
   436	
   437	  (void)dev;
   438	
   439	  if (slot == NULL || slot->pb == NULL)
   440	    {
   441	      return;
   442	    }
   443	
   444	  pb = slot->pb;
   445	
   446	  if (rv_lock(pb) == 0)
   447	    {
   448	      if (!slot->inflight || (apb && apb != slot->apb))
   449	        {
   450	          pb->callback_errors++;
   451	          if (pb->i2s_result >= 0) pb->i2s_result = -EPROTO;
   452	          rv_unlock(pb);
   453	          nxsem_post(&slot->done);
   454	          nxsem_post(&pb->i2s_done);
   455	          return;
   456	        }
   457	      slot->done_ms = rv_audio_now_ms();
   458	      if (pb->last_callback_ms &&
   459	          slot->done_ms - pb->last_callback_ms > pb->max_callback_gap_ms)
   460	        pb->max_callback_gap_ms = slot->done_ms - pb->last_callback_ms;
   461	      pb->last_callback_ms = slot->done_ms;
   462	      slot->result = result;
   463	      if (result == 0) pb->completed_source_bytes += slot->source_bytes;
   464	      slot->source_bytes = 0;
   465	      slot->inflight = 0;
   466	      slot->done_count++;
   467	
   468	      if (result < 0 && result != -ECANCELED && pb->i2s_result >= 0)
   469	        {
   470	          pb->i2s_result = result;
   471	        }
   472	
   473	      if (pb->i2s_inflight > 0)
   474	        {
   475	          pb->i2s_inflight--;
   476	        }
   477	
   478	      rv_unlock(pb);
   479	    }
   480	  else
   481	    {
   482	      slot->result = result;
   483	      if (result == 0) pb->completed_source_bytes += slot->source_bytes;
   484	      slot->source_bytes = 0;
   485	      slot->inflight = 0;
   486	      slot->done_count++;
