   112	static void rv_emit_event(struct rv_media_player *player, int event,
   113	                          int result)
   114	{
   115	  struct rv_media_event *pending;
   116	  pthread_t thread;
   117	  pthread_attr_t attr;
   118	
   119	  pthread_mutex_lock(&player->lock);
   120	  if (!player->callback)
   121	    {
   122	      pthread_mutex_unlock(&player->lock);
   123	      return;
   124	    }
   125	
   126	  pending = calloc(1, sizeof(*pending));
   127	  if (!pending)
   128	    {
   129	      pthread_mutex_unlock(&player->lock);
   130	      syslog(LOG_ERR, "[%s] event allocation failed event=%d\n",
   131	             RV_MEDIA_TAG, event);
   132	      return;
   133	    }
   134	
   135	  pending->callback = player->callback;
   136	  pending->cookie = player->callback_cookie;
   137	  pending->event = event;
   138	  pending->result = result;
   139	  pthread_mutex_unlock(&player->lock);
   140	
   141	  if (pthread_attr_init(&attr) != 0)
   142	    {
   143	      free(pending);
   144	      return;
   145	    }
   146	
   147	  (void)pthread_attr_setstacksize(&attr, 4096);
   148	  if (pthread_create(&thread, &attr, rv_event_worker, pending) == 0)
   149	    {
   150	      (void)pthread_detach(thread);
   151	    }
   152	  else
   153	    {
   154	      free(pending);
   155	    }
   156	
   157	  pthread_attr_destroy(&attr);
   158	}
