   238	static int rv_mp3_decode(struct rv_mp3_decoder *decoder,
   239	                         const unsigned char *data, size_t len)
   240	{
   241	  if (len > sizeof(decoder->input) - decoder->input_len)
   242	    {
   243	      return -ENOBUFS;
   244	    }
   245	
   246	  memcpy(decoder->input + decoder->input_len, data, len);
   247	  decoder->input_len += len;
   248	
   249	  while (decoder->input_len > 0)
   250	    {
   251	      int sync = MP3FindSyncWord(decoder->input, (int)decoder->input_len);
   252	      unsigned char *cursor;
   253	      int left;
   254	      int consumed;
   255	      int ret;
   256	      MP3FrameInfo info;
   257	
   258	      if (sync < 0)
   259	        {
   260	          /* Keep enough bytes for a sync word split across HTTP chunks. */
   261	          if (decoder->input_len > 3)
   262	            {
   263	              memmove(decoder->input, decoder->input + decoder->input_len - 3,
   264	                      3);
   265	              decoder->input_len = 3;
   266	            }
   267	          break;
   268	        }
   269	
   270	      if (sync > 0)
   271	        {
   272	          memmove(decoder->input, decoder->input + sync,
   273	                  decoder->input_len - (size_t)sync);
   274	          decoder->input_len -= (size_t)sync;
   275	        }
   276	
   277	      cursor = decoder->input;
   278	      left = (int)decoder->input_len;
   279	      ret = MP3Decode(decoder->decoder, &cursor, &left, decoder->decoded, 0);
   280	      consumed = (int)(cursor - decoder->input);
   281	      if (consumed > 0 && (size_t)consumed <= decoder->input_len)
   282	        {
   283	          memmove(decoder->input, decoder->input + consumed,
   284	                  decoder->input_len - (size_t)consumed);
   285	          decoder->input_len -= (size_t)consumed;
   286	        }
   287	
   288	      if (ret == ERR_MP3_INDATA_UNDERFLOW || ret == ERR_MP3_MAINDATA_UNDERFLOW)
   289	        {
   290	          break;
   291	        }
