1777	int robot_audio_playback_write(const uint8_t *pcm, size_t len)
1778	{
1779	  struct rv_playback_s *pb = &g_pb;
1780	  size_t offset = 0;
1781	
1782	  if (!pb->opened || pcm == NULL || len == 0)
1783	    {
1784	      return -EINVAL;
1785	    }
1786	
1787	  if ((len & 1) != 0)
1788	    {
1789	      /* PCM16 producer chunks must preserve sample alignment. */
1790	      printf("[RV-PB] reject odd PCM chunk len=%zu\n", len);
1791	      return -EINVAL;
1792	    }
1793	
1794	  if (pb->cache_until_eos)
1795	    {
1796	      size_t required;
1797	      int lock_ret = rv_lock(pb);
1798	      if (lock_ret < 0) return lock_ret;
1799	      if (pb->eos || pb->stopped)
1800	        { rv_unlock(pb); return pb->stopped ? -ECANCELED : -EPIPE; }
1801	      if (len > ROBOT_VOICE_TTS_CACHE_BYTES - pb->total_written)
1802	        {
1803	          rv_unlock(pb);
1804	          printf("[RV-PB] cache overflow id=%u incoming=%zu cached=%zu limit=%u; no audio played\n",
1805	                 pb->id, len, pb->total_written, ROBOT_VOICE_TTS_CACHE_BYTES);
1806	          return -EOVERFLOW;
1807	        }
1808	      required = pb->total_written + len;
1809	      if (required > pb->ring.capacity)
1810	        {
1811	          size_t capacity = pb->ring.capacity;
1812	          uint8_t *data;
1813	          while (capacity < required) capacity *= 2;
1814	          if (capacity > ROBOT_VOICE_TTS_CACHE_BYTES)
1815	            capacity = ROBOT_VOICE_TTS_CACHE_BYTES;
1816	          /* Voice has not consumed any PCM yet. It is contiguous from zero;
1817	           * restore head=count if the old capacity was exactly full. */
1818	          data = realloc(pb->ring.data, capacity);
1819	          if (!data) { rv_unlock(pb); return -ENOMEM; }
1820	          pb->ring.data = data;
1821	          pb->ring.capacity = capacity;
1822	          pb->ring.head = pb->ring.count;
1823	        }
1824	      rv_unlock(pb);
1825	    }
1826	
1827	  /*
1828	   * Producer side from tts_pcm_playback_guide.md:
1829	   *
1830	   * Never fail a valid long utterance just because the 256 KiB ring is
1831	   * temporarily full.  Wait for the dedicated playback worker to free space,
1832	   * then continue writing the same PCM chunk.
1833	   */
1834	  while (offset < len)
1835	    {
1836	      size_t buffered;
1837	      size_t space;
1838	      size_t n;
1839	      int ret;
1840	
1841	      if (pb->stopped)
1842	        {
1843	          return pb->terminal_tail_done ? -EPIPE : -ECANCELED;
1844	        }
1845	
1846	      ret = rv_get_result(pb);
1847	      if (ret < 0)
1848	        {
1849	          return ret;
1850	        }
1851	
1852	      buffered = rv_ring_count(pb);
1853	      space = pb->ring.capacity - buffered;
1854	      if (space < 2)
1855	        {
1856	          ret = nxsem_wait_uninterruptible(&pb->ring_space);
1857	          if (ret < 0)
1858	            {
1859	              return ret;
1860	            }
1861	          continue;
1862	        }
1863	
1864	      n = len - offset;
1865	      if (n > space)
1866	        {
1867	          n = space;
1868	        }
1869	
1870	      n &= ~(size_t)1;
1871	      if (n == 0)
1872	        {
1873	          continue;
1874	        }
1875	
1876	      ret = rv_ring_write(pb, pcm + offset, n);
1877	      if (ret == -ENOSPC)
1878	        {
1879	          continue;
1880	        }
1881	      if (ret < 0)
1882	        {
1883	          return ret;
1884	        }
1885	
1886	      offset += n;
1887	    }
1888	
1889	  return 0;
1890	}
