1387	      RV_VERBOSE("[RV-PB] I2S width request=%u actual=%d\n",
1388	             RV_WIRE_BITS, actual_width);
1389	      ret = actual_width < 0 ? actual_width : -ENOTSUP;
1390	      goto fail;
1391	    }
1392	
1393	  /* Include the upper APBs in the REAL allocation budget before requesting
1394	   * private DMA. apb_alloc can itself use internal memory on some builds.
1395	   * A smaller lower ring releases unused upper APBs before playback starts. */
