1027	static int contest_i2s_rx_interrupt(int irq, FAR void *context,
1028	                                    FAR void *arg)
1029	{
1030	  FAR struct contest_i2s_s *priv = arg;
1031	  uint32_t status;
1032	  irqstate_t flags;
1033	
1034	  (void)irq;
1035	  (void)context;
1036	
1037	  status = GET_GDMA_CH_REG(DMA_IN_INT_ST_CH0_REG, priv->dma_channel);
1038	  SET_GDMA_CH_REG(DMA_IN_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);
1039	
1040	  if ((status & (DMA_IN_SUC_EOF_CH0_INT_ST |
1041	                 DMA_IN_ERR_EOF_CH0_INT_ST)) == 0)
1042	    {
1043	      return OK;
1044	    }
1045	
1046	  flags = spin_lock_irqsave(&priv->lock);
1047	  if (priv->active != NULL)
1048	    {
1049	      priv->irq_status = status;
1050	      if ((status & DMA_IN_SUC_EOF_CH0_INT_ST) != 0)
1051	        {
1052	          priv->active->result = OK;
1053	          contest_i2s_rx_done_push(priv, priv->active);
1054	          priv->active = priv->pending;
1055	          priv->pending = NULL;
1056	          priv->eof_count++;
1057	
1058	          if (priv->active != NULL && priv->streaming)
1059	            {
1060	              contest_i2s_rx_start_active(priv);
1061	              priv->chained_count++;
1062	              if (priv->eof_count <= 2)
1063	                {
1064	                  syslog(LOG_INFO, "[C-I2S] rx eof=%lu chained\n",
1065	                         (unsigned long)priv->eof_count);
1066	                }
1067	            }
1068	          else
1069	            {
1070	              /* No pending transaction is either the intentional final
1071	               * drain or a potential underrun.  Count it only if a later
1072	               * submission resumes this idle stream.
1073	               */
1074	
1075	              priv->idle = true;
1076	            }
1077	        }
1078	      else
1079	        {
1080	          priv->active->result = -EIO;
1081	          contest_i2s_rx_done_push(priv, priv->active);
1082	          priv->active = NULL;
1083	          if (priv->pending != NULL)
1084	            {
1085	              priv->pending->result = -ECANCELED;
1086	              contest_i2s_rx_done_push(priv, priv->pending);
1087	              priv->pending = NULL;
1088	            }
1089	
1090	          priv->streaming = false;
1091	          contest_i2s_stop_hw(priv);
1092	        }
1093	
1094	      if (work_available(&priv->rx_work))
1095	        {
1096	          work_queue(HPWORK, &priv->rx_work, contest_i2s_rx_worker, priv,
1097	                     0);
1098	        }
1099	    }
1100	
1101	  spin_unlock_irqrestore(&priv->lock, flags);
1102	  return OK;
1103	}
