 292	static int rv_ring_write(struct rv_playback_s *pb,
 293	                         const uint8_t *src, size_t len)
 294	{
 295	  size_t first;
 296	  size_t second;
 297	  size_t space;
 298	  int ret;
 299	
 300	  if (pb == NULL || src == NULL || len == 0)
 301	    {
 302	      return -EINVAL;
 303	    }
 304	
 305	  if (pb->stopped)
 306	    {
 307	      return -ECANCELED;
 308	    }
 309	
 310	  ret = rv_lock(pb);
 311	  if (ret < 0)
 312	    {
 313	      return ret;
 314	    }
 315	
 316	  if (pb->eos)
 317	    {
 318	      rv_unlock(pb);
 319	      return -EPIPE;
 320	    }
 321	
 322	  space = pb->ring.capacity - pb->ring.count;
 323	  if (len > space)
 324	    {
 325	      size_t buffered = pb->ring.count;
 326	      rv_unlock(pb);
 327	
 328	      RV_VERBOSE("[RV-PB] PCM cache full buffered=%zu incoming=%zu capacity=%u\n",
 329	             buffered, len, (unsigned int)pb->ring.capacity);
 330	      return -ENOSPC;
 331	    }
 332	
 333	  first = pb->ring.capacity - pb->ring.head;
 334	  if (first > len)
 335	    {
 336	      first = len;
 337	    }
 338	
 339	  memcpy(pb->ring.data + pb->ring.head, src, first);
 340	  pb->ring.head = (pb->ring.head + first) % pb->ring.capacity;
 341	  pb->ring.count += first;
 342	
 343	  second = len - first;
 344	  if (second > 0)
 345	    {
 346	      memcpy(pb->ring.data + pb->ring.head, src + first, second);
 347	      pb->ring.head = (pb->ring.head + second) % pb->ring.capacity;
 348	      pb->ring.count += second;
 349	    }
 350	
 351	  if (pb->ring.count > pb->ring_max_play)
 352	    {
 353	      pb->ring_max_play = pb->ring.count;
 354	    }
 355	
 356	  {
 357	    unsigned long long now = rv_audio_now_ms();
 358	    if (!pb->first_pcm_ms) pb->first_pcm_ms = now;
 359	    if (pb->last_pcm_ms && now - pb->last_pcm_ms > pb->max_pcm_gap_ms)
 360	      pb->max_pcm_gap_ms = now - pb->last_pcm_ms;
 361	    pb->last_pcm_ms = now;
 362	    pb->input_hash = rv_pcm_hash(pb->input_hash, src, len);
 363	    pb->total_written += len;
 364	  }
 365	  rv_unlock(pb);
 366	  nxsem_post(&pb->ring_data);
 367	  return 0;
 368	}
 369	
 370	static size_t rv_ring_read(struct rv_playback_s *pb,
 371	                           uint8_t *dst, size_t wanted)
 372	{
 373	  size_t n;
 374	  size_t first;
 375	
 376	  if (rv_lock(pb) < 0)
 377	    {
 378	      return 0;
 379	    }
 380	
 381	  n = pb->ring.count;
 382	  if (n > wanted)
 383	    {
 384	      n = wanted;
 385	    }
 386	
 387	  first = pb->ring.capacity - pb->ring.tail;
 388	  if (first > n)
 389	    {
 390	      first = n;
 391	    }
 392	
 393	  if (first > 0)
 394	    {
 395	      memcpy(dst, pb->ring.data + pb->ring.tail, first);
 396	      pb->ring.tail = (pb->ring.tail + first) % pb->ring.capacity;
 397	      pb->ring.count -= first;
 398	    }
 399	
 400	  if (first < n)
 401	    {
 402	      size_t second = n - first;
 403	
 404	      memcpy(dst + first, pb->ring.data + pb->ring.tail, second);
 405	      pb->ring.tail = (pb->ring.tail + second) % pb->ring.capacity;
 406	      pb->ring.count -= second;
 407	    }
 408	
 409	  if ((pb->state == RV_STATE_PLAYING || pb->state == RV_STATE_DRAINING) &&
 410	      pb->ring.count < pb->ring_min_play)
 411	    {
 412	      pb->ring_min_play = pb->ring.count;
 413	    }
 414	
 415	  if (n > 0)
 416	    {
 417	      pb->output_hash = rv_pcm_hash(pb->output_hash, dst, n);
 418	      pb->total_read += n;
 419	    }
 420	  rv_unlock(pb);
 421	
 422	  if (n > 0)
 423	    {
 424	      nxsem_post(&pb->ring_space);
 425	    }
 426	
 427	  return n;
 428	}
