1943	          ret = -join_ret;
1944	        }
1945	
1946	      pb->worker_started = 0;
1947	    }
1948	
1949	  if (rv_get_result(pb) < 0 && ret >= 0)
1950	    {
1951	      ret = rv_get_result(pb);
1952	    }
1953	
1954	  if (pb->i2s != NULL && pb->i2s_started)
