  1904	static void contest_i2s_tx_set_format(FAR struct contest_i2s_tx_s *priv)
  1905	{
  1906	  uint32_t value = priv->data_width - 1;
  1907	
  1908	  /* ESP32-S3 standard Philips-I2S timing used by the original board driver:
  1909	   *
  1910	   *   - two physical 32-bit slots per WS frame
  1911	   *   - WS width = one slot = 32 BCLKs (50% LRCK duty cycle)
  1912	   *   - one-BCLK MSB shift (Philips, not left-justified)
  1913	   *   - only the left slot carries the mono PCM word
  1914	   *   - MSB first, normal byte order, with data left-aligned in that word
  1915	   *
  1916	   * Keep all of these explicit.  Relying on reset defaults makes this board
  1917	   * path fragile when another I2S user has touched the peripheral before us.
  1918	   */
  1919	
  1920	  modifyreg32(I2S_TX_CONF1_REG(CONTEST_I2S_TX_PORT), I2S_TX_BITS_MOD_M,
  1921	              FIELD_TO_VALUE(I2S_TX_BITS_MOD, value));
  1922	  modifyreg32(I2S_TX_CONF1_REG(CONTEST_I2S_TX_PORT),
  1923	              I2S_TX_TDM_CHAN_BITS_M,
  1924	              FIELD_TO_VALUE(I2S_TX_TDM_CHAN_BITS, value));
  1925	  modifyreg32(I2S_TX_CONF1_REG(CONTEST_I2S_TX_PORT),
  1926	              I2S_TX_HALF_SAMPLE_BITS_M,
  1927	              FIELD_TO_VALUE(I2S_TX_HALF_SAMPLE_BITS, value));
  1928	  modifyreg32(I2S_TX_CONF1_REG(CONTEST_I2S_TX_PORT),
  1929	              I2S_TX_TDM_WS_WIDTH_M,
  1930	              FIELD_TO_VALUE(I2S_TX_TDM_WS_WIDTH, value));
  1931	  modifyreg32(I2S_TX_CONF1_REG(CONTEST_I2S_TX_PORT),
  1932	              I2S_TX_MSB_SHIFT_M, I2S_TX_MSB_SHIFT);
  1933	
  1934	#ifdef I2S_TX_WS_IDLE_POL
  1935	  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT),
  1936	              I2S_TX_WS_IDLE_POL, 0);
  1937	#endif
  1938	
  1939	#ifdef I2S_TX_LEFT_ALIGN
  1940	  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT),
  1941	              0, I2S_TX_LEFT_ALIGN);
  1942	#endif
  1943	
  1944	
  1945	#ifdef I2S_TX_BIG_ENDIAN
  1946	  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT),
  1947	              I2S_TX_BIG_ENDIAN, 0);
  1948	#endif
  1949	
  1950	#ifdef I2S_TX_BIT_ORDER
  1951	  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT),
  1952	              I2S_TX_BIT_ORDER, 0);
  1953	#endif
  1954	
  1955	#ifdef I2S_TX_PCM_BYPASS
  1956	  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT),
  1957	              0, I2S_TX_PCM_BYPASS);
  1958	#endif
  1959	
  1960	  contest_i2s_tx_update_wait();
