  1963	static void contest_i2s_tx_set_rate(FAR struct contest_i2s_tx_s *priv)
  1964	{
  1965	  uint32_t mclk = priv->rate * CONTEST_I2S_MCLK_MULTIPLE;
  1966	  uint32_t mclk_div = CONTEST_I2S_SOURCE_CLOCK / mclk;
  1967	  uint32_t freq_diff = CONTEST_I2S_SOURCE_CLOCK % mclk;
  1968	  uint32_t bclk = priv->rate * CONTEST_I2S_TX_SLOTS * priv->data_width;
  1969	  uint32_t bclk_div = mclk / bclk;
  1970	  uint32_t numerator = 0;   /* b */
  1971	  uint32_t denominator = 1; /* a */
  1972	  uint32_t x = 0;
  1973	  uint32_t y = 0;
  1974	  uint32_t z = 0;
  1975	  uint32_t yn1 = 0;
  1976	  uint32_t regval;
  1977	  uint32_t a;
  1978	
  1979	  /*
  1980	   * Match Espressif ESP32-S3 i2s_ll_tx_set_clk() semantics exactly.
  1981	   *
  1982	   *   Fmclk = Fsrc / (N + b/a)
  1983	   *
  1984	   * The previous local implementation had a subtle but critical error:
  1985	   * for b <= a/2 it programmed Y = a % b, while the ESP32-S3 LL requires
  1986	   * Y = a % b + 1.
  1987	   *
  1988	   * At 24 kHz:
  1989	   *   mclk = 6.144 MHz
  1990	   *   160 MHz / 6.144 MHz = 26 + 1/24
  1991	   *   N=26, a=24, b=1 -> X=23, Y=1, Z=1, YN1=0.
  1992	   */
  1993	
  1994	  if (mclk == 0 || bclk == 0 || bclk_div == 0)
  1995	    {
  1996	      return;
  1997	    }
  1998	
  1999	  if (freq_diff != 0)
  2000	    {
  2001	      for (a = 2; a <= 63; a++)
  2002	        {
  2003	          uint32_t b = (freq_diff * a + mclk / 2) / mclk;
  2004	
  2005	          if (b != 0 && freq_diff * a == mclk * b)
  2006	            {
  2007	              numerator = b;
  2008	              denominator = a;
  2009	              break;
  2010	            }
  2011	        }
  2012	    }
  2013	
  2014	  if (numerator != 0)
  2015	    {
  2016	      if (numerator > denominator / 2)
  2017	        {
  2018	          uint32_t inv = denominator - numerator;
  2019	
  2020	          x = denominator / inv - 1;
  2021	          y = denominator % inv;
  2022	          z = inv;
  2023	          yn1 = 1;
  2024	        }
  2025	      else
  2026	        {
  2027	          x = denominator / numerator - 1;
  2028	          y = denominator % numerator + 1;
  2029	          z = numerator;
  2030	          yn1 = 0;
  2031	        }
  2032	    }
  2033	
  2034	  regval = getreg32(I2S_TX_CLKM_DIV_CONF_REG(CONTEST_I2S_TX_PORT));
  2035	  regval &= ~(I2S_TX_CLKM_DIV_Z_M | I2S_TX_CLKM_DIV_Y_M |
  2036	              I2S_TX_CLKM_DIV_X_M | I2S_TX_CLKM_DIV_YN1_M);
  2037	  regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_Z, z);
  2038	  regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_Y, y);
  2039	  regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_X, x);
  2040	  if (yn1 != 0)
  2041	    {
  2042	      regval |= I2S_TX_CLKM_DIV_YN1_M;
  2043	    }
  2044	
  2045	  putreg32(regval, I2S_TX_CLKM_DIV_CONF_REG(CONTEST_I2S_TX_PORT));
  2046	
  2047	  regval = getreg32(I2S_TX_CLKM_CONF_REG(CONTEST_I2S_TX_PORT));
  2048	  regval &= ~I2S_TX_CLKM_DIV_NUM_M;
  2049	  regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_NUM, mclk_div);
  2050	  putreg32(regval, I2S_TX_CLKM_CONF_REG(CONTEST_I2S_TX_PORT));
  2051	
  2052	  modifyreg32(I2S_TX_CONF1_REG(CONTEST_I2S_TX_PORT), I2S_TX_BCK_DIV_NUM_M,
  2053	              FIELD_TO_VALUE(I2S_TX_BCK_DIV_NUM, bclk_div - 1));
  2054	
  2055	  contest_i2s_tx_update_wait();
  2056	
  2057	  syslog(LOG_INFO,
  2058	         "[C-I2S] tx fracclk rate=%lu N=%lu a=%lu b=%lu "
  2059	         "X=%lu Y=%lu Z=%lu YN1=%lu bdiv=%lu\n",
  2060	         (unsigned long)priv->rate,
  2061	         (unsigned long)mclk_div,
  2062	         (unsigned long)denominator,
  2063	         (unsigned long)numerator,
  2064	         (unsigned long)x,
  2065	         (unsigned long)y,
  2066	         (unsigned long)z,
  2067	         (unsigned long)yn1,
  2068	         (unsigned long)bclk_div);
  2069	}
