  2071	static void contest_i2s_tx_set_channels(
  2072	  FAR struct contest_i2s_tx_s *priv)
  2073	{
  2074	  uint32_t channels_mask;
  2075	
  2076	  /* The original ESP-IDF simplex codec uses slot_mode=MONO with LEFT mask.
  2077	   * On ESP32-S3 HW v2 TX_MONO means *copy to both slots* and is therefore
  2078	   * deliberately clear here; the LEFT channel mask provides the one active
  2079	   * DMA word per frame.  Two physical slots (TOT_CHAN_NUM=1) still preserve
  2080	   * the 64-BCLK LRCK frame. */
  2081	  modifyreg32(I2S_TX_TDM_CTRL_REG(CONTEST_I2S_TX_PORT),
  2082	              I2S_TX_TDM_TOT_CHAN_NUM_M,
  2083	              FIELD_TO_VALUE(I2S_TX_TDM_TOT_CHAN_NUM, 1));
  2084	
  2085	  DEBUGASSERT(priv->channels == 1);
  2086	  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT),
  2087	              I2S_TX_MONO_M | I2S_TX_CHAN_EQUAL_M, 0);
  2088	
  2089	  channels_mask = getreg32(I2S_TX_TDM_CTRL_REG(CONTEST_I2S_TX_PORT));
  2090	  channels_mask &= 0xffff0000;
  2091	#ifdef I2S_TX_TDM_SKIP_MSK_EN
  2092	  channels_mask &= ~I2S_TX_TDM_SKIP_MSK_EN;
  2093	#endif
  2094	  channels_mask |= I2S_TX_TDM_CHAN0_EN;
  2095	
  2096	  putreg32(channels_mask, I2S_TX_TDM_CTRL_REG(CONTEST_I2S_TX_PORT));
  2097	  contest_i2s_tx_update_wait();
  2098	}
