175	static int rv_write_pcm(struct rv_mp3_decoder *decoder, const int16_t *samples,
176	                        int sample_count, int channels, int sample_rate)
177	{
178	  int mono_count = 0;
179	  int output_count = 0;
180	  int i;
181	
182	  if (channels < 1 || channels > 2 || sample_rate <= 0 ||
183	      sample_count <= 0)
184	    {
185	      return -EINVAL;
186	    }
187	
188	  for (i = 0; i < sample_count / channels && mono_count <
189	       (int)(sizeof(decoder->mono) / sizeof(decoder->mono[0])); i++)
190	    {
191	      int value = samples[i * channels];
192	      if (channels == 2)
193	        {
194	          value = (value + samples[i * channels + 1]) / 2;
195	        }
196	
197	      decoder->mono[mono_count++] = (int16_t)value;
198	    }
199	
200	  /* A small accumulator is sufficient here because the output contract is
201	   * fixed at 24 kHz. It avoids a second large resampling buffer. */
202	  for (i = 0; i < mono_count; i++)
203	    {
204	      decoder->phase += RV_OUTPUT_RATE;
205	      if (decoder->phase >= sample_rate)
206	        {
207	          decoder->phase -= sample_rate;
208	          decoder->pcm[output_count++] =
209	            (int16_t)((decoder->mono[i] * RV_MUSIC_GAIN_NUM) /
210	                      RV_MUSIC_GAIN_DEN);
211	          if (output_count == (int)(sizeof(decoder->pcm) /
212	                                    sizeof(decoder->pcm[0])))
213	            {
214	              int ret = robot_audio_playback_write(
215	                  (const uint8_t *)decoder->pcm, sizeof(decoder->pcm));
216	              if (ret < 0)
217	                {
218	                  return ret;
219	                }
220	              output_count = 0;
221	            }
222	        }
223	    }
224	
225	  if (output_count > 0)
226	    {
227	      int ret = robot_audio_playback_write((const uint8_t *)decoder->pcm,
228	                                           (size_t)output_count * sizeof(int16_t));
229	      if (ret < 0)
230	        {
231	          return ret;
232	        }
233	    }
234	
235	  return 0;
236	}
