346	static int rv_normalize_url(const char *url, char *normalized, size_t cap)
347	{
348	  const char *prefix = "https://music.163.com/";
349	  size_t prefix_len = strlen(prefix);
350	
351	  if (!url || !normalized || cap == 0)
352	    {
353	      return -EINVAL;
354	    }
355	
356	  if (strncmp(url, prefix, prefix_len) == 0)
357	    {
358	      int n = snprintf(normalized, cap, "http://music.163.com/%s",
359	                       url + prefix_len);
360	      return n >= 0 && (size_t)n < cap ? 0 : -ENAMETOOLONG;
361	    }
362	
363	  if (strncmp(url, "http://", 7) == 0)
364	    {
365	      if (strlen(url) >= cap)
366	        {
367	          return -ENAMETOOLONG;
368	        }
369	      strcpy(normalized, url);
370	      return 0;
371	    }
372	
373	  return -ENOTSUP;
374	}
