376	static void *rv_url_worker(void *arg)
377	{
378	  struct rv_media_player *player = arg;
379	  int result = 0;
380	
381	#ifdef CONFIG_LIB_HELIX_MP3
382	  struct rv_mp3_decoder *decoder;
383	  char *http_buffer;
384	  struct webclient_context context;
385	
386	  decoder = calloc(1, sizeof(*decoder));
387	  http_buffer = malloc(RV_HTTP_BUFFER_CAP);
388	  if (!decoder || !http_buffer)
389	    {
390	      result = -ENOMEM;
391	      goto decoder_cleanup;
392	    }
393	
394	  decoder->decoder = MP3InitDecoder();
395	  if (!decoder->decoder)
396	    {
397	      result = -ENOMEM;
398	      goto decoder_cleanup;
399	    }
400	
401	  decoder->player = player;
402	
403	  webclient_set_defaults(&context);
404	  context.url = player->url;
405	  context.buffer = http_buffer;
406	  context.buflen = RV_HTTP_BUFFER_CAP;
407	  context.sink_callback = rv_mp3_sink;
408	  context.sink_callback_arg = decoder;
409	  context.timeout_sec = 30;
410	
411	  syslog(LOG_INFO, "[%s] HTTP MP3 begin url=%s\n", RV_MEDIA_TAG,
412	         player->url);
413	  result = webclient_perform(&context);
414	  if (rv_player_stop_requested(player))
415	    {
416	      /* A sink-side -ECANCELED is an expected user stop, not playback failure. */
417	      result = 0;
418	    }
419	  else if (result == 0 && context.http_status >= 300)
420	    {
421	      result = -EIO;
422	    }
423	
424	decoder_cleanup:
425	  if (decoder)
426	    {
427	      if (decoder->decoder)
428	        {
429	          MP3FreeDecoder(decoder->decoder);
430	        }
431	      free(decoder);
432	    }
433	  free(http_buffer);
434	#else
435	  result = -ENOSYS;
436	#endif
437	
438	  bool stopped = rv_player_stop_requested(player);
439	
440	  pthread_mutex_lock(&player->lock);
441	  bool playback_open = player->playback_open;
442	  player->playback_open = false;
443	  pthread_mutex_unlock(&player->lock);
444	  if (playback_open)
445	    {
446	      if (!stopped)
447	        {
448	          robot_audio_playback_finish();
449	        }
450	      robot_audio_playback_close();
451	    }
452	
453	  pthread_mutex_lock(&player->lock);
454	  player->worker_done = true;
455	  pthread_mutex_unlock(&player->lock);
456	
457	  if (stopped)
458	    {
459	      syslog(LOG_INFO, "[%s] HTTP MP3 stopped by request\n", RV_MEDIA_TAG);
460	    }
461	  else
462	    {
463	      syslog(result == 0 ? LOG_INFO : LOG_ERR,
464	             "[%s] HTTP MP3 complete rc=%d\n", RV_MEDIA_TAG, result);
465	      rv_emit_event(player, RV_EVENT_COMPLETED, result);
466	    }
467	  return NULL;
468	}
