bool robot_music_media_is_active(void)
{
  bool active;

  pthread_mutex_lock(&g_music_lock);
  active = g_active_music != NULL && g_active_music->started &&
           !g_active_music->closing;
  pthread_mutex_unlock(&g_music_lock);
