 * the microphone RX and speaker TX paths required by this board.
 ****************************************************************************/

#include <nuttx/config.h>

#if defined(CONFIG_CONTEST_BOARD_I2S0_RX) || \
    defined(CONFIG_CONTEST_BOARD_I2S1_TX)

#include <errno.h>
#include <limits.h>
#include <stdint.h>
#include <string.h>
