  bool dma_diag_armed;
  struct contest_i2s_rx_dma_diag_s dma_diag;
  struct work_s rx_work;
  struct contest_i2s_rx_xfer_s xfer[CONTEST_I2S_RX_XFER_COUNT];
};

struct contest_i2s_tx_s
{
  struct i2s_dev_s dev;
  spinlock_t lock;
