static const char* TAG = "vela_tls";

/* The contest WLAN netcard uses a 590-byte packet buffer.  Keep encrypted
 * application records below its TCP payload budget so a large audio upload
 * does not drive the vendor TX path through fragmented record bursts. */
#define TLS_WRITE_CHUNK_BYTES 480

/* The software CHACHA20-POLY1305 path was observed with CPU1 idle-stack
 * corruption during sustained uploads on this ESP32-S3 Wi-Fi build.  The MiMo
 * endpoint supports this TLS 1.2 AES-GCM suite, which uses the AES path. */
