  if (pb->ring.data == NULL)
    {
      printf("[RV-PB] ring alloc failed bytes=%u mode=%s\n",
             (unsigned int)pb->ring.capacity,
             RV_FULL_CACHE_AB_TEST ? "full-cache" : "streaming");
      return -ENOMEM;
    }

