         "source=%uHz/mono/%ubit wire=%uHz/mono-left/%ubit resample=none\n",
         RV_RING_BYTES, pb->start_prebuffer, RV_REBUFFER_BYTES,
         RV_TTS_SAMPLE_RATE, RV_TTS_BITS,
         RV_WIRE_SAMPLE_RATE, RV_WIRE_BITS);
  RV_VERBOSE("[RV-PB] open id=%u mode=%s capacity=%zu cache_limit=%u source=24000/mono16\n",
         pb->id, cache_until_eos ? "voice-complete-cache" : "music-stream",
         pb->ring.capacity, cache_until_eos ? ROBOT_VOICE_TTS_CACHE_BYTES : RV_RING_BYTES);
