    unsigned int sequence, unsigned long long ready_ms)
{
  struct rv_playback_s *pb = &g_pb;
  if (!pb->opened || rv_lock(pb) < 0) return;
  pb->run_id = run_id;
  pb->sentence = sequence;
  pb->tts_ready_ms = ready_ms;
  rv_unlock(pb);
}

int robot_audio_playback_open(void)
{
