 165	/* ── Persistent connection pool (keep-alive) ─────────────────── */
 166	/* Keeps one live TLS connection per host:port so repeated calls to
 167	 * the same endpoint (Feishu REST, LLM API) skip the TLS handshake. */
 168	
 169	#ifdef CONFIG_AI_AGENT_TLS_CONN_POOL_SIZE
 170	#define CONN_POOL_SIZE CONFIG_AI_AGENT_TLS_CONN_POOL_SIZE
 171	#else
 172	#define CONN_POOL_SIZE 2
 173	#endif
 174	
 175	typedef struct {
 176	    tls_ctx_t ctx;
 177	    char host[128];
 178	    char port[8];
 179	    bool in_use; /* locked by a request */
 180	    bool valid; /* connection is alive */
 181	} conn_slot_t;
 182	
 183	static conn_slot_t s_pool[CONN_POOL_SIZE];
 184	static pthread_mutex_t s_pool_lock = PTHREAD_MUTEX_INITIALIZER;
 185	
 186	/* The ESP32-S3 WLAN/TLS stack is not stable with overlapping handshakes.
 187	 * Keep the pool metadata lock short, but serialize the complete request
 188	 * lifecycle below so every caller shares one transport at a time. */
 189	static pthread_mutex_t s_transport_lock = PTHREAD_MUTEX_INITIALIZER;
 190	
 191	/* Acquire a slot for host:port.  Returns a locked, connected ctx or NULL. */
 192	static conn_slot_t* pool_acquire(const char* host, const char* port)
 193	{
 194	    pthread_mutex_lock(&s_pool_lock);
 195	
 196	    /* 1. Find an existing valid slot for this host:port */
 197	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
 198	        conn_slot_t* s = &s_pool[i];
 199	        if (s->valid && !s->in_use && strcmp(s->host, host) == 0 && strcmp(s->port, port) == 0) {
 200	            s->in_use = true;
 201	            pthread_mutex_unlock(&s_pool_lock);
 202	            return s;
 203	        }
 204	    }
 205	
 206	    /* 2. Find an empty slot */
 207	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
 208	        if (!s_pool[i].valid && !s_pool[i].in_use) {
 209	            s_pool[i].in_use = true;
 210	            pthread_mutex_unlock(&s_pool_lock);
 211	            return &s_pool[i];
 212	        }
 213	    }
 214	
 215	    /* 3. Evict the first non-in-use slot */
 216	    for (int i = 0; i < CONN_POOL_SIZE; i++) {
 217	        if (!s_pool[i].in_use) {
 218	            tls_ctx_free(&s_pool[i].ctx);
 219	            s_pool[i].valid = false;
 220	            s_pool[i].in_use = true;
 221	            pthread_mutex_unlock(&s_pool_lock);
 222	            return &s_pool[i];
 223	        }
 224	    }
 225	
 226	    pthread_mutex_unlock(&s_pool_lock);
 227	    return NULL; /* all slots busy — caller falls back to ephemeral */
 228	}
