 230	/* Return a slot to the pool.  keep=true means the connection is still alive. */
 231	static void pool_release(conn_slot_t* s, const char* host, const char* port, bool keep)
 232	{
 233	    pthread_mutex_lock(&s_pool_lock);
 234	    if (keep) {
 235	        strncpy(s->host, host, sizeof(s->host) - 1);
 236	        strncpy(s->port, port, sizeof(s->port) - 1);
 237	        s->valid = true;
 238	    } else {
 239	        tls_ctx_free(&s->ctx);
 240	        s->valid = false;
 241	        s->host[0] = '\0';
 242	    }
 243	    s->in_use = false;
 244	    pthread_mutex_unlock(&s_pool_lock);
