 480	    struct timespec start;
 481	    clock_gettime(CLOCK_MONOTONIC, &start);
 482	    bool startup_warned = false;
 483	
 484	    while (g_poll_running) {
 485	        bool has_ip = check_interfaces();
 486	
 487	        if (has_ip) {
 488	            set_net_state(NET_STATE_CONNECTED);
 489	            startup_warned = false;
 490	        } else {
 491	            set_net_state(NET_STATE_DISCONNECTED);
 492	
 493	            /* Check startup timeout */
 494	            if (!startup_warned) {
 495	                struct timespec now;
 496	                clock_gettime(CLOCK_MONOTONIC, &now);
 497	                long elapsed_ms = (now.tv_sec - start.tv_sec) * 1000L
 498	                    + (now.tv_nsec - start.tv_nsec) / 1000000L;
 499	                if (elapsed_ms >= NET_STARTUP_TIMEOUT_MS) {
 500	                    syslog(LOG_WARNING,
 501	                        "[%s] No IP after %d ms startup timeout, "
 502	                        "continuing poll\n",
