 505	                }
 506	            }
 507	        }
 508	
 509	        /* Sleep for poll interval, but wake early on force check */
 510	        struct timespec ts;
 511	        clock_gettime(CLOCK_REALTIME, &ts);
 512	        ts.tv_sec += NET_POLL_INTERVAL_MS / 1000;
 513	        ts.tv_nsec += (NET_POLL_INTERVAL_MS % 1000) * 1000000L;
 514	        if (ts.tv_nsec >= 1000000000L) {
