 516	            ts.tv_nsec -= 1000000000L;
 517	        }
 518	
 519	        pthread_mutex_lock(&g_net_mutex);
 520	        while (!g_force_check && g_poll_running) {
 521	            int rc = pthread_cond_timedwait(&g_net_cond, &g_net_mutex, &ts);
 522	            if (rc == ETIMEDOUT) {
 523	                break;
 524	            }
 525	        }

