   660	/* Detect a stopped I2S DMA worker even when Media has not queued a FINAL
   661	 * buffer.  Without this poll, APBs already copied into the private PCM ring
   662	 * can be returned and the Media thread can then wait forever for an event. */
   663	static void contest_media_check_health(FAR struct contest_media_sink_s *sink)
   664	{
   665	  uint32_t now_ms;
   666	  uint32_t last_pcm_ms;
   667	  uint32_t started_ms;
   668	  uint64_t completed;
   669	  uint64_t pending;
   670	  unsigned int queued;
   671	  bool started;
   672	  int ret;
   673	
   674	  if (__atomic_load_n(&sink->completion_sent, __ATOMIC_ACQUIRE) ||
   675	      sink->stream_error < 0 || contest_media_pace_aborted(sink))
   676	    {
   677	      return;
   678	    }
   679	
   680	  ret = contest_media_progress(sink, &completed, &pending, &started);
   681	  if (!started)
   682	    {
   683	      return;
   684	    }
   685	
   686	  now_ms = (uint32_t)contest_media_now_ms();
   687	  last_pcm_ms = __atomic_load_n(&sink->last_pcm_ms, __ATOMIC_ACQUIRE);
   688	  started_ms = __atomic_load_n(&sink->started_ms, __ATOMIC_ACQUIRE);
   689	  if (ret >= 0 && !sink->eos &&
   690	      (uint32_t)(now_ms - (last_pcm_ms ? last_pcm_ms : started_ms)) >=
   691	      CONTEST_MEDIA_STALL_TIMEOUT_MS)
   692	    {
   693	      ret = -ETIMEDOUT;
   694	      syslog(LOG_ERR,
   695	             "[MEDIA-BRIDGE] no PCM input for %u ms; closing stalled stream\n",
   696	             CONTEST_MEDIA_STALL_TIMEOUT_MS);
   697	    }
   698	  else if (ret >= 0)
   699	    {
   700	      return;
   701	    }
   702	
   703	  sink->stream_error = ret;
   704	  sink->eos = true;
   705	  syslog(LOG_ERR,
   706	         "[MEDIA-BRIDGE] playback backend failed while streaming rc=%d; "
   707	         "closing and returning to caller\n", ret);
