static void *rv_worker(void *arg)
{
  struct rv_playback_s *pb = arg;
  uint8_t block[RV_SOURCE_BLOCK_BYTES];
  unsigned int slot_index = 0;
  int primed_slots = 0;
  int ret = 0;
  bool terminal_tail = false;

  pb->state = RV_STATE_PREBUFFER;

  if (pb->native_media)
    {
      printf("[RV-PB] native worker ready slots=%u prebuffer=%u\n",
             pb->slot_count, pb->start_prebuffer);
    }

  while (!pb->stopped)
    {
      struct rv_slot_s *slot;

      terminal_tail = false;
      size_t available;
      size_t want;
      size_t got;
      bool prime_silence = false;
      bool final_block = false;

      ret = rv_get_result(pb);
      if (ret < 0)
        {
          printf("[RV-PB] I2S worker error=%d\n", ret);
          break;
        }

      if (pb->state == RV_STATE_PREBUFFER || pb->state == RV_STATE_REBUFFER)
        {
          size_t threshold = pb->state == RV_STATE_PREBUFFER ?
                             pb->start_prebuffer : RV_REBUFFER_BYTES;
          const char *from = pb->state == RV_STATE_PREBUFFER ?
                             "PREBUFFER" : "REBUFFER";

          ret = rv_wait_buffer(pb, threshold);
          if (ret < 0)
            {
              break;
            }

          if (pb->stopped) { ret = -ECANCELED; break; }
          available = rv_ring_count(pb);
          if (available >= 2)
            {
              pb->state = RV_STATE_PLAYING;
              primed_slots = 0;
              slot_index = 0;

              if (pb->ring_min_play == (size_t)-1)
                {
                  pb->ring_min_play = available;
                }

              if (available > pb->ring_max_play)
                {
                  pb->ring_max_play = available;
                }

              (void)from;
            }
          else if (pb->eos)
            {
              pb->state = RV_STATE_DRAINING;
            }
          else
            {
              continue;
            }
        }

      if (pb->state == RV_STATE_DRAINING)
        {
          break;
        }

      slot = &pb->slots[slot_index];

      /* Prime the negotiated number of slots, then refill in that same
       * round-robin order. Each source block expands to the fixed wire size;
       * a larger ring gives more callback/worker scheduling headroom. */
      if (primed_slots >= pb->slot_count)
        {
          ret = rv_wait_slot(pb, slot);
          if (ret < 0)
            {
              break;
            }
        }

        {
          pthread_mutex_unlock(&decoder->queue_lock);
          return -ECANCELED;
        }

      amount = sizeof(decoder->queue) - decoder->queue_count;
      if (amount > len - offset) amount = len - offset;
      first = sizeof(decoder->queue) - decoder->queue_head;
      if (first > amount) first = amount;
      memcpy(decoder->queue + decoder->queue_head, src + offset, first);
      if (first < amount)
        memcpy(decoder->queue, src + offset + first, amount - first);
      decoder->queue_head = (decoder->queue_head + amount) %
                            sizeof(decoder->queue);
      decoder->queue_count += amount;
      offset += amount;
      pthread_cond_signal(&decoder->queue_data);
      pthread_mutex_unlock(&decoder->queue_lock);
    }

  return 0;
}

static void *rv_mp3_decode_worker(void *arg)
{
  struct rv_mp3_decoder *decoder = arg;
  unsigned char chunk[RV_MP3_QUEUE_CHUNK];

  for (;;)
    {
      size_t amount;
      size_t first;
      int ret;

      pthread_mutex_lock(&decoder->queue_lock);
      while (decoder->queue_count == 0 && !decoder->queue_stop)
        pthread_cond_wait(&decoder->queue_data, &decoder->queue_lock);

      if (decoder->queue_count == 0 && decoder->queue_stop)
        {
          pthread_mutex_unlock(&decoder->queue_lock);
          break;
        }

      amount = decoder->queue_count;
      if (amount > sizeof(chunk)) amount = sizeof(chunk);
      first = sizeof(decoder->queue) - decoder->queue_tail;
      if (first > amount) first = amount;
      memcpy(chunk, decoder->queue + decoder->queue_tail, first);
      if (first < amount)
        memcpy(chunk + first, decoder->queue, amount - first);
      decoder->queue_tail = (decoder->queue_tail + amount) %
                            sizeof(decoder->queue);
      decoder->queue_count -= amount;
      pthread_cond_broadcast(&decoder->queue_space);
      pthread_mutex_unlock(&decoder->queue_lock);

      ret = rv_mp3_decode(decoder, chunk, amount);
      if (ret < 0)
        {
          pthread_mutex_lock(&decoder->queue_lock);
          if (decoder->queue_error == 0) decoder->queue_error = ret;
          decoder->queue_stop = true;
          pthread_cond_broadcast(&decoder->queue_space);
          pthread_cond_broadcast(&decoder->queue_data);
          pthread_mutex_unlock(&decoder->queue_lock);
          break;
        }
    }

  return NULL;
}

