int robot_audio_playback_write(const uint8_t *pcm, size_t len)
{
  struct rv_playback_s *pb = &g_pb;
  size_t offset = 0;

  if (!pb->opened || pcm == NULL || len == 0)
    {
      return -EINVAL;
    }

  if ((len & 1) != 0)
    {
      /* PCM16 producer chunks must preserve sample alignment. */
      printf("[RV-PB] reject odd PCM chunk len=%zu\n", len);
      return -EINVAL;
    }

  if (pb->cache_until_eos)
    {
      size_t required;
      int lock_ret = rv_lock(pb);
      if (lock_ret < 0) return lock_ret;
      if (pb->eos || pb->stopped)
        { rv_unlock(pb); return pb->stopped ? -ECANCELED : -EPIPE; }
      if (len > ROBOT_VOICE_TTS_CACHE_BYTES - pb->total_written)
        {
          rv_unlock(pb);
          printf("[RV-PB] cache overflow id=%u incoming=%zu cached=%zu limit=%u; no audio played\n",
                 pb->id, len, pb->total_written, ROBOT_VOICE_TTS_CACHE_BYTES);
          return -EOVERFLOW;
        }
      required = pb->total_written + len;
      if (required > pb->ring.capacity)
        {
          size_t capacity = pb->ring.capacity;
          uint8_t *data;
          while (capacity < required) capacity *= 2;
          if (capacity > ROBOT_VOICE_TTS_CACHE_BYTES)
            capacity = ROBOT_VOICE_TTS_CACHE_BYTES;
          /* Voice has not consumed any PCM yet. It is contiguous from zero;
           * restore head=count if the old capacity was exactly full. */
          data = realloc(pb->ring.data, capacity);
          if (!data) { rv_unlock(pb); return -ENOMEM; }
          pb->ring.data = data;
          pb->ring.capacity = capacity;
          pb->ring.head = pb->ring.count;
        }
      rv_unlock(pb);
    }

  /*
   * Producer side from tts_pcm_playback_guide.md:
   *
   * Never fail a valid long utterance just because the 256 KiB ring is
   * temporarily full.  Wait for the dedicated playback worker to free space,
   * then continue writing the same PCM chunk.
   */
  while (offset < len)
    {
      size_t buffered;
      size_t space;
      size_t n;
      int ret;

      if (pb->stopped)
        {
          return pb->terminal_tail_done ? -EPIPE : -ECANCELED;
        }

      ret = rv_get_result(pb);
      if (ret < 0)
        {
          return ret;
        }

      buffered = rv_ring_count(pb);
      space = pb->ring.capacity - buffered;
      if (space < 2)
        {
          ret = nxsem_wait_uninterruptible(&pb->ring_space);
          if (ret < 0)
            {
              return ret;
            }
          continue;
        }

      n = len - offset;
      if (n > space)
        {
          n = space;
        }

      n &= ~(size_t)1;
      if (n == 0)
        {
          continue;
        }

      ret = rv_ring_write(pb, pcm + offset, n);
      if (ret == -ENOSPC)
        {
          continue;
        }
      if (ret < 0)
      ret = rv_write_pcm(decoder, decoder->decoded, info.outputSamps,
                         info.nChans, info.samprate);
      if (ret < 0)
        {
          /* Preserve the playback/I2S error.  Mapping every sink failure to
           * EIO made network truncation and audio-device failures
           * indistinguishable on the board. */
          return ret;
        }
      decoder->frame_count++;
    }

  return 0;
}

static int rv_mp3_queue_write(struct rv_mp3_decoder *decoder,
                              const unsigned char *src, size_t len)
{
  size_t offset = 0;

  while (offset < len)
    {
      size_t amount;
      size_t first;

      pthread_mutex_lock(&decoder->queue_lock);
      while (decoder->queue_count == sizeof(decoder->queue) &&
             decoder->queue_error == 0 && !decoder->queue_stop &&
             !rv_player_stop_requested(decoder->player))
        {
          pthread_cond_wait(&decoder->queue_space, &decoder->queue_lock);
        }

      if (decoder->queue_error < 0)
        {
          int error = decoder->queue_error;
          pthread_mutex_unlock(&decoder->queue_lock);
          return error;
        }

      if (decoder->queue_stop || rv_player_stop_requested(decoder->player))
        {
          pthread_mutex_unlock(&decoder->queue_lock);
          return -ECANCELED;
        }

      amount = sizeof(decoder->queue) - decoder->queue_count;
      if (amount > len - offset) amount = len - offset;
      first = sizeof(decoder->queue) - decoder->queue_head;
      if (first > amount) first = amount;
      memcpy(decoder->queue + decoder->queue_head, src + offset, first);
      if (first < amount)
        memcpy(decoder->queue, src + offset + first, amount - first);
      decoder->queue_head = (decoder->queue_head + amount) %
                            sizeof(decoder->queue);
      decoder->queue_count += amount;
      if (decoder->queue_count > decoder->queue_high_water)
        {
          decoder->queue_high_water = decoder->queue_count;
        }
      offset += amount;
      pthread_cond_signal(&decoder->queue_data);
      pthread_mutex_unlock(&decoder->queue_lock);
    }

  return 0;
}

static void *rv_mp3_decode_worker(void *arg)
{
  struct rv_mp3_decoder *decoder = arg;
  unsigned char chunk[RV_MP3_QUEUE_CHUNK];

  for (;;)
    {
      size_t amount;
      size_t first;
      int ret;

      pthread_mutex_lock(&decoder->queue_lock);
      while (decoder->queue_count == 0 && !decoder->queue_stop)
        pthread_cond_wait(&decoder->queue_data, &decoder->queue_lock);

      if (decoder->queue_count == 0 && decoder->queue_stop)
        {
          pthread_mutex_unlock(&decoder->queue_lock);
          break;
        }

      amount = decoder->queue_count;
      if (amount > sizeof(chunk)) amount = sizeof(chunk);
      first = sizeof(decoder->queue) - decoder->queue_tail;
      if (first > amount) first = amount;
      memcpy(chunk, decoder->queue + decoder->queue_tail, first);
      if (first < amount)
        memcpy(chunk + first, decoder->queue, amount - first);
      decoder->queue_tail = (decoder->queue_tail + amount) %
                            sizeof(decoder->queue);
      decoder->queue_count -= amount;
      pthread_cond_broadcast(&decoder->queue_space);
      pthread_mutex_unlock(&decoder->queue_lock);

      ret = rv_mp3_decode(decoder, chunk, amount);
      if (ret < 0)
        {
          pthread_mutex_lock(&decoder->queue_lock);
          if (decoder->queue_error == 0) decoder->queue_error = ret;
          decoder->queue_stop = true;
          pthread_cond_broadcast(&decoder->queue_space);
          pthread_cond_broadcast(&decoder->queue_data);
          pthread_mutex_unlock(&decoder->queue_lock);
          break;
        }
    }

  return NULL;
}

