          sizeof(payload.data.music.category) - 1);
  strncpy(payload.data.music.mood, mood != NULL ? mood : "",
          sizeof(payload.data.music.mood) - 1);
  return robot_proactive_post_ex(type, "music", "music state changed",
                                 &payload);
}

