/*
 * Contest-local observer for the official Music DJ status API.
 *
 * The official media player owns playback and its event callback.  This
 * module deliberately does not open another player or inspect private state;
 * it polls the public music_status Tool API at a low rate and reports only
 * confirmed state transitions to the contest World State.
 *
 * SPDX-License-Identifier: Apache-2.0
 */

#include <nuttx/config.h>

#include <errno.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

#include "cJSON.h"
#include "tools/tool_media.h"
#include "robot_music_observer.h"
#include "robot_proactive.h"

#define ROBOT_MUSIC_POLL_MS 2000
#define ROBOT_MUSIC_START_DELAY_MS 5000
#define ROBOT_MUSIC_STATUS_SIZE 768

enum robot_observed_music_state_e
{
  ROBOT_OBSERVED_MUSIC_UNKNOWN = 0,
  ROBOT_OBSERVED_MUSIC_PLAYING,
  ROBOT_OBSERVED_MUSIC_PAUSED,
  ROBOT_OBSERVED_MUSIC_STOPPED,
};

struct robot_music_observer_runtime_s
{
  pthread_mutex_t lock;
  pthread_cond_t cond;
  pthread_t thread;
  bool started;
  bool stop_requested;
  enum robot_observed_music_state_e last_state;
  char last_track[64];
};

static struct robot_music_observer_runtime_s g_music_observer =
{
  .lock = PTHREAD_MUTEX_INITIALIZER,
  .cond = PTHREAD_COND_INITIALIZER,
};

static int robot_music_observer_read_status(
    enum robot_observed_music_state_e *state, char *track, size_t track_size)
{
  char output[ROBOT_MUSIC_STATUS_SIZE];
  cJSON *root;
  cJSON *state_json;
  cJSON *url_json;
  const char *state_text;
  const char *url_text;

  if (state == NULL || track == NULL || track_size == 0)
    {
      return -EINVAL;
    }

  memset(output, 0, sizeof(output));
  if (tool_music_status_execute("{}", output, sizeof(output)) < 0)
    {
      return -EIO;
    }

  root = cJSON_Parse(output);
  if (root == NULL)
    {
      return -EINVAL;
    }

  state_json = cJSON_GetObjectItem(root, "state");
  state_text = cJSON_GetStringValue(state_json);
  url_json = cJSON_GetObjectItem(root, "url");
  url_text = cJSON_GetStringValue(url_json);
  track[0] = '\0';

  if (state_text != NULL && strcmp(state_text, "PLAYING") == 0)
    {
      *state = ROBOT_OBSERVED_MUSIC_PLAYING;
    }
  else if (state_text != NULL && strcmp(state_text, "PAUSED") == 0)
    {
      *state = ROBOT_OBSERVED_MUSIC_PAUSED;
    }
  else
    {
      *state = ROBOT_OBSERVED_MUSIC_STOPPED;
    }

  if (url_text != NULL)
    {
      snprintf(track, track_size, "%s", url_text);
    }

  cJSON_Delete(root);
  return 0;
}

static void robot_music_observer_sample(void)
{
  enum robot_observed_music_state_e observed;
  enum robot_observed_music_state_e previous;
  char track[64];
  char previous_track[64];
  bool report_playing;
  bool report_stopped;

  if (robot_music_observer_read_status(&observed, track, sizeof(track)) < 0)
    {
      return;
    }

  pthread_mutex_lock(&g_music_observer.lock);
  previous = g_music_observer.last_state;
  snprintf(previous_track, sizeof(previous_track), "%s",
           g_music_observer.last_track);
  g_music_observer.last_state = observed;
  if (observed == ROBOT_OBSERVED_MUSIC_PLAYING)
    {
      snprintf(g_music_observer.last_track,
               sizeof(g_music_observer.last_track), "%s", track);
    }
  else if (observed == ROBOT_OBSERVED_MUSIC_STOPPED)
    {
      g_music_observer.last_track[0] = '\0';
    }
  pthread_mutex_unlock(&g_music_observer.lock);

  report_playing = observed == ROBOT_OBSERVED_MUSIC_PLAYING;
  report_stopped = observed == ROBOT_OBSERVED_MUSIC_STOPPED &&
                   (previous == ROBOT_OBSERVED_MUSIC_PLAYING ||
                    previous == ROBOT_OBSERVED_MUSIC_PAUSED);

  if (report_playing)
    {
      /* PAUSED is state-only: keep the last confirmed track without waking
       * the Agent, then let PLAYING resume be observed normally. */
      if (previous != ROBOT_OBSERVED_MUSIC_PLAYING ||
          strcmp(previous_track, track) != 0)
        {
          printf("[ROBOT-MUSIC] official status PLAYING track_changed=%d\n",
                 strcmp(previous_track, track) == 0 ? 0 : 1);
        }
      (void)robot_proactive_music_update(ROBOT_MUSIC_PLAYING, track,
                                         "", "", 0);
    }
  else if (report_stopped)
    {
      printf("[ROBOT-MUSIC] official status STOPPED\n");
      (void)robot_proactive_music_update(ROBOT_MUSIC_STOPPED, "", "", "", 0);
    }
}

static void *robot_music_observer_worker(void *arg)
{
  struct timespec startup_deadline;
  bool stop_requested;

  (void)arg;

  /*
   * voice_channel_init() runs before the official agent loop and its first
   * tool-buffer allocations.  Do not call the official media Tool from that
   * startup window: tool_media lazily initializes its private media context
   * on the first status query, so an early query can race Agent startup.
   * Keep the observer thread alive, but defer the first query until all
   * normal Agent startup work has settled.
   */
  clock_gettime(CLOCK_REALTIME, &startup_deadline);
  startup_deadline.tv_sec += ROBOT_MUSIC_START_DELAY_MS / 1000;
  startup_deadline.tv_nsec +=
    (ROBOT_MUSIC_START_DELAY_MS % 1000) * 1000000L;
  if (startup_deadline.tv_nsec >= 1000000000L)
    {
      startup_deadline.tv_sec++;
      startup_deadline.tv_nsec -= 1000000000L;
    }

  pthread_mutex_lock(&g_music_observer.lock);
  if (!g_music_observer.stop_requested)
    {
      (void)pthread_cond_timedwait(&g_music_observer.cond,
                                   &g_music_observer.lock,
                                   &startup_deadline);
    }
  stop_requested = g_music_observer.stop_requested;
  pthread_mutex_unlock(&g_music_observer.lock);

  printf("[ROBOT-MUSIC] observer started delay_ms=%u interval_ms=%u\n",
         ROBOT_MUSIC_START_DELAY_MS, ROBOT_MUSIC_POLL_MS);
  if (stop_requested)
    {
      goto stopped;
    }

  while (true)
    {
      struct timespec ts;

      robot_music_observer_sample();
      pthread_mutex_lock(&g_music_observer.lock);
      if (g_music_observer.stop_requested)
        {
          pthread_mutex_unlock(&g_music_observer.lock);
          break;
        }
      clock_gettime(CLOCK_REALTIME, &ts);
      ts.tv_sec += ROBOT_MUSIC_POLL_MS / 1000;
      ts.tv_nsec += (ROBOT_MUSIC_POLL_MS % 1000) * 1000000L;
      if (ts.tv_nsec >= 1000000000L)
        {
          ts.tv_sec++;
          ts.tv_nsec -= 1000000000L;
        }
      pthread_cond_timedwait(&g_music_observer.cond,
                             &g_music_observer.lock, &ts);
      if (g_music_observer.stop_requested)
        {
          pthread_mutex_unlock(&g_music_observer.lock);
          break;
        }
      pthread_mutex_unlock(&g_music_observer.lock);
    }

stopped:
  pthread_mutex_lock(&g_music_observer.lock);
  g_music_observer.started = false;
  pthread_mutex_unlock(&g_music_observer.lock);
  printf("[ROBOT-MUSIC] observer stopped\n");
  return NULL;
}

int robot_music_observer_start(void)
{
  pthread_attr_t attr;
  int ret;

  pthread_mutex_lock(&g_music_observer.lock);
  if (g_music_observer.started)
    {
      pthread_mutex_unlock(&g_music_observer.lock);
      return 0;
    }
  g_music_observer.stop_requested = false;
  g_music_observer.last_state = ROBOT_OBSERVED_MUSIC_UNKNOWN;
  g_music_observer.last_track[0] = '\0';
  /* Publish ownership before create so a fast worker cannot race a second
   * start call while the creator is still returning. */
  g_music_observer.started = true;
/*
 * Contest-local proactive agent runtime.
 *
 * SPDX-License-Identifier: Apache-2.0
 */

#include <nuttx/config.h>

#include <errno.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include "agent_config.h"
#include "core/message_bus.h"
#include "robot_proactive.h"
#include "robot_world_state.h"

struct robot_proactive_runtime_s
{
  pthread_mutex_t lock;
  pthread_cond_t cond;
  struct robot_event_s queue[ROBOT_PROACTIVE_QUEUE_DEPTH];
  unsigned int head;
  unsigned int tail;
  unsigned int count;
  uint32_t next_event_id;
  bool initialized;
  bool started;
  bool stop_requested;
  pthread_t thread;
  bool pending_music_valid;
  struct robot_event_s pending_music;
};

static struct robot_proactive_runtime_s g_proactive =
{
  .lock = PTHREAD_MUTEX_INITIALIZER,
  .cond = PTHREAD_COND_INITIALIZER,
};

static uint64_t robot_proactive_monotonic_ms(void)
{
  struct timespec ts;

  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint64_t)ts.tv_sec * 1000ULL +
         (uint64_t)ts.tv_nsec / 1000000ULL;
}

static void robot_proactive_realtime_after_ms(struct timespec *ts,
                                              uint32_t timeout_ms)
{
  clock_gettime(CLOCK_REALTIME, ts);
  ts->tv_sec += (time_t)(timeout_ms / 1000U);
  ts->tv_nsec += (long)(timeout_ms % 1000U) * 1000000L;
  if (ts->tv_nsec >= 1000000000L)
    {
      ts->tv_sec++;
      ts->tv_nsec -= 1000000000L;
    }
}

static void robot_proactive_drop(const struct robot_event_s *event,
                                 const char *reason)
{
  printf("[ROBOT-PROACTIVE] drop id=%u type=%s reason=%s\n",
         event->id, robot_event_type_name(event->type), reason);
}

static bool robot_proactive_is_music_event(enum robot_event_type_e type)
{
  return type >= ROBOT_EVENT_MUSIC_STARTED &&
         type <= ROBOT_EVENT_MUSIC_STOPPED;
}

static void robot_proactive_defer_music(const struct robot_event_s *event,
                                        const char *reason)
{
  pthread_mutex_lock(&g_proactive.lock);
  if (!g_proactive.pending_music_valid ||
      event->id >= g_proactive.pending_music.id)
    {
      g_proactive.pending_music = *event;
      g_proactive.pending_music_valid = true;
      printf("[ROBOT-PROACTIVE] music deferred id=%u reason=%s\n",
             event->id, reason);
    }
  pthread_cond_signal(&g_proactive.cond);
  pthread_mutex_unlock(&g_proactive.lock);
}

static int robot_proactive_send_to_agent(const struct robot_event_s *event,
                                         const struct robot_world_state_s *state)
{
  char content[768];
  agent_msg_t msg;
  int len;
  int ret;
  uint64_t now_ms = robot_proactive_monotonic_ms();
  uint64_t idle_seconds = 0;

  if (event->type == ROBOT_EVENT_IDLE_LONG &&
      now_ms >= state->last_user_activity_ms)
    {
      idle_seconds = (now_ms - state->last_user_activity_ms) / 1000ULL;
    }

  len = snprintf(content, sizeof(content),
                 "[ROBOT_INTERNAL_EVENT]\n"
                 "event_id=%u\n"
                 "created_ms=%llu\n"
                 "type=%s\n"
                 "source=%s\n"
                 "idle_seconds=%llu\n"
                 "detail=%s\n"
                 "music_playing=%d\n"
                 "music_track=%s\n"
                 "music_category=%s\n"
                 "music_mood=%s\n"
                 "music_tempo_bpm=%u\n\n"
                 "This is a structured internal robot event, not user speech.\n"
                 "Use the matching proactive Skill when available. Decide whether\n"
                 "a brief natural interaction is useful; keep spoken output short.",
                 event->id, (unsigned long long)event->created_ms,
                 robot_event_type_name(event->type),
                 event->source,
                 (unsigned long long)idle_seconds, event->detail,
                 state->music_playing ? 1 : 0, state->music_track,
                 state->music_category, state->music_mood,
                 (unsigned int)state->music_tempo_bpm);
  if (len < 0 || (size_t)len >= sizeof(content))
    {
      return -EOVERFLOW;
    }

  memset(&msg, 0, sizeof(msg));
  strncpy(msg.channel, AGENT_CHAN_VOICE, sizeof(msg.channel) - 1);
  strncpy(msg.chat_id, "robot_proactive", sizeof(msg.chat_id) - 1);
  msg.content = strdup(content);
  if (msg.content == NULL)
    {
      return -ENOMEM;
    }

  ret = message_bus_push_inbound(&msg);
  if (ret != OK)
    {
      free(msg.content);
      return -EAGAIN;
    }

  printf("[ROBOT-PROACTIVE] inbound id=%u channel=%s chat_id=%s\n",
         event->id, msg.channel, msg.chat_id);
  return 0;
}

static void robot_proactive_process(const struct robot_event_s *event)
{
  struct robot_world_state_s state;
  uint64_t now_ms;
  int ret;

  if (robot_world_state_snapshot(&state) < 0 || !state.initialized)
    {
      robot_proactive_drop(event, "world-unavailable");
      return;
    }

  if (!state.proactive_enabled)
    {
      robot_proactive_drop(event, "disabled");
      return;
    }

  now_ms = robot_proactive_monotonic_ms();
  if (event->id <= state.last_processed_event_id)
    {
      robot_proactive_drop(event, "duplicate-event-id");
      return;
    }

  if (state.last_proactive_ms != 0 &&
      now_ms - state.last_proactive_ms < ROBOT_PROACTIVE_COOLDOWN_MS)
    {
      if (robot_proactive_is_music_event(event->type))
        {
          robot_proactive_defer_music(event, "cooldown");
        }
      else
        {
          robot_proactive_drop(event, "cooldown");
        }
      return;
    }

  if (event->type >= 0 && event->type < ROBOT_EVENT_TYPE_COUNT &&
      state.last_event_type_ms[event->type] != 0 &&
      now_ms - state.last_event_type_ms[event->type] <
        (event->type >= ROBOT_EVENT_MUSIC_STARTED &&
         event->type <= ROBOT_EVENT_MUSIC_STOPPED ?
         ROBOT_PROACTIVE_MUSIC_COOLDOWN_MS : ROBOT_PROACTIVE_COOLDOWN_MS))
    {
      if (robot_proactive_is_music_event(event->type))
        {
          robot_proactive_defer_music(event, "event-cooldown");
        }
      else
        {
          robot_proactive_drop(event, "event-cooldown");
        }
      return;
    }

  if (event->type != ROBOT_EVENT_MANUAL_TEST &&
      event->created_ms != 0 && now_ms >= event->created_ms &&
      now_ms - event->created_ms > ROBOT_PROACTIVE_EVENT_FRESHNESS_MS)
    {
      robot_proactive_drop(event, "stale");
      return;
    }

  if (event->type != ROBOT_EVENT_MANUAL_TEST &&
      (state.conversation_active || state.motion_active || state.tts_active))
    {
      if (robot_proactive_is_music_event(event->type))
        {
          robot_proactive_defer_music(event, "robot-busy");
        }
      else
        {
          robot_proactive_drop(event, "robot-busy");
        }
      return;
    }

  if (event->type == ROBOT_EVENT_MANUAL_TEST)
    {
      /* Manual tests intentionally bypass scenario-specific predicates. */
    }
  else if (event->type == ROBOT_EVENT_IDLE_LONG)
    {
      if (!state.user_has_interacted)
        {
          robot_proactive_drop(event, "no-user-activity");
          return;
        }
      if (state.idle_event_fired)
        {
          robot_proactive_drop(event, "already-fired");
          return;
        }
      if (now_ms - state.last_user_activity_ms < ROBOT_PROACTIVE_IDLE_MS &&
          strcmp(event->detail, "manual diagnostic trigger") != 0)
        {
          robot_proactive_drop(event, "not-idle");
          return;
        }
    }
  else if (event->type == ROBOT_EVENT_USER_ACTIVITY)
    {
      robot_proactive_drop(event, "state-only-event");
      return;
    }
  else if (event->type < ROBOT_EVENT_MUSIC_STARTED ||
           event->type > ROBOT_EVENT_MEAL_WINDOW)
    {
      robot_proactive_drop(event, "unknown-type");
      return;
    }

  printf("[ROBOT-PROACTIVE] accept id=%u type=%s\n",
         event->id, robot_event_type_name(event->type));
  ret = robot_proactive_send_to_agent(event, &state);
  if (ret < 0)
    {
      printf("[ROBOT-PROACTIVE] inbound failed id=%u rc=%d\n",
             event->id, ret);
    }
  else
    {
      robot_world_state_note_proactive(event->id, event->type);
    }
}

static void robot_proactive_try_pending_music(void)
{
  struct robot_event_s event;
  struct robot_world_state_s state;
  uint64_t now_ms;
  bool stale;
  bool eligible;

  pthread_mutex_lock(&g_proactive.lock);
  if (g_proactive.pending_music_valid)
    {
      event = g_proactive.pending_music;
    }
  else
    {
      pthread_mutex_unlock(&g_proactive.lock);
      return;
    }
  pthread_mutex_unlock(&g_proactive.lock);

  if (robot_world_state_snapshot(&state) < 0 || !state.initialized ||
      !state.proactive_enabled || state.conversation_active ||
      state.motion_active || state.tts_active)
    {
      return;
    }

  now_ms = robot_proactive_monotonic_ms();
  stale = event.created_ms != 0 && now_ms >= event.created_ms &&
          now_ms - event.created_ms > ROBOT_PROACTIVE_EVENT_FRESHNESS_MS;
  eligible = !stale &&
             (state.last_proactive_ms == 0 ||
              now_ms - state.last_proactive_ms >= ROBOT_PROACTIVE_COOLDOWN_MS) &&
             (state.last_event_type_ms[event.type] == 0 ||
              now_ms - state.last_event_type_ms[event.type] >=
                ROBOT_PROACTIVE_MUSIC_COOLDOWN_MS);
  if (!eligible)
    {
      if (stale)
        {
          robot_proactive_drop(&event, "pending-stale");
          pthread_mutex_lock(&g_proactive.lock);
          if (g_proactive.pending_music_valid &&
              g_proactive.pending_music.id == event.id)
            {
              g_proactive.pending_music_valid = false;
            }
          pthread_mutex_unlock(&g_proactive.lock);
        }
      return;
    }

  pthread_mutex_lock(&g_proactive.lock);
  if (g_proactive.pending_music_valid &&
      g_proactive.pending_music.id == event.id)
    {
      g_proactive.pending_music_valid = false;
      eligible = true;
    }
  else
    {
      eligible = false;
    }
  pthread_mutex_unlock(&g_proactive.lock);

  if (eligible)
    {
      printf("[ROBOT-PROACTIVE] dispatch deferred music id=%u\n", event.id);
      robot_proactive_process(&event);
    }
}


