  timeout_ms = (uint32_t)((uint64_t)cycles * period_ms * 4ULL +
                          ROBOT_MOTION_WAIT_MARGIN_MS);
  if (timeout_ms > ROBOT_MOTION_MAX_TIMEOUT_MS)
    {
      timeout_ms = ROBOT_MOTION_MAX_TIMEOUT_MS;
    }

