      snprintf(output, output_size,
               "{\"ok\":false,\"error\":\"reaction display unavailable\"}");
      return ERROR;
    }

  snprintf(output, output_size,
           "{\"ok\":true,\"expression\":\"%s\",\"duration_ms\":%u,"
           "\"temporary\":true}",
           robot_expression_name(expression), duration_ms);
  return OK;
}

