                 robot_motion_direction_name(direction));
        }
      return -EBUSY;
    }

  request_id = ++g_motion.next_request_id;
  if (request_id == 0)
    {
      request_id = ++g_motion.next_request_id;
    }
  g_motion.request.source = source;
  g_motion.request.type = type;
}

