/*
 * Contest-local proactive agent runtime.
 *
 * SPDX-License-Identifier: Apache-2.0
 */

#include <nuttx/config.h>

#include <errno.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include "agent_config.h"
#include "core/message_bus.h"
#include "robot_action_guard.h"
#include "robot_expression.h"
#include "robot_motion.h"
#include "robot_proactive.h"
#include "robot_world_state.h"

struct robot_proactive_runtime_s
{
  pthread_mutex_t lock;
  pthread_cond_t cond;
  struct robot_event_s queue[ROBOT_PROACTIVE_QUEUE_DEPTH];
  unsigned int head;
  unsigned int tail;
  unsigned int count;
  uint32_t next_event_id;
  bool initialized;
  bool started;
  bool stop_requested;
  pthread_t thread;
  bool pending_music_valid;
  struct robot_event_s pending_music;
};

static struct robot_proactive_runtime_s g_proactive =
{
  .lock = PTHREAD_MUTEX_INITIALIZER,
  .cond = PTHREAD_COND_INITIALIZER,
};

static uint64_t robot_proactive_monotonic_ms(void)
{
  struct timespec ts;

  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint64_t)ts.tv_sec * 1000ULL +
         (uint64_t)ts.tv_nsec / 1000000ULL;
}

static void robot_proactive_realtime_after_ms(struct timespec *ts,
                                              uint32_t timeout_ms)
{
  clock_gettime(CLOCK_REALTIME, ts);
  ts->tv_sec += (time_t)(timeout_ms / 1000U);
  ts->tv_nsec += (long)(timeout_ms % 1000U) * 1000000L;
  if (ts->tv_nsec >= 1000000000L)
    {
      ts->tv_sec++;
      ts->tv_nsec -= 1000000000L;
    }
}

static void robot_proactive_drop(const struct robot_event_s *event,
                                 const char *reason)
{
  printf("[ROBOT-PROACTIVE] drop id=%u type=%s reason=%s\n",
         event->id, robot_event_type_name(event->type), reason);
}

static bool robot_proactive_is_music_event(enum robot_event_type_e type)
{
  return type >= ROBOT_EVENT_MUSIC_STARTED &&
         type <= ROBOT_EVENT_MUSIC_STOPPED;
}

static bool robot_proactive_is_music_stop(const struct robot_event_s *event)
{
  return event != NULL && event->type == ROBOT_EVENT_MUSIC_STOPPED;
}

/*
 * Music playback is already a confirmed physical action.  Keep its companion
 * reaction local so it cannot start another Agent/LLM request while the MP3
 * stream is using the same WLAN connection and heap.
 */
static int robot_proactive_apply_music_reaction(
    const struct robot_event_s *event,
    const struct robot_world_state_s *state)
{
  int expression_ret;
  int motion_ret = 0;
  bool calm;

  if (event == NULL || state == NULL)
    {
