--- 3 ---
 * Music playback is already a confirmed physical action.  Keep its companion
 * reaction local so it cannot start another Agent/LLM request while the MP3
 * stream is using the same WLAN connection and heap.
 */
static int robot_proactive_apply_music_reaction(
    const struct robot_event_s *event,
    const struct robot_world_state_s *state)
{
  int expression_ret;
  int motion_ret = 0;
  bool calm;
  bool music_active;

  if (event == NULL || state == NULL)
    {
      return -EINVAL;
    }

  if (event->type == ROBOT_EVENT_MUSIC_STOPPED)
    {
      expression_ret = robot_expression_clear(ROBOT_EXPRESSION_SOURCE_MUSIC);
      printf("[ROBOT-MUSIC] local reaction stopped expression_rc=%d\n",
             expression_ret);
      return expression_ret;
    }

  calm = strcmp(state->music_mood, "calm") == 0 ||
         strcmp(state->music_mood, "sleep") == 0 ||
         strcmp(state->music_mood, "lullaby") == 0 ||
         strcmp(state->music_category, "sleep") == 0;
  music_active = robot_music_media_is_active();
  expression_ret = robot_expression_set(
      ROBOT_EXPRESSION_SOURCE_MUSIC,
      calm ? ROBOT_EXPRESSION_SLEEPY : ROBOT_EXPRESSION_SINGING,
      0);
  if (expression_ret < 0)
    {
      printf("[ROBOT-MUSIC] local expression failed rc=%d\n",
             expression_ret);
    }

  /*
   * A servo startup pulse can draw more current than the ESP32-S3 board
   * supply can provide while the audio/network path is active.  Use only a
   * 3-degree, slow tail response, and only while the music stream is still
   * active.  Manual motion tools remain available for explicit requests.
   */
  if (!calm && music_active)
    {
      /* Let the MP3 worker establish its first buffer before PWM starts. */
      usleep(1500 * 1000);
      if (robot_music_media_is_active() && !robot_motion_is_busy())
        {
          robot_action_guard_begin(ROBOT_ACTION_MOTION,
                                   "robot_music_companion");
          robot_world_state_set_motion_active(true);
          motion_ret = robot_motion_tail_wag_sync(
              ROBOT_MOTION_SOURCE_BEHAVIOR, 1, 3000, 3);
          robot_world_state_set_motion_active(false);
          robot_action_guard_end(ROBOT_ACTION_MOTION,
                                 "robot_music_companion", motion_ret);
        }
      else
        {
          printf("[ROBOT-MUSIC] tail skipped reason=music-ended-or-busy\n");
        }
    }

  printf("[ROBOT-MOTION] summary writes=%u skipped=%u total_angle_delta=%u "
         "heavy_phases=%u\n", ctx.command_count, ctx.skipped_count,
         ctx.total_angle_delta, heavy_phases);
  robotctl_servo_close(&ctx);
  return ret;
}

static int robot_motion_execute_tail_wag(
    const struct robot_motion_request_s *request)
{
