 67	int robot_action_guard_init(void)
 68	{
 69	  pthread_mutex_lock(&g_guard.lock);
 70	  if (g_guard.initialized)
 71	    {
 72	      pthread_mutex_unlock(&g_guard.lock);
 73	      return 0;
 74	    }
 75	
 76	  g_guard.initialized = true;
 77	  pthread_mutex_unlock(&g_guard.lock);
 78	  /*
 79	   * Cache invalidation is deliberately synchronous.  A periodic worker that
 80	   * frees cache entries while the Agent builds cJSON/LLM requests can race
 81	   * the shared heap and turn a harmless Tool call into a free-list panic.
 82	   * begin/end still invalidate at both physical-action boundaries.
 83	   */
