 88	static uint32_t robot_action_guard_extend(enum robot_action_type_e type,
 89	                                          const char *tool_name,
 90	                                          bool begin)
 91	{
 92	  uint64_t now;
 93	  uint64_t requested_until;
 94	  uint32_t generation;
 95	  bool extended;
 96	
 97	  now = robot_action_guard_now_ms();
 98	  requested_until = now + ROBOT_ACTION_CACHE_GUARD_WINDOW_MS;
 99	
100	  pthread_mutex_lock(&g_guard.lock);
101	  extended = requested_until > g_guard.guard_until_ms;
102	  if (extended)
103	    {
104	      g_guard.guard_until_ms = requested_until;
105	    }
106	  if (begin)
107	    {
108	      g_guard.generation++;
109	    }
110	  generation = g_guard.generation;
111	  pthread_mutex_unlock(&g_guard.lock);
112	
113	  printf("[ROBOT-ACTION] %s type=%s tool=%s gen=%lu\n",
114	         begin ? "begin" : "end", robot_action_type_name(type),
115	         tool_name != NULL ? tool_name : "unknown",
116	         (unsigned long)generation);
117	  if (extended)
118	    {
119	      printf("[ROBOT-ACTION] guard window %s\n",
120	             begin ? "started" : "extended");
121	    }
122	
123	  return generation;
124	}
