 81	static bool rv_player_stop_requested(struct rv_media_player *player)
 82	{
 83	  bool stop = false;
 84	
 85	  if (player == NULL)
 86	    {
 87	      return true;
 88	    }
 89	
 90	  pthread_mutex_lock(&player->lock);
 91	  stop = player->stop_requested;
 92	  pthread_mutex_unlock(&player->lock);
