 96	static void *rv_event_worker(void *arg)
 97	{
 98	  struct rv_media_event *event = arg;
 99	
100	  /* media_player_prepare/start are called while tool_media holds its lock.
101	   * Delivering synchronously would deadlock its callback. */
102	  usleep(1000);
103	  if (event->callback)
