166	  size_t input_len;
167	  int phase;
168	  int sample_rate;
169	  int channels;
170	  int16_t decoded[RV_PCM_SAMPLES_CAP];
171	  int16_t mono[RV_PCM_SAMPLES_CAP / 2];
172	  int16_t pcm[RV_PCM_SAMPLES_CAP / 2];
