411	  syslog(LOG_INFO, "[%s] HTTP MP3 begin url=%s\n", RV_MEDIA_TAG,
412	         player->url);
413	  result = webclient_perform(&context);
414	  if (rv_player_stop_requested(player))
415	    {
416	      /* A sink-side -ECANCELED is an expected user stop, not playback failure. */
417	      result = 0;
418	    }
419	  else if (result == 0 && context.http_status >= 300)
420	    {
421	      result = -EIO;
422	    }
