424	decoder_cleanup:
425	  if (decoder)
426	    {
427	      if (decoder->decoder)
428	        {
429	          MP3FreeDecoder(decoder->decoder);
430	        }

445	static int rv_mp3_queue_write(struct rv_mp3_decoder *decoder,
446	                              const unsigned char *src, size_t len)
447	{
448	  size_t offset = 0;
449	
450	  while (offset < len)
451	    {
452	      size_t amount;
453	      size_t first;
454	
455	      pthread_mutex_lock(&decoder->queue_lock);
456	      while (decoder->queue_count == sizeof(decoder->queue) &&
457	             decoder->queue_error == 0 && !decoder->queue_stop &&
458	             !rv_player_stop_requested(decoder->player))
459	        {
460	          pthread_cond_wait(&decoder->queue_space, &decoder->queue_lock);
461	        }
462	
463	      if (decoder->queue_error < 0)
464	        {
465	          int error = decoder->queue_error;
466	          pthread_mutex_unlock(&decoder->queue_lock);
467	          return error;
468	        }
469	
470	      if (decoder->queue_stop || rv_player_stop_requested(decoder->player))
471	        {
472	          pthread_mutex_unlock(&decoder->queue_lock);
473	          return -ECANCELED;
474	        }
475	
476	      amount = sizeof(decoder->queue) - decoder->queue_count;
477	      if (amount > len - offset) amount = len - offset;
478	      first = sizeof(decoder->queue) - decoder->queue_head;
479	      if (first > amount) first = amount;
480	      memcpy(decoder->queue + decoder->queue_head, src + offset, first);
481	      if (first < amount)
482	        memcpy(decoder->queue, src + offset + first, amount - first);
483	      decoder->queue_head = (decoder->queue_head + amount) %
484	                            sizeof(decoder->queue);
485	      decoder->queue_count += amount;
486	      if (decoder->queue_count > decoder->queue_high_water)
487	        {
488	          decoder->queue_high_water = decoder->queue_count;
489	        }
490	      offset += amount;
491	      pthread_cond_signal(&decoder->queue_data);
492	      pthread_mutex_unlock(&decoder->queue_lock);
493	    }
494	
495	  return 0;
496	}
497	
498	static void *rv_mp3_decode_worker(void *arg)
499	{
500	  struct rv_mp3_decoder *decoder = arg;
501	  unsigned char chunk[RV_MP3_QUEUE_CHUNK];
502	
503	  for (;;)
504	    {
505	      size_t amount;
506	      size_t first;
507	      int ret;
508	
509	      pthread_mutex_lock(&decoder->queue_lock);
510	      while (decoder->queue_count == 0 && !decoder->queue_stop)
511	        pthread_cond_wait(&decoder->queue_data, &decoder->queue_lock);
512	
513	      if (decoder->queue_count == 0 && decoder->queue_stop)
514	        {
515	          pthread_mutex_unlock(&decoder->queue_lock);
516	          break;
517	        }
518	
519	      amount = decoder->queue_count;
520	      if (amount > sizeof(chunk)) amount = sizeof(chunk);
521	      first = sizeof(decoder->queue) - decoder->queue_tail;
522	      if (first > amount) first = amount;
523	      memcpy(chunk, decoder->queue + decoder->queue_tail, first);
524	      if (first < amount)
525	        memcpy(chunk + first, decoder->queue, amount - first);
526	      decoder->queue_tail = (decoder->queue_tail + amount) %
527	                            sizeof(decoder->queue);
528	      decoder->queue_count -= amount;
529	      pthread_cond_broadcast(&decoder->queue_space);
530	      pthread_mutex_unlock(&decoder->queue_lock);
531	
532	      ret = rv_mp3_decode(decoder, chunk, amount);
533	      if (ret < 0)
534	        {
535	          pthread_mutex_lock(&decoder->queue_lock);
536	          if (decoder->queue_error == 0) decoder->queue_error = ret;
537	          decoder->queue_stop = true;
538	          pthread_cond_broadcast(&decoder->queue_space);
539	          pthread_cond_broadcast(&decoder->queue_data);
540	          pthread_mutex_unlock(&decoder->queue_lock);
541	          break;
542	        }
543	    }
544	
545	  return NULL;
546	}
