548	static int rv_mp3_sink(char **buffer, int offset, int datend, int *buflen,
549	                       void *arg)
550	{
551	  struct rv_mp3_decoder *decoder = arg;
552	  unsigned long long now_ms;
553	  unsigned long long gap_ms = 0;
554	  bool report = false;
555	  int ret;
556	
557	  (void)buflen;
558	  if (!decoder)
559	    {
560	      syslog(LOG_ERR, "[%s] MP3 sink called without decoder\n", RV_MEDIA_TAG);
561	      return -EINVAL;
562	    }
563	
564	  if (!buffer || !*buffer || offset < 0 || datend < offset)
565	    {
566	      if (decoder->sink_error == 0)
567	        {
568	          decoder->sink_error = -EINVAL;
569	        }
570	      syslog(LOG_ERR, "[%s] invalid MP3 sink range offset=%d end=%d\n",
571	             RV_MEDIA_TAG, offset, datend);
572	      return -EINVAL;
573	    }
574	
575	  if (rv_player_stop_requested(decoder->player))
576	    {
577	      syslog(LOG_INFO, "[%s] HTTP MP3 stop observed in sink\n", RV_MEDIA_TAG);
578	      return -ECANCELED;
579	    }
580	
581	  now_ms = rv_media_now_ms();
582	  if (decoder->last_sink_ms != 0 && now_ms >= decoder->last_sink_ms)
583	    {
584	      gap_ms = now_ms - decoder->last_sink_ms;
585	      if (gap_ms > decoder->max_sink_gap_ms)
586	        {
587	          decoder->max_sink_gap_ms = gap_ms;
588	        }
589	    }
590	  decoder->last_sink_ms = now_ms;
591	  decoder->sink_calls++;
592	  decoder->http_bytes += (size_t)(datend - offset);
593	
594	  /* Report stream cadence once per second.  This is intentionally separate
595	   * from the packet-level [WLAN-TLS] driver trace, so a long HTTP gap can be
596	   * correlated with Wi-Fi/TLS diagnostics without flooding the console. */
597	  report = decoder->sink_calls == 1;
598	  if (now_ms != 0 && decoder->last_report_ms != 0 &&
599	      now_ms >= decoder->last_report_ms &&
600	      now_ms - decoder->last_report_ms >= 1000)
601	    {
602	      report = true;
603	    }
604	  else if (now_ms == 0 && (decoder->sink_calls % 32) == 0)
605	    {
606	      report = true;
607	    }
608	
609	  if (report)
610	    {
611	      size_t queue_depth;
612	      size_t queue_high_water;
613	
614	      pthread_mutex_lock(&decoder->queue_lock);
615	      queue_depth = decoder->queue_count;
616	      queue_high_water = decoder->queue_high_water;
617	      pthread_mutex_unlock(&decoder->queue_lock);
618	      syslog(LOG_INFO,
619	             "[RV-MUSIC-NET] rx=%zu pcm=%zu frames=%lu callbacks=%lu "
620	             "last_gap_ms=%llu max_gap_ms=%llu decode_errors=%lu "
621	             "queue=%zu/%zu queue_high=%zu\n",
622	             decoder->http_bytes, decoder->pcm_bytes, decoder->frame_count,
623	             decoder->sink_calls,
624	             gap_ms, decoder->max_sink_gap_ms, decoder->decoder_errors,
625	             queue_depth, sizeof(decoder->queue), queue_high_water);
626	      decoder->last_report_ms = now_ms;
627	    }
628	
629	  ret = rv_mp3_queue_write(decoder,
630	                           (const unsigned char *)*buffer + offset,
631	                           (size_t)(datend - offset));
632	  if (ret < 0)
633	    {
634	      if (decoder->sink_error == 0)
635	        {
636	          decoder->sink_error = ret;
637	          syslog(LOG_ERR, "[%s] MP3 sink failed rc=%d http=%zu frames=%lu "
638	                 "decode_errors=%lu\n", RV_MEDIA_TAG, ret,
639	                 decoder->http_bytes, decoder->frame_count,
640	                 decoder->decoder_errors);
641	        }
642	
643	      return ret;
644	    }
645	
646	  return rv_player_stop_requested(decoder->player) ? -ECANCELED : 0;
647	}
