   109	static bool robot_skill_matches(
   110	  const struct contest_skill_resource_s *resource, const char *path)
   111	{
   112	  FILE *file;
   113	  unsigned char buffer[128];
   114	  size_t offset = 0;
   115	
   116	  file = fopen(path, "rb");
   117	  if (file == NULL)
   118	    {
   119	      printf("[ROBOT-SKILL] name=%s stage=open-target errno=%d\n",
   120	             resource->filename, errno);
   121	      return false;
   122	    }
   123	
   124	  while (offset < resource->size)
   125	    {
   126	      size_t want = resource->size - offset;
   127	      size_t got;
   128	
   129	      if (want > sizeof(buffer))
   130	        {
   131	          want = sizeof(buffer);
   132	        }
   133	      got = fread(buffer, 1, want, file);
   134	      if (got != want)
   135	        {
   136	          printf("[ROBOT-SKILL] name=%s stage=read-existing errno=%d\n",
   137	                 resource->filename, errno != 0 ? errno : EIO);
   138	          fclose(file);
   139	          return false;
   140	        }
   141	      if (memcmp(buffer, resource->content + offset, got) != 0)
   142	        {
   143	          fclose(file);
   144	          return false;
   145	        }
   146	      offset += got;
   147	    }
   148	
   149	  if (fgetc(file) != EOF || ferror(file) != 0)
   150	    {
   151	      printf("[ROBOT-SKILL] name=%s stage=read-existing errno=%d\n",
   152	             resource->filename, errno != 0 ? errno : EIO);
   153	      fclose(file);
   154	      return false;
   155	    }
   156	
   157	  if (fclose(file) != 0)
   158	    {
   159	      printf("[ROBOT-SKILL] name=%s stage=close errno=%d\n",
   160	             resource->filename, errno != 0 ? errno : EIO);
   161	      return false;
   162	    }
   163	  return true;
   164	}
