   166	static int robot_skill_write_atomic(
   167	  const struct contest_skill_resource_s *resource, const char *path,
   168	  const char *tmp)
   169	{
   170	  FILE *file;
   171	  size_t written;
   172	  int saved_errno;
   173	
   174	  file = fopen(tmp, "wb");
