   176	    {
   177	      saved_errno = errno;
   178	      printf("[ROBOT-SKILL] name=%s stage=open-temp errno=%d\n",
   179	             resource->filename, saved_errno);
   180	      return -saved_errno;
   181	    }
   182	
   183	  written = fwrite(resource->content, 1, resource->size, file);
   184	  if (written != resource->size)
