   207	      printf("[ROBOT-SKILL] name=%s stage=close errno=%d\n",
   208	             resource->filename, saved_errno);
   209	      unlink(tmp);
   210	      return -saved_errno;
   211	    }
   212	
   213	  if (rename(tmp, path) != 0)
   214	    {
   215	      saved_errno = errno != 0 ? errno : EIO;
   216	      printf("[ROBOT-SKILL] name=%s stage=rename errno=%d\n",
   217	             resource->filename, saved_errno);
   218	      unlink(tmp);
   219	      return -saved_errno;
   220	    }
   221	  return 0;
   222	}
