bool robot_music_media_owns_reply(unsigned long run)
{
  bool owns;

  pthread_mutex_lock(&g_music_lock);
  owns = run != 0 && g_active_music != NULL && g_active_music->started &&
         g_active_music->run == run;
  pthread_mutex_unlock(&g_music_lock);
  return owns;
}

bool robot_music_media_is_active(void)
{
  bool active;

  pthread_mutex_lock(&g_music_lock);
  active = g_active_music != NULL && g_active_music->started &&
           !g_active_music->closing;
  pthread_mutex_unlock(&g_music_lock);
  return active;
}

bool robot_music_media_is_ready(void)
{
  return robot_music_media_is_active() &&
         robot_audio_playback_buffered_bytes() >= ROBOT_MUSIC_READY_BYTES;
}

