         info->nChans >= 1 && info->nChans <= 2 &&
         info->samprate >= 8000 && info->samprate <= 48000 &&
         info->outputSamps > 0 &&
         info->outputSamps <= RV_PCM_SAMPLES_CAP &&
         info->outputSamps % info->nChans == 0;
