   289	              decoder->pcm_bytes += sizeof(decoder->pcm);
   290	              output_count = 0;
   291	            }
   292	        }
   293	    }
   294	
   295	  if (output_count > 0)
   296	    {
   297	      int ret = robot_audio_playback_write((const uint8_t *)decoder->pcm,
   298	                                           (size_t)output_count * sizeof(int16_t));
   299	      if (ret < 0)
   300	        {
   301	          if (decoder->pcm_error == 0)
   302	            {
   303	              decoder->pcm_error = ret;
   304	            }
   305	          return ret;
   306	        }
   307	      decoder->pcm_bytes += (size_t)output_count * sizeof(int16_t);
   308	    }
   309	
   310	  return 0;
   311	}
