   313	static int rv_mp3_decode(struct rv_mp3_decoder *decoder,
   314	                         const unsigned char *data, size_t len)
   315	{
   316	  if (len > sizeof(decoder->input) - decoder->input_len)
   317	    {
   318	      return -ENOBUFS;
   319	    }
   320	
   321	  memcpy(decoder->input + decoder->input_len, data, len);
   322	  decoder->input_len += len;
   323	
   324	  while (decoder->input_len > 0)
   325	    {
   326	      int sync = MP3FindSyncWord(decoder->input, (int)decoder->input_len);
   327	      unsigned char *cursor;
   328	      int left;
   329	      int consumed;
   330	      int ret;
   331	      MP3FrameInfo info;
   332	      size_t input_len_before;
   333	
   334	      if (sync < 0)
   335	        {
   336	          /* Keep enough bytes for a sync word split across HTTP chunks. */
   337	          if (decoder->input_len > 3)
   338	            {
   339	              memmove(decoder->input, decoder->input + decoder->input_len - 3,
   340	                      3);
   341	              decoder->input_len = 3;
   342	            }
   343	          break;
   344	        }
   345	
   346	      if (sync > 0)
   347	        {
   348	          memmove(decoder->input, decoder->input + sync,
   349	                  decoder->input_len - (size_t)sync);
   350	          decoder->input_len -= (size_t)sync;
   351	        }
   352	
   353	      cursor = decoder->input;
   354	      left = (int)decoder->input_len;
   355	      input_len_before = decoder->input_len;
   356	      ret = MP3Decode(decoder->decoder, &cursor, &left, decoder->decoded, 0);
   357	      consumed = (int)(cursor - decoder->input);
   358	
   359	      /* Helix advances the input pointer past the header and side-info before
   360	       * it discovers that the main data is incomplete.  Those bytes still
   361	       * belong to the current frame and must be retained for the next HTTP
   362	       * chunk.  Dropping them makes the next call scan the middle of a frame,
   363	       * which produces invalid headers, bad frame info, and audible clicks. */
   364	      if (ret == ERR_MP3_INDATA_UNDERFLOW)
   365	        {
   366	          decoder->indata_underflows++;
   367	          decoder->last_decoder_error = ret;
   368	          break;
   369	        }
   370	
   371	      if (consumed > 0 && (size_t)consumed <= decoder->input_len)
   372	        {
   373	          memmove(decoder->input, decoder->input + consumed,
   374	                  decoder->input_len - (size_t)consumed);
   375	          decoder->input_len -= (size_t)consumed;
   376	        }
   377	
   378	      if (ret == ERR_MP3_MAINDATA_UNDERFLOW)
   379	        {
   380	          /* The frame was copied into Helix's bit reservoir and consumed.
   381	           * It is not valid PCM, but it must not be replayed on retry. */
   382	          decoder->maindata_underflows++;
   383	          decoder->last_decoder_error = ret;
   384	          break;
   385	        }
   386	
   387	      if (ret < 0)
   388	        {
   389	          decoder->decoder_errors++;
   390	          decoder->last_decoder_error = ret;
   391	          /* Drop one byte and search for the next frame rather than looping
   392	           * forever on an ID3 or malformed chunk. */
   393	          if (decoder->input_len > 0)
   394	            {
   395	              memmove(decoder->input, decoder->input + 1,
   396	                      decoder->input_len - 1);
   397	              decoder->input_len--;
   398	            }
   399	          continue;
   400	        }
   401	
   402	      /* A successful decode should consume one frame.  If Helix reports
   403	       * success without advancing, discard one byte and resynchronize so a
   404	       * damaged header cannot spin forever or abort the HTTP sink. */
   405	
   406	      if (consumed <= 0 || (size_t)consumed > input_len_before)
   407	        {
   408	          decoder->decoder_errors++;
   409	          decoder->last_decoder_error = -EILSEQ;
   410	          if (decoder->input_len > 0)
   411	            {
   412	              memmove(decoder->input, decoder->input + 1,
   413	                      decoder->input_len - 1);
   414	              decoder->input_len--;
   415	              continue;
   416	            }
   417	
   418	          break;
   419	        }
   420	
   421	      MP3GetLastFrameInfo(decoder->decoder, &info);
   422	      if (!rv_mp3_frame_info_valid(&info))
   423	        {
   424	          decoder->decoder_errors++;
   425	          decoder->bad_frame_info++;
   426	          decoder->last_decoder_error = -EINVAL;
   427	          if (decoder->bad_frame_info == 1)
   428	            {
   429	              syslog(LOG_ERR,
   430	                     "[%s] invalid MP3 frame info samples=%d channels=%d "
   431	                     "rate=%d consumed=%d\n",
   432	                     RV_MEDIA_TAG, info.outputSamps, info.nChans,
   433	                     info.samprate, consumed);
   434	            }
   435	
   436	          /* The corrupt frame has already been consumed.  Skip it and keep
   437	           * receiving the rest of the HTTP body.  Returning -EINVAL here
   438	           * would make webclient_perform abort the entire download. */
   439	          continue;
   440	        }
   441	
   442	      __atomic_store_n(&decoder->bitrate, info.bitrate, __ATOMIC_RELAXED);
   443	      ret = rv_write_pcm(decoder, decoder->decoded, info.outputSamps,
   444	                         info.nChans, info.samprate);
   445	      if (ret < 0)
   446	        {
   447	          /* Preserve the playback/I2S error.  Mapping every sink failure to
   448	           * EIO made network truncation and audio-device failures
   449	           * indistinguishable on the board. */
   450	          return ret;
   451	        }
   452	      decoder->frame_count++;
   453	    }
   454	
   455	  return 0;
   456	}
