   458	static int rv_mp3_queue_write(struct rv_mp3_decoder *decoder,
   459	                              const unsigned char *src, size_t len)
   460	{
   461	  size_t offset = 0;
   462	
   463	  while (offset < len)
   464	    {
   465	      size_t amount;
   466	      size_t first;
   467	
   468	      pthread_mutex_lock(&decoder->queue_lock);
   469	      while (decoder->queue_count == sizeof(decoder->queue) &&
   470	             decoder->queue_error == 0 && !decoder->queue_stop &&
   471	             !rv_player_stop_requested(decoder->player))
   472	        {
   473	          pthread_cond_wait(&decoder->queue_space, &decoder->queue_lock);
   474	        }
   475	
   476	      if (decoder->queue_error < 0)
   477	        {
   478	          int error = decoder->queue_error;
   479	          pthread_mutex_unlock(&decoder->queue_lock);
   480	          return error;
   481	        }
   482	
   483	      if (decoder->queue_stop || rv_player_stop_requested(decoder->player))
   484	        {
   485	          pthread_mutex_unlock(&decoder->queue_lock);
   486	          return -ECANCELED;
   487	        }
   488	
   489	      amount = sizeof(decoder->queue) - decoder->queue_count;
   490	      if (amount > len - offset) amount = len - offset;
   491	      first = sizeof(decoder->queue) - decoder->queue_head;
   492	      if (first > amount) first = amount;
   493	      memcpy(decoder->queue + decoder->queue_head, src + offset, first);
   494	      if (first < amount)
   495	        memcpy(decoder->queue, src + offset + first, amount - first);
   496	      decoder->queue_head = (decoder->queue_head + amount) %
   497	                            sizeof(decoder->queue);
   498	      decoder->queue_count += amount;
   499	      if (decoder->queue_count > decoder->queue_high_water)
   500	        {
   501	          decoder->queue_high_water = decoder->queue_count;
   502	        }
   503	      offset += amount;
   504	      pthread_cond_signal(&decoder->queue_data);
   505	      pthread_mutex_unlock(&decoder->queue_lock);
   506	    }
   507	
   508	  return 0;
   509	}
   510	
   511	static void *rv_mp3_decode_worker(void *arg)
   512	{
   513	  struct rv_mp3_decoder *decoder = arg;
   514	  unsigned char chunk[RV_MP3_QUEUE_CHUNK];
   515	
   516	  for (;;)
   517	    {
   518	      size_t amount;
   519	      size_t first;
   520	      int ret;

   520	      int ret;
   521	
   522	      pthread_mutex_lock(&decoder->queue_lock);
   523	      while (decoder->queue_count == 0 && !decoder->queue_stop)
   524	        pthread_cond_wait(&decoder->queue_data, &decoder->queue_lock);
   525	
   526	      if (decoder->queue_count == 0 && decoder->queue_stop)
   527	        {
   528	          pthread_mutex_unlock(&decoder->queue_lock);
   529	          break;
   530	        }
   531	
   532	      amount = decoder->queue_count;
   533	      if (amount > sizeof(chunk)) amount = sizeof(chunk);
   534	      first = sizeof(decoder->queue) - decoder->queue_tail;
   535	      if (first > amount) first = amount;
   536	      memcpy(chunk, decoder->queue + decoder->queue_tail, first);
   537	      if (first < amount)
   538	        memcpy(chunk + first, decoder->queue, amount - first);
   539	      decoder->queue_tail = (decoder->queue_tail + amount) %
   540	                            sizeof(decoder->queue);
   541	      decoder->queue_count -= amount;
   542	      pthread_cond_broadcast(&decoder->queue_space);
   543	      pthread_mutex_unlock(&decoder->queue_lock);
   544	
   545	      ret = rv_mp3_decode(decoder, chunk, amount);
   546	      if (ret < 0)
   547	        {
   548	          pthread_mutex_lock(&decoder->queue_lock);
   549	          if (decoder->queue_error == 0) decoder->queue_error = ret;
   550	          decoder->queue_stop = true;
   551	          pthread_cond_broadcast(&decoder->queue_space);
   552	          pthread_cond_broadcast(&decoder->queue_data);
   553	          pthread_mutex_unlock(&decoder->queue_lock);
   554	          break;
   555	        }
   556	    }
   557	
   558	  return NULL;
   559	}
