   561	static int rv_mp3_sink(char **buffer, int offset, int datend, int *buflen,
   562	                       void *arg)
   563	{
   564	  struct rv_mp3_decoder *decoder = arg;
   565	  unsigned long long now_ms;
   566	  unsigned long long gap_ms = 0;
   567	  bool report = false;
   568	  int ret;
   569	
   570	  (void)buflen;
   571	  if (!decoder)
   572	    {
   573	      syslog(LOG_ERR, "[%s] MP3 sink called without decoder\n", RV_MEDIA_TAG);
   574	      return -EINVAL;
   575	    }
   576	
   577	  if (!buffer || !*buffer || offset < 0 || datend < offset)
   578	    {
   579	      if (decoder->sink_error == 0)
   580	        {
   581	          decoder->sink_error = -EINVAL;
   582	        }
   583	      syslog(LOG_ERR, "[%s] invalid MP3 sink range offset=%d end=%d\n",
   584	             RV_MEDIA_TAG, offset, datend);
   585	      return -EINVAL;
   586	    }
   587	
   588	  if (rv_player_stop_requested(decoder->player))
   589	    {
   590	      syslog(LOG_INFO, "[%s] HTTP MP3 stop observed in sink\n", RV_MEDIA_TAG);
   591	      return -ECANCELED;
   592	    }
   593	
   594	  /* A reconnect must start at the exact byte offset requested.  Reject a
   595	   * server that ignores Range before adding any bytes to the live decoder;
   596	   * otherwise the restarted response would duplicate the beginning of the
   597	   * song in the current MP3 stream. */
   598	  if (decoder->resume_pending)
   599	    {
   600	      decoder->resume_pending = false;
   601	      if (decoder->http_context != NULL &&
   602	          decoder->http_context->http_status == 200)
   603	        {
   604	          /* Some music CDNs ignore Range. Re-fetch from byte zero and drop
   605	           * the already queued prefix so playback continues without a
   606	           * repeated intro. */
   607	          decoder->resume_skip_remaining = decoder->stream_offset;
   608	        }
   609	      else if (decoder->http_context != NULL &&
   610	               decoder->http_context->http_status == 206)
   611	        {
   612	          decoder->resume_skip_remaining = 0;
   613	        }
   614	      else if (decoder->http_context == NULL ||
   615	               decoder->http_context->http_status != 206)
   616	        {
   617	          decoder->resume_rejected = true;
   618	          if (decoder->sink_error == 0)
   619	            {
   620	              decoder->sink_error = -EPROTO;
   621	            }
   622	
   623	          syslog(LOG_ERR,
   624	                 "[%s] HTTP Range resume rejected status=%ld offset=%zu\n",
   625	                 RV_MEDIA_TAG,
   626	                 decoder->http_context != NULL ?
   627	                   decoder->http_context->http_status : 0,
   628	                 decoder->stream_offset);
   629	          return -EPROTO;
   630	        }
   631	    }
   632	
   633	  now_ms = rv_media_now_ms();
   634	  if (decoder->last_sink_ms != 0 && now_ms >= decoder->last_sink_ms)
   635	    {
   636	      gap_ms = now_ms - decoder->last_sink_ms;
   637	      if (gap_ms > decoder->max_sink_gap_ms)
   638	        {
   639	          decoder->max_sink_gap_ms = gap_ms;
   640	        }
   641	    }
   642	  decoder->last_sink_ms = now_ms;
   643	  decoder->sink_calls++;
   644	  decoder->http_bytes += (size_t)(datend - offset);
   645	
   646	  if (decoder->resume_skip_remaining != 0)
   647	    {
   648	      size_t amount = (size_t)(datend - offset);
   649	
   650	      if (amount <= decoder->resume_skip_remaining)
   651	        {
   652	          decoder->resume_skip_remaining -= amount;
   653	          return rv_player_stop_requested(decoder->player) ?
   654	                 -ECANCELED : 0;
   655	        }
   656	
   657	      offset += (int)decoder->resume_skip_remaining;
   658	      decoder->resume_skip_remaining = 0;
   659	    }
   660	
   661	  /* Report stream cadence once per second.  This is intentionally separate
   662	   * from the packet-level [WLAN-TLS] driver trace, so a long HTTP gap can be
   663	   * correlated with Wi-Fi/TLS diagnostics without flooding the console. */
   664	  report = decoder->sink_calls == 1;
   665	  if (now_ms != 0 && decoder->last_report_ms != 0 &&
   666	      now_ms >= decoder->last_report_ms &&
   667	      now_ms - decoder->last_report_ms >= 1000)
   668	    {
   669	      report = true;
   670	    }
   671	  else if (now_ms == 0 && (decoder->sink_calls % 32) == 0)
   672	    {
   673	      report = true;
   674	    }
   675	
   676	  if (report)
   677	    {
   678	      size_t queue_depth;
   679	      size_t queue_high_water;
   680	
   681	      pthread_mutex_lock(&decoder->queue_lock);
   682	      queue_depth = decoder->queue_count;
   683	      queue_high_water = decoder->queue_high_water;
   684	      pthread_mutex_unlock(&decoder->queue_lock);
   685	      syslog(LOG_INFO,
   686	             "[RV-MUSIC-NET] rx=%zu pcm=%zu frames=%lu callbacks=%lu "
   687	             "last_gap_ms=%llu max_gap_ms=%llu decode_errors=%lu "
   688	             "queue=%zu/%zu queue_high=%zu\n",
   689	             decoder->http_bytes, decoder->pcm_bytes, decoder->frame_count,
   690	             decoder->sink_calls,
   691	             gap_ms, decoder->max_sink_gap_ms, decoder->decoder_errors,
   692	             queue_depth, sizeof(decoder->queue), queue_high_water);
   693	      decoder->last_report_ms = now_ms;
   694	    }
   695	
   696	  unsigned long long enqueue_ms = rv_media_now_ms();
   697	  ret = rv_mp3_queue_write(decoder,
   698	                           (const unsigned char *)*buffer + offset,
   699	                           (size_t)(datend - offset));
   700	  if (ret < 0)
   701	    {
   702	      if (decoder->sink_error == 0)
   703	        {
   704	          decoder->sink_error = ret;
   705	          syslog(LOG_ERR, "[%s] MP3 sink failed rc=%d http=%z…15262 tokens truncated…]
   119	                                             [ROBOT_OLED_ROW_BYTES],
   120	                             int center_y, bool open)
