void robot_audio_playback_set_stop_on_short_underrun(bool enable)
{
  g_stop_on_short_underrun = enable ? 1 : 0;
  RV_VERBOSE("[RV-PB] short-tail policy=%s\n",
         enable ? "play-real-tail-then-stop" : "normal");
