      RV_MAX_INFLIGHT != RV_LOWER_DMA_RING_SLOTS)
    {
      printf("[RV-PB] lower contract mismatch wire_block=%u/%u slots=%u/%u\n",
             RV_WIRE_BLOCK_BYTES, RV_LOWER_DMA_SLOT_BYTES,
             RV_MAX_INFLIGHT, RV_LOWER_DMA_RING_SLOTS);
      return -EINVAL;
    }

  pb->i2s = board_voice_speaker_i2s();
  if (pb->i2s == NULL)
    {
      return -ENODEV;
    }

