        }
      for (unsigned int i = pb->slot_count; i < RV_MAX_INFLIGHT; i++)
        {
          if (pb->slots[i].apb) apb_free(pb->slots[i].apb);
          pb->slots[i].apb = NULL;
        }
      break;
    }
  if (!pb->i2s_started)
    {
      printf("[RV-PB] DMA unavailable rc=%d; minimum ring allocation failed\n", ret);
      goto fail;
    }
