    }

  usleep(ROBOT_OLED_SELFTEST_DELAY_US);

  printf("[RV-OLED] selftest ALL_OFF begin\n");
  ret = robot_oled_fill(false);
  printf("[RV-OLED] selftest ALL_OFF rc=%d\n", ret);
  if (ret < 0)
