          g_oled_queue.head =
              (g_oled_queue.head + 1) % ROBOT_OLED_QUEUE_DEPTH;
          g_oled_queue.count--;
          state_change = !have_current || expression != current_expression;
          current_expression = expression;
          animation_tick = 0;
          frame = robot_oled_animation_frame(current_expression,
                                              animation_tick);
          current_frame = frame;
          have_current = true;
          render_now = true;
          printf("[RV-OLED] state expression=%d frame=%u pending=%u\n",
                 expression, frame, g_oled_queue.count);
        }
      else if (have_current)
        {
          unsigned int next_frame;

          animation_tick++;
          next_frame = robot_oled_animation_frame(current_expression,
                                                   animation_tick);
          if (next_frame != current_frame)
            {
              current_frame = next_frame;
              frame = next_frame;
              expression = current_expression;
              render_now = true;
            }
        }

      pthread_mutex_unlock(&g_oled_queue.lock);

      clock_gettime(CLOCK_MONOTONIC, &now);
      now_ms = (unsigned long long)now.tv_sec * 1000ull +
               (unsigned long long)now.tv_nsec / 1000000ull;
      if (have_current && now_ms >= next_status_refresh_ms)
        {
          render_now = true;
          expression = current_expression;
          frame = current_frame;
          next_status_refresh_ms = now_ms + ROBOT_OLED_STATUS_REFRESH_MS;
        }

