    }

  if (ret == 0)
    {
      pthread_mutex_lock(&g_wifi_recovery_lock);
      g_wifi_connect_failures = 0;
      pthread_mutex_unlock(&g_wifi_recovery_lock);
      RV_EVENT("[网络恢复] connected\n");
    }
  else
    {
