+  static const uint8_t glyphs[4][5] =
+    {
+      {0x1, 0x1, 0x1, 0x1, 0x7}, /* L */
+      {0x7, 0x5, 0x5, 0x5, 0x7}, /* O */
+      {0x2, 0x5, 0x7, 0x5, 0x5}, /* A */
