481	{
482	    media_ctx_init_once();
483	
484	    cJSON* root = cJSON_Parse(input_json);
485	    if (!root) {
486	        return respond_error(output, output_size,
487	            "EINVAL_ARG", "Invalid JSON input");
488	    }
489	
490	    cJSON* j_url = cJSON_GetObjectItem(root, "url");
491	    if (!j_url || !cJSON_IsString(j_url) || !j_url->valuestring[0]) {
492	        cJSON_Delete(root);
493	        return respond_error(output, output_size,
494	            "EINVAL_ARG", "Missing or empty 'url'");
495	    }
496	
497	    /* Build media options string for prepare().
498	     * For raw PCM files, format info is required because there is no
499	     * container header for avformat to auto-detect. */
500	
501	    char options_buf[MEDIA_OPTIONS_MAX] = { 0 };
502	    const char* options = NULL;
503	
504	    cJSON* j_opts = cJSON_GetObjectItem(root, "options");
505	    if (j_opts && cJSON_IsString(j_opts) && j_opts->valuestring[0]) {
506	        snprintf(options_buf, sizeof(options_buf), "%s",
507	            j_opts->valuestring);
508	        options = options_buf;
509	    } else {
510	        cJSON* j_fmt = cJSON_GetObjectItem(root, "format");
511	        cJSON* j_rate = cJSON_GetObjectItem(root, "sample_rate");
512	        cJSON* j_ch = cJSON_GetObjectItem(root, "channels");
513	
514	        /* Treat empty strings and zero values as "not provided" so
515	         * that bogus LLM args like format="" sample_rate=0 channels=0
516	         * fall through to auto-detection instead of producing an
517	         * invalid options string. */
518	
519	        bool has_fmt = j_fmt && cJSON_IsString(j_fmt)
520	            && j_fmt->valuestring[0];
521	        bool has_rate = j_rate && cJSON_IsNumber(j_rate)
522	            && (int)j_rate->valuedouble > 0;
523	        bool has_ch = j_ch && cJSON_IsNumber(j_ch)
524	            && (int)j_ch->valuedouble > 0;
525	
526	        if (has_fmt || has_rate || has_ch) {
527	            const char* fmt = has_fmt ? j_fmt->valuestring : "s16le";
528	            int rate = has_rate ? (int)j_rate->valuedouble : 16000;
529	            int ch = has_ch ? (int)j_ch->valuedouble : 1;
530	            const char* layout = (ch == 2) ? "stereo" : "mono";
531	
532	            snprintf(options_buf, sizeof(options_buf),
533	                "format=%s:sample_rate=%d:ch_layout=%s",
534	                fmt, rate, layout);
535	            options = options_buf;
536	        }
537	    }
538	
539	    /* Auto-detect: if URL ends with .pcm and no options given,
540	     * provide a sensible default (s16le, 16kHz, mono). */
541	
542	    if (!options) {
543	        const char* ext = strrchr(j_url->valuestring, '.');
544	        if (ext && strcasecmp(ext, ".pcm") == 0) {
545	            snprintf(options_buf, sizeof(options_buf),
546	                "format=s16le:sample_rate=16000:ch_layout=mono");
547	            options = options_buf;
548	            syslog(LOG_INFO,
