 58	typedef enum {
 59	    MEDIA_STATE_IDLE = 0,
 60	    MEDIA_STATE_PREPARED,
 61	    MEDIA_STATE_PLAYING,
 62	    MEDIA_STATE_PAUSED,
 63	    MEDIA_STATE_COMPLETED,
 64	    MEDIA_STATE_ERROR,
 65	} media_state_e;
 66	
 67	typedef struct
 68	{
 69	    pthread_mutex_t lock;
