 78	    /* Event confirmation via semaphore */
 79	
 80	    sem_t sem; /* posted by event callback */
 81	    int last_event; /* MEDIA_EVENT_* from callback */
 82	    int last_result; /* result code from callback */
 83	} media_ctx_t;
