 96	static void media_ctx_init_once(void)
 97	{
 98	    if (g_media_initialized) {
 99	        return;
100	    }
101	
102	    memset(&g_media, 0, sizeof(g_media));
103	    pthread_mutex_init(&g_media.lock, NULL);
104	    sem_init(&g_media.sem, 0, 0);
105	    g_media.state = MEDIA_STATE_IDLE;
106	    g_media.handle = NULL;
107	    g_media.session_id = 0;
108	    g_media.volume = 50;
109	    g_media.exiting = false;
110	    g_media.last_event = 0;
111	    g_media.last_result = 0;
112	    g_media_initialized = true;
113	}
