120	    case MEDIA_STATE_PREPARED:
700	            pthread_mutex_unlock(&g_media.lock);
701	            cJSON_Delete(root);
702	            return respond_error(output, output_size,
703	                "EIO_MEDIA", "media_player_start failed");
704	        }
705	
706	        if (wait_event(MEDIA_EVENT_STARTED, TIMEOUT_START_MS) != 0) {
707	            /* Same as PREPARED — on some hardware the event callback
708	             * never fires.  If start() returned 0, assume it worked. */
709	
710	            syslog(LOG_WARNING,
711	                "[%s] STARTED event not confirmed within %d ms, "
712	                "proceeding anyway (start ret was 0)\n",
713	                TAG, TIMEOUT_START_MS);
714	            g_media.state = MEDIA_STATE_PLAYING;
715	        }
716	
717	        /* State is now PLAYING (set by event callback or forced above) */
718	
719	        /* Fallback seek after start if pre-seek was not done */
720	
721	        if (start_pos > 0) {
722	            ret = media_player_seek(g_media.handle,
723	                (unsigned int)start_pos);
724	            if (ret >= 0) {
725	                /* Best-effort, don't fail the whole play for this */
726	
727	                wait_event(MEDIA_EVENT_SEEKED, TIMEOUT_SEEK_MS);
728	            }
729	        }
730	    }
731	
732	    /* Build response */
733	
734	    char extra[256];
735	    snprintf(extra, sizeof(extra),
736	        "\"session_id\":%" PRIu32 ",\"url\":\"%s\","
737	        "\"start_position_ms\":%d",
738	        sid, url, start_pos);
739	
740	    int rc = respond_ok_state(output, output_size, extra);
741	
742	    pthread_mutex_unlock(&g_media.lock);
743	    cJSON_Delete(root);
744	    return rc;
745	}
