747	/**
748	 * music_pause — pause + wait MEDIA_EVENT_PAUSED.
749	 */
750	
751	int tool_music_pause_execute(const char* input_json,
752	    char* output, size_t output_size)
753	{
754	    (void)input_json;
755	    media_ctx_init_once();
756	
757	    pthread_mutex_lock(&g_media.lock);
758	
759	    if (g_media.state == MEDIA_STATE_PAUSED) {
760	        int rc = respond_ok_state(output, output_size, "\"noop\":true");
761	        pthread_mutex_unlock(&g_media.lock);
762	        return rc;
763	    }
764	
765	    if (g_media.state != MEDIA_STATE_PLAYING) {
766	        pthread_mutex_unlock(&g_media.lock);
767	        return respond_error(output, output_size,
768	            "EINVAL_STATE",
769	            "Cannot pause: not playing");
770	    }
771	
772	    int ret = media_player_pause(g_media.handle);
773	    if (ret < 0) {
774	        syslog(LOG_ERR, "[%s] media_player_pause send failed: %d\n",
775	            TAG, ret);
776	        pthread_mutex_unlock(&g_media.lock);
777	        return respond_error(output, output_size,
778	            "EIO_MEDIA", "media_player_pause failed");
779	    }
780	
781	    if (wait_event(MEDIA_EVENT_PAUSED, TIMEOUT_PAUSE_MS) != 0) {
782	        syslog(LOG_ERR, "[%s] Pause not confirmed\n", TAG);
783	        pthread_mutex_unlock(&g_media.lock);
784	        return respond_error(output, output_size,
785	            "EIO_MEDIA",
786	            "media_player_pause timed out");
787	    }
788	
789	    syslog(LOG_INFO, "[%s] Paused session %" PRIu32 "\n",
790	        TAG, g_media.session_id);
791	
792	    int rc = respond_ok_state(output, output_size, NULL);
793	    pthread_mutex_unlock(&g_media.lock);
794	    return rc;
795	}
