799	 */
800	
801	int tool_music_resume_execute(const char* input_json,
802	    char* output, size_t output_size)
803	{
804	    (void)input_json;
805	    media_ctx_init_once();
806	
807	    pthread_mutex_lock(&g_media.lock);
808	
809	    if (g_media.state == MEDIA_STATE_PLAYING) {
810	        int rc = respond_ok_state(output, output_size, "\"noop\":true");
811	        pthread_mutex_unlock(&g_media.lock);
812	        return rc;
813	    }
814	
815	    if (g_media.state != MEDIA_STATE_PAUSED && g_media.state != MEDIA_STATE_PREPARED) {
816	        pthread_mutex_unlock(&g_media.lock);
817	        return respond_error(output, output_size,
818	            "EINVAL_STATE",
819	            "Cannot resume: not paused or prepared");
820	    }
821	
822	    int ret = media_player_start(g_media.handle);
823	    if (ret < 0) {
824	        syslog(LOG_ERR, "[%s] media_player_start (resume) send failed: %d\n",
825	            TAG, ret);
826	        pthread_mutex_unlock(&g_media.lock);
827	        return respond_error(output, output_size,
828	            "EIO_MEDIA", "media_player_start failed");
829	    }
830	
831	    if (wait_event(MEDIA_EVENT_STARTED, TIMEOUT_START_MS) != 0) {
832	        syslog(LOG_ERR, "[%s] Resume/start not confirmed\n", TAG);
833	        pthread_mutex_unlock(&g_media.lock);
834	        return respond_error(output, output_size,
835	            "EIO_MEDIA",
836	            "media_player_start timed out");
837	    }
838	
839	    syslog(LOG_INFO, "[%s] Resumed session %" PRIu32 "\n",
840	        TAG, g_media.session_id);
841	
842	    int rc = respond_ok_state(output, output_size, NULL);
843	    pthread_mutex_unlock(&g_media.lock);
844	    return rc;
845	}
