872	
873	            wait_event(MEDIA_EVENT_STOPPED, TIMEOUT_STOP_MS);
874	        }
875	    }
876	
877	    /* Always force close to ensure clean state */
878	
879	    force_close_locked();
880	
881	    int rc = respond_ok_state(output, output_size, NULL);
882	    pthread_mutex_unlock(&g_media.lock);
883	    return rc;
884	}
