/* ── CLI thread ───────────────────────────────────────────────── */

static void* cli_thread(void* arg)
{
    (void)arg;
    char line[LINE_LEN];
    char* argv[MAX_ARGS];

    syslog(LOG_INFO, "[%s] NSH CLI started. Type 'help' for commands.\n", TAG);
    pthread_mutex_lock(&g_stdout_lock);
    printf("vela> ");
    fflush(stdout);
    pthread_mutex_unlock(&g_stdout_lock);

    while (fgets(line, sizeof(line), stdin) != NULL) {
        /* Strip trailing newline */
        size_t len = strlen(line);
        while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r'))
            line[--len] = '\0';

        if (len == 0) {
            pthread_mutex_lock(&g_stdout_lock);
            printf("vela> ");
            fflush(stdout);
            pthread_mutex_unlock(&g_stdout_lock);
            continue;
        }

        int argc = tokenise(line, argv, MAX_ARGS);
        if (argc == 0) {
            pthread_mutex_lock(&g_stdout_lock);
            printf("vela> ");
            fflush(stdout);
            pthread_mutex_unlock(&g_stdout_lock);
            continue;
        }

        const char* cmd = argv[0];

        if (strcmp(cmd, "help") == 0)
            cmd_help();
        else if (strcmp(cmd, "net_status") == 0)
            cmd_net_status();
        else if (strcmp(cmd, "net_dns") == 0) {
            if (argc != 2) printf("Usage: net_dns <host>\n");
            else {
                int rc = network_dns_probe(argv[1]);
                if (rc < 0) printf("DNS failed: rc=%d; run net_status and check the DHCP/router DNS.\n", rc);
            }
        }
        else if (strcmp(cmd, "net_test") == 0)
            cmd_net_test();
        else if (strcmp(cmd, "set_feishu_app") == 0)
            cmd_set_feishu_app(argc, argv);
        else if (strcmp(cmd, "set_feishu_user_token") == 0)
            cmd_set_feishu_user_token(argc, argv);
        else if (strcmp(cmd, "set_llm") == 0)
            cmd_set_llm(argc, argv);
        else if (strcmp(cmd, "set_vision_llm") == 0)
            cmd_set_vision_llm(argc, argv);
        else if (strcmp(cmd, "list_models") == 0)
            cmd_list_models(argc, argv);
        else if (strcmp(cmd, "memory_read") == 0)
            cmd_memory_read();
        else if (strcmp(cmd, "memory_write") == 0)
            cmd_memory_write(argc, argv);
        else if (strcmp(cmd, "session_list") == 0)
            cmd_session_list();
        else if (strcmp(cmd, "session_clear") == 0)
            cmd_session_clear(argc, argv);

                break;
            case 0x08: /* WS close */
                syslog(LOG_INFO, "[%s] Server WS close; reconnecting\n", TAG);
                s_ws.connected = false;
                break;
            default:
                break;
            }
        }

        ws_free(&s_ws);
        syslog(LOG_WARNING, "[%s] WS disconnected; reconnecting in 5s\n", TAG);
        sleep(5);
    }

    return NULL;
}

/* ── Public API ──────────────────────────────────────────────── */

int feishu_bot_init(void)
{
    memset(&s_ws, 0, sizeof(s_ws));
    mbedtls_net_init(&s_ws.net);
    sem_init(&s_cred_sem, 0, 0);

    /* Initialize RNG */
    if (!s_rng_ready) {
        mbedtls_ctr_drbg_init(&s_ctr_drbg);
        int ret = mbedtls_ctr_drbg_seed(&s_ctr_drbg, simple_entropy_func, NULL,
            (const unsigned char*)TAG, strlen(TAG));
        if (ret != 0) {
            syslog(LOG_ERR, "[%s] ctr_drbg_seed failed: -0x%04x\n", TAG, -ret);
            return ERROR;
        }
        s_rng_ready = true;
        syslog(LOG_INFO, "[%s] RNG ready\n", TAG);
    }

    char tmp[64] = { 0 };

    if (claw_config_get(AGENT_CFG_KEY_FEISHU_APP_ID, tmp, sizeof(tmp)) == OK &&
        tmp[0]) {
        strncpy(s_app_id, tmp, sizeof(s_app_id) - 1);
    }

    memset(tmp, 0, sizeof(tmp));
    if (claw_config_get(AGENT_CFG_KEY_FEISHU_APP_SECRET, tmp, sizeof(tmp)) == OK &&
        tmp[0]) {
        strncpy(s_app_secret, tmp, sizeof(s_app_secret) - 1);
    }

    memset(tmp, 0, sizeof(tmp));
    if (claw_config_get(AGENT_CFG_KEY_FEISHU_USER_TOKEN, tmp, sizeof(tmp)) == OK &&
        tmp[0]) {
        strncpy(s_user_token, tmp, sizeof(s_user_token) - 1);
        syslog(LOG_INFO, "[%s] Feishu user_token loaded\n", TAG);
    }

    if (s_app_id[0]) {
        syslog(LOG_INFO, "[%s] Feishu app_id=%s\n", TAG, s_app_id);
    } else {
        syslog(LOG_WARNING,
            "[%s] No Feishu credentials. Use CLI: set_feishu_app <app_id> <app_secret>\n",
            TAG);
    }

    return OK;
}

int feishu_bot_start(void)
{
    return agent_task_create(feishu_poll_task, "feishu_poll",
        AGENT_FEISHU_POLL_STACK, NULL, AGENT_FEISHU_POLL_PRIO);
}

