/* ── Background polling task ─────────────────────────────────── */

static void* feishu_poll_task(void* arg)
{
    (void)arg;
    syslog(LOG_INFO, "[%s] Feishu polling task started\n", TAG);

    const size_t frame_buf_size = 65536;
    uint8_t* frame_buf = malloc(frame_buf_size);

    if (!frame_buf) {
        syslog(LOG_ERR, "[%s] OOM for frame_buf\n", TAG);
        return NULL;
    }

    char* ws_host = malloc(128);
    char* ws_path = malloc(768);

    if (!ws_host || !ws_path) {
        syslog(LOG_ERR, "[%s] OOM for ws_host/ws_path\n", TAG);
        free(frame_buf);
        free(ws_host);
        free(ws_path);
        return NULL;
    }

    int32_t svc_id = 0;

    while (1) {
        /* Credentials check */
        if (s_app_id[0] == '\0' || s_app_secret[0] == '\0') {
            static int s_no_cred_logged = 0;
            if (!s_no_cred_logged) {
                syslog(LOG_WARNING,
                    "[%s] No app_id/app_secret. Use: "
                    "set_feishu_app <id> <secret>\n", TAG);
                s_no_cred_logged = 1;
            }
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            ts.tv_sec += 60;
            sem_timedwait(&s_cred_sem, &ts);
            continue;
        }

        /* Refresh access token */
        if (feishu_token_expired()) {
            if (feishu_get_app_token() != OK) {
                syslog(LOG_WARNING, "[%s] Token refresh failed; retry in 30s\n", TAG);
                sleep(30);
                continue;
            }
        }

        /* Get WS endpoint */
        memset(ws_host, 0, 128);
        memset(ws_path, 0, 768);
        if (feishu_create_connection(ws_host, 128, ws_path, 768) != OK) {
            syslog(LOG_WARNING, "[%s] create_connection failed; retry in 10s\n", TAG);
            sleep(10);
#endif
        agent_loop_start();
        ws_server_start();
#ifdef CONFIG_AI_AGENT_NODE
        node_client_start();
#endif
#ifdef CONFIG_AI_AGENT_MQTT
        mqtt_channel_start();
#endif
#ifdef CONFIG_AI_AGENT_WEIXIN
        weixin_channel_start();
#endif
        g_net_services_started = true;
    } else if (state == NET_STATE_DISCONNECTED) {
        syslog(LOG_WARNING,
            "[%s] Network lost, services may be affected\n", TAG);
        /* Services will handle disconnection via their own error paths.
         * We just log the event here. g_net_services_started stays true
         * so we don't re-start services that are already running. */
    }
}
