static bool filter_stale_message(cJSON* msg)
{
    /* Feishu sends create_time as a Unix timestamp in milliseconds.  The
     * board clock starts near the Unix epoch until network time is set, so
     * timestamp filtering must be disabled while the clock is unsynchronized.
     */
    static bool clock_warning_logged;
    const long long min_valid_epoch = 1577836800LL; /* 2020-01-01 UTC */
    cJSON* ct = cJSON_GetObjectItem(msg, "create_time");

    if (!cJSON_IsString(ct) || !ct->valuestring[0]) {
        return false;
    }

    long long create_value = atoll(ct->valuestring);
    if (create_value <= 0) {
        return false;
    }

    /* Accept seconds too, since older event gateways used seconds. */
    long long create_ms = create_value < 100000000000LL
        ? create_value * 1000LL : create_value;
    long long now_sec = (long long)time(NULL);

    if (now_sec < min_valid_epoch) {
        if (!clock_warning_logged) {
            syslog(LOG_WARNING,
                "[%s] System clock unsynchronized (now=%lld); "
                "accepting Feishu message timestamps\n",
                TAG, now_sec);
            clock_warning_logged = true;
        }
        return false;
    }

    long long now_ms = now_sec * 1000LL;
    long long age_ms = now_ms - create_ms;

    /* A board clock can lag briefly after boot or NTP can step forward.  Only
     * reject messages that are demonstrably old; future timestamps are kept. */
    if (age_ms > 60000) {
        syslog(LOG_WARNING, "[%s] Stale message (age=%lldms), dropping\n",
            TAG, age_ms);
        return true;
    }

    if (age_ms < -120000) {
        syslog(LOG_DEBUG,
            "[%s] Message timestamp is ahead by %lldms; accepting\n",
            TAG, -age_ms);
    }
    return false;
}


