    (void)iface; (void)ssid; (void)pass;
    syslog(LOG_ERR, "[%s] enable CONFIG_WIRELESS_WAPI and CONFIG_NETUTILS_DHCPC for hardware WiFi\n", TAG);
    return -ENOSYS;
}
