450	     * consumes significant stack space. */
451	    char* hdr = malloc(4096);
452	    if (!hdr)
453	        return VELA_TLS_ERR_OVERFLOW;
454	
455	    int pos = 0;
456	    int ret;
457	
458	#define HDR_APPEND(fmt, ...)                                    \
459	    pos += snprintf(hdr + pos, 4096 - pos, fmt, ##__VA_ARGS__); \
460	    if (pos >= 4096) {                                          \
461	        free(hdr);                                              \
462	        return VELA_TLS_ERR_OVERFLOW;                           \
463	    }
464	
465	    HDR_APPEND("%s %s HTTP/1.1\r\n", method, path);
466	    HDR_APPEND("Host: %s\r\n", host);
467	    HDR_APPEND("Connection: keep-alive\r\n");
468	    HDR_APPEND("User-Agent: agent-vela/1.0\r\n");
469	
470	    if (body && body_len > 0) {
471	        HDR_APPEND("Content-Length: %zu\r\n", body_len);
472	    }
473	
474	    if (headers) {
475	        for (const vela_header_t* h = headers; h->name != NULL; h++) {
476	            HDR_APPEND("%s: %s\r\n", h->name, h->value);
477	        }
478	    }
479	
480	    HDR_APPEND("\r\n");
481	#undef HDR_APPEND
482	
483	    /* Write headers */
484	    int written = 0;
485	    while (written < pos) {
486	        ret = mbedtls_ssl_write(&ctx->ssl,
487	            (const unsigned char*)(hdr + written),
488	            (size_t)(pos - written));
489	        if (ret > 0) {
490	            written += ret;
491	        } else if (ret == 0) {
492	            free(hdr);
493	            return VELA_TLS_ERR_WRITE;
494	        } else if (ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
495	            free(hdr);
496	            return VELA_TLS_ERR_WRITE;
497	        }
498	    }
499	
500	    free(hdr);
